function salesProductBaseName(value, category = "") {
  const product = value && typeof value === "object" ? value : null;
  let rawName = String(product?.baseName || product?.name || value || "").trim();
  const categoryName = String(product?.category || category || "").trim();
  if (product && product.netContentValue) rawName = salesProductStripVariantSuffix(rawName, salesProductTitleSizeText(product.netContentValue, product.netContentUnit));
  if (!categoryName) return rawName;
  const oldPrefix = `${categoryName} · `;
  const newSuffix = `-${categoryName}`;
  if (rawName.toLowerCase().startsWith(oldPrefix.toLowerCase())) rawName = rawName.slice(oldPrefix.length).trim();
  if (rawName.toLowerCase().endsWith(newSuffix.toLowerCase())) rawName = rawName.slice(0, -newSuffix.length).trim();
  const displaySuffix = ` ${categoryName}`;
  if (rawName.toLowerCase().endsWith(displaySuffix.toLowerCase())) rawName = rawName.slice(0, -displaySuffix.length).trim();
  return rawName;
}

function normalizeProductIdentity(value) {
  return String(value || "").normalize("NFKC").trim().replace(/\s+/g, " ").toLocaleLowerCase();
}

function isSackPurchaseUnit(unit) {
  return ["sack", "bag", "bag / বস্তা", "বস্তা"].includes(normalizeProductIdentity(unit));
}

function salesProductDisplayTitle(category, baseName, variantLabel = "", includeCategoryInTitle = true) {
  const cleanCategory = String(category || "").trim();
  const cleanName = salesProductBaseName(baseName, cleanCategory);
  const cleanVariant = String(variantLabel || "").trim();
  const normalizedName = normalizeProductIdentity(cleanName);
  const normalizedVariant = normalizeProductIdentity(cleanVariant);
  const nameAlreadyIncludesVariant = cleanVariant && (normalizedName === normalizedVariant || normalizedName.endsWith(` ${normalizedVariant}`));
  return [cleanName, cleanVariant && !nameAlreadyIncludesVariant ? cleanVariant : "", includeCategoryInTitle ? cleanCategory : ""].filter(Boolean).join(" ");
}

function salesProductTitle(product) {
  return salesProductDisplayTitle(product?.category, salesProductBaseName(product), product?.variantLabel, product?.includeCategoryInTitle !== false);
}

function salesProductIdentityName(baseName, variantLabel = "") {
  const cleanName = String(baseName || "").trim();
  const cleanVariant = String(variantLabel || "").trim();
  const normalizedName = normalizeProductIdentity(cleanName);
  const normalizedVariant = normalizeProductIdentity(cleanVariant);
  return cleanVariant && normalizedName !== normalizedVariant && !normalizedName.endsWith(` ${normalizedVariant}`)
    ? `${cleanName} ${cleanVariant}`.trim()
    : cleanName;
}

function salesProductShortDisplayName(value, category = "") {
  const words = salesProductSkuWords(salesProductBaseName(value, category));
  const genericWords = new Set(["DETERGENT", "POWDER", "LAUNDRY", "WASHING", "CLEANING", "MOSQUITO", "COIL", "SOAP", "SHAMPOO", "BATHING", "PERSONAL", "CARE", "SNACK", "SNACKS", "CHANACHUR", "DRINK", "DRINKS", "BEVERAGE", "WATER"]);
  const coreWords = words.filter((word) => !genericWords.has(word));
  return (coreWords.length ? coreWords : words).map((word) => word[0] + word.slice(1).toLowerCase()).join(" ") || "Product name needed";
}

function salesProductTitleSizeText(netContentValue, netContentUnit = "g") {
  const size = Number(netContentValue);
  const unit = String(netContentUnit || "g").trim() || "g";
  const displayUnit = unit.toLowerCase() === "g" ? "gm" : unit;
  return Number.isFinite(size) && size > 0 ? `${String(Number(size.toFixed(3)))} ${displayUnit}` : "";
}

function salesProductVariantTitle(value, netContentValue, netContentUnit = "g") {
  const title = String(value || "").trim();
  const size = salesProductTitleSizeText(netContentValue, netContentUnit);
  return title && size ? `${title}-${size}` : title;
}

function salesProductStripVariantSuffix(value, sizeValue) {
  const title = String(value || "").trim();
  const size = String(sizeValue || "").trim();
  if (!size) return title;
  const legacySize = size.replace(/\s+gm$/i, " g");
  const suffix = [`-${size}`, ` · ${size}`, `-${legacySize}`, ` · ${legacySize}`].find((candidate) => title.toLowerCase().endsWith(candidate.toLowerCase()));
  return suffix ? title.slice(0, -suffix.length).trim().replace(/\s+/g, " ") : title;
}

function salesProductFormBaseName(form, value, category = "", variantLabelValue) {
  const savedSize = String(form?.dataset.productTitleSize || "").trim();
  let title = salesProductStripVariantSuffix(value, savedSize);
  const cleanCategory = String(category || "").trim();
  const variantLabel = String(variantLabelValue === undefined ? (form?.querySelector('[name="variantLabel"]')?.value || "") : variantLabelValue).trim();
  if (cleanCategory) {
    const categorySuffix = ` ${cleanCategory}`;
    if (title.toLowerCase().endsWith(categorySuffix.toLowerCase())) title = title.slice(0, -categorySuffix.length).trim();
  }
  if (variantLabel) {
    const variantSuffix = ` ${variantLabel}`;
    if (normalizeProductIdentity(title) === normalizeProductIdentity(variantLabel)) title = "";
    else if (title.toLowerCase().endsWith(variantSuffix.toLowerCase())) title = title.slice(0, -variantSuffix.length).trim();
  }
  return salesProductBaseName(title, category);
}

