function updateAutomaticSalesProductImage(form) {
  if (!form || form.dataset.imageMode === "manual") return;
  const nameInput = form.querySelector("[data-product-name]");
  const skuInput = form.querySelector('[name="sku"]');
  const skuDisplay = form.querySelector("[data-product-sku-display]");
  const categoryInput = form.querySelector("[data-product-category]");
  const variant = Number(form.dataset.imageVariant || 0);
  const image = autoSalesProductImage(salesProductIdentityName(salesProductFormBaseName(form, nameInput?.value || "", categoryInput?.value || ""), form.querySelector('[name="variantLabel"]')?.value), categoryInput?.value || "", variant);
  const hidden = form.querySelector('[name="image"]');
  const preview = form.querySelector("[data-product-image-preview]");
  if (hidden) hidden.value = image;
  if (preview) {
    const img = document.createElement("img");
    img.src = image;
    img.alt = "Automatic product illustration";
    preview.replaceChildren(img);
  }
}

try {
  const savedCategories = JSON.parse(localStorage.getItem(productCategoryStorageKey) || "[]");
  if (Array.isArray(savedCategories)) savedCategories.forEach((saved) => {
    const name = String(saved?.name || "").trim();
    if (!name) return;
    const existing = categories.find((item) => String(item.id) === String(saved.id)) || categories.find((item) => item.name.toLowerCase() === name.toLowerCase());
    if (existing) Object.assign(existing, saved, { id: existing.id, name });
    else categories.push({ id: saved.id || Date.now() + Math.random(), parent: "Product Category", type: "Goods", ...saved, name });
  });
} catch { /* Use the built-in product categories if browser storage is unavailable. */ }

