const defaultAccountingJournals = [
  { code: "INV", name: "Sales", type: "sales", accountCode: "4000", active: true },
  { code: "BILL", name: "Purchases", type: "purchase", accountCode: "6000", active: true },
  { code: "BNK1", name: "Bank", type: "bank", accountCode: "1010", active: true },
  { code: "MISC", name: "Miscellaneous Operations", type: "misc", accountCode: "", active: true },
  { code: "CSH6", name: "Cash", type: "cash", accountCode: "1000", active: true },
];

function readAccountingAccounts() {
  try {
    const rows = JSON.parse(localStorage.getItem("odooAccountingAccounts") || "null");
    if (!Array.isArray(rows)) return defaultAccountingAccounts.map((item) => ({ ...item }));
    const legacyNames = { "1000": ["Cash on Hand", "Cash"], "1010": ["Bank Current Account", "Bank"], "4000": ["Wholesale Sales Revenue", "Product Sales"], "6000": ["Operating Expenses", "Expenses"] };
    const normalized = rows.filter((item) => item && typeof item === "object").map((item) => {
      const seed = defaultAccountingAccounts.find((account) => String(account.code) === String(item.code));
      const oldNames = legacyNames[String(item.code)];
      return seed && oldNames?.includes(String(item.name)) ? { ...item, name: seed.name } : item;
    });
    const known = new Set(normalized.map((item) => String(item.code)));
    return [...normalized, ...defaultAccountingAccounts.filter((item) => !known.has(String(item.code))).map((item) => ({ ...item }))];
  }
  catch { return defaultAccountingAccounts.map((item) => ({ ...item })); }
}

function readAccountingJournals() {
  try {
    const rows = JSON.parse(localStorage.getItem("odooAccountingJournals") || "null");
    if (!Array.isArray(rows)) return defaultAccountingJournals.map((item) => ({ ...item }));
    const legacyDefaults = [
      { code: "INV", name: "Customer Invoices", type: "sales", update: { name: "Sales", accountCode: "4000", active: true } },
      { code: "BILL", name: "Vendor Bills", type: "purchase", update: { name: "Purchases", accountCode: "6000", active: true } },
      { code: "BNK", name: "Bank", type: "bank", update: { code: "BNK1", accountCode: "1010", active: true } },
      { code: "CSH", name: "Cash", type: "cash", update: { code: "CSH6", accountCode: "1000", active: true } },
      { code: "MISC", name: "Miscellaneous", type: "misc", update: { name: "Miscellaneous Operations", accountCode: "", active: true } },
    ];
    const normalized = rows.filter((item) => item && typeof item === "object").map((item) => {
      const legacy = legacyDefaults.find((candidate) => String(item.code).toUpperCase() === candidate.code && item.name === candidate.name && item.type === candidate.type);
      if (legacy) return { ...item, ...legacy.update };
      if (String(item.code).toUpperCase() === "MFS" && item.name === "Mobile Financial Service" && item.type === "bank") return { ...item, active: false };
      return item;
    });
    const known = new Set(normalized.map((item) => String(item.code).toLowerCase()));
    return [...normalized, ...defaultAccountingJournals.filter((item) => !known.has(String(item.code).toLowerCase())).map((item) => ({ ...item }))];
  }
  catch { return defaultAccountingJournals.map((item) => ({ ...item })); }
}

function readAccountingSettings() {
  try { return { basis: "accrual", currency: "BDT", fiscalYearStart: "07-01", taxRounding: "per_line", country: "Bangladesh", ...JSON.parse(localStorage.getItem("odooAccountingSettings") || "{}") }; }
  catch { return { basis: "accrual", currency: "BDT", fiscalYearStart: "07-01", taxRounding: "per_line", country: "Bangladesh" }; }
}

