function readLastRoute() {
  const fallback = { page: "launcher", module: "launcher" };
  const urlRoute = routeFromHash();
  if (urlRoute) return urlRoute;
  try {
    const saved = JSON.parse(localStorage.getItem("odooLastRoute") || "null");
    if (!saved || !pageLabels[saved.page] || !validRouteModules.includes(saved.module)) return fallback;
    const editor = ["product-configuration", "sales-product", "warehouse", "category", "uom", "gift-item"].includes(saved.editor?.kind) ? saved.editor : null;
    return routeFromHash(routeHashFor(saved.module, saved.page, editor)) || fallback;
  } catch { return fallback; }
}

const validRouteModules = ["launcher", "purchase", "inventory", "dashboards", "accounting", "invoicing", "sales", "crm", "contacts", "settings", "discuss", "todo", "appointments", "apps"];
const moduleHomePages = {
  launcher: "launcher", purchase: "rfq", inventory: "inventory-overview", dashboards: "dashboards-home",
  accounting: "accounting-dashboard", invoicing: "invoice-dashboard", sales: "sales-quotations",
  crm: "crm-pipeline", contacts: "contacts", settings: "settings", discuss: "discuss", todo: "todo", appointments: "appointments", apps: "apps",
};
const modulePagePrefixes = { sales: "sales-", crm: "crm-", inventory: "inventory-", dashboards: "dashboards-", accounting: "accounting-", invoicing: "invoice-" };
const accountingInvoicingPages = ["invoice-taxes", "invoice-journals", "invoice-currencies", "invoice-fiscal-positions", "invoice-reminders", "invoice-payment-terms", "invoice-product-categories", "invoice-analysis", "invoice-document-layout"];

function moduleForPage(page, previousModule = "purchase") {
  return page === "activities" ? (previousModule === "launcher" ? "purchase" : previousModule)
    : page === "contacts" ? "contacts"
      : page.startsWith("inventory-") ? "inventory"
        : page.startsWith("dashboards-") ? "dashboards"
          : page.startsWith("accounting-") ? "accounting"
            : accountingInvoicingPages.includes(page) && previousModule === "accounting" ? "accounting"
              : page.startsWith("invoice-") ? "invoicing"
                : page.startsWith("crm-") ? "crm"
                : page.startsWith("sales-") || ["salespersons-report", "sales-products-report", "sales-customers-report"].includes(page) ? "sales"
                  : page === "settings" ? "settings"
                    : page === "discuss" ? "discuss"
                      : page === "todo" ? "todo"
                        : page === "appointments" ? "appointments"
                      : page === "apps" ? "apps" : "purchase";
}

function routePageSegment(module, page) {
  if (moduleHomePages[module] === page) return "";
  const prefix = modulePagePrefixes[module];
  return prefix && page.startsWith(prefix) ? page.slice(prefix.length) : page;
}

function routeHashFor(module, page, editor = null) {
  if (module === "launcher" || page === "launcher") return "#/";
  const segment = routePageSegment(module, page);
  const path = `#/${encodeURIComponent(module)}${segment ? `/${encodeURIComponent(segment)}` : ""}`;
  const supportsWarehouseEditor = module === "inventory" && page === "inventory-warehouses" && editor?.kind === "warehouse";
  const supportsCategoryEditor = module === "inventory" && page === "inventory-categories" && editor?.kind === "category";
  const supportsUomEditor = module === "inventory" && page === "inventory-units" && editor?.kind === "uom";
  const supportsGiftItemEditor = module === "inventory" && page === "inventory-gift-configurations" && editor?.kind === "gift-item";
  const supportsProductEditor = module === "inventory" || module === "sales";
  const supportsConfigurationEditor = module === "inventory" && editor?.kind === "product-configuration";
  const supportsSalesProductEditor = supportsProductEditor && editor?.kind === "sales-product";
  if (!supportsWarehouseEditor && !supportsCategoryEditor && !supportsUomEditor && !supportsGiftItemEditor && !supportsConfigurationEditor && !supportsSalesProductEditor) return path;
  const params = new URLSearchParams({ editor: editor.kind });
  if (editor.id != null && editor.id !== "") params.set("id", String(editor.id));
  if (editor.returnPage) params.set("returnPage", String(editor.returnPage));
  if (editor.returnPickerId) params.set("returnPickerId", String(editor.returnPickerId));
  if (editor.returnToProduct) params.set("returnToProduct", "1");
  if (editor.fromProduct) params.set("fromProduct", "1");
  if (editor.configurationId) params.set("configuration", String(editor.configurationId));
  if (editor.tab) params.set("tab", String(editor.tab));
  return `${path}?${params.toString()}`;
}

function routeFromHash(hash = window.location.hash) {
  const source = String(hash || "");
  if (!source.startsWith("#")) return null;
  const [rawPath, rawQuery = ""] = source.slice(1).split("?", 2);
  const path = rawPath.replace(/^\/+|\/+$/g, "");
  if (!path) return { page: "launcher", module: "launcher" };
  let parts;
  try { parts = path.split("/").map((part) => decodeURIComponent(part)); }
  catch { return null; }
  const [module, segment, extra] = parts;
  if (extra || !validRouteModules.includes(module)) return null;
  if (!segment) return { page: moduleHomePages[module], module };
  const page = Object.keys(pageLabels).find((candidate) => {
    // CRM's Activities page shares the `/activities` route segment with the cross-module Activities page.
    // In a CRM URL, prefer the CRM-specific route so refreshes keep the CRM view selected.
    if (module === "crm" && candidate === "activities") return false;
    return moduleForPage(candidate, module) === module && routePageSegment(module, candidate) === segment;
  });
  if (!page) return null;
  const supportsProductEditor = module === "inventory" || module === "sales";
  const params = new URLSearchParams(rawQuery);
  let editor = null;
  if (params.has("editor")) {
    const kind = params.get("editor");
    const returnPage = params.get("returnPage") || page;
    if (kind === "warehouse") {
      if (module !== "inventory" || page !== "inventory-warehouses") return null;
      editor = { kind, id: params.get("id") || null };
    } else if (kind === "category") {
      if (module !== "inventory" || page !== "inventory-categories") return null;
      editor = { kind, id: params.get("id") || null };
    } else if (kind === "uom") {
      if (module !== "inventory" || page !== "inventory-units") return null;
      editor = { kind, id: params.get("id") || null };
    } else if (kind === "gift-item") {
      if (module !== "inventory" || page !== "inventory-gift-configurations") return null;
      const editorReturnPage = params.get("returnPage") || page;
      if (!["inventory-gift-configurations", "inventory-products"].includes(editorReturnPage)) return null;
      editor = {
        kind,
        id: params.get("id") || null,
        returnPage: editorReturnPage,
        returnToProduct: params.get("returnToProduct") === "1",
        returnPickerId: params.get("returnPickerId") || "",
      };
    } else if (kind === "product-configuration") {
      const allowedTabs = ["configuration", "purchase", "inventory", "units-pricing"];
      if (module !== "inventory" || !pageLabels[returnPage] || moduleForPage(returnPage, module) !== "inventory") return null;
      const requestedTab = params.get("tab");
      editor = {
        kind,
        id: params.get("id") || null,
        returnPage,
        fromProduct: params.get("fromProduct") === "1",
        tab: allowedTabs.includes(requestedTab) ? requestedTab : "units-pricing",
      };
    } else if (kind === "sales-product") {
      const allowedTabs = ["configuration", "promotional-offer", "purchase", "inventory", "unit-pricing"];
      if (!supportsProductEditor || !pageLabels[returnPage] || moduleForPage(returnPage, module) !== module) return null;
      const requestedTab = params.get("tab");
      editor = {
        kind,
        id: params.get("id") || null,
        returnPage,
        configurationId: params.get("configuration") || null,
        tab: allowedTabs.includes(requestedTab) ? requestedTab : "configuration",
      };
    } else return null;
  }
  return { page, module, editor };
}

