function readSavedSettings() {
  try {
    const saved = JSON.parse(localStorage.getItem("odooFmcgSettings") || "{}");
    return { ...defaultSettings, ...saved,
      invitedUsers: Array.isArray(saved.invitedUsers) ? saved.invitedUsers : [...defaultSettings.invitedUsers],
      enabledLanguages: Array.isArray(saved.enabledLanguages) ? saved.enabledLanguages : [...defaultSettings.enabledLanguages],
      companies: Array.isArray(saved.companies) && saved.companies.length ? saved.companies : defaultSettings.companies.map((company) => ({ ...company })),
    };
  } catch { return { ...defaultSettings, invitedUsers: [], enabledLanguages: [...defaultSettings.enabledLanguages], companies: defaultSettings.companies.map((company) => ({ ...company })) }; }
}

function readPackRules() {
  if (isFreshCompanyStart) return [];
  const confirmedCoilRule = { id: "coil-carton-30", product: "Mosquito coil", sku: "Standard carton", stockUom: "Piece", purchasePack: "Carton", quantity: 30 };
  try {
    const parsedRules = JSON.parse(localStorage.getItem("odooFmcgPackRules") || "[]");
    const savedRules = Array.isArray(parsedRules) ? parsedRules : [];
    return [confirmedCoilRule, ...savedRules.filter((rule) => rule.id !== confirmedCoilRule.id)];
  } catch { return [confirmedCoilRule]; }
}

