const pageContent = document.querySelector("#page-content");
let inventoryGiftItemReturnView = null;
const launcherView = document.querySelector("#launcher-view");
const menuPopover = document.querySelector("#menu-popover");
const modalRoot = document.querySelector("#modal-root");
const toastRegion = document.querySelector("#toast-region");

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
}

function money(value) {
  return Number(value || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function initials(name) {
  return String(name || "?").split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toUpperCase();
}

function showToast(message) {
  toastRegion.classList.remove("product-save-notice-region");
  toastRegion.innerHTML = `<div class="toast">${escapeHtml(message)}</div>`;
  window.clearTimeout(state.toastTimer);
  state.toastTimer = window.setTimeout(() => { toastRegion.innerHTML = ""; }, 3400);
}

function showProductSaveNotice({ type = "success", title, message, code = "" }) {
  const isError = type === "error";
  const role = isError ? "alert" : "status";
  toastRegion.classList.add("product-save-notice-region");
  toastRegion.innerHTML = `<div class="product-save-notice ${isError ? "is-error" : "is-success"}" role="${role}" aria-live="${isError ? "assertive" : "polite"}"><span class="product-save-notice-icon" aria-hidden="true">${isError ? "!" : "✓"}</span><div><strong>${escapeHtml(title || (isError ? "Product was not saved" : "Saved successfully"))}</strong><p>${escapeHtml(message)}</p>${code ? `<small>Error code: <code>${escapeHtml(code)}</code></small>` : ""}</div></div>`;
  window.clearTimeout(state.toastTimer);
  state.toastTimer = window.setTimeout(() => {
    toastRegion.innerHTML = "";
    toastRegion.classList.remove("product-save-notice-region");
  }, 4200);
}

function persistLastRoute({ historyMode = "push" } = {}) {
  const editor = state.inventoryGiftItemEditor
    ? { kind: "gift-item", id: state.inventoryGiftItemEditor.id || null, returnPage: state.inventoryGiftItemEditor.returnPage || state.page, returnToProduct: Boolean(state.inventoryGiftItemEditor.returnToProduct), returnPickerId: state.inventoryGiftItemEditor.returnPickerId || "" }
    : state.inventoryUomEditor
    ? { kind: "uom", id: state.inventoryUomEditor.id || null }
    : state.inventoryCategoryEditor
    ? { kind: "category", id: state.inventoryCategoryEditor.id || null }
    : state.inventoryWarehouseEditor
    ? { kind: "warehouse", id: state.inventoryWarehouseEditor.id || null }
    : state.inventoryProductConfigurationEditor
    ? { kind: "product-configuration", id: state.inventoryProductConfigurationEditor.id || null, returnPage: state.inventoryProductConfigurationEditor.returnPage || state.page, fromProduct: Boolean(state.inventoryProductConfigurationEditor.fromProduct), tab: state.inventoryProductConfigurationEditor.tab || "units-pricing" }
    : state.salesProductEditor
      ? { kind: "sales-product", id: state.salesProductEditor.id || null, returnPage: state.salesProductEditor.returnPage || state.page, configurationId: state.salesProductEditor.pendingConfigurationId || state.salesProductEditor.configurationId || null, tab: state.salesProductEditor.tab || "configuration" }
      : null;
  const routeSnapshot = { page: state.page, module: state.module, ...(editor ? { editor } : {}) };
  try { localStorage.setItem("odooLastRoute", JSON.stringify(routeSnapshot)); }
  catch { /* Keep the current route for this tab if browser storage is unavailable. */ }
  if (historyMode === "none") return;
  const nextHash = routeHashFor(state.module, state.page, editor);
  if (window.location.hash === nextHash) return;
  if (historyMode === "replace") window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}${nextHash}`);
  else window.location.hash = nextHash;
}

function setPage(page, routeOverride = null) {
  let nextPage = pageLabels[page] ? page : "rfq";
  const requiredInventorySetting = inventorySettingPageRequirements[nextPage];
  if (requiredInventorySetting && !inventorySettingsRequirementsMet(requiredInventorySetting)) {
    nextPage = "inventory-settings";
    routeOverride = { module: "inventory" };
    showToast("Enable this Inventory feature in Settings before opening its workflow.");
  }
  if (inventoryGiftItemReturnView && nextPage !== inventoryGiftItemReturnView.page) inventoryGiftItemReturnView = null;
  if (nextPage !== "settings") state.companyProfileEditor = null;
  if (nextPage !== "inventory-putaway-rules") state.inventoryCategoryPutawayFilter = "";
  state.inventoryPutawayRulesFromCategory = false;
  if (nextPage !== "inventory-products") state.inventoryProductFiltersOpen = false;
  state.module = routeOverride?.module || moduleForPage(nextPage, state.module);
  if (nextPage === "settings" && state.page !== "settings") state.settingsSection = "general";
  if (nextPage !== "settings") state.settingsSearch = "";
  state.page = nextPage;
  state.salesEditor = null;
  state.salesProductEditor = routeOverride?.editor?.kind === "sales-product" ? { id: routeOverride.editor.id ? Number(routeOverride.editor.id) : null, returnPage: routeOverride.editor.returnPage || nextPage, configurationId: routeOverride.editor.configurationId || null, pendingConfigurationId: routeOverride.editor.configurationId || null, tab: routeOverride.editor.tab || "configuration" } : false;
  state.purchaseEditor = null;
  state.receiptEditor = null;
  state.invoiceEditor = null;
  state.invoicePaymentEditor = null;
  state.contactEditor = null;
  state.accountingFormEditor = null;
  state.inventoryDeliveryEditor = null;
  state.inventoryTransferEditor = null;
  state.inventoryWarehouseEditor = routeOverride?.editor?.kind === "warehouse" ? { ...routeOverride.editor } : null;
  state.inventoryCategoryEditor = routeOverride?.editor?.kind === "category" ? { ...routeOverride.editor } : null;
  state.inventoryUomEditor = routeOverride?.editor?.kind === "uom" ? { ...routeOverride.editor } : null;
  state.inventoryGiftItemEditor = routeOverride?.editor?.kind === "gift-item" ? { ...routeOverride.editor } : null;
  state.inventoryCategoryAccountPicker = null;
  state.inventoryProductConfigurationEditor = routeOverride?.editor?.kind === "product-configuration" ? { ...routeOverride.editor } : null;
  state.salesOrderTab = "order-lines";
  state.search = "";
  state.quickFilter = "";
  state.salesQuickFilter = "";
  state.view = nextPage === "inventory-products" ? "kanban" : "list";
  state.selected.clear();
  state.launcher = false;
  persistLastRoute({ historyMode: ["warehouse", "category", "uom"].includes(routeOverride?.editor?.kind) ? "push" : routeOverride ? "none" : "push" });
  closeMenus();
  closeActivityPopover();
  render();
}

function closeMenus() {
  menuPopover.hidden = true;
  menuPopover.innerHTML = "";
  closeUserProfilePopover();
  document.querySelector(".settings-user-record-menu")?.remove();
  document.querySelector(".settings-users-kebab")?.setAttribute("aria-expanded", "false");
  document.querySelectorAll(".primary-nav button.is-open").forEach((button) => button.classList.remove("is-open"));
  document.querySelectorAll(".inventory-category-action-menu").forEach((menu) => { menu.hidden = true; });
  document.querySelectorAll(".inventory-category-marketing-submenu").forEach((menu) => { menu.hidden = true; });
  document.querySelectorAll(".inventory-category-gear").forEach((button) => button.setAttribute("aria-expanded", "false"));
  document.querySelectorAll("[data-inventory-action='category-toggle-marketing']").forEach((button) => button.setAttribute("aria-expanded", "false"));
  document.querySelectorAll(".action-dropdown").forEach((menu) => menu.remove());
  document.querySelectorAll(".toolbar-more-menu").forEach((menu) => menu.remove());
  document.querySelectorAll(".erp-product-header-dropdown").forEach((menu) => menu.remove());
  document.querySelectorAll("[data-product-header-menu]").forEach((button) => button.setAttribute("aria-expanded", "false"));
}

function openLauncher() {
  state.page = "launcher";
  state.module = "launcher";
  state.launcher = true;
  state.salesProductEditor = false;
  state.inventoryProductConfigurationEditor = null;
  state.inventoryCategoryEditor = null;
  state.inventoryUomEditor = null;
  state.inventoryCategoryAccountPicker = null;
  persistLastRoute();
  state.invoiceEditor = null;
  state.invoicePaymentEditor = null;
  state.contactEditor = null;
  state.accountingFormEditor = null;
  state.purchaseEditor = null;
  state.receiptEditor = null;
  state.search = "";
  state.selected.clear();
  closeMenus();
  closeActivityPopover();
  render();
}

function applyHashRoute() {
  const route = routeFromHash();
  if (!route) return;
  if (route.page === "launcher") { openLauncher(); return; }
  if (inventoryGiftItemReturnView && route.page === inventoryGiftItemReturnView.page && route.module === inventoryGiftItemReturnView.module && route.editor?.kind === "sales-product") {
    const returnView = inventoryGiftItemReturnView;
    inventoryGiftItemReturnView = null;
    state.inventoryGiftItemEditor = null;
    state.page = returnView.page;
    state.module = returnView.module;
    state.launcher = false;
    persistLastRoute({ historyMode: "none" });
    render();
    pageContent.replaceChildren(returnView.content);
    return;
  }
  if (state.page === route.page && state.module === route.module && state.launcher === (route.page === "launcher")) {
    const nextEditor = route.editor || null;
    const currentEditor = state.inventoryProductConfigurationEditor
      ? { kind: "product-configuration", ...state.inventoryProductConfigurationEditor }
      : state.inventoryCategoryEditor
        ? { kind: "category", ...state.inventoryCategoryEditor }
      : state.inventoryUomEditor
        ? { kind: "uom", ...state.inventoryUomEditor }
      : state.inventoryGiftItemEditor
        ? { kind: "gift-item", ...state.inventoryGiftItemEditor }
      : state.salesProductEditor
        ? { kind: "sales-product", ...state.salesProductEditor, configurationId: state.salesProductEditor.pendingConfigurationId || state.salesProductEditor.configurationId || null }
        : null;
    const sameEditor = (!nextEditor && !currentEditor) || (nextEditor && currentEditor
      && nextEditor.kind === currentEditor.kind
      && String(nextEditor.id || "") === String(currentEditor.id || "")
      && nextEditor.returnPage === currentEditor.returnPage
      && Boolean(nextEditor.fromProduct) === Boolean(currentEditor.fromProduct)
      && Boolean(nextEditor.returnToProduct) === Boolean(currentEditor.returnToProduct)
      && String(nextEditor.returnPickerId || "") === String(currentEditor.returnPickerId || "")
      && String(nextEditor.configurationId || "") === String(currentEditor.configurationId || ""));
    if (!sameEditor) {
      state.inventoryProductConfigurationEditor = nextEditor?.kind === "product-configuration" ? { ...nextEditor } : null;
      state.inventoryCategoryEditor = nextEditor?.kind === "category" ? { ...nextEditor } : null;
      state.inventoryUomEditor = nextEditor?.kind === "uom" ? { ...nextEditor } : null;
      state.inventoryGiftItemEditor = nextEditor?.kind === "gift-item" ? { ...nextEditor } : null;
      state.salesProductEditor = nextEditor?.kind === "sales-product" ? { ...nextEditor, id: nextEditor.id ? Number(nextEditor.id) : null, pendingConfigurationId: nextEditor.configurationId || null } : false;
      state.salesProductImageData = null;
      render();
    } else if (nextEditor && nextEditor.tab !== currentEditor.tab) {
      if (nextEditor.kind === "product-configuration") state.inventoryProductConfigurationEditor.tab = nextEditor.tab;
      else if (nextEditor.kind === "sales-product") state.salesProductEditor.tab = nextEditor.tab;
      render();
    }
    persistLastRoute({ historyMode: "none" });
    return;
  }
  setPage(route.page, route);
}

window.addEventListener("hashchange", applyHashRoute);
window.addEventListener("popstate", applyHashRoute);

function persistDiscussThreads() {
  try { localStorage.setItem("odooDiscussThreads", JSON.stringify(state.discussThreads)); return true; }
  catch { showToast("This browser could not save the discussion locally."); return false; }
}

function discussDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleString("en-BD", { dateStyle: "medium", timeStyle: "short" });
}

function renderDiscussPage() {
  const threads = [...state.discussThreads].sort((a, b) => new Date(b.messages?.at(-1)?.date || 0) - new Date(a.messages?.at(-1)?.date || 0));
  const visibleThreads = threads.filter((thread) => state.discussFilter === "Starred" ? thread.starred : state.discussFilter === "History" ? (thread.archived || false) : !thread.archived);
  const activeThread = visibleThreads.find((thread) => String(thread.id) === String(state.discussActiveThreadId)) || visibleThreads[0] || null;
  const threadList = visibleThreads.length ? visibleThreads.map((thread) => {
    const latest = thread.messages?.at(-1);
    return `<article class="discuss-thread-row ${activeThread?.id === thread.id ? "is-active" : ""}"><button class="discuss-thread-open" type="button" data-discuss-thread="${escapeHtml(thread.id)}"><strong>${escapeHtml(thread.name)}</strong><span>${escapeHtml(latest?.text || "No messages yet")}</span><small>${escapeHtml(discussDate(latest?.date))}</small></button><button class="discuss-star ${thread.starred ? "is-starred" : ""}" type="button" data-discuss-star="${escapeHtml(thread.id)}" aria-label="${thread.starred ? "Remove from" : "Add to"} starred" title="Star conversation">${thread.starred ? "★" : "☆"}</button></article>`;
  }).join("") : `<div class="discuss-list-empty"><span>✉</span><p>${state.discussFilter === "Starred" ? "No starred conversations" : state.discussFilter === "History" ? "No archived conversations" : "No conversations yet"}</p></div>`;
  const messages = activeThread?.messages?.length ? activeThread.messages.map((message) => `<article class="discuss-message"><div class="discuss-message-avatar">${escapeHtml(initials(message.sender || "You"))}</div><div><header><strong>${escapeHtml(message.sender || "You")}</strong><time>${escapeHtml(discussDate(message.date))}</time></header><p>${escapeHtml(message.text).replace(/\n/g, "<br>")}</p></div></article>`).join("") : `<div class="discuss-empty"><span class="discuss-empty-icon">✉</span><h2>${activeThread ? escapeHtml(activeThread.name) : "Your conversations start here"}</h2><p>${activeThread ? "Send a message to start this conversation." : "Create a local conversation for your team. Messages stay in this browser until a live Odoo Discuss service is connected."}</p>${activeThread ? "" : `<button class="action-button" type="button" data-action="new-discuss-message">New Message</button>`}</div>`;
  const reply = activeThread ? `<form class="discuss-reply" id="discuss-reply-form" data-thread-id="${escapeHtml(activeThread.id)}"><textarea name="message" rows="2" placeholder="Write a message..." required></textarea><button class="action-button" type="submit">Send</button></form>` : "";
  return `<section class="discuss-page"><aside class="discuss-sidebar"><div class="discuss-sidebar-heading"><h1>Discuss</h1><button class="action-button" type="button" data-action="new-discuss-message">New Message</button></div><nav class="discuss-filters" aria-label="Conversation filters">${["Inbox", "Starred", "History"].map((filter) => `<button type="button" data-discuss-filter="${filter}" class="${state.discussFilter === filter ? "is-active" : ""}">${filter}</button>`).join("")}</nav><div class="discuss-thread-list">${threadList}</div></aside><section class="discuss-conversation">${activeThread ? `<header class="discuss-conversation-heading"><div><h2>${escapeHtml(activeThread.name)}</h2><span>Local conversation</span></div><button class="soft-icon-button" type="button" data-discuss-star="${escapeHtml(activeThread.id)}" aria-label="Toggle star">${activeThread.starred ? "★" : "☆"}</button></header>` : ""}<div class="discuss-messages">${messages}</div>${reply}</section><p class="discuss-local-note">Local prototype · messages are stored in this browser only</p></section>`;
}

function persistTodoData() {
  try {
    localStorage.setItem("odooTodoStages", JSON.stringify(state.todoStages));
    localStorage.setItem("odooTodoItems", JSON.stringify(state.todoItems));
    return true;
  } catch { showToast("To-do changes could not be saved in this browser."); return false; }
}

function todoStageName(stageId) { return state.todoStages.find((stage) => String(stage.id) === String(stageId))?.name || "Inbox"; }

function todoDeadlineLabel(value) {
  if (!value) return "";
  const date = new Date(`${value}T12:00:00`);
  if (Number.isNaN(date.getTime())) return "";
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const due = new Date(date); due.setHours(0, 0, 0, 0);
  const days = Math.round((due - today) / 86400000);
  if (days === 0) return "Today";
  if (days === 1) return "Tomorrow";
  if (days > 1 && days < 8) return `In ${days} days`;
  return new Intl.DateTimeFormat("en", { month: "short", day: "numeric" }).format(date);
}

function todoSafeId(value) { return String(value || "").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || `stage-${Date.now()}`; }

function todoCardMarkup(item) {
  const stage = state.todoStages.find((row) => String(row.id) === String(item.stageId));
  const done = stage?.id === "done";
  const deadline = todoDeadlineLabel(item.deadline);
  const tagClass = todoSafeId(item.tag);
  const avatars = (item.assignees || []).slice(0, 3).map((name, index) => `<span class="todo-avatar avatar-${index % 4}" title="${escapeHtml(name)}">${escapeHtml(initials(name))}</span>`).join("");
  const source = item.linkedReceiptId ? `<button type="button" class="todo-source-link" data-todo-action="open-receipt" data-id="${escapeHtml(item.id)}">Inventory · Receipt</button>` : "";
  const summaryLines = String(item.description || "").split("\n").filter(Boolean).slice(0, item.linkedReceiptId ? 2 : 1);
  const summary = summaryLines.length ? `<p class="todo-card-summary">${escapeHtml(summaryLines.join(" · "))}</p>` : "";
  return `<article class="todo-card ${done ? "is-done" : ""}" draggable="true" data-todo-drag="${escapeHtml(item.id)}" data-todo-id="${escapeHtml(item.id)}"><button type="button" class="todo-card-title" data-todo-action="edit" data-id="${escapeHtml(item.id)}">${escapeHtml(item.title)}</button>${deadline ? `<span class="todo-deadline">${escapeHtml(deadline)}</span>` : ""}${item.tag ? `<span class="todo-tag ${tagClass}">${escapeHtml(item.tag)}</span>` : ""}${source}${summary}<footer><div class="todo-card-tools"><span class="todo-stars" aria-label="Priority ${Number(item.priority || 0)} of 3">${[1, 2, 3].map((star) => `<button type="button" class="${Number(item.priority || 0) >= star ? "is-priority" : ""}" data-todo-action="priority" data-id="${escapeHtml(item.id)}" data-priority="${star}" aria-label="Set priority ${star}">${Number(item.priority || 0) >= star ? "★" : "☆"}</button>`).join("")}</span>${item.reminder ? `<span class="todo-reminder" title="Reminder">◷</span>` : ""}${item.mail ? `<span class="todo-mail" title="Email">✉</span>` : ""}</div><div class="todo-card-people">${avatars}<button type="button" class="todo-complete" data-todo-action="complete" data-id="${escapeHtml(item.id)}" aria-label="${done ? "Reopen" : "Mark done"}" title="${done ? "Reopen" : "Mark done"}">${done ? "✓" : "✓"}</button></div></footer></article>`;
}

function renderTodoBoard() {
  const query = String(state.todoSearch || "").trim().toLocaleLowerCase();
  const groups = state.todoStages.filter((stage) => !["done", "cancelled"].includes(String(stage.id)));
  const visibleTasks = state.todoItems.filter((item) => {
    const isClosed = ["done", "cancelled"].includes(String(item.stageId));
    if (state.todoOpenOnly && isClosed) return false;
    if (query && ![item.title, item.tag, item.description, item.sourceSummary].some((value) => String(value || "").toLocaleLowerCase().includes(query))) return false;
    return true;
  });
  const lanes = groups.map((stage) => {
    const items = visibleTasks.filter((item) => String(item.stageId) === String(stage.id));
    const progress = Math.min(100, items.length * 20);
    const isQuick = String(state.todoQuickCreateStage) === String(stage.id);
    const menuOpen = String(state.todoStageMenu) === String(stage.id);
    const quickForm = isQuick ? `<form class="todo-quick-form" id="todo-quick-form" data-stage-id="${escapeHtml(stage.id)}"><div class="todo-quick-heading"><label for="todo-quick-title">To-do Title <sup>?</sup></label><button type="button" data-todo-action="quick-close" aria-label="Close">×</button></div><input id="todo-quick-title" name="title" placeholder="e.g. Send Invitations" maxlength="120" required><label for="todo-quick-deadline">Deadline</label><input id="todo-quick-deadline" name="deadline" type="date"><div class="todo-quick-actions"><button class="action-button" type="submit">Add</button><button class="action-button secondary" type="button" data-todo-action="quick-edit" data-stage-id="${escapeHtml(stage.id)}">Edit</button><button class="soft-icon-button todo-quick-delete" type="button" data-todo-action="quick-close" aria-label="Discard">▣</button></div></form>` : "";
    return `<section class="todo-lane ${stage.folded ? "is-folded" : ""}" data-todo-drop-stage="${escapeHtml(stage.id)}"><header class="todo-lane-header"><div class="todo-lane-title-row"><h2>${escapeHtml(stage.name)}</h2><button type="button" class="todo-lane-add" data-todo-action="quick-open" data-stage-id="${escapeHtml(stage.id)}" aria-label="Add to ${escapeHtml(stage.name)}">+</button><button type="button" class="todo-lane-menu-toggle" data-todo-action="stage-menu" data-stage-id="${escapeHtml(stage.id)}" aria-label="${escapeHtml(stage.name)} options">⋮</button><span class="todo-lane-count">${items.length}</span></div><div class="todo-progress"><span style="width:${progress}%"></span></div>${menuOpen ? `<div class="todo-stage-menu"><button type="button" data-todo-action="fold" data-stage-id="${escapeHtml(stage.id)}">${stage.folded ? "Unfold" : "Fold"}</button><button type="button" data-todo-action="stage-edit" data-stage-id="${escapeHtml(stage.id)}">✎ Edit</button><button type="button" data-todo-action="automation" data-stage-id="${escapeHtml(stage.id)}">✣ Automations</button><button type="button" class="is-danger" data-todo-action="stage-delete" data-stage-id="${escapeHtml(stage.id)}">▤ Delete</button></div>` : ""}</header>${stage.folded ? "" : `<div class="todo-lane-cards">${quickForm}${items.map(todoCardMarkup).join("")}</div>`}</section>`;
  }).join("");
  const closedMarkup = ["done", "cancelled"].map((id) => {
    const stage = state.todoStages.find((item) => String(item.id) === id);
    if (!stage) return "";
    const count = state.todoItems.filter((item) => String(item.stageId) === id).length;
    const expanded = state.todoCollapsedGroups.has(id);
    const groupItems = visibleTasks.filter((item) => String(item.stageId) === id);
    return `<section class="todo-closed-group ${expanded ? "is-expanded" : ""}" data-todo-drop-stage="${id}"><button type="button" data-todo-action="toggle-closed" data-stage-id="${id}" aria-expanded="${expanded}">${escapeHtml(stage.name)}${id === "cancelled" && count ? ` (${count})` : ""}<span>‹</span></button>${expanded ? `<div>${groupItems.map(todoCardMarkup).join("") || `<p>No matching ${stage.name.toLocaleLowerCase()} to-dos</p>`}</div>` : ""}</section>`;
  }).join("");
  return `<div class="todo-board-scroll"><div class="todo-board">${lanes}<aside class="todo-closed-groups">${closedMarkup}</aside></div></div>`;
}

function renderTodoPage() {
  return `<section class="todo-page"><header class="todo-toolbar"><div class="todo-toolbar-title"><button class="action-button" type="button" data-todo-action="quick-open" data-stage-id="inbox">New</button><h1>To-dos</h1><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button></div><label class="todo-search">${icon("search")}<button type="button" class="todo-filter-icon" data-todo-action="toggle-filter" aria-label="Filters" title="Filters">${icon("filter")}</button>${state.todoOpenOnly ? `<button type="button" class="todo-filter-chip" data-todo-action="clear-filter">Open <span aria-hidden="true">×</span></button>` : ""}<input id="todo-search-input" type="search" value="${escapeHtml(state.todoSearch)}" placeholder="Search..." autocomplete="off"></label><div class="todo-view-buttons"><button type="button" class="is-active" aria-label="Kanban view" title="Kanban">▦</button><button type="button" data-action="toast" data-message="List view is not enabled for this local To-do board yet." aria-label="List view" title="List">☰</button><button type="button" data-action="toast" data-message="Calendar view is not enabled for this local To-do board yet." aria-label="Calendar view" title="Calendar">▣</button><button type="button" data-action="toast" data-message="Activity view is not enabled for this local To-do board yet." aria-label="Activity view" title="Activity">◷</button></div></header><div class="todo-board-region">${renderTodoBoard()}</div><input id="todo-import-file" type="file" accept=".csv,text/csv" hidden></section>`;
}

function renderAppointmentsPage() {
  return `<section class="appointments-page"><header><span class="appointments-page-icon">31</span><div><p>APPLICATION</p><h1>Appointments</h1><span>The app icon is ready. Appointment screens and workflows will be added when you provide those requirements.</span></div></header><div class="appointments-placeholder"><strong>Appointments</strong><p>This app is reserved for the appointment workflow. Its configuration and booking features are not set up yet.</p></div></section>`;
}

function openTodoTaskModal(item = null, stageId = "inbox", quickValues = null) {
  const stageOptions = state.todoStages.map((stage) => `<option value="${escapeHtml(stage.id)}" ${String(stage.id) === String(item?.stageId || stageId) ? "selected" : ""}>${escapeHtml(stage.name)}</option>`).join("");
  const assignees = (item?.assignees || []).join(", ");
  const sourceNotice = item?.linkedReceiptId ? `<p class="todo-linked-notice">Linked receipt ${escapeHtml(item.linkedReceiptRef || "")} · summary is generated from the inventory receipt. <button type="button" data-todo-action="open-receipt" data-id="${escapeHtml(item.id)}">Open Receipt</button></p>` : "";
  openModal(`<header class="modal-header"><div><h2>${item ? "Edit To-do" : "New To-do"}</h2><p>Task details</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="todo-task-form" data-id="${escapeHtml(item?.id || "")}"><div class="modal-body"><div class="form-grid"><div class="field wide"><label>To-do Title</label><input name="title" maxlength="120" required value="${escapeHtml(quickValues?.title || item?.title || "")}"></div><div class="field"><label>Deadline</label><input name="deadline" type="date" value="${escapeHtml(quickValues?.deadline || item?.deadline || "")}"></div><div class="field"><label>Stage</label><select name="stageId">${stageOptions}</select></div><div class="field"><label>Tag</label><input name="tag" maxlength="40" placeholder="e.g. Work" value="${escapeHtml(item?.tag || "")}"></div><div class="field"><label>Priority</label><select name="priority">${[0, 1, 2, 3].map((level) => `<option value="${level}" ${Number(item?.priority || 0) === level ? "selected" : ""}>${level ? "★".repeat(level) : "No priority"}</option>`).join("")}</select></div><div class="field wide"><label>Assignees</label><input name="assignees" placeholder="Names separated by commas" value="${escapeHtml(assignees)}"></div><label class="todo-reminder-toggle"><input name="reminder" type="checkbox" ${item?.reminder ? "checked" : ""}> Reminder</label><div class="field wide"><label>Description / Summary</label><textarea name="description" rows="4" maxlength="2000" ${item?.linkedReceiptId ? "readonly" : ""}>${escapeHtml(item?.description || "")}</textarea></div>${sourceNotice}</div></div><footer class="modal-footer">${item ? `<button class="action-button secondary is-danger" type="button" data-todo-action="delete" data-id="${escapeHtml(item.id)}">Delete</button>` : ""}<button class="action-button secondary" type="button" data-action="close-modal">Discard</button><button class="action-button" type="submit">Save</button></footer></form>`, true);
}

function openTodoStageModal(stage) {
  if (!stage) return;
  openModal(`<header class="modal-header"><div><h2>Edit: ${escapeHtml(stage.name)}</h2><p>To-do stage</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form id="todo-stage-form" data-id="${escapeHtml(stage.id)}"><div class="modal-body"><div class="field"><label>Stage Name</label><input name="name" value="${escapeHtml(stage.name)}" required maxlength="50"></div><div class="field"><label>Rotting in</label><div class="todo-rotting-input"><input name="rottingDays" type="number" min="0" step="1" value="${Number(stage.rottingDays || 0)}"><span>days</span></div></div><label class="todo-reminder-toggle"><input name="folded" type="checkbox" ${stage.folded ? "checked" : ""}> Fold by Default</label></div><footer class="modal-footer"><button class="action-button secondary" type="button" data-action="close-modal">Discard</button><button class="action-button" type="submit">Save</button></footer></form>`, true);
}

function createInventoryReceiptTodo(receipt) {
  if (!receipt) return null;
  const lines = (receipt.lines || []).map((line) => `${line.product} ${money(line.qty)} ${line.uom}`).join(", ");
  const summary = [`Vendor: ${receipt.vendor || "—"}`, `Products: ${lines || "No product lines"}`, `Destination: ${receipt.destination || "WH/Stock"}`, `Scheduled: ${receipt.scheduledDate || "Not set"}`, receipt.sourceDocument ? `Source: ${receipt.sourceDocument}` : "", receipt.note ? `Note: ${receipt.note}` : "", `Receipt: ${receipt.ref}`].filter(Boolean).join("\n");
  let task = state.todoItems.find((item) => String(item.linkedReceiptId) === String(receipt.id));
  const oldTask = task ? { ...task, assignees: [...(task.assignees || [])] } : null;
  const record = { ...(task || {}), id: task?.id || `receipt-${receipt.id}`, title: `Receive ${receipt.ref} · ${receipt.vendor || "Supplier"}`, stageId: task?.stageId || "inbox", priority: Number(task?.priority || 0), tag: "Inventory", deadline: String(receipt.scheduledDate || "").slice(0, 10), assignees: receipt.responsible ? [receipt.responsible] : [], description: summary, reminder: true, linkedReceiptId: receipt.id, linkedReceiptRef: receipt.ref, sourceSummary: summary, updatedAt: new Date().toISOString() };
  if (task) Object.assign(task, record); else { task = record; state.todoItems.unshift(task); }
  if (!persistTodoData()) {
    if (oldTask) Object.assign(task, oldTask);
    else state.todoItems = state.todoItems.filter((item) => String(item.id) !== String(record.id));
    return null;
  }
  return task;
}

function handleTodoAction(button) {
  const action = button.dataset.todoAction;
  const id = button.dataset.id;
  const stageId = button.dataset.stageId;
  const task = state.todoItems.find((item) => String(item.id) === String(id));
  const stage = state.todoStages.find((item) => String(item.id) === String(stageId));
  if (action === "quick-open") { state.todoQuickCreateStage = stageId || "inbox"; render(); document.querySelector("#todo-quick-title")?.focus(); return true; }
  if (action === "quick-close") { state.todoQuickCreateStage = null; render(); return true; }
  if (action === "quick-edit") {
    const form = document.querySelector("#todo-quick-form");
    const values = form ? { title: String(new FormData(form).get("title") || ""), deadline: String(new FormData(form).get("deadline") || "") } : null;
    state.todoQuickCreateStage = null; openTodoTaskModal(null, stageId || "inbox", values); return true;
  }
  if (action === "toggle-filter") { state.todoOpenOnly = !state.todoOpenOnly; render(); return true; }
  if (action === "clear-filter") { state.todoOpenOnly = false; render(); return true; }
  if (action === "stage-menu") { state.todoStageMenu = String(state.todoStageMenu) === String(stageId) ? null : stageId; render(); return true; }
  if (action === "fold" && stage) { stage.folded = !stage.folded; state.todoStageMenu = null; persistTodoData(); render(); return true; }
  if (action === "stage-edit" && stage) { state.todoStageMenu = null; openTodoStageModal(stage); return true; }
  if (action === "automation" && stage) {
    state.todoStageMenu = null;
    openModal(`<header class="modal-header"><div><h2>Automations</h2><p>${escapeHtml(stage.name)}</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><div class="modal-body"><p class="modal-help">Stage automations are listed here. This local workspace does not have a connected automation service yet.</p><label class="todo-reminder-toggle"><input type="checkbox" disabled> Create an activity when a to-do enters this stage</label></div><footer class="modal-footer"><button class="action-button" type="button" data-action="close-modal">Close</button></footer>`);
    return true;
  }
  if (action === "stage-delete" && stage) {
    state.todoStageMenu = null;
    if (["inbox", "done", "cancelled"].includes(String(stage.id))) { showToast("Inbox, Done and Cancelled are required stages."); return true; }
    if (!window.confirm(`Delete the ${stage.name} stage? Its to-dos will move to Inbox.`)) return true;
    state.todoItems.forEach((item) => { if (String(item.stageId) === String(stage.id)) item.stageId = "inbox"; });
    state.todoStages = state.todoStages.filter((item) => String(item.id) !== String(stage.id));
    persistTodoData(); render(); return true;
  }
  if (action === "toggle-closed") {
    if (state.todoCollapsedGroups.has(String(stageId))) state.todoCollapsedGroups.delete(String(stageId)); else state.todoCollapsedGroups.add(String(stageId));
    render(); return true;
  }
  if (action === "edit" && task) { openTodoTaskModal(task); return true; }
  if (action === "priority" && task) { task.priority = Number(button.dataset.priority) || 0; persistTodoData(); render(); return true; }
  if (action === "complete" && task) {
    task.stageId = String(task.stageId) === "done" ? "inbox" : "done";
    task.completedAt = String(task.stageId) === "done" ? new Date().toISOString() : "";
    persistTodoData(); render(); return true;
  }
  if (action === "delete" && task) {
    if (task.linkedReceiptId) { showToast("This to-do is linked to an inventory receipt. Delete or cancel it from the receipt first."); return true; }
    if (!window.confirm(`Delete “${task.title}”?`)) return true;
    state.todoItems = state.todoItems.filter((item) => String(item.id) !== String(task.id));
    persistTodoData(); closeModal(); render(); return true;
  }
  if (action === "open-receipt" && task) {
    const receipt = state.purchaseReceipts.find((item) => String(item.id) === String(task.linkedReceiptId));
    if (!receipt) { showToast("The linked receipt could not be found."); return true; }
    closeModal();
    setPage("inventory-receipts");
    state.receiptEditor = { orderId: receipt.orderId || null, id: receipt.id, returnPage: "inventory-receipts" };
    state.receiptTab = "operations"; render(); return true;
  }
  return false;
}

function inventoryLogoMarkup(className = "") {
  return `<svg class="${className}" viewBox="0 0 48 48" role="img" aria-label="Inventory" xmlns="http://www.w3.org/2000/svg"><path d="M24 3 44 14.5 24 26 4 14.5 24 3Z" fill="#FFB51B"/><path d="M4 14.5 24 26v21L4 35.5v-21Z" fill="#F36B32"/><path d="M24 26 44 14.5v21L24 47V26Z" fill="#A74387"/><path d="m24 3 20 11.5-6.1 3.5L18 6.5 24 3Z" fill="#F39A20" opacity=".9"/><path d="m17.7 22.4 6.3 3.6v21l-6.3-3.6v-21Z" fill="#E85736" opacity=".75"/></svg>`;
}

