  const apps = [
    ["Discuss", "Team messages and conversations", "discuss"],
    ["Appointments", "Appointment app · internal screens will be added later", "appointments"],
    ["To-do", "Plan tasks, deadlines and follow-up work", "todo"],
    ["Contacts", "Suppliers, dealers and business contacts", "contacts"],
    ["CRM", "Leads, opportunities, activities and partnerships", "crm"],
    ["Sales", "Wholesale quotations, orders and customers", "sales"],
    ["Dashboards", "Sales and finance analysis", "dashboard"],
    ["Accounting", "Journal entries, ledgers and financial reports", "accounting"],
    ["Invoicing", "Invoices, bills, payments and reporting", "invoice"],
    ["Purchase", "RFQs, purchase orders and suppliers", "purchase"],
    ["Inventory", "Receipts, depot stock, deliveries and product movements", "inventory"],
    ["Settings", "Company, user and business configuration", "settings"],
  ];
