function settingsRouteNotice(title, page) {
  return `<section class="settings-module-landing"><span class="settings-landing-mark">${settingsAppMark(title.toLowerCase().replace("invoicing", "invoice"))}</span><div><p class="settings-eyebrow">APPLICATION CONFIGURATION</p><h1>${escapeHtml(title)} settings</h1><p>Open this application's configuration workspace to review its operational settings.</p><button type="button" class="action-button" data-settings-open-route="${escapeHtml(page)}">Open ${escapeHtml(title)} settings</button></div></section>`;
}

const settingsApplicationItems = [["general", "General Settings", "settings"], ["contacts-settings", "Contacts", "contacts"], ["crm-settings", "CRM", "crm"], ["sales-settings", "Sales", "sales"], ["invoicing", "Invoicing", "invoice"], ["purchase", "Purchase", "purchase"], ["inventory-settings", "Inventory", "inventory"], ["accounting-settings", "Accounting", "accounting"]];

function renderSettingsApplicationSidebar(activeSection) {
  return `<aside class="settings-sidebar" aria-label="Settings applications">${settingsApplicationItems.map(([target, label, mark]) => `<button type="button" class="${(activeSection === target || (target === "general" && ["users", "user-list", "user-form"].includes(activeSection))) ? "is-active" : ""}" data-settings-app="${target}"><span class="settings-app-mark ${mark}">${settingsAppMark(mark)}</span>${label}</button>`).join("")}</aside>`;
}

function renderSettingsToolbar({ saveAction = 'data-action="save-settings"', discardAction = 'data-action="discard-settings"', searchValue = state.settingsSearch, placeholder = "Search...", saveType = "button", form = "" } = {}) {
  return `<section class="settings-toolbar"><div class="settings-toolbar-actions"><button class="action-button" type="${saveType}" ${form ? `form="${form}"` : ""} ${saveAction}>Save</button><button class="action-button secondary" type="button" ${discardAction}>Discard</button><span>Settings</span></div><label class="search-box">${icon("search")}<input id="settings-search" type="search" value="${escapeHtml(searchValue)}" placeholder="${escapeHtml(placeholder)}"></label></section>`;
}

function renderSettingsWorkspace(activeSection, content, toolbarOptions = {}) {
  return `${renderSettingsToolbar(toolbarOptions)}<div class="settings-shell">${renderSettingsApplicationSidebar(activeSection)}<main class="settings-content">${content}</main></div>`;
}

function persistGeneralSettings() {
  try { localStorage.setItem("odooFmcgSettings", JSON.stringify(state.settings)); return true; }
  catch { showToast("This browser could not save settings locally."); return false; }
}

function openCompanyProfileEditor(companyId = null, options = {}) {
  const rows = state.settings.companies || [];
  const company = companyId ? rows.find((row) => String(row.id) === String(companyId)) : null;
  const isNew = Boolean(options.isNew);
  const isActive = !isNew && (!companyId || !rows.length || String(rows[0]?.id) === String(companyId));
  const source = isNew ? {} : isActive ? {
    id: rows[0]?.id || "main-company",
    name: state.settings.companyName || "",
    tagline: state.settings.companyTagline || "",
    email: state.settings.companyEmail || "",
    phone: state.settings.companyPhone || "",
    mobile: state.settings.companyMobile || "",
    street: state.settings.companyStreet || "",
    street2: state.settings.companyStreet2 || "",
    city: state.settings.companyCity || "",
    region: state.settings.companyState || "",
    zip: state.settings.companyZip || "",
    country: state.settings.country || "BD",
    website: state.settings.companyWebsite || "",
    vat: state.settings.companyVat || "",
    registry: state.settings.companyRegistry || "",
    currency: state.settings.currency || "BDT",
    externalCode: state.settings.companyExternalCode || "",
    timezone: state.settings.companyTimezone || state.settings.timezone || "Asia/Dhaka",
    emailDomain: state.settings.companyEmailDomain || "",
    color: state.settings.companyColor || "#875a7b",
    partnerName: state.settings.companyPartnerName || "",
    socialX: state.settings.companySocialX || "",
    socialFacebook: state.settings.companySocialFacebook || "",
    socialGithub: state.settings.companySocialGithub || "",
    socialLinkedin: state.settings.companySocialLinkedin || "",
    socialYoutube: state.settings.companySocialYoutube || "",
    logo: state.settings.companyLogo || "",
  } : { ...(company || {}) };
  const countryCodes = { Bangladesh: "BD", India: "IN", Singapore: "SG", "United States": "US", "United Kingdom": "GB", China: "CN", Pakistan: "PK", Nepal: "NP", "United Arab Emirates": "AE", Belgium: "BE", France: "FR", Germany: "DE", Canada: "CA", Australia: "AU" };
  source.country = countryCodes[source.country] || source.country || "BD";
  state.companyProfileEditor = {
    companyId: isActive ? (rows[0]?.id || "main-company") : (company?.id || null),
    isActive,
    isNew,
    returnSection: options.returnSection || state.settingsSection || "general",
    profile: source,
    tab: options.tab || "general",
  };
  render();
}

function companyProfileFieldMarkup(profile, label, name, placeholder = "", type = "text", required = false) {
  return `<label class="settings-company-record-field"><span>${escapeHtml(label)}${required ? " *" : ""}</span><input name="${escapeHtml(name)}" type="${escapeHtml(type)}" value="${escapeHtml(profile[name] || "")}" placeholder="${escapeHtml(placeholder)}" ${required ? "required" : ""}></label>`;
}

function companyProfileSelectMarkup(profile, label, name, choices) {
  return `<label class="settings-company-record-field"><span>${escapeHtml(label)}</span><select name="${escapeHtml(name)}">${choices.map(([value, text]) => `<option value="${escapeHtml(value)}" ${String(profile[name] || "") === value ? "selected" : ""}>${escapeHtml(text)}</option>`).join("")}</select></label>`;
}

function companyProfileFieldsMarkup(profile, options = {}) {
  const prefix = options.prefix || "";
  const field = (label, name, placeholder = "", type = "text", required = false) => companyProfileFieldMarkup({ ...profile, [`${prefix}${name}`]: profile[name] }, label, `${prefix}${name}`, placeholder, type, required);
  const select = (label, name, choices) => companyProfileSelectMarkup({ ...profile, [`${prefix}${name}`]: profile[name] }, label, `${prefix}${name}`, choices);
  const countries = [["", ""], ["BD", "Bangladesh"], ["IN", "India"], ["PK", "Pakistan"], ["NP", "Nepal"], ["AE", "United Arab Emirates"], ["SG", "Singapore"], ["US", "United States"], ["GB", "United Kingdom"], ["CN", "China"], ["BE", "Belgium"], ["FR", "France"], ["DE", "Germany"], ["CA", "Canada"], ["AU", "Australia"]];
  const currencies = [["BDT", "BDT · Bangladeshi Taka (৳)"], ["USD", "USD · US Dollar ($)"], ["EUR", "EUR · Euro (€)"], ["INR", "INR · Indian Rupee (₹)"], ["SGD", "SGD · Singapore Dollar ($)"], ["AED", "AED · UAE Dirham"], ["GBP", "GBP · Pound Sterling (£)"], ["CAD", "CAD · Canadian Dollar ($)"], ["AUD", "AUD · Australian Dollar ($)"], ["CNY", "CNY · Chinese Yuan (¥)"], ["PKR", "PKR · Pakistani Rupee"], ["NPR", "NPR · Nepalese Rupee"]];
  const timezones = typeof Intl.supportedValuesOf === "function" ? Intl.supportedValuesOf("timeZone") : ["Asia/Dhaka", "Asia/Kolkata", "Asia/Karachi", "Asia/Kathmandu", "Asia/Dubai", "Asia/Singapore", "Asia/Tokyo", "Asia/Shanghai", "Europe/Brussels", "Europe/London", "Europe/Paris", "America/Los_Angeles", "America/Chicago", "America/New_York", "Australia/Sydney", "UTC"];
  const timezoneChoices = [...new Set([profile.timezone, ...timezones].filter(Boolean))].map((zone) => [zone, zone]);
  return `<div class="settings-company-record-fields-layout"><section class="settings-company-record-section"><h2>Address</h2><div class="settings-company-record-grid">${field("Street", "street", "Street...")}${field("Street 2", "street2", "Street 2...")}${field("City", "city", "City")}${field("State", "region", "State")}${field("ZIP", "zip", "ZIP")}${select("Country", "country", countries)}</div><div class="settings-company-record-grid settings-company-record-grid-single">${field("TIN", "vat", "Tax Identification Number")}</div></section><section class="settings-company-record-section"><h2>Contact &amp; Company Details</h2><div class="settings-company-record-grid">${field("Phone", "phone", "+880", "tel")}${field("Mobile", "mobile", "+880", "tel")}${field("Email", "email", "info@company.com", "email")}${field("Website", "website", "https://www.example.com", "url")}${field("Email Domain", "emailDomain", "company.com")}${field("Partner", "partnerName", "Partner contact")}${field("Job Position", "tagline", "Company tagline")}</div><div class="settings-company-color-row"><label class="settings-company-record-field"><span>Color</span><input name="${escapeHtml(prefix)}color" type="color" value="${escapeHtml(profile.color || "#875a7b")}"></label></div></section><section class="settings-company-record-section"><h2>Localization &amp; Registration</h2><div class="settings-company-record-grid">${select("Currency", "currency", currencies)}${field("External Code", "externalCode", "Code used in work entry exports")}${select("Timezone", "timezone", timezoneChoices)}${field("Company Registry", "registry", "Company registration number")}</div></section><section class="settings-company-record-section"><h2>Social Media</h2><div class="settings-company-record-grid">${field("X Account", "socialX", "https://x.com/...")}${field("Facebook Account", "socialFacebook", "https://facebook.com/...")}${field("GitHub Account", "socialGithub", "https://github.com/...")}${field("LinkedIn Account", "socialLinkedin", "https://linkedin.com/company/...")}${field("YouTube Account", "socialYoutube", "https://youtube.com/...")}</div></section></div>`;
}

function openCompanyBranchCreateModal(parentCompanyId) {
  const parent = (state.settings.companies || []).find((company) => String(company.id) === String(parentCompanyId)) || state.companyProfileEditor?.profile;
  if (!parent) { showToast("Save this company before adding a branch."); return; }
  const countryCodeByName = { Bangladesh: "BD", India: "IN", Pakistan: "PK", Nepal: "NP", "United Arab Emirates": "AE", Singapore: "SG", "United States": "US", "United Kingdom": "GB", China: "CN", Belgium: "BE", France: "FR", Germany: "DE", Canada: "CA", Australia: "AU" };
  const blank = { country: parent.countryCode || countryCodeByName[parent.country] || "BD", currency: parent.currency || "BDT", timezone: parent.timezone || "Asia/Dhaka", color: "#875a7b" };
  state.companyBranchEditor = { parentCompanyId, logo: "" };
  const branchLogo = `<span class="settings-logo-placeholder">${escapeHtml(initials(parent.name || "Company"))}</span>`;
  const form = `<header class="modal-header"><div><h2>Create Branches</h2></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="company-branch-form"><input type="hidden" name="parentCompanyId" value="${escapeHtml(parentCompanyId)}"><div class="modal-body settings-company-branch-modal-body"><div class="settings-company-branch-name"><div class="settings-company-record-logo"><div data-company-branch-logo>${branchLogo}</div><label class="text-action" for="company-branch-logo-upload">Change Logo</label><input id="company-branch-logo-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><label class="settings-company-name-field"><span>Company Name</span><input name="name" type="text" placeholder="e.g. My Company" required></label></div><nav class="settings-company-record-tabs" aria-label="Branch sections"><button type="button" class="is-active" data-company-branch-tab="general">General Information</button><button type="button" data-company-branch-tab="branches">Branches</button></nav><div class="settings-company-branch-fields">${companyProfileFieldsMarkup(blank, { prefix: "branch_" })}</div><div class="settings-company-branch-related" hidden><p>Branches created here will be linked to ${escapeHtml(parent.name || "this company")}.</p></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`;
  openModal(form);
}

function renderCompanyProfileSettings() {
  const editor = state.companyProfileEditor;
  const profile = editor?.profile || {};
  const logo = profile.logo
    ? `<img src="${escapeHtml(profile.logo)}" alt="Company logo">`
    : `<span class="settings-logo-placeholder">${escapeHtml(initials(profile.name || "Company"))}</span>`;
  const title = editor?.isNew ? "New Company" : (profile.name || "Company");
  const branches = (state.settings.companies || []).filter((company) => String(company.parentCompanyId || "") === String(editor?.companyId || ""));
  const branchRows = branches.length ? branches.map((branch) => `<tr><td><button type="button" class="text-action" data-edit-company="${escapeHtml(branch.id)}">${escapeHtml(branch.name)}</button></td><td>${escapeHtml(branch.partnerName || "")}</td><td>${escapeHtml(branch.branchLabel || "")}</td></tr>`).join("") : '<tr><td colspan="3" class="settings-company-empty-branches">No branches yet</td></tr>';
  const branchContent = `<section class="settings-company-branches"><table><thead><tr><th>Company Name</th><th>Partner</th><th>Branches</th></tr></thead><tbody>${branchRows}</tbody><tfoot><tr><td colspan="3"><button type="button" class="text-action" data-company-profile-action="new-branch">Add a line</button></td></tr></tfoot></table></section>`;
  const archived = Boolean(profile.archived);
  const headingMenu = `<div class="settings-company-record-menu-wrap"><button type="button" class="settings-company-record-kebab" data-company-profile-action="menu" aria-label="Company actions" aria-expanded="false">⋮</button><div class="settings-company-record-menu" hidden><div class="settings-company-menu-item has-submenu"><button type="button" data-company-record-action="print">▣ &nbsp; Print <span>›</span></button><div class="settings-company-menu-submenu"><button type="button" data-company-record-action="preview-internal">Preview Internal Report</button><button type="button" data-company-record-action="preview-external">Preview External Report</button><button type="button" data-company-record-action="report-layout">Report Layout Preview</button></div></div><button type="button" data-company-record-action="${archived ? "unarchive" : "archive"}">▣ &nbsp; ${archived ? "Unarchive" : "Archive"}</button><button type="button" class="is-danger" data-company-record-action="delete">▣ &nbsp; Delete</button><div class="settings-company-menu-divider"></div><div class="settings-company-menu-item has-submenu"><button type="button" data-company-record-action="marketing">✣ &nbsp; Marketing <span>›</span></button><div class="settings-company-menu-submenu"><button type="button" data-company-record-action="marketing-campaigns">Campaigns</button><button type="button" data-company-record-action="marketing-automation">Marketing Automation</button></div></div><button type="button" data-company-record-action="kiosk">↗ &nbsp; Open Kiosk Url</button></div></div>`;
  return `<div class="settings-page-heading settings-company-record-heading"><div><p class="settings-eyebrow">USERS &amp; COMPANIES / COMPANIES</p><h1>${escapeHtml(title)}</h1><p>Company identity, address, contact details and registration.</p></div><div class="settings-company-record-heading-actions">${editor?.isNew ? "" : headingMenu}<button type="button" class="action-button secondary" data-company-profile-action="back">← ${editor?.returnSection === "users" ? "Users & Companies" : "General Settings"}</button></div></div><form id="company-profile-form" class="settings-company-record-form"><input type="hidden" name="companyId" value="${escapeHtml(editor?.companyId || "")}"><input type="hidden" name="isActive" value="${editor?.isActive ? "1" : "0"}"><section class="settings-company-record-card"><div class="settings-company-record-logo"><div>${logo}</div><label class="text-action" for="company-logo-upload">Change Logo</label><input id="company-logo-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><div class="settings-company-record-main"><label class="settings-company-name-field"><span>Company Name</span><input name="name" type="text" value="${escapeHtml(profile.name || "")}" placeholder="e.g. My Company" required></label><nav class="settings-company-record-tabs" aria-label="Company sections"><button type="button" class="${editor?.tab !== "branches" ? "is-active" : ""}" data-company-profile-tab="general">General Information</button><button type="button" class="${editor?.tab === "branches" ? "is-active" : ""}" data-company-profile-tab="branches">Branches</button></nav><div class="settings-company-profile-panel" ${editor?.tab === "branches" ? "hidden" : ""}>${companyProfileFieldsMarkup(profile)}</div><div class="settings-company-profile-panel" ${editor?.tab !== "branches" ? "hidden" : ""}>${branchContent}</div><footer class="settings-company-record-footer"><span>Company information is shared across documents and connected business modules.</span><div><button type="button" class="action-button secondary" data-company-profile-action="back">Discard</button><button type="submit" class="action-button">Save</button></div></footer></div></section></form>`;
}

function handleSettingsAction(action) {
  if (action === "company-info") {
    openCompanyProfileEditor(null, { returnSection: state.settingsSection });
    return;
  }
  if (action === "new-user") {
    openSettingsUserEditor(null, { isNew: true });
    return;
  }
  if (action === "email-servers") {
    state.settings.customEmailServers = true;
    render();
    const serverField = pageContent.querySelector('[data-setting="outgoingMailServer"]');
    serverField?.scrollIntoView({ block: "center", behavior: "smooth" });
    serverField?.focus({ preventScroll: true });
    return;
  }
  if (action === "document-layout") {
    openModal(`<header class="modal-header"><div><h2>Document Layout</h2><p>Choose the branding shown on quotes, invoices, and orders.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form data-settings-modal-form="Document layout"><div class="modal-body"><div class="form-grid"><div class="field"><label>Document style</label><select data-setting="documentLayout"><option value="clean" ${settingValue("documentLayout") === "clean" ? "selected" : ""}>Clean</option><option value="boxed" ${settingValue("documentLayout") === "boxed" ? "selected" : ""}>Boxed</option><option value="bold" ${settingValue("documentLayout") === "bold" ? "selected" : ""}>Bold</option></select></div><div class="field"><label>Company logo</label><label class="text-action" for="company-logo-upload">Change Logo</label></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`);
    return;
  }
  if (action === "email-templates") {
    openModal(`<header class="modal-header"><div><h2>Email Templates</h2><p>Customize the look and feel of automated emails.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form data-settings-modal-form="Email template colors"><div class="modal-body"><div class="settings-template-colors"><label>Button Text<input type="color" data-setting="emailButtonTextColor" value="${escapeHtml(settingValue("emailButtonTextColor"))}"></label><label>Button Color<input type="color" data-setting="emailButtonColor" value="${escapeHtml(settingValue("emailButtonColor"))}"></label></div><div class="settings-email-button-preview" style="--email-button-text:${escapeHtml(settingValue("emailButtonTextColor"))};--email-button-color:${escapeHtml(settingValue("emailButtonColor"))}">Example button</div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`);
    return;
  }
  if (action === "digest-emails") {
    openModal(`<header class="modal-header"><div><h2>Digest Emails</h2><p>Choose the periodic summary sent to users.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form data-settings-modal-form="Digest emails"><div class="modal-body"><div class="field"><label><input type="checkbox" data-setting="digestEmail" ${settingValue("digestEmail") ? "checked" : ""}> Enable Digest Email</label></div><div class="field"><label>Template</label><select data-setting="digestTemplate"><option ${settingValue("digestTemplate") === "Your Odoo Periodic Digest" ? "selected" : ""}>Your Odoo Periodic Digest</option><option ${settingValue("digestTemplate") === "Sales Summary" ? "selected" : ""}>Sales Summary</option><option ${settingValue("digestTemplate") === "Purchase Summary" ? "selected" : ""}>Purchase Summary</option></select></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`);
    return;
  }
  if (action === "default-access") {
    openModal(`<header class="modal-header"><div><h2>Default Access Rights</h2><p>Choose the access type assigned when inviting a new user.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form data-settings-modal-form="Default access rights"><div class="modal-body"><div class="field"><label>Default user type</label><select data-setting="defaultAccessLevel"><option value="internal" ${settingValue("defaultAccessLevel") === "internal" ? "selected" : ""}>Internal user</option><option value="portal" ${settingValue("defaultAccessLevel") === "portal" ? "selected" : ""}>Portal user</option><option value="public" ${settingValue("defaultAccessLevel") === "public" ? "selected" : ""}>Public user</option></select></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`);
    return;
  }
  if (action === "developer-tools") {
    state.settings.developerMode = true;
    if (!persistGeneralSettings()) return;
    render(); showToast("Developer mode is active in this local workspace."); return;
  }
  if (action === "mapbox-help") {
    openModal(`<header class="modal-header"><div><h2>Mapbox</h2><p>Get a Mapbox token, then enter it in Integrations.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><div class="modal-body"><a class="text-action" href="https://account.mapbox.com/auth/signup/" target="_blank" rel="noopener">→ Sign up to MapBox to get a free token</a></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Close</button></footer>`);
    return;
  }
  if (action === "manage-users") {
    state.settingsSection = "user-list"; state.settingsSearch = ""; render(); return;
  }
  if (["manage-user", "company-info"].includes(action)) {
    state.settingsSection = "users"; state.settingsSearch = ""; render(); return;
  }
  if (action === "add-company") {
    openCompanyProfileEditor(null, { isNew: true, returnSection: "users" });
    return;
  }
  const messages = {
    "activity-types": ["Activity Types", "Add follow-up activity types in the live Discuss workflow."],
    "activity-plans": ["Activity Plans", "Activity plans assign repeatable work sequences in the live Discuss workflow."],
    "activity-roles": ["Activity Roles", "Activity roles are managed with the connected user and activity records."],
    certificates: ["Certificates", "Certificate files and signing actions require a connected Odoo server."],
    keys: ["Keys", "Signing and encryption keys require the connected Odoo security store."],
    "api-keys": ["API Keys", "Create live API keys from the connected user account. This local prototype does not create authentication secrets."],
    "oauth-providers": ["OAuth Providers", "Provider client IDs and callback URLs require the live Odoo database."],
    "barcode-key": ["Barcode API Key", "Enter a valid barcode lookup service key in the Integrations section."],
    "unsplash-help": ["Unsplash Image Library", "Create an Unsplash developer application, then enter its access key and application ID in Integrations."],
    "recaptcha-help": ["reCAPTCHA v3", "Create site and secret keys for your production domain, then enter them in Integrations."],
    "google-places-help": ["Google Places", "Enable Places API and billing for your Google project, then enter its key in Integrations."],
    "phone-providers": ["Phone Providers", "Configure a VoIP provider on the live Odoo server before making calls."],
    iap: ["In-App Purchase Services", "SMS and partner enrichment credits are provided by the live Odoo account."],
    "default-access": ["Default Access Rights", "The selected default role is saved locally. Group permissions need a connected Odoo server."],
    "developer-tools": ["Developer Tools", "Enable Developer Mode to expose technical identifiers in this local workspace."],
    "email-servers": ["Mail Servers", "Enter your SMTP and IMAP host details in the Emails section, then save settings."],
    "document-layout": ["Document Layout", "The selected document style and company logo are saved in General Settings."],
    "email-templates": ["Email Templates", "The button text and button colors are saved in General Settings."],
    whatsapp: ["WhatsApp Business Accounts", "Connect a WhatsApp Business account in the live Odoo database to send or receive messages."],
  };
  const [title, description] = messages[action] || ["Configuration", "Review the settings shown on this page."];
  openModal(`<header class="modal-header"><div><h2>${escapeHtml(title)}</h2><p>${escapeHtml(description)}</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><div class="modal-body"><p class="settings-connection-note">This workspace stores settings in this browser. Live delivery, identity, map, phone, and cloud services require a connected Odoo server and valid provider credentials.</p></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Close</button></footer>`);
}

