  const integrations = `<div class="settings-grid two-col odoo-settings-grid settings-integrations-grid">${oauth}${googleAuth}${barcode}${ldap}${unsplash}${geolocation}${mapbox}${recaptcha}${turnstile}${googlePlaces}${mcp}${phone}</div>`;
  const cloud = `<div class="settings-grid two-col odoo-settings-grid settings-cloud-grid"><div class="settings-odoo-column"><div class="settings-odoo-tool"><strong>Cloud Storage Provider for new attachments</strong><p>Select the cloud storage provider to store new attachments.</p><select data-setting="cloudStorageProvider"><option value="none" ${settingValue("cloudStorageProvider") === "none" ? "selected" : ""}></option><option value="s3" ${settingValue("cloudStorageProvider") === "s3" ? "selected" : ""}>Amazon S3</option><option value="azure" ${settingValue("cloudStorageProvider") === "azure" ? "selected" : ""}>Azure Blob Storage</option><option value="google" ${settingValue("cloudStorageProvider") === "google" ? "selected" : ""}>Google Cloud Storage</option></select><strong class="settings-cloud-min">Minimum File Size</strong><p>Minimum size for attachments to be stored in the cloud storage</p><label class="settings-cloud-size"><input type="number" min="0" step="0.01" data-setting="minimumCloudFileSize" value="${escapeHtml(Number(settingValue("minimumCloudFileSize") || 20).toFixed(2))}"><span>MB</span></label></div></div><div class="settings-odoo-column">${odooSetting("uploadRecordAttachments", "Upload Record Attachments", "Upload record attachments to the cloud storage")}</div></div>`;
  const developer = `<div class="settings-odoo-tool settings-developer-tools"><button type="button" class="text-action" data-settings-action="developer-tools">Activate the developer mode</button><button type="button" class="text-action" data-settings-action="developer-tools">Activate the developer mode (with assets)</button><button type="button" class="text-action" data-settings-action="developer-tools">Activate the developer mode (with tests assets)</button></div>`;
  const section = (title, content, id) => `<section class="settings-section odoo-settings-section" data-settings-block="${id}"><header>${title}</header><div class="settings-section-body odoo-settings-body">${content}</div></section>`;
  return `${section("Users", users, "users")}${section("Languages", languageSection, "languages")}${section("Companies", companySection, "companies")}${section("Units of Measure", units, "uom")}${section("Emails", emails, "emails")}${section("Discuss", discuss, "discuss")}${section("Contacts", contacts, "contacts")}${section("Permissions", permissions, "permissions")}${section("Certificates and Keys", certificates, "certificates")}${section("Integrations", integrations, "integrations")}${section("Cloud Storage", cloud, "cloud")}${section("Developer Tools", developer, "developer")}`;
