function salesCurrency(value) {
  return `${money(value)} ৳`;
}

function inputLocalDate(date = new Date()) {
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return local.toISOString().slice(0, 10);
}

function inputLocalDateTime(date = new Date()) {
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return local.toISOString().slice(0, 16);
}

function formatInventoryStockDateTime(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value || "") : date.toLocaleString("en-US", { year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit", second: "2-digit" });
}

function saleRecords() {
  const query = state.search.trim().toLowerCase();
  let rows = state.salesOrders;
  if (state.page === "sales-quotations") rows = rows.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status));
  if (state.page === "sales-orders") rows = rows.filter((row) => ["Sales Order", "Delivered"].includes(row.status));
  if (state.salesQuickFilter === "To Confirm") rows = rows.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status));
  if (state.salesQuickFilter === "To Deliver") rows = rows.filter((row) => row.status === "Sales Order" && row.deliveryStatus !== "Delivered");
  if (state.salesQuickFilter === "To Invoice") rows = rows.filter((row) => row.status === "Sales Order" && row.invoiceStatus === "To Invoice");
  if (query) rows = rows.filter((row) => [row.ref, row.customer, row.salesperson, row.status, row.invoiceStatus].some((value) => String(value || "").toLowerCase().includes(query)));
  return [...rows].sort((a, b) => b.id - a.id);
}

function salesToolbar(title, options = {}) {
  const showNew = options.newAction !== false;
  const newLabel = options.newLabel || "New";
  const newActionMarkup = showNew ? `<button class="action-button" type="button" ${options.newActionAttribute || 'data-action="new-record"'}>${escapeHtml(newLabel)}</button>` : "";
  const availableViews = options.viewTypes || ["list", "kanban", "calendar", "chart", "activity"];
  const views = options.views === false ? "" : `<div class="view-controls" role="group" aria-label="View type">${availableViews.map((view) => `<button class="view-button ${state.view === view ? "is-active" : ""}" type="button" data-view="${view}" aria-label="${view} view" title="${view}">${icon(view === "activity" ? "clock" : view)}</button>`).join("")}</div>`;
  const pager = options.pager ? `<span class="sales-pager">${options.pager}</span>` : "";
  const searchMarkup = options.searchMarkup || `<label class="search-box sales-search inventory-products-search">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off"></label>`;
  if (options.centerSearch) return `<section class="page-toolbar sales-toolbar inventory-products-toolbar inventory-products-toolbar-centered"><div class="toolbar-title">${newActionMarkup}<span class="page-title">${escapeHtml(title)}</span><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button>${options.toolbarActions || ""}</div>${searchMarkup}<div class="sales-toolbar-end">${pager}${views}</div></section>`;
  if (options.searchBelow) return `<section class="page-toolbar sales-toolbar inventory-products-toolbar"><div class="toolbar-title">${newActionMarkup}<span class="page-title">${escapeHtml(title)}</span><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button>${options.toolbarActions || ""}</div><div class="sales-toolbar-end">${pager}${views}</div></section>${searchMarkup}`;
  return `<section class="page-toolbar sales-toolbar"><div class="toolbar-title">${newActionMarkup}<span class="page-title">${escapeHtml(title)}</span><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button>${options.toolbarActions || ""}</div><label class="search-box sales-search">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off"></label><div class="sales-toolbar-end">${pager}${views}</div></section>`;
}

function salesDashboard() {
  const today = new Date();
  today.setHours(23, 59, 59, 999);
  const start = new Date(today);
  if (state.salesPeriod === "last7") start.setDate(start.getDate() - 6);
  else if (state.salesPeriod === "last30") start.setDate(start.getDate() - 29);
  else if (state.salesPeriod === "month") start.setDate(1);
  else if (state.salesPeriod === "year") start.setMonth(0, 1);
  start.setHours(0, 0, 0, 0);
  const rows = state.salesOrders.filter((row) => {
    if (!row.orderDate) return false;
    const date = new Date(`${row.orderDate}T00:00:00`);
    return date >= start && date <= today;
  });
  const quotes = rows.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status)).length;
  const deliver = rows.filter((row) => row.status === "Sales Order" && row.deliveryStatus !== "Delivered").length;
  const invoice = rows.filter((row) => row.status === "Sales Order" && row.invoiceStatus === "To Invoice").length;
  const revenue = rows.filter((row) => ["Sales Order", "Delivered"].includes(row.status)).reduce((sum, row) => sum + Number(row.total || 0), 0);
  const cards = [[quotes, "To Confirm", "peach"], [deliver, "To Deliver", "lavender"], [invoice, "To Invoice", "aqua"]];
  const periodOptions = [["last7", "Last 7 days"], ["last30", "Last 30 days"], ["month", "This month"], ["year", "This year"]];
  return `<section class="sales-dashboard"><div class="sales-kpis">${cards.map(([value, label, color]) => `<button class="sales-kpi ${color} ${state.salesQuickFilter === label ? "is-active" : ""}" type="button" data-sales-filter="${label}"><strong>${value}</strong><span>${label}</span></button>`).join("")}</div><section class="sales-range-panel"><label>▦ <select aria-label="Sales reporting period" data-sales-period>${periodOptions.map(([value, label]) => `<option value="${value}" ${state.salesPeriod === value ? "selected" : ""}>${label}</option>`).join("")}</select></label><div><strong>Sales Orders</strong><span>${rows.filter((row) => ["Sales Order", "Delivered"].includes(row.status)).length}</span></div><div><strong>Sales Revenue</strong><span>${salesCurrency(revenue)}</span></div></section></section>`;
}

function salesStatusClass(status) {
  return ({ "Quotation": "rfq", "Quotation Sent": "sent", "Sales Order": "purchase", "Delivered": "purchase", "Done": "purchase", "Ready": "sent", "Waiting": "approval", "Draft": "rfq", "Partially Received": "sent", "Partially Delivered": "sent", "Cancelled": "cancelled", "To Invoice": "approval", "Invoice Draft": "approval", "Invoiced": "purchase", "Nothing to Invoice": "cancelled" })[status] || "";
}

function renderSalesOrderList() {
  const rows = saleRecords();
  const quotes = state.page === "sales-quotations";
  const total = rows.reduce((sum, row) => sum + Number(row.total || 0), 0);
  const body = rows.length ? `<tbody>${rows.map((row) => `<tr><td><input type="checkbox" aria-label="Select ${escapeHtml(row.ref)}"></td><td><button class="reference-link" type="button" data-open-sale="${row.id}">${escapeHtml(row.ref)}</button></td><td>${escapeHtml(row.orderDate || "—")}</td><td>${escapeHtml(row.deliveryDate || "—")}</td><td><span class="buyer-chip"><span class="person-avatar teal">${escapeHtml(initials(row.customer))}</span>${escapeHtml(row.customer)}</span></td><td class="money-cell">${salesCurrency(row.total)}</td><td><span class="status-pill ${salesStatusClass(row.status)}">${escapeHtml(row.status)}</span></td><td><span class="status-pill ${salesStatusClass(row.invoiceStatus)}">${escapeHtml(row.invoiceStatus)}</span></td><td><button class="soft-icon-button" type="button" data-action="toast" data-message="No scheduled activity for this document." aria-label="Activities">◷</button></td></tr>`).join("")}</tbody>` : `<tbody><tr><td colspan="9"><div class="empty-state sales-empty"><div class="empty-illustration">${icon("doc")}</div><h2>No ${quotes ? "quotation" : "sales order"} found. Let's create one!</h2><p>Prepare a wholesale quotation for a dealer or depot, then confirm it as a sales order. Set piece, packet, carton, bag, or kilogram quantities per SKU.</p><button class="action-button" type="button" data-action="new-record">Create</button></div></td></tr></tbody>`;
  const activeFilter = state.salesQuickFilter ? `<span class="filter-chip">${escapeHtml(state.salesQuickFilter)} <button type="button" data-action="clear-sales-filter" aria-label="Clear filter">×</button></span>` : "";
  return `${salesToolbar(pageLabels[state.page], { pager: `${rows.length ? `1-${rows.length}` : "0"} / ${rows.length}` })}${quotes ? salesDashboard() : ""}<section class="list-toolbar"><div class="list-toolbar-left">${activeFilter}<span class="results-count">${rows.length} record${rows.length === 1 ? "" : "s"}</span></div><div class="list-toolbar-right"><button class="soft-icon-button" type="button" data-action="filters" title="Filters" aria-label="Filters">${icon("filter")}</button><button class="soft-icon-button" type="button" data-action="configure-columns" title="List settings" aria-label="Configure columns">☷</button></div></section><div class="table-wrap"><table class="data-table sales-order-table"><thead><tr><th><input type="checkbox" aria-label="Select all rows"></th><th>Number</th><th>Order Date</th><th>Promised Delivery</th><th>Customer</th><th class="money-cell">Total</th><th>Status</th><th>Invoice Status</th><th>Activities</th></tr></thead>${body}</table></div>${rows.length ? `<div class="table-total"><span>Total</span><strong>${salesCurrency(total)}</strong></div>` : ""}`;
}

function renderSalesProducts() {
  return `${salesToolbar("Products", { centerSearch: true, views: false })}${renderSharedProductCatalog("sales", "salesProductCategoryFilter", "Sales")}`;
}

function renderSalesCustomers() {
  const rows = searchable(state.salesCustomers, ["name", "phone", "area", "customerCode", "type"]).map((customer) => `<tr><td><span class="buyer-chip"><span class="person-avatar teal">${escapeHtml(initials(customer.name))}</span><strong>${escapeHtml(customer.name)}</strong></span><small class="sales-secondary">${escapeHtml(customer.customerCode || "")}</small></td><td>${escapeHtml(customer.phone || "—")}</td><td>${escapeHtml(customer.area || "—")}</td><td>${escapeHtml(customer.type || "Dealer")}</td><td class="money-cell">${salesCurrency(customer.creditLimit || 0)}</td><td><span class="status-pill purchase">Active</span></td></tr>`);
  return `${salesToolbar("Customers")}<div class="sales-section-note"><strong>Dealer & depot accounts</strong><span>Capture delivery area and agreed credit limit per customer; keep cash / credit terms on each quotation.</span></div>${simpleTable(["Customer", "Phone", "Area", "Channel", "Credit Limit · BDT", "Status"], rows, "No customers yet. Add a dealer or depot account to start a quotation.")}`;
}

function salesReportPanel(title, subtitle, metrics) {
  return `<article class="report-panel"><h2>${escapeHtml(title)}</h2><p>${escapeHtml(subtitle)}</p><div class="sales-metric-list">${metrics.map(([label, value]) => `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("") || `<div class="sales-report-empty">Sales activity will appear after orders are confirmed.</div>`}</div></article>`;
}

function renderSalesReport() {
  const orders = state.salesOrders.filter((row) => ["Sales Order", "Delivered"].includes(row.status));
  const revenue = orders.reduce((sum, row) => sum + Number(row.total || 0), 0);
  if (state.page === "salespersons-report") {
    const grouped = new Map();
    orders.forEach((row) => { const person = row.salesperson || "Unassigned"; const item = grouped.get(person) || { count: 0, total: 0 }; item.count += 1; item.total += Number(row.total || 0); grouped.set(person, item); });
    return `${salesToolbar("Salespersons", { newAction: false, views: false })}<section class="report-page"><div class="report-grid">${salesReportPanel("Sales by salesperson", "Confirmed wholesale orders grouped by assigned salesperson.", [...grouped].map(([name, value]) => [name, `${value.count} orders · ${salesCurrency(value.total)}`]))}${salesReportPanel("Sales team coverage", "Assign dealers and depot territories to your sales team.", [])}</div></section>`;
  }
  if (state.page === "sales-products-report") {
    const groupedProducts = new Map();
    const groupedCategories = new Map();
    orders.flatMap((row) => row.lines || []).forEach((line) => {
      const product = salesProducts.find((item) => String(item.sku || "") === String(line.sku || "") || item.name === line.product);
      const category = product?.category || "Uncategorized";
      const productName = line.product || product?.name || "Unknown product";
      const productItem = groupedProducts.get(productName) || { qty: 0, total: 0, uom: line.uom };
      productItem.qty += Number(line.qty || 0);
      productItem.total += Number(line.subtotal || 0);
      groupedProducts.set(productName, productItem);
      const categoryItem = groupedCategories.get(category) || { lines: 0, total: 0 };
      categoryItem.lines += 1;
      categoryItem.total += Number(line.subtotal || 0);
      groupedCategories.set(category, categoryItem);
    });
    return `${salesToolbar("Sales by Product", { newAction: false, views: false })}<section class="report-page"><div class="report-grid">${salesReportPanel("Product movement", "Confirmed quantity and sales value. Quantities remain in the selected invoice unit.", [...groupedProducts].map(([name, value]) => [name, `${value.qty} ${value.uom} · ${salesCurrency(value.total)}`]))}${salesReportPanel("Category performance", "Confirmed sales lines grouped by the category assigned to each product.", [...groupedCategories].sort(([a], [b]) => a.localeCompare(b)).map(([name, value]) => [name, `${value.lines} product lines · ${salesCurrency(value.total)}`]))}</div></section>`;
  }
  if (state.page === "sales-customers-report") {
    const grouped = new Map();
    orders.forEach((row) => { const item = grouped.get(row.customer) || { count: 0, total: 0 }; item.count += 1; item.total += Number(row.total || 0); grouped.set(row.customer, item); });
    return `${salesToolbar("Sales by Customer", { newAction: false, views: false })}<section class="report-page">${salesReportPanel("Dealer & depot sales", "Compare confirmed order count and sales value by customer.", [...grouped].map(([name, value]) => [name, `${value.count} orders · ${salesCurrency(value.total)}`]))}</section>`;
  }
  return `${salesToolbar("Sales Analysis", { newAction: false, views: false })}<section class="report-page"><div class="report-kpis"><div class="report-kpi"><span>Confirmed Sales</span><strong>${orders.length}</strong></div><div class="report-kpi"><span>Sales Revenue</span><strong>${salesCurrency(revenue)}</strong></div><div class="report-kpi"><span>Average Order</span><strong>${salesCurrency(orders.length ? revenue / orders.length : 0)}</strong></div><div class="report-kpi"><span>To Invoice</span><strong>${orders.filter((row) => row.invoiceStatus === "To Invoice").length}</strong></div></div><div class="report-grid">${salesReportPanel("Order status", "Wholesale orders in this workspace.", [["Quotations", String(state.salesOrders.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status)).length)], ["Confirmed", String(orders.length)], ["Delivered", String(orders.filter((row) => row.deliveryStatus === "Delivered").length)]])}${salesReportPanel("Sales by product", "Open Reporting → Products to review quantity and value by SKU.", [])}</div><p class="sales-disclaimer">This workspace records invoice quantities and BDT prices. VAT and tax are governed by the Accounting product/tax configuration.</p></section>`;
}

function renderSalesSettingsContent() {
  const value = (key, fallback) => Object.prototype.hasOwnProperty.call(state.salesSettings, key) ? state.salesSettings[key] : fallback;
  const input = (key, title, description, fallback, attrs = "") => `<div class="odoo-setting sales-setting-field" data-setting-row><label for="sales-setting-${key}">${escapeHtml(title)}</label><p>${escapeHtml(description)}</p><input id="sales-setting-${key}" name="${key}" type="number" min="1" max="365" step="1" required value="${escapeHtml(value(key, fallback))}" data-sales-setting="${key}" ${attrs}></div>`;
  const textInput = (key, title, description, fallback, attrs = "") => `<div class="odoo-setting sales-setting-field" data-setting-row><label for="sales-setting-${key}">${escapeHtml(title)}</label><p>${escapeHtml(description)}</p><input id="sales-setting-${key}" name="${key}" type="text" value="${escapeHtml(value(key, fallback))}" data-sales-setting="${key}" ${attrs}></div>`;
  const select = (key, title, description, fallback, options) => `<div class="odoo-setting sales-setting-field" data-setting-row><label for="sales-setting-${key}">${escapeHtml(title)}</label><p>${escapeHtml(description)}</p><select id="sales-setting-${key}" name="${key}" data-sales-setting="${key}">${options.map(([option, caption]) => `<option value="${escapeHtml(option)}" ${String(value(key, fallback)) === option ? "selected" : ""}>${escapeHtml(caption)}</option>`).join("")}</select></div>`;
  const toggle = (key, title, description, fallback) => `<div class="odoo-setting" data-setting-row><label><input type="checkbox" name="${key}" data-sales-setting="${key}" ${value(key, fallback) === true ? "checked" : ""}><span>${escapeHtml(title)}</span></label><p>${escapeHtml(description)}</p></div>`;
  const sharedConfig = (title, description, links) => `<div class="settings-odoo-tool sales-settings-shared" data-setting-row><strong>${escapeHtml(title)}</strong><p>${escapeHtml(description)}</p>${links.map(([page, label]) => `<button type="button" class="text-action" data-module-page="${page}">→ ${escapeHtml(label)}</button>`).join("")}</div>`;
  const section = (id, title, left, right) => `<section class="settings-section odoo-settings-section sales-odoo-settings-section" data-settings-block="${id}"><header>${title}</header><div class="settings-section-body odoo-settings-body"><div class="settings-grid two-col odoo-settings-grid"><div class="settings-odoo-column">${left}</div><div class="settings-odoo-column">${right}</div></div></div></section>`;
  const paymentTerms = purchasePaymentTermOptions([String(value("defaultPaymentTerms", "Due on receipt"))]);
  const inventoryEnabled = (key, fallback = true) => (state.inventoryConfig || {})[key] !== undefined ? (state.inventoryConfig || {})[key] !== false : fallback;
  const variantStatus = inventoryEnabled("productVariants") ? "Enabled" : "Disabled";
  const unitStatus = inventoryEnabled("unitsOfMeasure") ? "Enabled" : "Disabled";
  const deliveryStatus = inventoryEnabled("deliveryMethods") ? "Enabled" : "Disabled";
  const productCatalog = section("sales-product-catalog", "Product Catalog",
    sharedConfig("Variants", `Product variants are ${variantStatus.toLowerCase()} in Inventory. Keep attributes and SKU variants on the shared product master.`, [["inventory-attributes", "Configure product attributes"], ["inventory-products", "Open Inventory Products"]]),
    sharedConfig("Units of Measure & Packagings", `Shared purchase and sales units are ${unitStatus.toLowerCase()} in Inventory. SKU-level pack conversions remain canonical there.`, [["inventory-units", "Configure Units & Packagings"]]));
  const pricing = section("sales-pricing", "Pricing",
    toggle("lineDiscountsEnabled", "Order line discounts", "Allow approved percentage discounts on dealer and depot order lines. Existing saved discounts remain visible.", true),
    sharedConfig("Product prices & tax", "Sales uses the same SKU price, sales tax, unit and category configured for Inventory, Purchase and Invoicing.", [["sales-products", "Open shared Products"], ["invoice-taxes", "Review tax configuration"]]));
  const orderDefaults = section("sales-quotations-orders", "Quotations & Orders",
    `${input("quotationValidity", "Quotation Validity", "Default period a dealer quotation remains valid; adjust a specific quotation when needed.", 7)}${select("defaultPaymentTerms", "Default Payment Terms", "Applied to new dealer quotations unless the Contact has its own terms.", "Due on receipt", paymentTerms.map((term) => [term, term]))}${textInput("defaultSalesperson", "Default Salesperson", "Leave blank to use the current user.", "", 'maxlength="120" placeholder="Use current user"')}`,
    `${select("defaultDeliveryPolicy", "Default Delivery Policy", "Choose whether available products can ship before the full order is ready.", "partial", [["partial", "As soon as possible"], ["all", "Deliver all products at once"]])}${toggle("requireProductBeforeConfirmation", "Mandatory Product", "Prevent sending or confirming a sales order without at least one product line.", true)}${toggle("lockConfirmedSales", "Lock Confirmed Sales", "Make a sales order read-only after confirmation.", false)}${toggle("showLineNumbers", "Line Numbers", "Show line numbers on product, section and note rows.", false)}${toggle("productImagesOnQuotation", "Product Images", "Include the shared Inventory product image on quotation previews and printouts.", false)}`);
  const invoicing = section("sales-invoicing", "Invoicing",
    select("invoicePolicy", "Invoicing Policy", "Default quantity basis for new products. Existing products keep the policy saved on their shared product record.", "Ordered quantities", [["Ordered quantities", "Ordered quantities"], ["Delivered quantities", "Delivered quantities"]]),
    sharedConfig("Customer invoices & VAT", "Confirmed sales orders flow into Invoicing. Receivables, VAT rates and fiscal rules stay managed in the shared Accounting configuration.", [["invoice-settings", "Open Invoicing settings"], ["invoice-taxes", "Configure taxes"]]));
  const logistics = section("sales-delivery", "Delivery",
    sharedConfig("Delivery Methods", `Delivery methods are ${deliveryStatus.toLowerCase()} in Inventory. Configure the shared method and charges once for Sales and stock operations.`, [["inventory-delivery-methods", "Configure Delivery Methods"]]),
    sharedConfig("Depot delivery policy", "Sales delivery policy defaults are set above. Warehouses, receipts and stock movements are managed by the shared Inventory workflow.", [["inventory-settings", "Open Inventory Settings"]]));
  const crmHandoff = section("sales-crm", "CRM & Lead Handoff",
    sharedConfig("Leads & Opportunities", "Lead qualification, scoring, enrichment and assignment are configured once in CRM and shared with the Sales workflow.", [["crm-settings", "Open CRM Settings"], ["crm-pipeline", "Open CRM Pipeline"]]),
    sharedConfig("Sales team assignment", "Manage CRM sales teams and assignment rules from the CRM source configuration.", [["crm-sales-teams", "Configure CRM Sales Teams"]]));
  return `<form id="sales-settings-form" class="sales-odoo-settings-form">${productCatalog}${pricing}${orderDefaults}${crmHandoff}${invoicing}${logistics}</form>`;
}

function renderSalesSettings() {
  return renderSettingsWorkspace("sales-settings", renderSalesSettingsContent(), { saveAction: 'data-sales-settings-action="save"', discardAction: 'data-sales-settings-action="discard"' });
}

function renderSalesConfig() {
  const content = {
    "sales-teams": ["Sales Teams", "Group salespeople by depot, region, or trade channel.", "Team", "Add a team"],
    "sales-payments": ["Payment Methods", "Record cash, bank transfer, or other approved settlement methods on sales documents.", "Method", "Add a payment method"],
    "sales-templates": ["Quotation Templates", "Reuse a checked quotation structure for repeat dealer orders.", "Template", "Create a template"],
    "sales-headers-footers": ["Headers / Footers", "Set the company details and standard note printed on quotations and sales documents.", "Document block", "Configure document layout"],
  }[state.page];
  if (state.page === "sales-headers-footers") {
    const layout = state.invoiceLayout;
    return `${salesToolbar("Headers / Footers", { newAction: false, views: false })}<section class="sales-settings-page"><div class="settings-page-heading"><div><p class="settings-eyebrow">SHARED DOCUMENT LAYOUT</p><h1>Quotation & invoice header</h1><p>These company details are shared by Sales quotations and Invoicing documents.</p></div><span class="region-status"><i></i> Sales ↔ Invoicing</span></div>${renderInvoiceLayoutForm(true)}</section>`;
  }
  const stored = state.salesConfig[state.page] || [];
  const rows = stored.map((name) => `<tr><td>${escapeHtml(name)}</td><td><span class="status-pill purchase">Active</span></td></tr>`);
  return `${salesToolbar(pageLabels[state.page])}<div class="sales-section-note"><strong>${escapeHtml(content[0])}</strong><span>${escapeHtml(content[1])}</span></div><section class="sales-config-area">${rows.length ? simpleTable([content[2], "Status"], rows, "") : `<div class="empty-state"><h2>${escapeHtml(content[0])}</h2><p>${escapeHtml(content[1])}</p><button class="action-button" type="button" data-action="new-record">${escapeHtml(content[3])}</button></div>`}</section>`;
}

function renderActivitiesPage() {
  const headers = ["Activity Type", "Assigned to", "Role", "Requested By", "Requested On", "Due Date", "Done Date", "Feedback", "Model", ...state.activityCustomFields.map((field) => field.name)];
  return `${salesToolbar("Activities", { newAction: false, pager: "0 / 0", views: false })}<section class="list-toolbar"><div class="list-toolbar-left"><span class="results-count">0 activities</span></div><div class="list-toolbar-right"><div class="view-controls" role="group" aria-label="Activity view">${[["list", "list"], ["kanban", "kanban"], ["calendar", "calendar"], ["pivot", "pivot"], ["chart", "chart"]].map(([view, glyph]) => `<button class="view-button ${state.view === view ? "is-active" : ""}" type="button" data-view="${view}" aria-label="${view} view">${icon(glyph)}</button>`).join("")}</div><button class="soft-icon-button" type="button" data-action="configure-columns" title="List settings" aria-label="Configure columns">☷</button></div></section><div class="table-wrap"><table class="data-table activities-table"><thead><tr><th><input type="checkbox" aria-label="Select all activities"></th>${headers.map((header) => `<th class="${header === "Due Date" ? "sorted-column" : ""}">${escapeHtml(header)}</th>`).join("")}</tr></thead><tbody><tr><td colspan="${headers.length + 1}"><div class="empty-state activities-list-empty"><div class="activities-empty-icon">✓</div><h2>Congratulations, you're done with your activities.</h2><p>Scheduled follow-ups from orders and invoices will appear here.</p></div></td></tr></tbody></table></div>`;
}

function renderSalesPage() {
  if (state.salesEditor) return renderSalesDocumentForm();
  if (state.salesProductEditor) return renderSalesProductForm();
  if (["sales-quotations", "sales-orders"].includes(state.page)) return renderSalesOrderList();
  if (state.page === "sales-products") return renderSalesProducts();
  if (state.page === "sales-customers") return renderSalesCustomers();
  if (["sales-report", "salespersons-report", "sales-products-report", "sales-customers-report"].includes(state.page)) return renderSalesReport();
  if (state.page === "sales-settings") return renderSalesSettings();
  return renderSalesConfig();
}

function dashboardDateRange() {
  const days = Number(state.dashboardPeriod) || 90;
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  end.setDate(end.getDate() + state.dashboardOffset * days);
  const start = new Date(end);
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - days + 1);
  const priorEnd = new Date(start.getTime() - 1);
  const priorStart = new Date(priorEnd);
  priorStart.setDate(priorStart.getDate() - days + 1);
  return { start, end, priorStart, priorEnd, days };
}

function dashboardDateInRange(value, start, end) {
  if (!value) return false;
  const date = new Date(`${value}T00:00:00`);
  return !Number.isNaN(date.valueOf()) && date >= start && date <= end;
}

function dashboardPeriods() {
  const { start, end, priorStart, priorEnd } = dashboardDateRange();
  return {
    currentSales: state.salesOrders.filter((row) => dashboardDateInRange(row.orderDate, start, end)),
    priorSales: state.salesOrders.filter((row) => dashboardDateInRange(row.orderDate, priorStart, priorEnd)),
    currentInvoices: state.invoices.filter((row) => dashboardDateInRange(row.invoiceDate, start, end)),
    priorInvoices: state.invoices.filter((row) => dashboardDateInRange(row.invoiceDate, priorStart, priorEnd)),
  };
}

function dashboardConfirmedSales(rows) {
  return rows.filter((row) => ["Sales Order", "Delivered"].includes(row.status));
}

function dashboardTrend(current, previous) {
  if (!previous && !current) return "No activity in this period";
  if (!previous) return "New activity in this period";
  const change = ((current - previous) / Math.abs(previous)) * 100;
  const arrow = change > 0 ? "↑" : change < 0 ? "↓" : "→";
  return `${arrow} ${Math.abs(change).toFixed(1)}% vs previous period`;
}

function dashboardKpi(title, value, subtitle, tone = "teal") {
  return `<article class="dashboard-kpi ${tone}"><header>${escapeHtml(title)}</header><strong>${escapeHtml(value)}</strong><span>${escapeHtml(subtitle)}</span></article>`;
}

function dashboardMonthBuckets(rows, dateField, amountField) {
  const { start, end } = dashboardDateRange();
  const buckets = new Map();
  const cursor = new Date(start.getFullYear(), start.getMonth(), 1);
  const lastMonth = new Date(end.getFullYear(), end.getMonth(), 1);
  while (cursor <= lastMonth) {
    const key = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`;
    buckets.set(key, 0);
    cursor.setMonth(cursor.getMonth() + 1);
  }
  rows.forEach((row) => {
    const date = row[dateField];
    if (!dashboardDateInRange(date, start, end)) return;
    const key = String(date).slice(0, 7);
    buckets.set(key, (buckets.get(key) || 0) + Number(row[amountField] || 0));
  });
  return [...buckets].map(([key, value]) => ({ label: new Date(`${key}-01T00:00:00`).toLocaleDateString("en-US", { month: "short", year: "2-digit" }), value }));
}

function dashboardLineChart(title, points, emptyMessage = "No recorded activity in this period") {
  const width = 900;
  const height = 300;
  const left = 64;
  const right = 24;
  const top = 20;
  const bottom = 48;
  const chartWidth = width - left - right;
  const chartHeight = height - top - bottom;
  const max = Math.max(1, ...points.map((point) => Number(point.value || 0)));
  const linePoints = points.map((point, index) => {
    const x = left + (points.length < 2 ? chartWidth / 2 : index * chartWidth / (points.length - 1));
    const y = top + chartHeight - (Number(point.value || 0) / max) * chartHeight;
    return { ...point, x, y };
  });
  const grids = Array.from({ length: 5 }, (_, index) => {
    const y = top + index * chartHeight / 4;
    const value = max * (1 - index / 4);
    return `<g><line x1="${left}" y1="${y}" x2="${width - right}" y2="${y}"/><text x="${left - 10}" y="${y + 4}" text-anchor="end">${salesCurrency(value).replace(/\.00/, "")}</text></g>`;
  }).join("");
  const path = linePoints.map((point, index) => `${index ? "L" : "M"}${point.x},${point.y}`).join(" ");
  const area = linePoints.length > 1 ? `${path} L${linePoints[linePoints.length - 1].x},${top + chartHeight} L${linePoints[0].x},${top + chartHeight} Z` : "";
  const labels = linePoints.map((point) => `<text x="${point.x}" y="${height - 17}" text-anchor="middle">${escapeHtml(point.label)}</text>`).join("");
  const series = points.some((point) => point.value > 0)
    ? `<path class="dashboard-chart-area" d="${area}"/><path class="dashboard-chart-line" d="${path}"/>${linePoints.map((point) => `<circle class="dashboard-chart-point" cx="${point.x}" cy="${point.y}" r="4"><title>${escapeHtml(point.label)}: ${salesCurrency(point.value)}</title></circle>`).join("")}`
    : `<text class="dashboard-chart-empty-text" x="${left + chartWidth / 2}" y="${top + chartHeight / 2}" text-anchor="middle">${escapeHtml(emptyMessage)}</text>`;
  return `<article class="dashboard-chart-card"><header><h2>${escapeHtml(title)}</h2><button type="button" data-action="dashboard-expand-chart" aria-label="Expand chart">⛶</button></header><div class="dashboard-chart-plot"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(title)} chart">${grids}<text class="dashboard-y-label" transform="translate(17 ${top + chartHeight / 2}) rotate(-90)" text-anchor="middle">Revenue · BDT</text>${series}${labels}</svg></div></article>`;
}

function dashboardProducts(currentSales) {
  const aggregate = new Map();
  dashboardConfirmedSales(currentSales).forEach((order) => (order.lines || []).forEach((line) => {
    if (line.type && line.type !== "product") return;
    const name = line.product || line.description || "Product";
    const current = aggregate.get(name) || { name, sku: line.sku || "", quantity: 0, revenue: 0 };
    current.quantity += Number(line.qty || 0) * Number(line.stockFactor || 1);
    current.revenue += Number(line.amount ?? line.subtotal ?? (Number(line.qty || 0) * Number(line.price || 0)));
    aggregate.set(name, current);
  }));
  return [...aggregate.values()].sort((a, b) => b.revenue - a.revenue);
}

function dashboardDateTitle() {
  const { start, end } = dashboardDateRange();
  const fmt = (date) => date.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
  return `${fmt(start)} – ${fmt(end)}`;
}

function dashboardToolbar() {
  const period = Number(state.dashboardPeriod) || 90;
  return `<section class="dashboard-toolbar"><div class="dashboard-toolbar-title"><h1>Dashboards</h1><span>${escapeHtml(dashboardDateTitle())}</span></div><label class="search-box dashboard-search">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off"><span class="dashboard-search-caret">▾</span></label><div class="dashboard-date-controls"><label class="dashboard-period-select"><span aria-hidden="true">▦</span><select aria-label="Dashboard date range" data-dashboard-period><option value="30" ${period === 30 ? "selected" : ""}>Last 30 Days</option><option value="90" ${period === 90 ? "selected" : ""}>Last 90 Days</option></select></label><button type="button" class="dashboard-arrow-button" data-action="dashboard-previous" aria-label="Previous date range">‹</button><button type="button" class="dashboard-arrow-button" data-action="dashboard-next" aria-label="Next date range" ${state.dashboardOffset >= 0 ? "disabled" : ""}>›</button></div><div class="dashboard-header-actions"><button type="button" data-action="dashboard-share">${icon("share")} Share</button><button type="button" class="dashboard-favorite ${state.dashboardFavorites.has(state.dashboardActive) ? "is-active" : ""}" data-action="dashboard-favorite" aria-label="Toggle favorite">★</button></div></section>`;
}

function dashboardSectionNav() {
  const query = state.search.trim().toLowerCase();
  return `<aside class="dashboard-sidebar ${state.dashboardSidebarCollapsed ? "is-collapsed" : ""}"><button class="dashboard-sidebar-collapse" type="button" data-action="toggle-dashboard-sidebar" aria-label="${state.dashboardSidebarCollapsed ? "Expand" : "Collapse"} dashboard sidebar">${state.dashboardSidebarCollapsed ? "›" : "◧"}</button>${state.dashboardSidebarCollapsed ? "" : state.dashboardSections.map((section) => {
    const records = state.dashboardRecords.filter((item) => item.published && item.section === section && (!query || item.name.toLowerCase().includes(query)));
    if (!records.length) return "";
    const collapsed = state.dashboardCollapsedSections.has(section);
    return `<section><h2><button type="button" data-action="toggle-dashboard-section" data-section="${escapeHtml(section)}" aria-expanded="${!collapsed}">${escapeHtml(section)}</button></h2>${collapsed ? "" : records.map((item) => `<button type="button" class="dashboard-side-link ${item.type === state.dashboardActive ? "is-active" : ""}" data-dashboard-type="${escapeHtml(item.type)}">${escapeHtml(item.name)}</button>`).join("")}</section>`;
  }).join("")}${!state.dashboardRecords.some((item) => item.published && (!query || item.name.toLowerCase().includes(query))) ? `<p class="dashboard-nav-empty">No published dashboards</p>` : ""}</aside>`;
}

function renderDashboardSales(currentSales, priorSales) {
  const confirmed = dashboardConfirmedSales(currentSales);
  const priorConfirmed = dashboardConfirmedSales(priorSales);
  const revenue = confirmed.reduce((sum, row) => sum + Number(row.total || 0), 0);
  const priorRevenue = priorConfirmed.reduce((sum, row) => sum + Number(row.total || 0), 0);
  const avg = confirmed.length ? revenue / confirmed.length : 0;
  const priorAvg = priorConfirmed.length ? priorRevenue / priorConfirmed.length : 0;
  const quotes = currentSales.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status)).length;
  const priorQuotes = priorSales.filter((row) => ["Quotation", "Quotation Sent"].includes(row.status)).length;
  const points = dashboardMonthBuckets(confirmed, "orderDate", "total");
  return `<div class="dashboard-kpi-grid">${dashboardKpi("Quotations", String(quotes), dashboardTrend(quotes, priorQuotes), "amber")}${dashboardKpi("Orders", String(confirmed.length), dashboardTrend(confirmed.length, priorConfirmed.length), "violet")}${dashboardKpi("Revenue", salesCurrency(revenue), dashboardTrend(revenue, priorRevenue), revenue < priorRevenue ? "red" : "teal")}${dashboardKpi("Average Order", salesCurrency(avg), dashboardTrend(avg, priorAvg), "blue")}</div>${dashboardLineChart("Monthly Sales", points)}`;
}

function renderDashboardProduct(currentSales) {
  const productsByRevenue = dashboardProducts(currentSales);
  const best = [...productsByRevenue].sort((a, b) => b.quantity - a.quantity)[0];
  const categorySales = new Map();
  productsByRevenue.forEach((product) => {
    const info = salesProducts.find((item) => item.name === product.name || item.sku === product.sku);
    const category = info?.category || "Other FMCG";
    categorySales.set(category, (categorySales.get(category) || 0) + product.revenue);
  });
  const bestCategory = [...categorySales].sort((a, b) => b[1] - a[1])[0];
  const units = productsByRevenue.reduce((sum, product) => sum + product.quantity, 0);
  const top = productsByRevenue.slice(0, 7);
  const maximum = Math.max(1, ...top.map((item) => item.revenue));
  const chart = `<article class="dashboard-chart-card dashboard-product-chart"><header><h2>Best Sellers by Revenue</h2><button type="button" data-action="dashboard-expand-chart" aria-label="Expand chart">⛶</button></header>${top.length ? `<div class="dashboard-bar-list">${top.map((item) => `<div class="dashboard-bar-row"><span title="${escapeHtml(item.name)}">${escapeHtml(item.name)}</span><div><i style="width:${Math.max(3, item.revenue / maximum * 100)}%"></i></div><strong>${salesCurrency(item.revenue)}</strong></div>`).join("")}</div>` : `<div class="dashboard-empty-chart">No confirmed product sales in this period.</div>`}</article>`;
  return `<div class="dashboard-kpi-grid dashboard-product-kpis">${dashboardKpi("Best Seller", best?.name || "—", best ? `${best.quantity.toLocaleString("en-BD")} stock units sold` : "No recorded product sales", "teal")}${dashboardKpi("Best Category", bestCategory?.[0] || "—", bestCategory ? salesCurrency(bestCategory[1]) : "No category sales recorded", "violet")}${dashboardKpi("Units Sold", units.toLocaleString("en-BD", { maximumFractionDigits: 3 }), "Normalized to each product's stock unit", "blue")}${dashboardKpi("Product Revenue", salesCurrency(top.reduce((sum, item) => sum + item.revenue, 0)), "Confirmed sales orders", "amber")}</div>${chart}`;
}

function renderDashboardInvoicing(currentInvoices, priorInvoices) {
  const issued = currentInvoices.filter((invoice) => invoice.kind === "out_invoice" && !["Cancelled", "Reversed"].includes(invoice.status));
  const priorIssued = priorInvoices.filter((invoice) => invoice.kind === "out_invoice" && !["Cancelled", "Reversed"].includes(invoice.status));
  const value = issued.reduce((sum, invoice) => sum + Number(invoice.total || 0), 0);
  const priorValue = priorIssued.reduce((sum, invoice) => sum + Number(invoice.total || 0), 0);
  const open = state.invoices.filter((invoice) => invoice.kind === "out_invoice" && ["Posted", "Partial", "Overdue"].includes(invoiceDisplayStatus(invoice))).reduce((sum, invoice) => sum + Number(invoice.amountDue || 0), 0);
  const dailySales = value / Math.max(1, Number(state.dashboardPeriod));
  const dso = dailySales ? `${Math.round(open / dailySales)} days` : "—";
  const average = issued.length ? value / issued.length : 0;
  const priorAverage = priorIssued.length ? priorValue / priorIssued.length : 0;
  const points = dashboardMonthBuckets(issued, "invoiceDate", "total");
  return `<div class="dashboard-kpi-grid dashboard-invoice-kpis">${dashboardKpi("Invoiced", salesCurrency(value), dashboardTrend(value, priorValue), "teal")}${dashboardKpi("Average Invoice", salesCurrency(average), dashboardTrend(average, priorAverage), "blue")}${dashboardKpi("DSO", dso, open ? `${salesCurrency(open)} outstanding` : "No open customer balance", "violet")}</div>${dashboardLineChart("Invoiced by Month", points, "No customer invoices in this period")}`;
}

function renderDashboardInventoryStock() {
  const products = salesProducts.filter((product) => !product.archived).map((product) => ({ product, onHand: inventoryStockHistoricalQty(product, state.inventoryStockReportDate), incoming: inventoryIncoming(product), outgoing: inventoryOutgoing(product) }));
  const totalOnHand = products.reduce((sum, row) => sum + row.onHand, 0);
  const totalIncoming = products.reduce((sum, row) => sum + row.incoming, 0);
  const totalValue = products.reduce((sum, row) => sum + row.onHand * Number(row.product.cost || 0), 0);
  const lowStock = products.filter(({ product, onHand, incoming, outgoing }) => { const rule = state.inventoryRules.find((item) => item.sku === product.sku); return rule && Number(rule.min || 0) > 0 && Math.max(0, onHand + incoming - outgoing) <= Number(rule.min || 0); }).length;
  const rows = [...products].sort((a, b) => b.onHand - a.onHand || a.product.name.localeCompare(b.product.name)).slice(0, 10);
  const body = rows.length ? rows.map(({ product, onHand, incoming, outgoing }) => `<tr><td>${escapeHtml(product.name)}</td><td>${escapeHtml(product.sku || "—")}</td><td>${escapeHtml(product.category || "—")}</td><td>${money(onHand)}</td><td>${money(incoming)}</td><td>${money(outgoing)}</td><td>${escapeHtml(product.stockUom || "Units")}</td></tr>`).join("") : `<tr><td colspan="7">No active products.</td></tr>`;
  return `<div class="dashboard-inventory-stock-heading"><div><h2>Inventory at Date</h2><p>Stock totals for active products${state.inventoryStockReportDateTime ? ` · ${escapeHtml(formatInventoryStockDateTime(state.inventoryStockReportDateTime))}` : " · Live stock"}</p></div><button type="button" class="action-button secondary" data-module-page="inventory-stock">Open Inventory</button></div><div class="dashboard-kpi-grid">${dashboardKpi("Products", products.length.toLocaleString("en-BD"), "Active products", "blue")}${dashboardKpi("On Hand", totalOnHand.toLocaleString("en-BD", { maximumFractionDigits: 3 }), "Total stock units", "teal")}${dashboardKpi("Stock Value", salesCurrency(totalValue), "On hand × unit cost", "violet")}${dashboardKpi("Incoming", totalIncoming.toLocaleString("en-BD", { maximumFractionDigits: 3 }), `${lowStock} items at or below reorder level`, lowStock ? "amber" : "teal")}</div><article class="dashboard-chart-card dashboard-inventory-stock-table-card"><header><h2>On Hand by Product</h2><span>Top 10 products</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Reference</th><th>Category</th><th>On Hand</th><th>Incoming</th><th>Outgoing</th><th>Unit</th></tr></thead><tbody>${body}</tbody></table></div></article>`;
}

function renderDashboardWorkspace() {
  const typeByPage = { "dashboards-sales": "sales", "dashboards-product": "product", "dashboards-invoicing": "invoicing", "dashboards-inventory-stock": "inventory-stock" };
  const type = typeByPage[state.page] || state.dashboardActive || "sales";
  state.dashboardActive = type;
  const data = dashboardPeriods();
  const content = type === "inventory-stock" ? renderDashboardInventoryStock() : type === "product" ? renderDashboardProduct(data.currentSales) : type === "invoicing" ? renderDashboardInvoicing(data.currentInvoices, data.priorInvoices) : renderDashboardSales(data.currentSales, data.priorSales);
  return `${dashboardToolbar()}<section class="dashboard-layout ${state.dashboardSidebarCollapsed ? "is-collapsed" : ""}">${dashboardSectionNav()}<main class="dashboard-main">${content}</main></section>`;
}

function dashboardConfigToolbar(title, action, label) {
  return `<section class="dashboard-config-toolbar"><div class="dashboard-config-title"><button class="action-button" type="button" data-action="${action}">${escapeHtml(label)}</button><h1>${escapeHtml(title)}</h1><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button></div><label class="search-box dashboard-config-search">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off"></label><span class="dashboard-config-pager">1-${state.page === "dashboards-config" ? state.dashboardRecords.length : state.dashboardSections.length} / ${state.page === "dashboards-config" ? state.dashboardRecords.length : state.dashboardSections.length}</span></section>`;
}

function renderDashboardConfig() {
  const query = state.search.trim().toLowerCase();
  const records = state.dashboardRecords.filter((record) => [record.name, record.section, record.accessGroup, record.allowedUsers].join(" ").toLowerCase().includes(query));
  const groups = state.dashboardSections.map((section) => ({ section, records: records.filter((record) => record.section === section) })).filter((group) => group.records.length);
  const unknown = records.filter((record) => !state.dashboardSections.includes(record.section));
  if (unknown.length) groups.push({ section: "Other", records: unknown });
  const groupRows = groups.map(({ section, records: groupRecords }) => `<tr class="dashboard-group-row"><td colspan="7"><span>▾</span><strong>${escapeHtml(section)}</strong><small>${groupRecords.length} ${groupRecords.length === 1 ? "record" : "records"}</small></td></tr>${groupRecords.map((record) => `<tr><td class="dashboard-check-cell"><input type="checkbox" aria-label="Select ${escapeHtml(record.name)}"></td><td><span class="dashboard-drag-handle" aria-hidden="true">⠿</span><button type="button" class="dashboard-record-name" data-action="edit-dashboard" data-id="${escapeHtml(record.id)}">${escapeHtml(record.name)}</button></td><td><span class="dashboard-access-pill">${escapeHtml(record.accessGroup || "All Users")}</span></td><td>${escapeHtml(record.allowedUsers || "—")}</td><td><button type="button" class="dashboard-publish-toggle ${record.published ? "is-on" : ""}" data-action="toggle-dashboard-published" data-id="${escapeHtml(record.id)}" aria-label="${record.published ? "Unpublish" : "Publish"} ${escapeHtml(record.name)}" aria-pressed="${Boolean(record.published)}"><i></i></button></td><td><button type="button" class="dashboard-inline-link" data-action="dashboard-view-record" data-type="${escapeHtml(record.type)}">◉ View</button></td><td><button type="button" class="dashboard-inline-link spreadsheet-link" data-action="dashboard-edit-spreadsheet" data-id="${escapeHtml(record.id)}">✎ Edit in Spreadsheet</button></td></tr>`).join("")}`).join("");
  const table = `<div class="table-wrap dashboard-table-wrap"><table class="data-table dashboard-config-table"><thead><tr><th><input type="checkbox" aria-label="Select all dashboards"></th><th>Name</th><th>Access Groups</th><th>Allowed Users</th><th>Published</th><th></th><th></th></tr></thead><tbody>${groupRows || `<tr><td colspan="7"><div class="dashboard-empty-config">No dashboards match this search.</div></td></tr>`}</tbody></table></div>`;
  return `${dashboardConfigToolbar("Dashboards", "new-dashboard", "New")}${table}`;
}

function renderDashboardSections() {
  const query = state.search.trim().toLowerCase();
  const sections = state.dashboardSections.filter((section) => section.toLowerCase().includes(query));
  const rows = sections.map((section) => `<tr><td class="dashboard-check-cell"><input type="checkbox" aria-label="Select ${escapeHtml(section)}"></td><td><span class="dashboard-drag-handle" aria-hidden="true">⠿</span><button type="button" class="dashboard-record-name" data-action="edit-dashboard-section" data-section="${escapeHtml(section)}">${escapeHtml(section)}</button></td></tr>`).join("");
  const newRow = state.dashboardNewSection ? `<tr class="dashboard-new-section-row"><td class="dashboard-check-cell"><input type="checkbox" disabled></td><td><span class="dashboard-drag-handle" aria-hidden="true">⠿</span><form data-form="inline-dashboard-section"><input name="section" aria-label="New section name" autocomplete="off" maxlength="60" required><button type="submit" class="dashboard-inline-link">Save</button><button type="button" class="dashboard-inline-link" data-action="cancel-dashboard-section">Cancel</button></form></td></tr>` : "";
  return `${dashboardConfigToolbar("Sections", "new-dashboard-section", "New")}<div class="table-wrap dashboard-table-wrap"><table class="data-table dashboard-section-table"><thead><tr><th><input type="checkbox" aria-label="Select all sections"></th><th>Name</th></tr></thead><tbody>${rows}${newRow}${!rows && !newRow ? `<tr><td colspan="2"><div class="dashboard-empty-config">No sections match this search.</div></td></tr>` : ""}</tbody></table></div>`;
}

function renderDashboardsPage() {
  if (state.page === "dashboards-config") return renderDashboardConfig();
  if (state.page === "dashboards-sections") return renderDashboardSections();
  return renderDashboardWorkspace();
}

function persistDashboardRecords() {
  try { localStorage.setItem("odooDashboardRecords", JSON.stringify(state.dashboardRecords)); return true; }
  catch { showToast("Dashboard configuration could not be saved in this browser."); return false; }
}

function persistDashboardSections() {
  try { localStorage.setItem("odooDashboardSections", JSON.stringify(state.dashboardSections)); return true; }
  catch { showToast("Dashboard sections could not be saved in this browser."); return false; }
}

function openDashboardModal(record = null) {
  const editing = Boolean(record);
  const types = [["sales", "Sales"], ["product", "Product"], ["invoicing", "Invoicing"], ["inventory-stock", "Inventory (Stock)"]];
  const content = `<header class="modal-header"><div><h2>${editing ? "Edit Dashboard" : "New Dashboard"}</h2><p>Configure a local dashboard entry and its access group.</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="dashboard-form" data-id="${escapeHtml(record?.id || "")}"><div class="modal-body"><div class="form-grid"><div class="field"><label>Dashboard Name</label><input name="name" required maxlength="70" value="${escapeHtml(record?.name || "")}" placeholder="e.g. Depot Sales"></div><div class="field"><label>Section</label><select name="section">${state.dashboardSections.map((section) => `<option ${record?.section === section ? "selected" : ""}>${escapeHtml(section)}</option>`).join("")}</select></div><div class="field"><label>Dashboard View</label><select name="type">${types.map(([value, label]) => `<option value="${value}" ${record?.type === value ? "selected" : ""}>${label}</option>`).join("")}</select></div><div class="field"><label>Access Group</label><select name="accessGroup">${["Sales / Administrator", "Sales / User: Own Documents Only", "Accounting / Invoicing", "Accounting / Read-only", "All Users"].map((group) => `<option ${record?.accessGroup === group ? "selected" : ""}>${escapeHtml(group)}</option>`).join("")}</select></div><div class="field wide"><label>Allowed Users</label><input name="allowedUsers" value="${escapeHtml(record?.allowedUsers || "")}" placeholder="Optional user names or emails"></div><div class="field wide"><label class="check-label"><input type="checkbox" name="published" ${record ? (record.published ? "checked" : "") : "checked"}> Published</label></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save Dashboard</button></footer></form>`;
  openModal(content, true);
}

function openDashboardSectionModal(section) {
  openModal(`<header class="modal-header"><div><h2>Edit Section</h2><p>Change this dashboard group name.</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="dashboard-section-form" data-original="${escapeHtml(section)}"><div class="modal-body"><div class="field"><label>Section Name</label><input name="section" required maxlength="60" value="${escapeHtml(section)}"></div><button type="button" class="dashboard-danger-link" data-action="delete-dashboard-section" data-section="${escapeHtml(section)}">Delete Section</button></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save Section</button></footer></form>`, true);
}

function openDashboardImportModal() {
  openModal(`<header class="modal-header"><div><h2>Import Dashboards</h2><p>Upload a CSV exported from this dashboard registry.</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="dashboard-import-form"><div class="modal-body"><div class="upload-drop"><strong>Choose a dashboard CSV</strong><span>Name, Section, Access Group, Allowed Users, Published, Type</span><input name="file" type="file" accept=".csv,text/csv" required></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Cancel</button><button type="submit" class="action-button">Import</button></footer></form>`, true);
}

function parseCsvRows(text) {
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  const input = String(text || "").replace(/^\uFEFF/, "");
  for (let index = 0; index < input.length; index += 1) {
    const char = input[index];
    if (char === '"' && quoted && input[index + 1] === '"') { cell += '"'; index += 1; }
    else if (char === '"') quoted = !quoted;
    else if (char === "," && !quoted) { row.push(cell); cell = ""; }
    else if ((char === "\n" || char === "\r") && !quoted) {
      if (char === "\r" && input[index + 1] === "\n") index += 1;
      row.push(cell); cell = "";
      if (row.some((value) => value.trim())) rows.push(row);
      row = [];
    } else cell += char;
  }
  if (cell || row.length) { row.push(cell); if (row.some((value) => value.trim())) rows.push(row); }
  return rows;
}

function invoiceKindForPage(page = state.page) {
  return ({ "invoice-customer-invoices": "out_invoice", "invoice-credit-notes": "out_refund", "invoice-vendor-bills": "in_invoice", "invoice-vendor-refunds": "in_refund", "accounting-invoices": "out_invoice", "accounting-credit-notes": "out_refund", "accounting-bills": "in_invoice", "accounting-refunds": "in_refund" })[page] || "out_invoice";
}

function invoiceLabel(kind) {
  return ({ out_invoice: "Customer Invoice", out_refund: "Credit Note", in_invoice: "Vendor Bill", in_refund: "Vendor Refund" })[kind] || "Invoice";
}

function invoicePrefix(kind) {
  const prefix = state.invoiceLayout.invoicePrefix || "INV";
  return ({ out_invoice: prefix, out_refund: "CN", in_invoice: "BILL", in_refund: "VR" })[kind] || prefix;
}

function nextInvoiceReference(kind) {
  const prefix = invoicePrefix(kind);
  const year = new Date().getFullYear();
  const escapedPrefix = prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`^${escapedPrefix}/${year}/(\\d+)$`);
  const sequence = state.invoices.reduce((max, invoice) => {
    const match = String(invoice.ref || "").match(pattern);
    return match ? Math.max(max, Number(match[1])) : max;
  }, 0) + 1;
  return `${prefix}/${year}/${String(sequence).padStart(4, "0")}`;
}

function persistInvoiceData() {
  try {
    localStorage.setItem("odooInvoiceRegister", JSON.stringify(state.invoices));
    localStorage.setItem("odooInvoicePayments", JSON.stringify(state.invoicePayments));
    localStorage.setItem("odooInvoiceExpenses", JSON.stringify(state.invoiceExpenses));
    localStorage.setItem("odooInvoiceConfig", JSON.stringify(state.invoiceConfig));
    return true;
  } catch { return false; }
}

function amountForInvoice(invoice, key) {
  const value = Number(invoice?.[key] ?? 0);
  return salesCurrency(value);
}

function invoiceDateText(value) {
  if (!value) return "—";
  const date = new Date(`${value}T00:00:00`);
  return Number.isNaN(date.valueOf()) ? String(value) : date.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
}

function invoicesForCurrentPage() {
  const kind = invoiceKindForPage();
  const query = state.search.trim().toLowerCase();
  let rows = state.invoices.filter((invoice) => invoice.kind === kind);
  if (query) rows = rows.filter((invoice) => [invoice.ref, invoice.partner, invoice.origin, invoice.status, invoice.paymentTerms].some((value) => String(value || "").toLowerCase().includes(query)));
  return rows.sort((a, b) => b.id - a.id);
}

function invoiceToolbar(title, options = {}) {
  const showNew = options.newAction !== false;
  const upload = options.upload ? `<button class="action-button secondary" type="button" data-action="invoice-upload">Upload</button>` : "";
  const views = options.views === false ? "" : `<div class="view-controls" role="group" aria-label="View type">${["list", "kanban", "pivot", "chart", "calendar", "activity"].map((view) => `<button class="view-button ${state.view === view ? "is-active" : ""}" type="button" data-view="${view}" title="${view}" aria-label="${view} view">${icon(view === "activity" ? "clock" : view)}</button>`).join("")}</div>`;
  return `<section class="page-toolbar invoice-toolbar"><div class="toolbar-title">${showNew ? `<button class="action-button" type="button" data-action="new-record">New</button>` : ""}${upload}<span class="page-title">${escapeHtml(title)}</span><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button></div><label class="search-box invoice-search">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off"></label><div class="sales-toolbar-end">${views}</div></section>`;
}

function invoiceStatusClass(status) {
  return ({ Draft: "rfq", Sent: "sent", Posted: "purchase", Paid: "purchase", Partial: "approval", Overdue: "cancelled", Cancelled: "cancelled", Reversed: "cancelled" })[status] || "";
}

function invoiceDisplayStatus(invoice) {
  const status = invoice?.status || "Draft";
  if (["Posted", "Partial"].includes(status) && Number(invoice.amountDue || 0) > 0 && invoice.dueDate && invoice.dueDate < inputLocalDate()) return "Overdue";
  return status;
}

function invoiceDashboard() {
  const customerInvoices = state.invoices.filter((invoice) => invoice.kind.startsWith("out_") && !["Cancelled", "Reversed"].includes(invoice.status));
  const vendorBills = state.invoices.filter((invoice) => invoice.kind.startsWith("in_") && !["Cancelled", "Reversed"].includes(invoice.status));
  const expenses = state.invoiceExpenses;
  const openCustomers = customerInvoices.filter((invoice) => ["Posted", "Partial", "Overdue"].includes(invoiceDisplayStatus(invoice)));
  const openVendors = vendorBills.filter((invoice) => ["Posted", "Partial", "Overdue"].includes(invoiceDisplayStatus(invoice)));
  const receivable = openCustomers.reduce((sum, invoice) => sum + (invoice.kind === "out_refund" ? -1 : 1) * Number(invoice.amountDue || 0), 0);
  const payable = openVendors.reduce((sum, invoice) => sum + (invoice.kind === "in_refund" ? -1 : 1) * Number(invoice.amountDue || 0), 0);
  const invoiceValue = customerInvoices.reduce((sum, invoice) => sum + (invoice.kind === "out_refund" ? -1 : 1) * Number(invoice.total || 0), 0);
  const expenseValue = expenses.reduce((sum, expense) => sum + Number(expense.amount || 0), 0);
  const cards = [
    ["Invoices", invoiceValue, "invoice-customer-invoices"],
    ["Expenses", expenseValue, "invoice-expenses"],
    ["Receivable", receivable, "invoice-aged-receivable"],
    ["Payable", payable, "invoice-aged-payable"],
  ];
  const layoutReady = Boolean(state.invoiceLayout.companyName && state.invoiceLayout.address);
  return `${invoiceToolbar("Dashboard", { newAction: false, views: false })}<section class="invoice-dashboard"><div class="invoice-summary-grid">${cards.map(([label, value, page]) => `<button type="button" class="invoice-summary-card" data-module-page="${page}"><span>${label}</span><strong>${salesCurrency(value)}</strong></button>`).join("")}<button type="button" class="invoice-layout-promo ${layoutReady ? "is-ready" : ""}" data-module-page="invoice-document-layout"><span>${layoutReady ? "Invoice Layout Ready" : "Setup Your Invoice Layout"}</span><strong>↗</strong></button></div><div class="invoice-dashboard-grid"><article class="invoice-dashboard-panel invoice-action-panel"><header><div><h2>Sales</h2><p>Create and manage dealer invoices.</p></div></header><div class="invoice-panel-actions"><button class="action-button" type="button" data-action="new-record">New Invoice</button><button class="text-link" type="button" data-module-page="invoice-document-layout">Set Company Data</button><button class="text-link" type="button" data-module-page="invoice-online-payments">E-Invoicing Setup <small>${state.invoiceConfig.eInvoiceEnabled ? "Configured" : "Not connected"}</small></button></div><div class="invoice-panel-foot">Create invoices from confirmed Sales Orders; company header and footer are shared with Sales quotations.</div></article><article class="invoice-dashboard-panel invoice-action-panel"><header><div><h2>Purchases</h2><p>Track supplier bills, vendor balances, and payments.</p></div></header><div class="invoice-panel-actions"><button class="action-button secondary" type="button" data-action="invoice-upload">Upload Bill</button><button class="text-link" type="button" data-module-page="invoice-vendor-bills">Create a bill manually</button></div><div class="invoice-panel-foot">Three-way invoice matching stays linked to Purchase and receiving controls.</div></article><article class="invoice-dashboard-panel invoice-bank-card"><header><div><h2>Bank</h2><p>Connect journals and reconcile customer receipts.</p></div></header><button class="action-button secondary" type="button" data-module-page="invoice-bank">Setup Bank</button></article><article class="invoice-dashboard-panel invoice-tax-card"><header><div><h2>Tax Adjustments</h2><p>Configure product tax mapping after verifying current Bangladesh applicability.</p></div></header><button class="text-link" type="button" data-module-page="invoice-taxes">Configure Taxes</button><span class="invoice-configuration-status">${state.invoiceConfig.taxes?.length ? `${state.invoiceConfig.taxes.length} tax rules configured` : "No tax rates prefilled"}</span></article></div><section class="invoice-dashboard-bottom"><div><strong>Draft invoices</strong><span>${customerInvoices.filter((invoice) => invoice.status === "Draft").length}</span><button class="text-link" type="button" data-module-page="invoice-customer-invoices">Open invoice register</button></div><div><strong>Payments to reconcile</strong><span>${state.invoicePayments.filter((payment) => !payment.reconciled).length}</span><button class="text-link" type="button" data-module-page="invoice-customer-payments">Open payments</button></div></section></section>`;
}

function renderInvoiceList() {
  const rows = invoicesForCurrentPage();
  const kind = invoiceKindForPage();
  const vendor = kind.startsWith("in_");
  if (state.view !== "list") return `${invoiceToolbar(pageLabels[state.page], { upload: kind === "in_invoice" })}${renderInvoiceAlternateView(rows)}`;
  const body = rows.length ? rows.map((invoice) => { const status = invoiceDisplayStatus(invoice); return `<tr><td><input type="checkbox" aria-label="Select ${escapeHtml(invoice.ref)}"></td><td><button class="reference-link" type="button" data-open-invoice="${invoice.id}">${escapeHtml(invoice.ref)}</button></td><td>${escapeHtml(invoice.partner || "—")}</td><td>${invoiceDateText(invoice.invoiceDate)}</td><td>${invoiceDateText(invoice.dueDate)}</td><td>${invoice.reminderDate ? invoiceDateText(invoice.reminderDate) : "—"}</td><td class="money-cell">${amountForInvoice(invoice, "taxExcluded")}</td><td class="money-cell">${amountForInvoice(invoice, "total")}</td><td class="money-cell">${amountForInvoice(invoice, "amountDue")}</td><td><span class="status-pill ${invoiceStatusClass(status)}">${escapeHtml(status)}</span></td></tr>`; }).join("") : `<tr><td colspan="10"><div class="empty-state invoice-empty"><div class="empty-illustration">${icon("doc")}</div><h2>${kind === "out_invoice" ? "Create a customer invoice" : kind === "out_refund" ? "Create a customer credit note" : kind === "in_refund" ? "Create a vendor refund" : "Create a vendor bill"}</h2><p>Documents created from confirmed Sales Orders appear here as drafts. You can also create this document manually and review its shared invoice header before printing.</p><button class="action-button" type="button" data-action="new-record">Create</button></div></td></tr>`;
  const total = rows.reduce((sum, invoice) => sum + Number(invoice.total || 0), 0);
  const headers = vendor ? ["", "Number", "Vendor", "Bill Date", "Due Date", "Last Reminder", "Tax Excluded", "Total", "Amount Due", "Status"] : ["", "Number", "Customer", "Invoice Date", "Due Date", "Last Reminder", "Tax Excluded", "Total", "Amount Due", "Status"];
  return `${invoiceToolbar(pageLabels[state.page], { upload: kind === "in_invoice" })}<section class="list-toolbar"><div class="list-toolbar-left"><span class="results-count">${rows.length} document${rows.length === 1 ? "" : "s"}</span></div><div class="list-toolbar-right"><button class="soft-icon-button" type="button" data-action="filters" aria-label="Filters">${icon("filter")}</button><button class="soft-icon-button" type="button" data-action="configure-columns" aria-label="Configure columns">☷</button></div></section><div class="table-wrap"><table class="data-table invoice-table"><thead><tr>${headers.map((header) => `<th class="${["Total", "Amount Due", "Tax Excluded"].includes(header) ? "money-cell" : ""}">${escapeHtml(header)}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table></div>${rows.length ? `<div class="table-total"><span>Total</span><strong>${salesCurrency(total)}</strong></div>` : ""}`;
}

function renderInvoiceAlternateView(rows) {
  if (!rows.length) return `<div class="invoice-view-empty"><div class="empty-illustration">${icon("doc")}</div><h2>No documents to display</h2><p>Create or post an invoice to see it in this view.</p><button type="button" class="action-button" data-action="new-record">Create</button></div>`;
  const openButton = (invoice) => { const status = invoiceDisplayStatus(invoice); return `<button type="button" class="invoice-view-card" data-open-invoice="${invoice.id}"><span class="invoice-view-card-top"><strong>${escapeHtml(invoice.ref)}</strong><i class="status-pill ${invoiceStatusClass(status)}">${escapeHtml(status)}</i></span><span>${escapeHtml(invoice.partner || "Unassigned")}</span><small>${invoiceDateText(invoice.invoiceDate)} · Due ${invoiceDateText(invoice.dueDate)}</small><b>${salesCurrency(invoice.total)}</b><small>Amount due · ${salesCurrency(invoice.amountDue)}</small></button>`; };
  if (state.view === "kanban") return `<section class="invoice-kanban">${["Draft", "Posted", "Partial", "Paid", "Overdue"].map((status) => {
    const items = rows.filter((invoice) => invoiceDisplayStatus(invoice) === status);
    return `<article class="invoice-kanban-column"><header><strong>${status}</strong><span>${items.length}</span></header>${items.length ? items.map(openButton).join("") : `<p class="invoice-kanban-empty">No documents</p>`}</article>`;
  }).join("")}</section>`;
  if (state.view === "calendar") {
    const days = new Map();
    rows.forEach((invoice) => { const date = invoice.dueDate || invoice.invoiceDate || "Undated"; days.set(date, [...(days.get(date) || []), invoice]); });
    return `<section class="invoice-calendar-view">${[...days].sort(([a], [b]) => a.localeCompare(b)).map(([date, invoices]) => `<article><header><strong>${date === "Undated" ? date : invoiceDateText(date)}</strong><span>${invoices.length} document${invoices.length === 1 ? "" : "s"}</span></header>${invoices.map(openButton).join("")}</article>`).join("")}</section>`;
  }
  if (state.view === "activity") return `<section class="invoice-activity-view">${[...rows].sort((a, b) => String(a.dueDate || "").localeCompare(String(b.dueDate || ""))).map((invoice) => { const status = invoiceDisplayStatus(invoice); return `<article><span class="invoice-activity-dot ${invoice.amountDue > 0 ? "is-open" : ""}"></span><div><strong>${escapeHtml(invoice.ref)} · ${escapeHtml(invoice.partner || "Unassigned")}</strong><p>${status === "Draft" ? "Review and post this document" : invoice.amountDue > 0 ? `Follow up on ${salesCurrency(invoice.amountDue)} due ${invoiceDateText(invoice.dueDate)}` : "Document settled"}</p><small>${invoiceDateText(invoice.invoiceDate)} · ${escapeHtml(status)}</small></div><button class="text-link" data-open-invoice="${invoice.id}" type="button">Open</button></article>`; }).join("")}</section>`;
  const months = new Map();
  rows.forEach((invoice) => { const month = (invoice.invoiceDate || "Undated").slice(0, 7); months.set(month, (months.get(month) || 0) + Number(invoice.total || 0)); });
  const sorted = [...months].sort(([a], [b]) => a.localeCompare(b));
  const max = Math.max(1, ...sorted.map(([, value]) => value));
  if (state.view === "chart") return `<section class="invoice-chart-view"><header><div><strong>Invoice totals by month</strong><span>Recorded totals · BDT</span></div><span>${rows.length} documents</span></header><div class="invoice-chart-bars">${sorted.map(([month, value]) => `<div><span>${salesCurrency(value)}</span><i style="height:${Math.max(5, value / max * 100)}%"></i><small>${escapeHtml(month)}</small></div>`).join("")}</div></section>`;
  return `<section class="invoice-pivot-view"><div class="invoice-pivot-caption"><strong>Invoice Analysis</strong><span>Totals grouped by invoice month</span></div>${simpleTable(["Month", "Document Count", "Total · BDT"], sorted.map(([month, value]) => `<tr><td>${escapeHtml(month)}</td><td>${rows.filter((invoice) => (invoice.invoiceDate || "Undated").slice(0, 7) === month).length}</td><td class="money-cell">${salesCurrency(value)}</td></tr>`), "No invoice totals")}</section>`;
}

function renderInvoicePayments() {
  const vendor = ["invoice-vendor-payments", "accounting-vendor-payments"].includes(state.page);
  const rows = state.invoicePayments.filter((payment) => Boolean(payment.vendor) === vendor).filter((payment) => !state.search || [payment.ref, payment.partner, payment.journal, payment.state].some((value) => String(value || "").toLowerCase().includes(state.search.toLowerCase())));
  const tableRows = rows.map((payment) => `<tr><td>${invoiceDateText(payment.date)}</td><td>${escapeHtml(payment.ref)}</td><td>${escapeHtml(payment.journal || "Cash")}</td><td>${escapeHtml(payment.partner)}</td><td class="money-cell">${salesCurrency(payment.amount)}</td><td><span class="status-pill ${payment.reconciled ? "purchase" : "approval"}">${payment.reconciled ? "Reconciled" : "To Reconcile"}</span></td></tr>`);
  return `${invoiceToolbar(vendor ? "Vendor Payments" : "Payments")}<div class="sales-section-note"><strong>${vendor ? "Supplier settlements" : "Dealer receipts"}</strong><span>Register a payment against an open invoice and reconcile it to a configured journal.</span></div>${simpleTable(["Date", "Number", "Journal", vendor ? "Vendor" : "Customer", "Amount · BDT", "State"], tableRows, "No payments recorded")}`;
}

function renderInvoicePartners() {
  if (state.page === "invoice-products") return `${invoiceToolbar("Products", { newAction: false, views: false })}${renderSharedProductCatalog("sales", "invoiceProductCategoryFilter", "Invoice")}`;
  if (["invoice-customers", "accounting-customers-list"].includes(state.page)) {
    const rows = searchable(state.salesCustomers, ["name", "phone", "area", "type"]).map((partner) => `<tr><td>${escapeHtml(partner.customerCode || "—")}</td><td><strong>${escapeHtml(partner.name)}</strong></td><td>${escapeHtml(partner.phone || "—")}</td><td>${escapeHtml(partner.area || "—")}</td><td>${escapeHtml(partner.type || "Customer")}</td><td class="money-cell">${salesCurrency(partner.creditLimit || 0)}</td></tr>`);
    return `${invoiceToolbar("Customers")}<div class="sales-section-note"><strong>Customer accounts</strong><span>Sales and Invoicing share the same dealer/customer records.</span></div>${simpleTable(["Code", "Customer", "Phone", "Territory", "Type", "Credit Limit"], rows, "No customer accounts yet")}`;
  }
  if (["invoice-vendor-list", "accounting-vendors-list"].includes(state.page)) {
    const rows = searchable(vendors, ["name", "email", "phone"]).map((partner) => {
      const approved = isSupplierApproved(partner);
      const status = approved ? `<span class="status-pill purchase">Approved</span>` : `<span class="status-pill approval">Pending approval</span>`;
      const action = approved ? "—" : `<button class="action-button tertiary" type="button" data-action="approve-vendor" data-id="${partner.id}">Approve</button>`;
      return `<tr><td>V${String(partner.id).padStart(4, "0")}</td><td><strong>${escapeHtml(partner.name)}</strong></td><td>${escapeHtml(partner.email || "—")}</td><td>${escapeHtml(partner.phone || "—")}</td><td class="money-cell">${salesCurrency(partner.amount || 0)}</td><td>${partner.orders || 0}</td><td>${status}</td><td>${action}</td></tr>`;
    });
    return `${invoiceToolbar("Vendors")}<div class="sales-section-note"><strong>Supplier registration</strong><span>New suppliers stay pending until approved. Approved suppliers appear automatically in Inventory product setup.</span></div>${simpleTable(["Code", "Vendor", "Email", "Phone", "Purchase Total", "Orders", "Approval", ""], rows, "No vendors configured")}`;
  }
  const rows = salesProducts.map((product) => `<tr><td>${escapeHtml(product.sku)}</td><td>${escapeHtml(product.name)}</td><td>${escapeHtml(product.category)}</td><td>${escapeHtml(product.stockUom)}</td><td>${escapeHtml(product.saleUnits.join(", "))}</td><td class="money-cell">${salesCurrency(product.price)}</td><td>${product.unitFactors?.Carton ? `1 Carton = ${product.unitFactors.Carton} ${escapeHtml(product.stockUom)}` : "SKU conversion setup"}</td></tr>`);
  return `${invoiceToolbar("Products", { newAction: false })}<div class="sales-section-note"><strong>Invoiceable FMCG products</strong><span>Invoice units and verified conversions come from the shared Sales catalogue.</span></div>${simpleTable(["SKU", "Product", "Category", "Stock Unit", "Invoice Units", "Sale Price · BDT", "Pack Rule"], rows, "No invoiceable products")}`;
}

function renderInvoiceExpenses() {
  const rows = state.invoiceExpenses.filter((expense) => !state.search || [expense.ref, expense.category, expense.vendor, expense.description, expense.productName, expense.productSku].some((value) => String(value || "").toLowerCase().includes(state.search.toLowerCase()))).map((expense) => `<tr><td>${escapeHtml(expense.ref)}</td><td>${invoiceDateText(expense.date)}</td><td>${escapeHtml(expense.category)}</td><td>${escapeHtml(expense.vendor || "—")}</td><td>${expense.productId ? `<button type="button" class="reference-link" data-edit-sales-product="${expense.productId}">${escapeHtml(expense.productName || expense.productSku)}</button>` : "—"}</td><td>${escapeHtml(expense.description || "—")}</td><td class="money-cell">${salesCurrency(expense.amount)}</td><td><span class="status-pill ${expense.status === "Posted" ? "purchase" : "rfq"}">${escapeHtml(expense.status || "Draft")}</span></td><td>${expense.status === "Posted" ? escapeHtml(expense.journal || "Cash") : `<button type="button" class="action-button tertiary" data-action="post-expense" data-id="${expense.id}">Post to Ledger</button>`}</td></tr>`);
  return `${invoiceToolbar("Expenses")}<div class="sales-section-note"><strong>Operating expenses</strong><span>Post reviewed expenses to a configured cash or bank journal; product-linked expenses are shared with Inventory. Supplier bills belong in Vendors → Bills.</span></div>${simpleTable(["Number", "Date", "Category", "Vendor", "Product", "Description", "Amount · BDT", "Status", "Journal / Action"], rows, "No expenses recorded")}`;
}

function renderInvoiceReports() {
  const active = state.invoices.filter((invoice) => !["Cancelled", "Reversed"].includes(invoice.status));
  const isVendor = state.page === "invoice-aged-payable";
  const isReceivable = state.page === "invoice-aged-receivable";
  const rows = active.filter((invoice) => {
    if (isVendor) return invoice.kind.startsWith("in_");
    if (isReceivable || state.page === "invoice-customer-statement") return invoice.kind.startsWith("out_");
    return true;
  });
  if (["invoice-partner-ledger", "invoice-customer-statement", "invoice-aged-receivable", "invoice-aged-payable"].includes(state.page)) {
    const agingView = isVendor || isReceivable;
    const eligible = rows.filter((invoice) => agingView
      ? ["Posted", "Partial", "Overdue"].includes(invoiceDisplayStatus(invoice)) && Number(invoice.amountDue || 0) > 0
      : ["Posted", "Partial", "Paid", "Overdue"].includes(invoiceDisplayStatus(invoice)));
    const buckets = ["Current", "1–30 days", "31–60 days", "61–90 days", "90+ days"];
    const byPartner = new Map();
    eligible.forEach((invoice) => {
      const current = byPartner.get(invoice.partner) || { invoices: 0, due: 0, aging: Object.fromEntries(buckets.map((bucket) => [bucket, 0])) };
      const signedDue = (invoice.kind.endsWith("refund") ? -1 : 1) * Number(invoice.amountDue || 0);
      current.invoices += 1;
      current.due += signedDue;
      if (agingView && Number(invoice.amountDue || 0) > 0) {
        const daysLate = invoice.dueDate ? Math.max(0, Math.floor((new Date(`${inputLocalDate()}T00:00:00`) - new Date(`${invoice.dueDate}T00:00:00`)) / 86400000)) : 0;
        const bucket = daysLate === 0 ? "Current" : daysLate <= 30 ? "1–30 days" : daysLate <= 60 ? "31–60 days" : daysLate <= 90 ? "61–90 days" : "90+ days";
        current.aging[bucket] += signedDue;
      }
      byPartner.set(invoice.partner, current);
    });
    const tableRows = [...byPartner].map(([partner, value]) => agingView
      ? `<tr><td>${escapeHtml(partner || "Unassigned")}</td><td>${value.invoices}</td>${buckets.map((bucket) => `<td class="money-cell">${salesCurrency(value.aging[bucket])}</td>`).join("")}<td class="money-cell"><strong>${salesCurrency(value.due)}</strong></td></tr>`
      : `<tr><td>${escapeHtml(partner || "Unassigned")}</td><td>${value.invoices}</td><td class="money-cell">${salesCurrency(value.due)}</td><td>${value.due > 0 ? "Open balance" : "Settled"}</td></tr>`);
    const openDocs = eligible.filter((invoice) => Number(invoice.amountDue || 0) > 0);
    const balance = [...byPartner.values()].reduce((sum, value) => sum + value.due, 0);
    const overdue = eligible.filter((invoice) => invoiceDisplayStatus(invoice) === "Overdue").reduce((sum, invoice) => sum + (invoice.kind.endsWith("refund") ? -1 : 1) * Number(invoice.amountDue || 0), 0);
    const headers = agingView ? [isVendor ? "Vendor" : "Customer", "Open Documents", ...buckets, "Total · BDT"] : ["Customer / Partner", "Documents", "Balance · BDT", "Status"];
    return `${invoiceToolbar(pageLabels[state.page], { newAction: false, views: false })}<section class="report-page"><div class="report-kpis"><div class="report-kpi"><span>Partners</span><strong>${byPartner.size}</strong></div><div class="report-kpi"><span>Open Documents</span><strong>${openDocs.length}</strong></div><div class="report-kpi"><span>${agingView ? "Outstanding" : "Partner Balance"} · BDT</span><strong>${salesCurrency(balance)}</strong></div>${agingView ? `<div class="report-kpi"><span>Overdue · BDT</span><strong>${salesCurrency(overdue)}</strong></div>` : ""}</div>${simpleTable(headers, tableRows, agingView ? "No open balances to age" : "No posted partner documents")}</section>`;
  }
  if (state.page === "invoice-cashflow") {
    const periods = new Map();
    state.invoicePayments.forEach((payment) => {
      const month = String(payment.date || "Undated").slice(0, 7);
      const row = periods.get(month) || { receipts: 0, supplierPayments: 0, expenses: 0 };
      if (payment.vendor) row.supplierPayments += Number(payment.amount || 0); else row.receipts += Number(payment.amount || 0);
      periods.set(month, row);
    });
    state.invoiceExpenses.forEach((expense) => { const month = String(expense.date || "Undated").slice(0, 7); const row = periods.get(month) || { receipts: 0, supplierPayments: 0, expenses: 0 }; row.expenses += Number(expense.amount || 0); periods.set(month, row); });
    const periodRows = [...periods].sort(([a], [b]) => a.localeCompare(b)).map(([month, row]) => `<tr><td>${escapeHtml(month)}</td><td class="money-cell">${salesCurrency(row.receipts)}</td><td class="money-cell">${salesCurrency(row.supplierPayments)}</td><td class="money-cell">${salesCurrency(row.expenses)}</td><td class="money-cell"><strong>${salesCurrency(row.receipts - row.supplierPayments - row.expenses)}</strong></td></tr>`);
    const totalReceipts = state.invoicePayments.filter((payment) => !payment.vendor).reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
    const totalVendorPayments = state.invoicePayments.filter((payment) => payment.vendor).reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
    const totalExpenses = state.invoiceExpenses.reduce((sum, expense) => sum + Number(expense.amount || 0), 0);
    return `${invoiceToolbar("Cashflow Analysis", { newAction: false, views: false })}<section class="report-page"><div class="report-kpis"><div class="report-kpi"><span>Customer Receipts</span><strong>${salesCurrency(totalReceipts)}</strong></div><div class="report-kpi"><span>Vendor Payments</span><strong>${salesCurrency(totalVendorPayments)}</strong></div><div class="report-kpi"><span>Expenses</span><strong>${salesCurrency(totalExpenses)}</strong></div><div class="report-kpi"><span>Net Recorded Cashflow</span><strong>${salesCurrency(totalReceipts - totalVendorPayments - totalExpenses)}</strong></div></div>${simpleTable(["Period", "Customer Receipts", "Vendor Payments", "Expenses", "Net · BDT"], periodRows, "No payments or expenses recorded")}</section>`;
  }
  const byMonth = new Map();
  rows.forEach((invoice) => { const month = (invoice.invoiceDate || "").slice(0, 7) || "Unscheduled"; byMonth.set(month, (byMonth.get(month) || 0) + (invoice.kind.endsWith("refund") ? -1 : 1) * Number(invoice.total || 0)); });
  const reportRows = [...byMonth].sort(([a], [b]) => a.localeCompare(b)).map(([month, amount]) => `<tr><td>${escapeHtml(month)}</td><td class="money-cell">${salesCurrency(amount)}</td></tr>`);
  const heading = state.page === "invoice-cashflow" ? "Cashflow Analysis" : "Invoice Analysis";
  return `${invoiceToolbar(heading, { newAction: false, views: false })}<section class="report-page"><div class="report-kpis"><div class="report-kpi"><span>Invoice Documents</span><strong>${rows.length}</strong></div><div class="report-kpi"><span>Invoices & Bills · BDT</span><strong>${salesCurrency(rows.reduce((sum, invoice) => sum + Number(invoice.total || 0), 0))}</strong></div><div class="report-kpi"><span>Payments Registered</span><strong>${state.invoicePayments.length}</strong></div><div class="report-kpi"><span>Expenses · BDT</span><strong>${salesCurrency(state.invoiceExpenses.reduce((sum, expense) => sum + Number(expense.amount || 0), 0))}</strong></div></div><div class="report-grid"><article class="report-panel"><h2>${escapeHtml(heading)}</h2><p>Amounts use recorded invoice dates and BDT totals.</p>${simpleTable(["Period", "Total · BDT"], reportRows, "No posted or draft documents in this period")}</article><article class="report-panel"><h2>Tax review</h2><p>Tax reports depend on verified product tax configuration.</p><div class="sales-tax-note"><strong>${state.invoiceConfig.taxes?.length ? "Tax rules configured locally" : "No tax rates prefilled"}</strong><p>Validate each product's current Bangladesh VAT / supplementary duty applicability before posting a statutory invoice.</p></div></article></div></section>`;
}

function renderInvoiceLayoutForm(fromSales = false) {
  const layout = state.invoiceLayout;
  return `<form id="invoice-layout-form"><section class="settings-section"><header>Shared company header</header><div class="settings-section-body sales-settings-grid"><div class="field"><label>Company / Trading Name</label><input name="companyName" value="${escapeHtml(layout.companyName || "")}" placeholder="Company name"></div><div class="field"><label>Invoice Number Prefix</label><input name="invoicePrefix" value="${escapeHtml(layout.invoicePrefix || "")}" placeholder="INV"></div><div class="field"><label>Contact Phone</label><input name="phone" value="${escapeHtml(layout.phone || "")}" placeholder="+880"></div><div class="field"><label>Business Email</label><input name="email" type="email" value="${escapeHtml(layout.email || "")}" placeholder="accounts@company.com"></div><div class="field wide"><label>Registered / Depot Address</label><textarea name="address" placeholder="Business address">${escapeHtml(layout.address || "")}</textarea></div><div class="field"><label>VAT / BIN (if registered)</label><input name="bin" value="${escapeHtml(layout.bin || "")}" placeholder="Enter verified BIN"></div><div class="field"><label>Print Currency</label><input value="Bangladeshi Taka · BDT · ৳" readonly></div><div class="field wide"><label>Standard Invoice Footer</label><textarea name="footerNote" placeholder="Payment, delivery, return, or bank details">${escapeHtml(layout.footerNote || "")}</textarea></div></div></section><section class="invoice-layout-preview"><span class="settings-eyebrow">LIVE PREVIEW</span>${renderInvoiceHeaderPreview({ ref: `${layout.invoicePrefix || "INV"}/2026/0001`, partner: "Sample dealer", invoiceDate: inputLocalDate(), dueDate: "", lines: [], taxExcluded: 0, taxAmount: 0, total: 0 }, true)}</section><div class="sales-form-actions"><button class="action-button" type="submit">Save Shared Layout</button>${fromSales ? `<button class="action-button secondary" type="button" data-module-page="invoice-dashboard">Open Invoicing</button>` : ""}</div></form>`;
}

function renderInvoiceConfigPage() {
  if (state.page === "invoice-settings" || state.page === "invoice-document-layout") {
    return `${invoiceToolbar(state.page === "invoice-document-layout" ? "Invoice Layout" : "Settings", { newAction: false, views: false })}<section class="invoice-settings-page"><div class="settings-page-heading"><div><p class="settings-eyebrow">INVOICING CONFIGURATION</p><h1>${state.page === "invoice-document-layout" ? "Invoice document header" : "Company & accounting defaults"}</h1><p>Shared Sales quotation and invoice header, Bangladesh company profile, and reviewable invoice defaults.</p></div><span class="region-status"><i></i> Bangladesh · BDT</span></div>${state.page === "invoice-settings" ? `<section class="settings-section"><header>Company localization</header><div class="settings-section-body invoice-localization"><div><strong>Fiscal country</strong><span>Bangladesh · BD</span></div><div><strong>Company currency</strong><span>BDT · Bangladeshi Taka</span></div><div><strong>Tax localization</strong><span>${state.invoiceConfig.fiscalPackage || "Not connected"}</span></div><p>Country and currency are shown as the current workspace profile. Activate Bangladesh chart of accounts and product-specific fiscal positions in the connected Odoo Accounting database before posting.</p></div></section>` : ""}${renderInvoiceLayoutForm()}</section>`;
  }
  if (state.page === "invoice-taxes") {
    const taxes = state.invoiceConfig.taxes || [];
    const rows = taxes.map((tax) => `<tr><td>${escapeHtml(tax.name)}</td><td>${tax.scope === "purchase" ? "Purchase" : "Sales"}</td><td>${Number(tax.rate).toFixed(3)}%</td><td>${escapeHtml(tax.priceInclude ? "Included in price" : "Excluded from price")}</td><td><span class="status-pill ${tax.active ? "purchase" : "cancelled"}">${tax.active ? "Active · local draft" : "Archived"}</span></td></tr>`);
    return `${invoiceToolbar("Taxes")}<div class="sales-section-note"><strong>Product-specific tax mapping</strong><span>No statutory rates are assumed. Enter a rate only after confirming its current applicability for the product.</span></div>${simpleTable(["Tax Name", "Scope", "Rate", "Price Treatment", "Status"], rows, "No tax rules configured")}<div class="invoice-tax-footer"><button class="action-button" type="button" data-action="new-record">New Tax</button><button class="text-link" type="button" data-module-page="invoice-fiscal-positions">Configure fiscal positions</button></div>`;
  }
  if (state.page === "invoice-online-payments") {
    return `${invoiceToolbar("Online Payments", { newAction: false, views: false })}<section class="invoice-settings-page"><div class="sales-section-note"><strong>Online payment providers</strong><span>Provider credentials are not configured in this local prototype.</span></div><div class="invoice-config-cards"><article><h2>Customer payment links</h2><p>Add approved provider credentials in the live Odoo database to accept online payments.</p><span class="status-pill approval">Not connected</span></article><article><h2>Electronic invoicing</h2><p>Company identity, tax registration, and the required Bangladesh e-invoice service must be verified before activation.</p><span class="status-pill approval">Not connected</span></article></div></section>`;
  }
  const collections = state.invoiceConfig.collections || {};
  const items = collections[state.page] || [];
  const rows = items.map((item) => `<tr><td>${escapeHtml(item.name)}</td><td>${escapeHtml(item.detail || "—")}</td><td><span class="status-pill purchase">Active · local draft</span></td></tr>`);
  const descriptions = {
    "invoice-journals": ["Journals", "Sales, purchases, bank, cash, and miscellaneous accounting journals."],
    "invoice-currencies": ["Currencies", "Keep BDT as the company currency; enable other currencies only for actual foreign transactions."],
    "invoice-fiscal-positions": ["Fiscal Positions", "Map taxes by partner and product classification after local tax review."],
    "invoice-reminders": ["Invoice Reminders", "Define reminder cadence for overdue customer balances."],
    "invoice-payment-terms": ["Payment Terms", "Configure due on receipt and agreed dealer credit terms."],
    "invoice-product-categories": ["Product Categories", "Use categories to group consumer goods and assign verified accounts and taxes."],
    "invoice-bank": ["Bank Accounts", "Bank journals and reconciliation setup."],
    "invoice-tax-adjustments": ["Tax Adjustments", "Review adjustments against configured tax rules."],
  }[state.page] || [pageLabels[state.page] || "Configuration", "Accounting configuration records for this workspace."];
  return `${invoiceToolbar(descriptions[0])}<div class="sales-section-note"><strong>${escapeHtml(descriptions[0])}</strong><span>${escapeHtml(descriptions[1])}</span></div>${simpleTable(["Name", "Details", "Status"], rows, `No ${descriptions[0].toLowerCase()} configured`)}`;
}

function renderInvoicingPage() {
  if (state.page === "invoice-dashboard") return invoiceDashboard();
  if (["invoice-customer-invoices", "invoice-credit-notes", "invoice-vendor-bills", "invoice-vendor-refunds"].includes(state.page)) return renderInvoiceList();
  if (["invoice-customer-payments", "invoice-vendor-payments"].includes(state.page)) return renderInvoicePayments();
  if (["invoice-products", "invoice-customers", "invoice-vendor-list"].includes(state.page)) return renderInvoicePartners();
  if (state.page === "invoice-expenses") return renderInvoiceExpenses();
  if (["invoice-partner-ledger", "invoice-customer-statement", "invoice-aged-receivable", "invoice-aged-payable", "invoice-analysis", "invoice-cashflow"].includes(state.page)) return renderInvoiceReports();
  return renderInvoiceConfigPage();
}

function roundAccounting(value) { return Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100; }
function accountingAccount(code) { return state.accountingAccounts.find((account) => String(account.code) === String(code)); }
function accountingAccountName(code) { return code ? accountingAccount(code)?.name || `Unmapped account ${code}` : "—"; }
function accountingIsDebitNormal(type) { return ["asset", "expense"].includes(type); }
function accountingBalance(lines, code) { return roundAccounting(lines.filter((line) => String(line.accountCode) === String(code)).reduce((sum, line) => sum + Number(line.debit || 0) - Number(line.credit || 0), 0)); }
function accountingNaturalBalance(lines, account) { const value = accountingBalance(lines, account.code); return accountingIsDebitNormal(account.type) ? value : -value; }
function persistAccountingCollection(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { showToast("This browser could not save the accounting data locally."); return false; } }
function accountingUsableJournals() {
  const defaultOrder = new Map(defaultAccountingJournals.map((journal, index) => [journal.code.toLowerCase(), index]));
  return state.accountingJournals.filter((journal) => journal.active !== false).sort((left, right) =>
    (defaultOrder.get(String(left.code).toLowerCase()) ?? Number.MAX_SAFE_INTEGER) -
    (defaultOrder.get(String(right.code).toLowerCase()) ?? Number.MAX_SAFE_INTEGER));
}

function accountingJournalFor(type) {
  const journal = accountingUsableJournals().find((item) => item.type === type);
  return journal?.name || (type === "sales" ? "Sales" : type === "purchase" ? "Purchases" : type === "misc" ? "Miscellaneous Operations" : "Bank");
}

function accountingEntries() {
  const entries = [];
  const postedStates = ["Posted", "Partial", "Paid", "Overdue"];
  state.invoices.filter((invoice) => postedStates.includes(invoice.status)).forEach((invoice) => {
    const taxExcluded = roundAccounting(invoice.taxExcluded ?? invoice.total ?? 0);
    const taxAmount = roundAccounting(invoice.taxAmount || 0);
    const total = roundAccounting(invoice.total ?? taxExcluded + taxAmount);
    const customer = invoice.kind.startsWith("out_");
    const refund = invoice.kind.endsWith("refund");
    const documentAccountCode = invoice.accountingAccountCode || (invoice.kind.startsWith("in_") ? "5000" : "4000");
    let lines;
    if (customer && !refund) lines = [{ accountCode: "1100", partner: invoice.partner, label: invoice.ref, debit: total, credit: 0 }, { accountCode: documentAccountCode, partner: invoice.partner, label: invoice.ref, debit: 0, credit: taxExcluded }, ...(taxAmount ? [{ accountCode: "2100", partner: invoice.partner, label: `Output VAT · ${invoice.ref}`, debit: 0, credit: taxAmount }] : [])];
    else if (customer && Array.isArray(invoice.journalItems) && invoice.journalItems.length) lines = invoice.journalItems.map((line) => ({ accountCode: String(line.accountCode), partner: invoice.partner, label: line.label || invoice.ref, debit: roundAccounting(line.debit), credit: roundAccounting(line.credit), analytic: line.analytic || "", taxGrids: line.taxGrids || "" }));
    else if (customer) lines = [{ accountCode: "4010", partner: invoice.partner, label: invoice.ref, debit: taxExcluded, credit: 0 }, ...(taxAmount ? [{ accountCode: "2100", partner: invoice.partner, label: `Output VAT reversal · ${invoice.ref}`, debit: taxAmount, credit: 0 }] : []), { accountCode: "1100", partner: invoice.partner, label: invoice.ref, debit: 0, credit: total }];
    else if (!refund) lines = [{ accountCode: documentAccountCode, partner: invoice.partner, label: invoice.ref, debit: taxExcluded, credit: 0 }, ...(taxAmount ? [{ accountCode: "1300", partner: invoice.partner, label: `Input VAT · ${invoice.ref}`, debit: taxAmount, credit: 0 }] : []), { accountCode: "2000", partner: invoice.partner, label: invoice.ref, debit: 0, credit: total }];
    else lines = [{ accountCode: "2000", partner: invoice.partner, label: invoice.ref, debit: total, credit: 0 }, { accountCode: documentAccountCode, partner: invoice.partner, label: invoice.ref, debit: 0, credit: taxExcluded }, ...(taxAmount ? [{ accountCode: "1300", partner: invoice.partner, label: `Input VAT reversal · ${invoice.ref}`, debit: 0, credit: taxAmount }] : [])];
    entries.push({ id: `invoice-${invoice.id}`, ref: invoice.ref, date: invoice.invoiceDate || inputLocalDate(), journal: accountingJournalFor(customer ? "sales" : "purchase"), source: invoiceLabel(invoice.kind), partner: invoice.partner, lines, status: "Posted", sourceId: invoice.id });
  });
  state.invoicePayments.forEach((payment) => {
    const payJournal = state.accountingJournals.find((journal) => journal.name === payment.journal);
    const isCash = payJournal?.type === "cash" || /cash|bKash|Nagad/i.test(String(payment.journal || ""));
    const channelCode = payment.vendor ? "1030" : "1020";
    const amount = roundAccounting(payment.amount);
    const lines = payment.vendor ? [{ accountCode: "2000", partner: payment.partner, label: payment.ref, debit: amount, credit: 0 }, { accountCode: channelCode, partner: payment.partner, label: payment.ref, debit: 0, credit: amount }] : [{ accountCode: channelCode, partner: payment.partner, label: payment.ref, debit: amount, credit: 0 }, { accountCode: "1100", partner: payment.partner, label: payment.ref, debit: 0, credit: amount }];
    entries.push({ id: `payment-${payment.id}`, ref: payment.ref, date: payment.date || inputLocalDate(), journal: payment.journal || (isCash ? "Cash" : "Bank"), source: payment.vendor ? "Vendor Payment" : "Customer Receipt", partner: payment.partner, lines, status: payment.reconciled ? "Reconciled" : "To Reconcile", sourceId: payment.id });
    if (payment.reconciled) {
      const settlementAccount = payJournal?.accountCode || (isCash ? "1000" : "1010");
      const settlementDate = payment.reconciledDate || payment.date || inputLocalDate();
      const settlementLines = payment.vendor
        ? [{ accountCode: "1030", partner: payment.partner, label: payment.ref, debit: amount, credit: 0 }, { accountCode: settlementAccount, partner: payment.partner, label: payment.ref, debit: 0, credit: amount }]
        : [{ accountCode: settlementAccount, partner: payment.partner, label: payment.ref, debit: amount, credit: 0 }, { accountCode: "1020", partner: payment.partner, label: payment.ref, debit: 0, credit: amount }];
      entries.push({ id: `reconcile-payment-${payment.id}`, ref: `REC/${payment.ref}`, date: settlementDate, journal: payment.journal || (isCash ? "Cash" : "Bank"), source: "Bank Reconciliation", partner: payment.partner, lines: settlementLines, status: "Posted", sourceId: payment.id });
    }
  });
  state.invoiceExpenses.filter((expense) => expense.status === "Posted").forEach((expense) => {
    const journal = state.accountingJournals.find((item) => item.name === expense.journal) || state.accountingJournals.find((item) => item.type === "cash");
    const amount = roundAccounting(expense.amount);
    entries.push({ id: `expense-${expense.id}`, ref: expense.ref, date: expense.date || inputLocalDate(), journal: journal?.name || "Cash", source: "Operating Expense", partner: expense.vendor || "", status: "Posted", sourceId: expense.id, lines: [{ accountCode: "6000", partner: expense.vendor, label: `${expense.category} · ${expense.description || expense.ref}`, debit: amount, credit: 0 }, { accountCode: journal?.accountCode || "1000", partner: expense.vendor, label: expense.ref, debit: 0, credit: amount }] });
  });
  state.accountingEntries.filter((entry) => entry.status === "Posted").forEach((entry) => entries.push({ ...entry, source: "Manual Journal Entry" }));
  return entries.sort((a, b) => String(b.date).localeCompare(String(a.date)) || String(b.ref).localeCompare(String(a.ref)));
}

function accountingItems(options = {}) {
  const entries = accountingEntries();
  return entries.filter((entry) => (!options.end || String(entry.date) <= options.end) && (!options.start || String(entry.date) >= options.start))
    .flatMap((entry) => entry.lines.map((line, index) => ({ ...line, id: `${entry.id}-${index}`, entryId: entry.id, ref: entry.ref, date: entry.date, journal: entry.journal, source: entry.source, status: entry.status, accountName: accountingAccountName(line.accountCode), partner: line.partner || entry.partner || "—", label: line.label || entry.ref })))
    .filter((line) => !options.accountCode || String(line.accountCode) === String(options.accountCode));
}

function accountingToolbar(title, options = {}) {
  const action = options.newEntry ? `<button class="action-button" type="button" data-action="new-accounting-entry">New Entry</button>` : options.newAccount ? `<button class="action-button" type="button" data-action="new-accounting-account">New Account</button>` : options.newJournal ? `<button class="action-button" type="button" data-action="new-accounting-journal">New Journal</button>` : "";
  const dates = options.range ? `<div class="accounting-date-range"><label>From <input type="date" data-accounting-range="start" value="${escapeHtml(state.accountingRange.start)}"></label><label>To <input type="date" data-accounting-range="end" value="${escapeHtml(state.accountingRange.end)}"></label></div>` : "";
  return `<section class="page-toolbar accounting-toolbar"><div class="toolbar-title">${action}<span class="page-title">${escapeHtml(title)}</span><button class="more-button" type="button" data-action="toolbar-more" aria-label="More options">⋮</button></div><label class="search-box">${icon("search")}<input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search accounting records..." autocomplete="off"></label>${dates}</section>`;
}

function accountingAmount(value) { return salesCurrency(roundAccounting(value)); }
function accountingCashCodes() { return [...new Set(accountingUsableJournals().filter((journal) => ["bank", "card", "cash"].includes(journal.type)).map((journal) => String(journal.accountCode)))]; }
function accountingFiscalStart(dateValue, fiscalYearStart = "07-01") {
  const date = new Date(`${dateValue || inputLocalDate()}T00:00:00`);
  const [month, day] = String(fiscalYearStart || "07-01").split("-").map(Number);
  let year = date.getFullYear();
  if (date.getMonth() + 1 < month || (date.getMonth() + 1 === month && date.getDate() < day)) year -= 1;
  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function accountingDashboard() {
  const asOfItems = accountingItems({ end: state.accountingRange.end });
  const periodItems = accountingItems({ start: state.accountingRange.start, end: state.accountingRange.end });
  const income = state.accountingAccounts.filter((account) => account.type === "income").reduce((sum, account) => sum + accountingNaturalBalance(periodItems, account), 0);
  const expenses = state.accountingAccounts.filter((account) => account.type === "expense").reduce((sum, account) => sum + accountingNaturalBalance(periodItems, account), 0);
  const receivable = Math.max(0, accountingBalance(asOfItems, "1100"));
  const payable = Math.max(0, -accountingBalance(asOfItems, "2000"));
  const cash = accountingCashCodes().reduce((sum, code) => sum + accountingBalance(asOfItems, code), 0);
  const openPayments = state.invoicePayments.filter((payment) => !payment.reconciled).length;
  const customerInvoices = state.invoices.filter((invoice) => invoice.kind === "out_invoice");
  const vendorBills = state.invoices.filter((invoice) => invoice.kind === "in_invoice");
  const invoiceValue = customerInvoices.reduce((sum, invoice) => sum + Number(invoice.total || 0), 0);
  const expenseValue = expenses + state.invoices.filter((invoice) => invoice.kind === "in_invoice" && ["Posted", "Partial", "Paid", "Overdue"].includes(invoice.status)).reduce((sum, invoice) => sum + Number(invoice.taxExcluded || invoice.total || 0), 0);
  const cards = [
    ["Invoices", invoiceValue, "accounting-invoices"],
    ["Expenses", expenseValue, "accounting-profit-loss"],
    ["Cash", cash, "accounting-general-ledger"],
    ["Receivable", receivable, "accounting-aged-receivable"],
    ["Payable", payable, "accounting-aged-payable"],
  ];
  const layoutReady = Boolean(state.invoiceLayout.companyName && state.invoiceLayout.address);
  return `${accountingToolbar("Dashboard", { range: true })}<section class="invoice-dashboard accounting-native-dashboard"><div class="invoice-summary-grid">${cards.map(([label, amount, page]) => `<button type="button" class="invoice-summary-card" data-module-page="${page}"><span>${escapeHtml(label)}</span><strong>${accountingAmount(amount)}</strong></button>`).join("")}<button type="button" class="invoice-layout-promo ${layoutReady ? "is-ready" : ""}" data-module-page="invoice-document-layout"><span>${layoutReady ? "Invoice Layout Ready" : "Setup Your Invoice Layout"}</span><strong>▤</strong></button></div><div class="invoice-dashboard-grid"><article class="invoice-dashboard-panel invoice-action-panel"><header><div><h2>Sales</h2><p>Customer invoices, receipts and outstanding balances.</p></div></header><div class="invoice-panel-actions"><button class="action-button" type="button" data-module-page="accounting-invoices">Invoices</button><button class="text-link" type="button" data-module-page="accounting-credit-notes">Credit Notes</button><button class="text-link" type="button" data-module-page="accounting-customer-payments">Register / review receipts</button></div><div class="invoice-panel-foot">Confirmed Sales Orders create drafts here. Posting records receivables and sales in the shared ledger.</div></article><article class="invoice-dashboard-panel invoice-action-panel"><header><div><h2>Purchases</h2><p>Supplier bills, refunds and payments.</p></div></header><div class="invoice-panel-actions"><button class="action-button secondary" type="button" data-module-page="accounting-bills">Vendor Bills</button><button class="text-link" type="button" data-module-page="accounting-refunds">Refunds</button><button class="text-link" type="button" data-module-page="accounting-vendor-payments">Pay Supplier</button><button class="text-link" type="button" data-module-page="orders">Purchase Orders</button></div><div class="invoice-panel-foot">Post a bill to record Accounts Payable; register a payment to reduce the supplier balance.</div></article><article class="invoice-dashboard-panel invoice-bank-card"><header><div><h2>Bank & Reconciliation</h2><p>${openPayments} receipt or payment${openPayments === 1 ? "" : "s"} waiting to reconcile.</p></div></header><button class="action-button secondary" type="button" data-module-page="accounting-reconcile">Reconcile</button></article><article class="invoice-dashboard-panel invoice-tax-card"><header><div><h2>Accounting Review</h2><p>Review journals, statements and tax totals.</p></div></header><div class="invoice-panel-actions"><button class="text-link" type="button" data-module-page="accounting-journal-entries">Journal Entries</button><button class="text-link" type="button" data-module-page="accounting-trial-balance">Trial Balance</button><button class="text-link" type="button" data-module-page="accounting-tax-report">Tax Report</button><button class="text-link" type="button" data-module-page="accounting-settings">Bangladesh Settings</button></div></article></div><section class="invoice-dashboard-bottom"><div><strong>Draft documents</strong><span>${state.invoices.filter((invoice) => invoice.status === "Draft").length}</span><button class="text-link" type="button" data-module-page="accounting-invoices">Customer invoices</button></div><div><strong>Open vendor bills</strong><span>${vendorBills.filter((invoice) => Number(invoice.amountDue || 0) > 0 && invoice.status !== "Draft").length}</span><button class="text-link" type="button" data-module-page="accounting-aged-payable">View payable</button></div></section><section class="invoice-dashboard-bottom"><div><strong>Income this period</strong><span>${accountingAmount(income)}</span><button class="text-link" type="button" data-module-page="accounting-profit-loss">Profit and Loss</button></div><div><strong>Operating expenses</strong><span>${accountingAmount(expenses)}</span><button class="text-link" type="button" data-module-page="accounting-journal-items">Journal Items</button></div></section></section>`;
}

function accountingSearch(rows, fields) {
  const term = state.search.trim().toLowerCase();
  return term ? rows.filter((row) => fields.some((field) => String(row[field] ?? "").toLowerCase().includes(term))) : rows;
}

function renderAccountingEntries(title = "Journal Entries", audit = false) {
  const entries = accountingSearch(accountingEntries().filter((entry) => entry.date >= state.accountingRange.start && entry.date <= state.accountingRange.end), ["ref", "date", "journal", "source", "partner", "status"]);
  const rows = entries.map((entry) => {
    const debit = roundAccounting(entry.lines.reduce((sum, line) => sum + Number(line.debit || 0), 0));
    const credit = roundAccounting(entry.lines.reduce((sum, line) => sum + Number(line.credit || 0), 0));
    return `<tr><td>${escapeHtml(entry.ref)}</td><td>${invoiceDateText(entry.date)}</td><td>${escapeHtml(entry.journal)}</td><td>${escapeHtml(entry.source)}</td><td>${escapeHtml(entry.partner || "—")}</td><td class="money-cell">${accountingAmount(debit)}</td><td class="money-cell">${accountingAmount(credit)}</td><td><span class="status-pill ${entry.status === "Posted" ? "purchase" : "approval"}">${escapeHtml(entry.status)}</span></td></tr>`;
  });
  const note = audit
    ? "This is a read-only source register for this browser prototype. It is not an immutable audit log; use a secured accounting database for statutory audit evidence."
    : "Posted customer documents, supplier bills, payments and manual journals are listed here. Draft documents do not post to the ledger.";
  return `${accountingToolbar(title, { newEntry: !audit, range: true })}<div class="accounting-note"><strong>${audit ? "Local audit register" : "Double-entry ledger"}</strong><span>${note}</span></div>${simpleTable(["Number", "Date", "Journal", "Source", "Partner", "Debit · BDT", "Credit · BDT", "State"], rows, "No posted accounting entries in this period")}`;
}

function renderAccountingItems() {
  const items = accountingSearch(accountingItems({ start: state.accountingRange.start, end: state.accountingRange.end }), ["ref", "date", "journal", "accountCode", "accountName", "partner", "label"]);
  const rows = items.map((item) => `<tr><td>${escapeHtml(item.date)}</td><td>${escapeHtml(item.journal)}</td><td>${escapeHtml(item.ref)}</td><td>${escapeHtml(item.accountCode)}</td><td>${escapeHtml(item.accountName)}</td><td>${escapeHtml(item.partner)}</td><td>${escapeHtml(item.label)}</td><td class="money-cell">${accountingAmount(item.debit)}</td><td class="money-cell">${accountingAmount(item.credit)}</td></tr>`);
  return `${accountingToolbar("Journal Items", { range: true })}<div class="accounting-note"><strong>Posted journal lines</strong><span>Every posted record creates equal debits and credits across its accounts.</span></div>${simpleTable(["Date", "Journal", "Entry", "Code", "Account", "Partner", "Label", "Debit · BDT", "Credit · BDT"], rows, "No journal items in this period")}`;
}

function renderAccountingInventoryValuation() {
  const items = accountingSearch(accountingItems({ end: state.accountingRange.end }).filter((item) => String(item.accountCode) === "1200"), ["ref", "date", "journal", "partner", "label"]);
  const balance = accountingNaturalBalance(accountingItems({ end: state.accountingRange.end }), accountingAccount("1200") || { code: "1200", type: "asset" });
  const rows = items.map((item) => `<tr><td>${invoiceDateText(item.date)}</td><td>${escapeHtml(item.ref)}</td><td>${escapeHtml(item.journal)}</td><td>${escapeHtml(item.partner)}</td><td>${escapeHtml(item.label)}</td><td class="money-cell">${accountingAmount(item.debit)}</td><td class="money-cell">${accountingAmount(item.credit)}</td></tr>`);
  return `${accountingToolbar("Inventory Valuation", { range: true })}<div class="accounting-note accounting-caution"><strong>Manual ledger valuation</strong><span>Account 1200 only. Purchases and stock movements are not automatically valued or synchronized here; record reviewed opening and period-end adjustments with a journal entry.</span></div><section class="accounting-report-summary"><span>Inventory ledger balance</span><strong>${accountingAmount(balance)}</strong><span>As of</span><strong>${invoiceDateText(state.accountingRange.end)}</strong></section>${simpleTable(["Date", "Entry", "Journal", "Partner", "Memo", "Debit · BDT", "Credit · BDT"], rows, "No inventory valuation postings")}`;
}

function renderAccountingChart() {
  const accounts = accountingSearch(state.accountingAccounts, ["code", "name", "type", "group"]);
  const balances = accountingItems({ end: state.accountingRange.end });
  const rows = accounts.map((account) => `<tr><td>${escapeHtml(account.code)}</td><td><strong>${escapeHtml(account.name)}</strong></td><td>${escapeHtml(account.type)}</td><td>${escapeHtml(account.group || "—")}</td><td>${account.reconcile ? "Yes" : "No"}</td><td class="money-cell">${accountingAmount(accountingNaturalBalance(balances, account))}</td></tr>`);
  return `${accountingToolbar("Chart of Accounts", { newAccount: true })}<div class="accounting-note"><strong>Bangladesh · BDT default chart</strong><span>Odoo-style account names are localized for this company. These shared accounts feed Sales, Purchases, Inventory, invoices and the general ledger.</span></div>${simpleTable(["Code", "Account Name", "Type", "Group", "Reconcile", "Balance · BDT"], rows, "No accounts configured")}`;
}

function renderAccountingJournals() {
  const journals = accountingSearch(accountingUsableJournals(), ["name", "type", "code", "accountCode"]);
  const types = { sales: "Sales", purchase: "Purchase", bank: "Bank", card: "Card", cash: "Cash", misc: "Miscellaneous" };
  const rows = journals.map((journal) => `<tr><td><strong>${escapeHtml(journal.name)}</strong></td><td>${escapeHtml(types[journal.type] || journal.type)}</td><td>${escapeHtml(journal.code)}</td><td>${escapeHtml(journal.accountCode ? `${journal.accountCode} ${accountingAccountName(journal.accountCode)}` : "—")}</td></tr>`);
  return `${accountingToolbar("Journals", { newJournal: true })}<div class="accounting-note"><strong>Default journals</strong><span>Sales, Purchases, Bank, Miscellaneous Operations and Cash use the shared localized Chart of Accounts.</span></div>${simpleTable(["Journal Name", "Type", "Sequence Prefix", "Default Account"], rows, "No journals configured")}`;
}

function renderAccountingReconcile() {
  const payments = state.invoicePayments.filter((payment) => !payment.reconciled).filter((payment) => !state.search || [payment.ref, payment.partner, payment.journal].some((value) => String(value || "").toLowerCase().includes(state.search.toLowerCase())));
  const rows = payments.map((payment) => `<tr><td>${invoiceDateText(payment.date)}</td><td>${escapeHtml(payment.ref)}</td><td>${escapeHtml(payment.partner)}</td><td>${payment.vendor ? "Vendor Payment" : "Customer Receipt"}</td><td>${escapeHtml(payment.journal || "Bank")}</td><td class="money-cell">${accountingAmount(payment.amount)}</td><td><span class="status-pill approval">To Reconcile</span></td><td><button type="button" class="action-button tertiary" data-action="accounting-reconcile-payment" data-id="${payment.id}">Match to Bank</button></td></tr>`);
  return `${accountingToolbar("Reconcile", { range: true })}<div class="accounting-note"><strong>Outstanding receipts and payments</strong><span>Match a registered payment when it appears on your statement. This local action updates the ledger bank account; it does not connect to a bank feed.</span></div>${simpleTable(["Date", "Reference", "Partner", "Type", "Journal", "Amount · BDT", "State", "Action"], rows, "No payments waiting for reconciliation")}`;
}

function accountingSelectOptions(value = "") {
  return state.accountingAccounts.map((account) => `<option value="${escapeHtml(account.code)}" ${String(account.code) === String(value) ? "selected" : ""}>${escapeHtml(account.code)} · ${escapeHtml(account.name)}</option>`).join("");
}

function accountingEntryLineMarkup(line = {}) {
  return `<tr class="accounting-entry-line"><td><select name="accountCode" required><option value="">Choose account</option>${accountingSelectOptions(line.accountCode)}</select></td><td><input name="partner" value="${escapeHtml(line.partner || "")}" placeholder="Optional partner"></td><td><input name="label" value="${escapeHtml(line.label || "")}" placeholder="Line memo"></td><td><input name="debit" type="number" min="0" step="0.01" value="${line.debit ? Number(line.debit).toFixed(2) : ""}" placeholder="0.00"></td><td><input name="credit" type="number" min="0" step="0.01" value="${line.credit ? Number(line.credit).toFixed(2) : ""}" placeholder="0.00"></td><td><button class="soft-icon-button" type="button" data-action="remove-accounting-line" aria-label="Remove line">×</button></td></tr>`;
}

function openAccountingEntryModal() {
  if (state.accountingAccounts.length < 2) { showToast("Add at least two accounts before creating a journal entry."); return; }
  openAccountingForm("entry");
}

function openAccountingAccountModal() {
  openAccountingForm("account");
}

function openAccountingJournalModal() {
  const journalTypes = [
    { type: "bank", title: "Bank", description: "Connect your bank and payment gateways (PayPal, Stripe, ...) or record your transactions manually." },
    { type: "card", title: "Card", description: "Connect your credit card accounts and manage your payouts." },
    { type: "cash", title: "Cash", description: "Record your cash movements and transfers." },
    { type: "misc", title: "Miscellaneous Journal", description: "Payroll, depreciation, closing entries, deferred revenues, ...etc" },
    { type: "sales", title: "Sales Journal", description: "Create a separate journal for specific sales activities." },
    { type: "purchase", title: "Purchases Journal", description: "Create a separate journal to organize vendor bills." },
  ];
  const cards = journalTypes.map((item) => `<button class="accounting-journal-type-card" type="button" data-action="select-accounting-journal-type" data-journal-type="${item.type}"><span class="accounting-journal-type-copy"><strong>${item.title}</strong><span>${item.description}</span></span><span class="accounting-journal-type-art" aria-hidden="true">${accountingJournalTypeArtwork(item.type)}</span></button>`).join("");
  openModal(`<header class="accounting-journal-type-header"><h2>What type of journal do you want to add?</h2><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><div class="accounting-journal-type-grid">${cards}</div>`);
  modalRoot.querySelector(".modal-card")?.classList.add("accounting-journal-type-modal");
}

