function openOrderModal(orderId = null, prefillProductId = null, prefill = {}) {
  const order = purchaseOrders.find((item) => item.id === Number(orderId));
  const prefillProduct = prefillProductId ? salesProducts.find((item) => item.id === Number(prefillProductId)) : null;
  state.purchaseEditor = { id: order?.id || null, vendor: order?.vendor || prefill.vendor || "", vendorContactId: order?.vendorContactId || prefill.contactId || null, returnPage: state.page, prefillLines: Array.isArray(prefill.lines) ? prefill.lines : null, cartPrefill: Boolean(prefill.cartPrefill), prefillLine: prefillProduct ? { sku: prefillProduct.sku, qty: 1, uom: prefillProduct.stockUom, price: prefillProduct.purchasePrice ?? prefillProduct.cost ?? 0 } : null };
  state.receiptEditor = null;
  state.purchaseTab = "products";
  state.purchaseTaxMode = "excluded";
  state.purchaseFavorite = Boolean(order?.favorite);
  closeModal();
  render();
}

function productUnitConversions(product) {
  if (Array.isArray(product?.unitConversions)) return product.unitConversions;
  const stockUom = product?.stockUom || "Piece";
  const legacy = [...new Set([...(product?.saleUnits || []), ...state.packRules.filter((rule) => rule.product === product?.name || rule.sku === product?.sku).map((rule) => rule.purchasePack)])]
    .filter((unit) => unit && unit !== stockUom);
  return legacy.map((unit) => {
    const rule = state.packRules.find((item) => (item.product === product?.name || item.sku === product?.sku) && item.purchasePack === unit);
    return { unit, quantity: product?.unitFactors?.[unit] ?? rule?.quantity ?? "", purchaseEnabled: true, saleEnabled: (product?.saleUnits || []).includes(unit), allowFraction: false };
  });
}

function suggestedProductCategory(name = "") {
  const text = String(name || "").toLowerCase();
  if (/mosquito|coil|\bboss\b|mortein|good knight/.test(text)) return "Coil";
  if (/detergent|laundry|washing powder/.test(text)) return "Detergent";
  if (/chanachur|snack|chips|biscuit/.test(text)) return "Snacks";
  if (/soap|shampoo|body wash|lotion|toothpaste/.test(text)) return "Personal Care";
  if (/rice|spice|food|oil|drink|beverage/.test(text)) return "Food";
  return "Goods";
}

function defaultProductPurchaseQuantity(unit, stockUnit) {
  if (String(unit || "").toLowerCase() === String(stockUnit || "").toLowerCase()) return 1;
  return "";
}

const standardProductPurchaseUnits = ["Sack", "Bag / বস্তা", "Carton", "Pack", "Packet", "Piece", "Box", "Bottle", "Can", "Drum", "Pallet", "kg", "g", "mg", "L", "ml", "Ton"];
const productPurchaseUnitsStorageKey = "odooFmcgPurchaseUnits";
const lastProductPurchaseUnitStorageKey = "odooFmcgLastPurchaseUom";

function readCustomProductPurchaseUnits() {
  try {
    const saved = JSON.parse(localStorage.getItem(productPurchaseUnitsStorageKey) || "[]");
    return Array.isArray(saved) ? saved.map((unit) => String(unit || "").trim()).filter(Boolean) : [];
  } catch { return []; }
}

function productPurchaseUnitOptions(extraUnits = []) {
  const unique = new Map();
  [...standardProductPurchaseUnits, ...readCustomProductPurchaseUnits(), ...extraUnits]
    .map((unit) => String(unit || "").trim())
    .filter(Boolean)
    .forEach((unit) => { if (!unique.has(unit.toLowerCase())) unique.set(unit.toLowerCase(), unit); });
  return [...unique.values()];
}

function readLastProductPurchaseUnit() {
  try { return String(localStorage.getItem(lastProductPurchaseUnitStorageKey) || "").trim(); }
  catch { return ""; }
}

function persistLastProductPurchaseUnit(unit) {
  const value = String(unit || "").trim();
  if (!value) return false;
  try { localStorage.setItem(lastProductPurchaseUnitStorageKey, value); return true; }
  catch { return false; }
}

function persistCustomProductPurchaseUnit(unit) {
  const value = String(unit || "").trim().replace(/\s+/g, " ");
  if (!value) return false;
  if (standardProductPurchaseUnits.some((item) => item.toLowerCase() === value.toLowerCase())) return true;
  const saved = readCustomProductPurchaseUnits();
  if (!saved.some((item) => item.toLowerCase() === value.toLowerCase())) saved.push(value);
  try { localStorage.setItem(productPurchaseUnitsStorageKey, JSON.stringify(saved)); return true; }
  catch { return false; }
}

function productUnitFactor(product, unit) {
  if (!product || !unit) return null;
  if (String(unit).toLowerCase() === String(product.stockUom || "Piece").toLowerCase()) return 1;
  const conversion = productUnitConversions(product).find((item) => String(item.unit || "").trim().toLowerCase() === String(unit).trim().toLowerCase());
  const rule = state.packRules.find((item) => (item.product === product.name || item.sku === product.sku) && item.purchasePack === unit);
  const raw = conversion?.quantity ?? product.unitFactors?.[unit] ?? rule?.quantity;
  const factor = Number(raw);
  return Number.isFinite(factor) && factor > 0 ? factor : null;
}

function productSalesUnitPrice(product, unit) {
  const conversion = productUnitConversions(product).find((item) => String(item.unit || "").trim().toLowerCase() === String(unit || "").trim().toLowerCase());
  const override = conversion?.salePrice;
  if (override !== undefined && override !== null && String(override).trim() !== "") return Number(override);
  return Number(product?.price || 0) * Number(productUnitFactor(product, unit) || 1);
}

function productUnitConversionPreview(product, quantity, unit) {
  const qty = Number(quantity || 0);
  const factor = productUnitFactor(product, unit);
  if (!product || !Number.isFinite(qty) || qty <= 0 || !factor) return "";
  const stockUnit = product.stockUom || "Piece";
  const stockQuantity = qty * factor;
  const packageUnit = [product.purchaseUom, product.packUom, ...(product.saleUnits || [])]
    .find((candidate) => candidate && String(candidate).toLowerCase() !== String(stockUnit).toLowerCase() && productUnitFactor(product, candidate));
  const packageFactor = packageUnit ? productUnitFactor(product, packageUnit) : null;
  const formatQuantity = (value) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 3 }).format(value);
  return packageFactor
    ? `${formatQuantity(stockQuantity)} ${stockUnit} · ${formatQuantity(stockQuantity / packageFactor)} ${packageUnit}`
    : `${formatQuantity(stockQuantity)} ${stockUnit}`;
}

function productUnits(product, flow = "sale") {
  if (!product) return [];
  const base = product.stockUom || "Piece";
  const legacy = Array.isArray(product.unitConversions) ? [] : (product.saleUnits || [base]);
  const configured = productUnitConversions(product).filter((item) => flow === "purchase" ? item.purchaseEnabled !== false : item.saleEnabled !== false).map((item) => item.unit);
  const oldPurchase = flow === "purchase" ? state.packRules.filter((rule) => rule.product === product.name || rule.sku === product.sku).map((rule) => rule.purchasePack) : [];
  return [...new Set([base, ...legacy.filter((unit) => unit !== base), ...configured, ...oldPurchase].filter(Boolean))];
}

function productUnitAllowsFraction(product, unit) {
  const conversion = productUnitConversions(product).find((item) => String(item.unit || "").trim().toLowerCase() === String(unit || "").trim().toLowerCase());
  if (conversion?.allowFraction !== undefined) return Boolean(conversion.allowFraction);
  return /^(kg|g|mg|t|l|ml|m³|ft³)$/i.test(String(unit || "").trim());
}

function productUnitPrice(product, unit, flow = "sale") {
  const conversion = productUnitConversions(product).find((item) => String(item.unit || "").trim().toLowerCase() === String(unit || "").trim().toLowerCase());
  const raw = flow === "purchase" ? conversion?.purchasePrice : conversion?.salePrice;
  const specific = Number(raw);
  if (raw !== undefined && raw !== null && String(raw).trim() !== "" && Number.isFinite(specific) && specific >= 0) {
    const purchaseUnit = String(product?.purchaseUom || "").trim().toLowerCase();
    const selectedUnit = String(unit || "").trim().toLowerCase();
    const configuredPackagePrice = Number(product?.purchaseUnitPrice);
    // Product Configuration keeps the canonical purchase package price. Prefer it
    // when an old conversion row still contains zero for that same purchase unit.
    if (flow === "purchase" && specific === 0 && configuredPackagePrice > 0 && purchaseUnit && selectedUnit === purchaseUnit) {
      return configuredPackagePrice;
    }
    return specific;
  }
  const basePrice = Number(flow === "purchase" ? (product?.purchasePrice ?? product?.cost ?? 0) : (product?.price ?? 0));
  return basePrice * (productUnitFactor(product, unit) || 1);
}

function purchaseUnits(product) { return productUnits(product, "purchase"); }
function purchaseUnitAllowsFraction(unit, product = null) { return product ? productUnitAllowsFraction(product, unit) : /^(kg|g|mg|t|l|ml|m³|ft³)$/i.test(String(unit || "").trim()); }
function salesUnitAllowsFraction(product, unit) {
  if (!product) return purchaseUnitAllowsFraction(unit);
  return purchaseUnitAllowsFraction(unit, product) || String(unit || "").toLowerCase() !== String(product.stockUom || "Piece").toLowerCase();
}
function purchaseUnitFactor(product, unit) { return productUnitFactor(product, unit); }

function vendorBillForPurchaseOrder(orderId) {
  return state.invoices.find((invoice) => Number(invoice.purchaseOrderId) === Number(orderId) && invoice.kind === "in_invoice" && !["Cancelled", "Reversed"].includes(invoice.status)) || null;
}

function purchaseEmptyLineMarkup() {
  return "";
}

function syncPurchaseEmptyLine() {
  const tbody = document.querySelector("#order-line-items");
  if (!tbody) return;
  tbody.querySelector(".purchase-empty-lines")?.remove();
  if (!tbody.querySelector(".purchase-line, .purchase-special-line")) tbody.innerHTML = purchaseEmptyLineMarkup();
}

function purchaseLineMarkup(line = {}) {
  if (line.type === "section" || line.type === "note") {
    return `<tr class="purchase-special-line ${line.type === "note" ? "purchase-note" : ""}" data-line-type="${line.type}"><td colspan="6"><input data-purchase-description type="text" value="${escapeHtml(line.description || "")}" placeholder="${line.type === "section" ? "Section title" : "Add a note..."}" aria-label="${line.type === "section" ? "Section title" : "Purchase note"}"></td><td><button type="button" class="soft-icon-button" data-action="remove-order-line" aria-label="Remove line">×</button></td></tr>`;
  }
  const selected = salesProducts.find((item) => item.name === line.product || item.sku === line.sku) || (line.blank ? null : selectableProductRecords(null, "purchase")[0] || null);
  const selectableProducts = selectableProductRecords(selected, "purchase");
  const selectedUnit = line.uom || selected?.stockUom || "Piece";
  const units = selected ? purchaseUnits(selected) : [selectedUnit];
  const decimal = ["kg", "L"].includes(selectedUnit);
  const cost = line.price ?? selected?.purchasePrice ?? selected?.cost ?? 0;
  return `<tr class="order-line purchase-line"><td><select data-purchase-product aria-label="Product"><option value="" ${selected ? "" : "selected"}>Select a product...</option>${selectableProducts.map((item) => `<option value="${item.id}" ${item.id === selected?.id ? "selected" : ""}>${escapeHtml(item.name)} · ${escapeHtml(item.sku)}</option>`).join("")}</select><small class="purchase-product-note">${escapeHtml(selected?.sku || selected?.packNote || "")}</small></td><td><input data-line-qty type="number" min="${decimal ? "0.001" : "1"}" step="${decimal ? "0.001" : "1"}" value="${escapeHtml(line.qty ?? 1)}" aria-label="Quantity"></td><td><select class="purchase-unit-select" data-line-uom data-current-unit="${escapeHtml(selectedUnit)}" aria-label="Purchase unit">${units.map((unit) => { const factor = selected && purchaseUnitFactor(selected, unit); return `<option value="${escapeHtml(unit)}" ${unit === selectedUnit ? "selected" : ""} ${factor || !selected ? "" : "disabled"}>${escapeHtml(unit)}${factor || !selected ? "" : " · configure pack"}</option>`; }).join("")}</select></td><td><input data-line-price type="number" min="0" step="0.01" value="${escapeHtml(cost)}" aria-label="Unit price in taka"></td><td><select data-line-tax aria-label="Purchase tax">${invoiceTaxOptions("in_invoice", line.taxId || selected?.purchaseTaxId || null)}</select></td><td class="line-subtotal purchase-line-subtotal">${salesCurrency(line.amount || 0)}</td><td><button type="button" class="soft-icon-button" data-action="remove-order-line" aria-label="Remove line">×</button></td></tr>`;
}

function purchasePaymentTermOptions(extra = []) {
  const configured = (state.invoiceConfig?.collections?.["invoice-payment-terms"] || []).map((term) => typeof term === "string" ? term : term?.name).filter(Boolean);
  return [...new Set(["Immediate", "Cash on delivery", "Credit · 7 days", "Credit · 15 days", "Credit · 30 days", ...configured, ...extra].map((term) => String(term || "").trim()).filter(Boolean))];
}

function purchaseCatalogQuantity(value) {
  return new Intl.NumberFormat("en-US", { maximumFractionDigits: 3, useGrouping: false }).format(Number(value || 0));
}

function purchaseCatalogContext() {
  const context = state.purchaseCatalog?.context;
  return ["sales", "invoice-sales", "invoice-purchase", "inventory-picker", "pos-picker"].includes(context) ? context : "purchase";
}

function purchaseProductCartEntry(productId) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  return product ? (state.purchaseProductCart || []).find((row) => Number(row.productId) === Number(product.id)) || null : null;
}

function persistPurchaseProductCart() {
  try {
    localStorage.setItem("odooFmcgPurchaseProductCart", JSON.stringify(state.purchaseProductCart || []));
    return true;
  } catch {
    showToast("The Purchase cart could not be saved in this browser.");
    return false;
  }
}

function setPurchaseProductCartQuantity(productId, unit, quantity) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  const rawQuantity = Number(quantity);
  if (!product || !Number.isFinite(rawQuantity)) return false;
  const allowsFraction = purchaseUnitAllowsFraction(unit, product);
  const qty = allowsFraction ? rawQuantity : Math.trunc(rawQuantity);
  state.purchaseProductCart = (state.purchaseProductCart || []).filter((row) => Number(row.productId) !== Number(product.id));
  if (qty > 0 && purchaseUnitFactor(product, unit)) state.purchaseProductCart.push({ productId: Number(product.id), qty, unit });
  return persistPurchaseProductCart();
}

function purchaseProductCartCount() {
  return (state.purchaseProductCart || []).reduce((total, row) => total + (purchaseProductCartEntry(row.productId) ? 1 : 0), 0);
}

function purchaseProductCartModalMarkup() {
  const cart = (state.purchaseProductCart || []).map((row) => ({ row, product: salesProducts.find((item) => Number(item.id) === Number(row.productId)) })).filter(({ row, product }) => product && Number(row.qty) > 0 && purchaseUnitFactor(product, row.unit));
  const suppliers = purchaseSupplierOptions();
  const currentSupplier = findPurchaseSupplier(state.purchaseProductCartVendor, suppliers) || defaultPurchaseSupplier() || suppliers[0] || null;
  state.purchaseProductCartVendor = currentSupplier?.name || "";
  const vendorOptions = suppliers.map((supplier) => `<option value="${escapeHtml(supplier.name)}" ${supplier.name === currentSupplier?.name ? "selected" : ""}>${escapeHtml(supplier.name)}</option>`).join("");
  const lines = cart.map(({ row, product }) => {
    const price = purchaseCatalogVendorPrice(product, row.unit, currentSupplier?.name || "");
    return `<div class="purchase-product-cart-line"><span><strong>${escapeHtml(product.name)}</strong><small>${purchaseCatalogQuantity(row.qty)} ${escapeHtml(row.unit)}${product.packNote ? ` · ${escapeHtml(product.packNote)}` : ""}</small></span><strong>${salesCurrency(price * Number(row.qty))}</strong><button type="button" data-purchase-product-cart-remove="${escapeHtml(product.id)}" aria-label="Remove ${escapeHtml(product.name)} from cart">×</button></div>`;
  }).join("");
  const total = cart.reduce((sum, { row, product }) => sum + purchaseCatalogVendorPrice(product, row.unit, currentSupplier?.name || "") * Number(row.qty), 0);
  return `<header class="modal-header purchase-product-cart-header"><div><h2>Purchase Cart</h2><p>${cart.length} product line${cart.length === 1 ? "" : "s"} · Create an RFQ for these items</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body purchase-product-cart-body"><label class="purchase-product-cart-vendor"><span>Vendor</span><select data-purchase-product-cart-vendor ${suppliers.length ? "" : "disabled"}>${vendorOptions || '<option value="">No approved vendor available</option>'}</select></label>${cart.length ? `<div class="purchase-product-cart-lines">${lines}</div><div class="purchase-product-cart-total"><span>Estimated total</span><strong>${salesCurrency(total)}</strong></div>` : `<p class="purchase-product-cart-empty">Your cart is empty. Add products from the catalog to prepare a purchase RFQ.</p>`}${suppliers.length ? "" : `<p class="purchase-product-cart-note">Approve a supplier in Contacts before creating an RFQ.</p>`}</div><footer class="modal-footer purchase-product-cart-footer"><button type="button" class="action-button secondary" data-action="close-modal">Continue shopping</button><button type="button" class="action-button" data-purchase-product-cart-create ${cart.length && currentSupplier ? "" : "disabled aria-disabled=\"true\""}>Create RFQ</button></footer>`;
}

function openPurchaseProductCartModal() {
  openModal(purchaseProductCartModalMarkup());
  modalRoot.querySelector(".modal-card")?.classList.add("purchase-product-cart-modal");
}

function createPurchaseRfqFromProductCart() {
  const supplier = findPurchaseSupplier(state.purchaseProductCartVendor, purchaseSupplierOptions());
  if (!supplier) { showToast("Choose an approved vendor before creating the RFQ."); return; }
  const lines = (state.purchaseProductCart || []).map((row) => {
    const product = salesProducts.find((item) => Number(item.id) === Number(row.productId));
    return product && purchaseUnitFactor(product, row.unit) ? {
      product: product.name,
      sku: product.sku,
      qty: Number(row.qty),
      uom: row.unit,
      price: purchaseCatalogVendorPrice(product, row.unit, supplier.name),
    } : null;
  }).filter((line) => line && line.qty > 0);
  if (!lines.length) { showToast("Add at least one configured product to the Purchase cart."); return; }
  state.purchaseProductCartVendor = supplier.name;
  openOrderModal(null, null, { vendor: supplier.name, contactId: supplier.contactId, lines, cartPrefill: true });
  showToast("Cart items added to a new RFQ. Review the vendor and quantities before saving.");
}

function purchaseCatalogUsesSalesLines() {
  return ["sales", "invoice-sales"].includes(purchaseCatalogContext());
}

function purchaseCatalogIsInvoice() {
  return purchaseCatalogContext().startsWith("invoice-");
}

function purchaseCatalogFlow() {
  const context = purchaseCatalogContext();
  if (context === "invoice-purchase") return "purchase";
  if (["invoice-sales", "pos-picker"].includes(context)) return "sales";
  return context === "sales" ? currentSalesProductFlow() : "purchase";
}

function purchaseCatalogVendorName() {
  if (purchaseCatalogContext() === "invoice-purchase") return String(document.querySelector("#invoice-form [name='partner']")?.value || state.invoiceEditor?.partner || "").trim();
  if (purchaseCatalogContext() !== "purchase") return "";
  return String(document.querySelector("#order-vendor")?.value || state.purchaseEditor?.vendor || "").trim();
}

function purchaseCatalogVendorOptions() {
  const options = new Map();
  const add = (key, name, image = "") => {
    const normalizedName = String(name || "").trim();
    const normalizedKey = String(key || "").trim();
    if (normalizedKey && normalizedName && !options.has(normalizedKey)) options.set(normalizedKey, { key: normalizedKey, name: normalizedName, image });
  };
  productSupplierOptions().forEach((supplier) => add(supplier.key, supplier.name));
  vendors.forEach((supplier) => add(supplierFilterKey(supplier), supplier.name, supplier.image || supplier.avatar || ""));
  purchaseSupplierOptions({ includeUnapproved: true }).forEach((supplier) => {
    const key = supplierFilterKey(supplier);
    const contact = (state.contacts || []).find((item) => [supplier.contactId, supplier.id, supplier.supplierId].some((id) => id && String(item.id) === String(id)));
    add(key, supplier.name, supplier.image || supplier.avatar || contact?.image || contact?.avatar || "");
  });
  salesProducts.forEach((product) => (product.vendorPrices || []).forEach((row) => {
    const name = String(row.vendor || "").trim();
    const supplier = vendors.find((item) => String(item.name || "").toLowerCase() === name.toLowerCase());
    add(supplier ? supplierFilterKey(supplier) : `name:${name.toLowerCase()}`, name, supplier?.image || supplier?.avatar || "");
  }));
  return [...options.values()].sort((first, second) => first.name.localeCompare(second.name));
}

function purchaseCatalogVendorAvatarMarkup(vendor) {
  if (vendor.image) return `<img src="${escapeHtml(vendor.image)}" alt="">`;
  return `<span>${escapeHtml(initials(vendor.name))}</span>`;
}

function purchaseCatalogVendorMenuMarkup() {
  const query = String(state.purchaseCatalog?.vendorSearch || "").trim().toLowerCase();
  const allVendors = purchaseCatalogVendorOptions();
  const filtered = allVendors.filter((vendor) => !query || vendor.name.toLowerCase().includes(query));
  const limit = query || state.purchaseCatalog?.showAllVendors ? filtered.length : 8;
  const shown = filtered.slice(0, limit);
  const activeKey = state.purchaseCatalog?.supplierKey || "all";
  const allRow = `<button type="button" class="purchase-catalog-vendor-option ${activeKey === "all" ? "is-active" : ""}" data-purchase-catalog-vendor-option="all"><span class="purchase-catalog-vendor-avatar">⇄</span><span><strong>All vendors</strong><small>Show every purchase product</small></span></button>`;
  const vendorRows = shown.map((vendor) => `<button type="button" class="purchase-catalog-vendor-option ${String(activeKey) === vendor.key ? "is-active" : ""}" data-purchase-catalog-vendor-option="${escapeHtml(vendor.key)}"><span class="purchase-catalog-vendor-avatar">${purchaseCatalogVendorAvatarMarkup(vendor)}</span><span><strong>${escapeHtml(vendor.name)}</strong></span></button>`).join("");
  const more = !state.purchaseCatalog?.showAllVendors && filtered.length > shown.length ? `<button type="button" class="purchase-catalog-vendor-more" data-purchase-catalog-vendor-more>Search More…</button>` : "";
  return `<div class="purchase-catalog-vendor-menu" data-purchase-catalog-vendor-menu ${state.purchaseCatalog?.vendorMenuOpen ? "" : "hidden"}><label class="purchase-catalog-vendor-menu-search"><span aria-hidden="true">⌕</span><input type="search" value="${escapeHtml(state.purchaseCatalog?.vendorSearch || "")}" placeholder="Search vendors..." aria-label="Search vendors" data-purchase-catalog-vendor-search></label><div class="purchase-catalog-vendor-options">${allRow}${vendorRows || `<p>${query ? "No vendors match this search." : "No supplier contacts are available."}</p>`}</div>${more}</div>`;
}

function refreshPurchaseCatalogVendorMenu({ keepFocus = false } = {}) {
  const menu = modalRoot.querySelector("[data-purchase-catalog-vendor-menu]");
  if (!menu || !state.purchaseCatalog) return;
  menu.outerHTML = purchaseCatalogVendorMenuMarkup();
  const updated = modalRoot.querySelector("[data-purchase-catalog-vendor-menu]");
  if (updated) updated.hidden = !state.purchaseCatalog.vendorMenuOpen;
  modalRoot.querySelector(".purchase-catalog-vendor-picker")?.classList.toggle("is-open", Boolean(state.purchaseCatalog.vendorMenuOpen));
  modalRoot.querySelector("[data-purchase-catalog-vendor-open]")?.setAttribute("aria-expanded", String(Boolean(state.purchaseCatalog.vendorMenuOpen)));
  if (keepFocus) {
    const input = updated?.querySelector("[data-purchase-catalog-vendor-search]");
    input?.focus({ preventScroll: true });
    input?.setSelectionRange(input.value.length, input.value.length);
  }
}

function refreshPurchaseCatalogVendorChip() {
  const key = state.purchaseCatalog?.supplierKey || "all";
  const selected = purchaseCatalogVendorOptions().find((vendor) => vendor.key === key);
  const label = modalRoot.querySelector("[data-purchase-catalog-vendor-label]");
  if (label) label.textContent = selected?.name || "All vendors";
  const clear = modalRoot.querySelector("[data-purchase-catalog-vendor-clear]");
  if (clear) clear.hidden = key === "all";
  modalRoot.querySelector("[data-purchase-catalog-vendor-open]")?.setAttribute("aria-expanded", String(Boolean(state.purchaseCatalog?.vendorMenuOpen)));
  modalRoot.querySelector(".purchase-catalog-vendor-picker")?.classList.toggle("is-open", Boolean(state.purchaseCatalog?.vendorMenuOpen));
}

function purchaseCatalogVendorPrice(product, unit, vendorName = purchaseCatalogVendorName()) {
  const vendorRow = (product.vendorPrices || []).find((row) => String(row.vendor || "").trim().toLowerCase() === String(vendorName || "").trim().toLowerCase());
  const rowUnit = String(vendorRow?.unit || product.purchaseUom || product.stockUom || "").trim().toLowerCase();
  const targetUnit = String(unit || product.stockUom || "").trim().toLowerCase();
  const rawVendorPrice = vendorRow?.unitPrice ?? vendorRow?.purchasePrice ?? vendorRow?.price;
  const vendorUnitPrice = Number(rawVendorPrice);
  if (vendorRow && rawVendorPrice !== undefined && rawVendorPrice !== null && String(rawVendorPrice).trim() !== "" && Number.isFinite(vendorUnitPrice) && vendorUnitPrice >= 0) {
    if (rowUnit === targetUnit) return vendorUnitPrice;
    if (!vendorRow.unit && productUnitFactor(product, unit)) return vendorUnitPrice * Number(productUnitFactor(product, unit) || 1);
  }
  return productUnitPrice(product, unit, "purchase");
}

function purchaseCatalogOrderLines() {
  if (purchaseCatalogContext() === "invoice-sales" || purchaseCatalogContext() === "invoice-purchase") {
    const kind = document.querySelector("#invoice-form")?.dataset.kind || "out_invoice";
    return [...(document.querySelectorAll("#invoice-line-items .invoice-line") || [])].map((row) => {
      const productId = Number(row.querySelector("[data-invoice-product]")?.value || 0);
      const product = salesProducts.find((item) => Number(item.id) === productId);
      return product ? {
        row,
        product,
        unit: row.querySelector("[data-invoice-uom]")?.value || product.stockUom || "Piece",
        qty: Number(row.querySelector("[data-invoice-qty]")?.value || 0),
        price: Number(row.querySelector("[data-invoice-price]")?.value || 0),
        kind,
      } : null;
    }).filter(Boolean);
  }
  if (purchaseCatalogContext() === "sales") {
    return [...(document.querySelectorAll("#sale-line-items .sale-line") || [])].map((row) => {
      const productId = Number(row.querySelector("[data-sale-product]")?.value || 0);
      const product = salesProducts.find((item) => Number(item.id) === productId);
      return product ? {
        row,
        product,
        unit: row.querySelector("[data-sale-uom]")?.value || product.stockUom || "Piece",
        qty: Number(row.querySelector("[data-sale-qty]")?.value || 0),
        price: Number(row.querySelector("[data-sale-price]")?.value || 0),
      } : null;
    }).filter(Boolean);
  }
  return [...(document.querySelectorAll("#order-line-items .purchase-line") || [])].map((row) => {
    const productId = Number(row.querySelector("[data-purchase-product]")?.value || 0);
    const product = salesProducts.find((item) => Number(item.id) === productId);
    return product ? {
      row,
      product,
      unit: row.querySelector("[data-line-uom]")?.value || product.stockUom || "Piece",
      qty: Number(row.querySelector("[data-line-qty]")?.value || 0),
      price: Number(row.querySelector("[data-line-price]")?.value || 0),
    } : null;
  }).filter(Boolean);
}

function purchaseCatalogProductSelection(product, unit = "") {
  const matches = purchaseCatalogOrderLines().filter((line) => Number(line.product.id) === Number(product.id) && (!unit || String(line.unit).toLowerCase() === String(unit).toLowerCase()));
  return matches.length ? {
    lines: matches,
    unit: matches[0].unit,
    qty: matches.reduce((sum, line) => sum + line.qty, 0),
    price: matches[0].price,
  } : null;
}

function purchaseCatalogUnitOptions(product, selectedUnit) {
  const units = [...new Set([product.stockUom || "Piece", ...(purchaseCatalogFlow() !== "purchase" ? product.saleUnits || productUnits(product, "sale") : purchaseUnits(product))])];
  return units.map((unit) => {
    const factor = purchaseCatalogFlow() !== "purchase" ? productUnitFactor(product, unit) : purchaseUnitFactor(product, unit);
    return `<option value="${escapeHtml(unit)}" ${String(unit).toLowerCase() === String(selectedUnit).toLowerCase() ? "selected" : ""} ${factor ? "" : "disabled"}>${escapeHtml(unit)}${factor ? "" : " · configure pack"}</option>`;
  }).join("");
}

function purchaseCatalogImage(product) {
  if (product.image) return `<img src="${escapeHtml(product.image)}" alt="${escapeHtml(product.name)}">`;
  const name = String(product.name || "Product");
  const fallback = /mosquito|coil/i.test(name) ? "🦟" : /detergent/i.test(name) ? "🧺" : /soap/i.test(name) ? "🧼" : /shampoo/i.test(name) ? "🧴" : name.trim().slice(0, 1).toLocaleUpperCase();
  return `<span aria-hidden="true">${escapeHtml(fallback || "P")}</span>`;
}

function renderSharedProductCatalogCardFrame(product, { isSelected = false, topMarkup = "", titleMarkup = "", variant = "", priceMarkup = "", packageMarkup = "", stockMarkup = "", demandMarkup = "", detailsMarkup = "", footerMarkup = "" } = {}) {
  const productName = escapeHtml(product.name || "Product");
  const title = titleMarkup || `<strong>${productName}</strong>`;
  const variantMarkup = variant ? `<div class="purchase-catalog-variant-row"><span class="purchase-catalog-variant-label">Variant</span><strong class="purchase-catalog-variant">${escapeHtml(variant)}</strong></div>` : "";
  return `<article class="purchase-catalog-card shared-catalog-card ${topMarkup ? "shared-inventory-catalog-card" : ""} ${isSelected ? "is-selected" : ""}">${topMarkup}<header><div>${title}<small>${escapeHtml(product.sku || "")}</small></div><span class="purchase-catalog-image" aria-hidden="true">${purchaseCatalogImage(product)}</span></header>${priceMarkup}${variantMarkup}${packageMarkup}${stockMarkup}${demandMarkup}${detailsMarkup}<footer>${footerMarkup}</footer></article>`;
}

function inventoryProductCardStockMarkup(product, forecast) {
  const stockUnit = product.stockUom || "Units";
  const onHand = Number(product.onHand || 0);
  const breakdown = inventoryStockCartonBreakdown(product, onHand);
  const forecastBreakdown = inventoryStockCartonBreakdown(product, forecast);
  const onHandLabel = breakdown.cartonUnit
    ? `${breakdown.cartons} Carton · ${breakdown.pieces} ${String(stockUnit).toLowerCase() === "piece" ? "Piece" : stockUnit}`
    : `${purchaseCatalogQuantity(onHand)} ${stockUnit}`;
  const forecastLabel = forecastBreakdown.cartonUnit
    ? `${forecastBreakdown.cartons} Carton · ${forecastBreakdown.pieces} ${String(stockUnit).toLowerCase() === "piece" ? "Piece" : stockUnit}`
    : `${purchaseCatalogQuantity(forecast)} ${stockUnit}`;
  const breakdownTitle = breakdown.cartonUnit ? `1 ${breakdown.cartonUnit} = ${purchaseCatalogQuantity(breakdown.piecesPerCarton)} ${breakdown.unit}` : `On-hand quantity in ${stockUnit}`;
  return `<div class="purchase-catalog-stock"><span title="${escapeHtml(breakdownTitle)}"><strong>${escapeHtml(onHandLabel)}</strong> on hand</span><span>/ <strong>${escapeHtml(forecastLabel)}</strong> forecasted</span></div>`;
}

function purchaseCatalogAvailabilityMarkup(product) {
  const unit = product.stockUom || "Units";
  const onHand = Number(product.onHand || 0);
  const incoming = Number(inventoryIncoming(product) || 0);
  const outgoing = Number(inventoryOutgoing(product) || 0);
  const forecast = onHand + incoming - outgoing;
  const breakdown = inventoryStockCartonBreakdown(product, onHand);
  const balances = (state.inventoryBalances || []).filter((row) => row.sku === product.sku && Number(row.qty || 0) !== 0);
  const locations = balances.length
    ? `<div class="purchase-catalog-availability-locations"><h3>Locations</h3>${balances.map((row) => `<div><span>${escapeHtml(row.location || "WH/Stock")}</span><strong>${purchaseCatalogQuantity(row.qty)} ${escapeHtml(unit)}</strong></div>`).join("")}</div>`
    : "";
  const packSummary = breakdown.cartonUnit
    ? `${escapeHtml(breakdown.cartons)} ${escapeHtml(breakdown.cartonUnit)} · ${escapeHtml(breakdown.pieces)} ${escapeHtml(breakdown.unit)} (1 ${escapeHtml(breakdown.cartonUnit)} = ${purchaseCatalogQuantity(breakdown.piecesPerCarton)} ${escapeHtml(breakdown.unit)})`
    : `${purchaseCatalogQuantity(onHand)} ${escapeHtml(unit)}`;
  return `<div class="purchase-catalog-availability-overlay" data-purchase-catalog-availability-overlay><button type="button" class="purchase-catalog-availability-backdrop" data-purchase-catalog-availability-close aria-label="Close availability"></button><section class="purchase-catalog-availability-dialog" role="dialog" aria-modal="true" aria-labelledby="purchase-catalog-availability-title"><header><div><small>PRODUCT AVAILABILITY</small><h2 id="purchase-catalog-availability-title">${escapeHtml(product.name || "Product")}</h2><span>${escapeHtml(product.sku || "")}</span></div><button type="button" data-purchase-catalog-availability-close aria-label="Close">×</button></header><div class="purchase-catalog-availability-metrics"><div><span>On Hand</span><strong>${purchaseCatalogQuantity(onHand)} ${escapeHtml(unit)}</strong><small>${packSummary}</small></div><div><span>Free to Use</span><strong>${purchaseCatalogQuantity(Math.max(0, onHand - outgoing))} ${escapeHtml(unit)}</strong></div><div><span>Incoming</span><strong>${purchaseCatalogQuantity(incoming)} ${escapeHtml(unit)}</strong></div><div><span>Outgoing</span><strong>${purchaseCatalogQuantity(outgoing)} ${escapeHtml(unit)}</strong></div><div><span>Forecasted</span><strong>${purchaseCatalogQuantity(forecast)} ${escapeHtml(unit)}</strong></div></div>${locations}<footer><button type="button" class="action-button secondary" data-purchase-catalog-availability-close>Close</button></footer></section></div>`;
}

function showPurchaseCatalogAvailability(productId) {
  const product = salesProducts.find((item) => String(item.id) === String(productId));
  const root = modalRoot.querySelector(".purchase-catalog-enterprise");
  if (!product) return;
  if (!root && state.page === "products" && state.module === "purchase") {
    openModal(purchaseCatalogAvailabilityMarkup(product));
    modalRoot.querySelector(".modal-card")?.classList.add("purchase-product-availability-modal");
    modalRoot.querySelector("[data-purchase-catalog-availability-close]")?.focus({ preventScroll: true });
    return;
  }
  if (!root) return;
  root.querySelector("[data-purchase-catalog-availability-overlay]")?.remove();
  root.insertAdjacentHTML("beforeend", purchaseCatalogAvailabilityMarkup(product));
  root.querySelector("[data-purchase-catalog-availability-close]")?.focus({ preventScroll: true });
}

function purchaseCatalogProductCard(product, { purchaseProductsPage = false } = {}) {
  const selection = purchaseProductsPage ? purchaseProductCartEntry(product.id) : purchaseCatalogProductSelection(product);
  const flow = purchaseProductsPage ? "purchase" : purchaseCatalogFlow();
  const pickerOnly = !purchaseProductsPage && Boolean(state.purchaseCatalog?.pickerOnly);
  const units = [...new Set([product.stockUom || "Piece", ...(flow === "purchase" ? purchaseUnits(product) : product.saleUnits || productUnits(product, "sale"))])];
  const preferredUnit = pickerOnly ? (product.stockUom || "Piece") : selection?.unit || (units.find((unit) => String(unit).toLowerCase() === String(flow === "purchase" ? product.purchaseUom || "" : product.saleUom || "").toLowerCase()) || product.stockUom || units[0]);
  const selectedUnit = purchaseProductsPage ? (selection?.unit || preferredUnit) : state.purchaseCatalog?.units?.[product.id] || preferredUnit;
  const activeSelection = pickerOnly ? null : purchaseProductsPage ? selection : purchaseCatalogProductSelection(product, selectedUnit);
  const offer = flow !== "purchase" && purchaseCatalogContext() === "sales" ? salesProductOffer(product) : null;
  const unitPrice = activeSelection?.price ?? (flow === "purchase" && !pickerOnly ? purchaseCatalogVendorPrice(product, selectedUnit) : purchaseCatalogContext() === "invoice-sales" ? productSalesUnitPrice(product, selectedUnit) : offer ? salesProductOfferPrice(product, offer, selectedUnit) : productUnitPrice(product, selectedUnit, "sale"));
  const stockUnit = product.stockUom || "Piece";
  const forecast = Number(product.onHand || 0) + inventoryIncoming(product) - inventoryOutgoing(product);
  const demand = product.monthlyDemand ?? product.demandPerMonth ?? product.averageMonthlyDemand;
  const variant = product.variantLabel || product.variant || product.model || product.productClass || "";
  const allowsFraction = flow === "purchase" ? purchaseUnitAllowsFraction(selectedUnit, product) : salesUnitAllowsFraction(product, selectedUnit);
  const unitSelect = pickerOnly ? "" : `<select class="purchase-catalog-unit" ${purchaseProductsPage ? `data-purchase-product-cart-unit="${escapeHtml(product.id)}"` : `data-purchase-catalog-unit="${escapeHtml(product.id)}"`} aria-label="${flow === "purchase" ? "Purchase" : "Sales"} unit for ${escapeHtml(product.name)}">${purchaseCatalogUnitOptions(product, selectedUnit)}</select>`;
  const controls = purchaseProductsPage
    ? activeSelection
      ? `<div class="purchase-catalog-quantity-control"><button type="button" data-purchase-product-cart-quantity="minus" data-product-id="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="Remove one ${escapeHtml(product.name)} from cart">−</button><input type="number" min="${allowsFraction ? "0.001" : "1"}" step="${allowsFraction ? "0.001" : "1"}" value="${purchaseCatalogQuantity(activeSelection.qty)}" data-purchase-product-cart-quantity-input="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="${escapeHtml(product.name)} cart quantity">${unitSelect}<button type="button" data-purchase-product-cart-quantity="plus" data-product-id="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="Add one ${escapeHtml(product.name)} to cart">+</button></div>`
      : `<button type="button" class="purchase-catalog-add" data-purchase-product-cart-add="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.2 11.2h10.9l2-7.4H6.1M9 19a1 1 0 1 0 0 .1M17 19a1 1 0 1 0 0 .1"/></svg>Add to Cart</button>`
    : pickerOnly
    ? `<button type="button" class="purchase-catalog-add shared-catalog-select-product" data-purchase-catalog-product="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}">Select product</button>`
    : activeSelection
    ? `<div class="purchase-catalog-quantity-control"><button type="button" data-purchase-catalog-qty="minus" data-product-id="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="Decrease ${escapeHtml(product.name)} quantity">−</button><input type="number" min="${allowsFraction ? "0.001" : "1"}" step="${allowsFraction ? "0.001" : "1"}" value="${purchaseCatalogQuantity(activeSelection.qty)}" data-purchase-catalog-quantity="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="${escapeHtml(product.name)} quantity">${unitSelect}<button type="button" data-purchase-catalog-qty="plus" data-product-id="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}" aria-label="Increase ${escapeHtml(product.name)} quantity">+</button></div>`
    : `<button type="button" class="purchase-catalog-add" data-purchase-catalog-product="${escapeHtml(product.id)}" data-unit="${escapeHtml(selectedUnit)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.2 11.2h10.9l2-7.4H6.1M9 19a1 1 0 1 0 0 .1M17 19a1 1 0 1 0 0 .1"/></svg>Add to Cart</button>`;
  const packageFactor = flow === "purchase" && !pickerOnly ? purchaseUnitFactor(product, selectedUnit) : productUnitFactor(product, selectedUnit);
  const packNote = product.packNote || (packageFactor && String(selectedUnit).toLowerCase() !== String(stockUnit).toLowerCase() ? `${purchaseCatalogQuantity(packageFactor)} ${stockUnit} per ${selectedUnit}` : "");
  const packageDetail = [selectedUnit, packNote].filter(Boolean).join(" · ");
  const openProductMenuId = purchaseProductsPage ? state.purchaseProductsOpenMenuId : state.purchaseCatalog?.openProductMenuId;
  const pageSelectFavorite = purchaseProductsPage ? `<input class="inventory-product-select" type="checkbox" data-select-row="${escapeHtml(product.id)}" aria-label="Select ${escapeHtml(product.name)}" ${state.selected.has(Number(product.id)) ? "checked" : ""}><button type="button" class="inventory-product-card-favorite star-button ${product.favorite ? "is-favorite" : ""}" data-catalog-product-favorite="${escapeHtml(product.id)}" aria-label="${product.favorite ? "Remove from" : "Add to"} favorites" aria-pressed="${Boolean(product.favorite)}">${product.favorite ? "★" : "☆"}</button>` : "";
  const cardActions = pickerOnly ? "" : `<div class="purchase-catalog-card-actions ${purchaseProductsPage ? "purchase-products-card-actions" : ""}">${pageSelectFavorite}<button type="button" class="purchase-catalog-card-menu-button" data-purchase-catalog-card-menu="${escapeHtml(product.id)}" aria-label="More actions for ${escapeHtml(product.name)}" aria-expanded="${String(openProductMenuId) === String(product.id)}">⋮</button><div class="purchase-catalog-card-menu" role="menu" ${String(openProductMenuId) === String(product.id) ? "" : "hidden"}><button type="button" role="menuitem" data-purchase-catalog-card-action="edit" data-product-id="${escapeHtml(product.id)}">Edit</button><button type="button" role="menuitem" data-purchase-catalog-card-action="availability" data-product-id="${escapeHtml(product.id)}">View Availability</button><button type="button" role="menuitem" data-purchase-catalog-card-action="favorite" data-product-id="${escapeHtml(product.id)}">${product.favorite ? "★ Remove from Favorites" : "☆ Add to Favorites"}</button></div></div>`;
  return renderSharedProductCatalogCardFrame(product, {
    topMarkup: cardActions,
    titleMarkup: purchaseProductsPage ? `<button type="button" class="shared-catalog-title-button" data-edit-sales-product="${escapeHtml(product.id)}"><strong>${escapeHtml(salesProductTitle(product))}</strong></button>` : "",
    isSelected: Boolean(activeSelection),
    variant,
    priceMarkup: `<strong class="purchase-catalog-price">${salesCurrency(unitPrice)} <small>/ ${escapeHtml(selectedUnit)}</small></strong>`,
    stockMarkup: inventoryProductCardStockMarkup(product, forecast),
    demandMarkup: `<small class="purchase-catalog-demand">Demand: ${demand === undefined || demand === null || demand === "" ? "—" : purchaseCatalogQuantity(demand)} ${escapeHtml(stockUnit)} / month</small>`,
    packageMarkup: packageDetail ? `<small class="purchase-catalog-pack-note">${escapeHtml(packageDetail)}</small>` : "",
    detailsMarkup: pickerOnly ? "" : inventoryProductCardGiftMarkup(product),
    footerMarkup: controls,
  });
}

function purchaseCatalogSupplierMatches(product, supplierKey) {
  if (!supplierKey || supplierKey === "all") return true;
  const option = purchaseCatalogVendorOptions().find((item) => item.key === supplierKey);
  const supplier = vendors.find((item) => String(item.id) === String(supplierKey));
  const supplierName = String(option?.name || supplier?.name || "").trim().toLowerCase();
  if (String(product.supplierId || "") === String(supplierKey)) return true;
  const names = [productPrimarySupplierName(product), ...(product.vendorPrices || []).map((row) => row.vendor)].map((name) => String(name || "").trim().toLowerCase());
  if (!product.supplierId && !names.some(Boolean)) return true;
  return Boolean(supplierName && names.includes(supplierName));
}

function purchaseCatalogBaseProducts() {
  const catalog = state.purchaseCatalog || {};
  const flow = purchaseCatalogFlow();
  const baseProducts = catalog.pickerOnly
    ? salesProducts.filter((product) => !product.archived && (purchaseCatalogContext() === "pos-picker" ? productChannelEnabled(product, "pos") : inventoryStockProductType(product) === "Goods"))
    : selectableProductRecords(null, flow);
  return baseProducts.filter((product) => purchaseCatalogSupplierMatches(product, catalog.supplierKey) && (!catalog.suggest || inventoryNeedsReorder(product)));
}

function purchaseCatalogFilteredProducts() {
  const catalog = state.purchaseCatalog || {};
  const query = String(catalog.search || "").trim().toLowerCase();
  return purchaseCatalogBaseProducts().filter((product) => {
    if (catalog.category && catalog.category !== "all" && String(product.category || "Uncategorized").trim() !== catalog.category) return false;
    return !query || [product.name, product.sku, product.category, product.variantLabel, product.variant, product.model, product.packNote, productPrimarySupplierName(product), ...(product.vendorPrices || []).map((row) => row.vendor)].some((value) => String(value || "").toLowerCase().includes(query));
  }).sort((first, second) => String(first.name || "").localeCompare(String(second.name || "")));
}

function purchaseCatalogCategories() {
  return sharedProductCategoryNames(purchaseCatalogBaseProducts());
}

function purchaseCatalogOrderSummaryMarkup() {
  if (state.purchaseCatalog?.pickerOnly) return `<section class="purchase-catalog-order-card shared-catalog-picker-summary"><header><strong>${purchaseCatalogContext() === "pos-picker" ? "Point of Sale" : "Inventory"}</strong></header><div class="purchase-catalog-order-lines"><p>Select a product from the shared Inventory catalog.</p></div><footer><span>Product master · SKU and stock unit</span></footer></section>`;
  const lines = purchaseCatalogOrderLines();
  const salesContext = purchaseCatalogContext() === "sales";
  const invoiceContext = purchaseCatalogIsInvoice();
  const ref = invoiceContext ? (document.querySelector(".sales-document-heading h2")?.textContent || "New Invoice") : salesContext ? (document.querySelector("#sale-order-form [name='reference']")?.value || "New Sales Order") : (document.querySelector("#order-reference")?.value || "New Purchase Order");
  const total = document.querySelector(invoiceContext ? "#invoice-total" : salesContext ? "#sale-order-total" : "#order-total")?.textContent || salesCurrency(0);
  const grouped = new Map();
  lines.forEach(({ product, unit, qty, price }) => {
    const key = `${product.id}::${unit}`;
    const existing = grouped.get(key) || { product, unit, qty: 0, price };
    existing.qty += qty;
    grouped.set(key, existing);
  });
  const items = [...grouped.values()];
  return `<section class="purchase-catalog-order-card"><header><strong>${escapeHtml(ref)}</strong>${invoiceContext ? "" : `<button type="button" data-purchase-catalog-section>Add Section</button>`}</header><div class="purchase-catalog-order-lines">${items.length ? items.map((line) => `<div><span>${escapeHtml(line.product.name)}<small>${purchaseCatalogQuantity(line.qty)} ${escapeHtml(line.unit)}${line.product.packNote ? ` · ${escapeHtml(line.product.packNote)}` : ""}</small></span><strong>${salesCurrency(line.price * line.qty)}</strong></div>`).join("") : `<p>No products added yet.</p>`}</div><footer><span>${items.length} product line${items.length === 1 ? "" : "s"}</span><strong>Total <b>${escapeHtml(total)}</b></strong></footer></section>`;
}

function refreshPurchaseCatalogResults() {
  const root = modalRoot.querySelector(".purchase-catalog-modal-card");
  if (!root || !state.purchaseCatalog) return;
  const allProducts = purchaseCatalogFilteredProducts();
  const pageSize = 20;
  const totalPages = Math.max(1, Math.ceil(allProducts.length / pageSize));
  state.purchaseCatalog.page = Math.min(Math.max(1, Number(state.purchaseCatalog.page || 1)), totalPages);
  const start = (state.purchaseCatalog.page - 1) * pageSize;
  const pageProducts = allProducts.slice(start, start + pageSize);
  const grid = root.querySelector("[data-purchase-catalog-results]");
  const count = root.querySelector("[data-purchase-catalog-count]");
  const pager = root.querySelector("[data-purchase-catalog-pager]");
  const summary = root.querySelector("[data-purchase-catalog-order-summary]");
  const empty = state.purchaseCatalog.suggest ? "No replenishment suggestions" : "No products match these filters";
  if (grid) grid.innerHTML = pageProducts.length ? pageProducts.map(purchaseCatalogProductCard).join("") : `<div class="purchase-catalog-empty"><strong>${empty}</strong><p>Choose another category or vendor, or clear the search.</p></div>`;
  if (count) count.textContent = allProducts.length ? `${start + 1}-${Math.min(start + pageSize, allProducts.length)} / ${allProducts.length}` : "0 / 0";
  if (pager) pager.innerHTML = `<button type="button" data-purchase-catalog-page="previous" aria-label="Previous page" ${state.purchaseCatalog.page <= 1 ? "disabled" : ""}>‹</button><span>${state.purchaseCatalog.page} / ${totalPages}</span><button type="button" data-purchase-catalog-page="next" aria-label="Next page" ${state.purchaseCatalog.page >= totalPages ? "disabled" : ""}>›</button>`;
  if (summary) summary.innerHTML = purchaseCatalogOrderSummaryMarkup();
}

function renderPurchaseCatalogModal() {
  const salesContext = purchaseCatalogContext() === "sales" || purchaseCatalogContext() === "invoice-sales";
  const pickerOnly = Boolean(state.purchaseCatalog?.pickerOnly);
  const inventoryContext = ["inventory-picker", "pos-picker"].includes(purchaseCatalogContext());
  const invoiceContext = purchaseCatalogIsInvoice();
  const purchaseBackLabel = state.purchaseEditor ? "Back to Purchase Order" : "Back to Products";
  const documentLabel = pickerOnly ? (state.purchaseCatalog.parentModal ? "Back to form" : "Back") : invoiceContext ? "Back to Invoice" : salesContext ? (state.salesEditor?.id ? "Back to Sales Order" : "Back to Quotation") : purchaseBackLabel;
  const appName = invoiceContext ? "Invoicing" : salesContext ? "Sales" : inventoryContext ? "Inventory" : "Purchase";
  const navigationItems = inventoryContext ? ["Overview", "Operations", "Products", "Reporting", "Configuration"] : salesContext ? ["Orders", "Products", "Promotions", "Commissions", "Reporting", "Configuration"] : invoiceContext ? ["Customers", "Vendors", "Products", "Reporting", "Configuration"] : ["Orders", "Products", "Reporting", "Configuration"];
  const navigationMarkup = navigationItems.map((item) => `<span>${item}</span>`).join("");
  const categoryProducts = purchaseCatalogBaseProducts();
  const categoriesMarkup = purchaseCatalogCategories().map((category) => sharedProductCategoryButton(category, {
    selected: state.purchaseCatalog.category === category,
    count: categoryProducts.filter((product) => String(product.category || "Uncategorized").trim() === category).length,
    modal: true,
  })).join("");
  const supplierOptions = purchaseCatalogVendorOptions();
  const selectedVendor = purchaseCatalogVendorName();
  const matchingVendor = supplierOptions.find((item) => String(item.name).toLowerCase() === selectedVendor.toLowerCase());
  if (!state.purchaseCatalog.supplierKey && matchingVendor) state.purchaseCatalog.supplierKey = matchingVendor.key;
  const allVendors = !state.purchaseCatalog.supplierKey || state.purchaseCatalog.supplierKey === "all";
  const selectedVendorLabel = supplierOptions.find((vendor) => vendor.key === (state.purchaseCatalog.supplierKey || "all"))?.name || "All vendors";
  const vendorFilter = salesContext || pickerOnly ? "" : `<div class="purchase-catalog-vendor-picker"><span class="purchase-catalog-vendor-chip"><button type="button" class="purchase-catalog-vendor-open" data-purchase-catalog-vendor-open aria-haspopup="listbox" aria-expanded="${Boolean(state.purchaseCatalog.vendorMenuOpen)}"><b>Vendor</b><span data-purchase-catalog-vendor-label>${escapeHtml(selectedVendorLabel)}</span><i aria-hidden="true">▾</i></button><button type="button" data-purchase-catalog-vendor-clear aria-label="Clear vendor filter" ${allVendors ? "hidden" : ""}>×</button></span>${purchaseCatalogVendorMenuMarkup()}</div>`;
  const suggestMarkup = pickerOnly ? "" : `<section class="purchase-catalog-suggest"><span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18h6m-5 3h4m-2-19a7 7 0 0 0-4 12.8c.8.5 1 1.2 1 2.2h6c0-1 .2-1.7 1-2.2A7 7 0 0 0 12 2z"/></svg><strong>SUGGEST</strong></span><button type="button" class="purchase-catalog-switch ${state.purchaseCatalog.suggest ? "is-on" : ""}" data-purchase-catalog-suggest aria-pressed="${Boolean(state.purchaseCatalog.suggest)}"><i></i></button></section>`;
  const catalogDescription = pickerOnly ? "Shared Inventory catalog" : salesContext ? "Inventory catalog" : purchaseCatalogVendorName() || "All vendors";
  openModal(`<section class="purchase-catalog-enterprise ${purchaseCatalogContext() === "purchase" ? "purchase-catalog-purchase" : ""}">
    <header class="purchase-catalog-appbar"><div><strong>${appName}</strong><nav>${navigationMarkup}</nav></div><div class="purchase-catalog-user">${escapeHtml(state.companySettings?.name || "Arafat Chemica")}</div></header>
    <div class="purchase-catalog-toolbar"><button type="button" class="purchase-catalog-back" data-purchase-catalog-back>${documentLabel}</button><div><strong>Products</strong><small>${escapeHtml(catalogDescription)}</small></div><button type="button" class="purchase-catalog-close" data-action="close-modal" aria-label="Close catalog">×</button>
      <div class="purchase-catalog-searchbar"><div class="purchase-catalog-search"><span class="purchase-catalog-search-icon" aria-hidden="true">⌕</span>${vendorFilter}<input type="search" aria-label="Search products" value="${escapeHtml(state.purchaseCatalog.search || "")}" placeholder="Search..." data-purchase-catalog-search></div><span class="purchase-catalog-count" data-purchase-catalog-count></span><div class="purchase-catalog-pager" data-purchase-catalog-pager></div></div>
    </div>
     <div class="purchase-catalog-layout"><aside class="purchase-catalog-sidebar">${suggestMarkup}<div data-purchase-catalog-order-summary></div><section class="purchase-catalog-categories"><h3>Categories</h3>${sharedProductCategoryButton("all", { selected: state.purchaseCatalog.category === "all", count: categoryProducts.length, modal: true })}${categoriesMarkup}</section></aside><main class="purchase-catalog-main"><div class="inventory-product-grid" data-purchase-catalog-results></div></main></div>
  </section>`);
  modalRoot.classList.add("purchase-catalog-open");
  modalRoot.querySelector(".modal-card")?.classList.add("purchase-catalog-modal-card");
  refreshPurchaseCatalogResults();
  modalRoot.querySelector("[data-purchase-catalog-search]")?.focus({ preventScroll: true });
}

function restoreSharedProductCatalogParent() {
  const parentModal = state.purchaseCatalog?.parentModal || null;
  modalRoot.innerHTML = "";
  modalRoot.classList.remove("purchase-catalog-open");
  state.purchaseCatalog = null;
  if (parentModal) {
    modalRoot.append(parentModal);
    modalRoot.querySelector("input, select, textarea, button")?.focus({ preventScroll: true });
  }
}

function setSharedCatalogProductSelect(targetId, product, sourceButton = null) {
  const select = targetId === "manual-delivery-row"
    ? sourceButton?.closest(".inventory-manual-delivery-line")?.querySelector("[data-manual-delivery-product]")
    : targetId === "receipt-row"
      ? sourceButton?.closest(".purchase-receipt-line")?.querySelector("[data-receipt-product]")
      : document.getElementById(targetId);
  if (!select || !product) return;
  const value = String(product.id);
  if (![...select.options].some((option) => option.value === value)) {
    select.add(new Option(`${product.name} · ${product.sku || ""}`, value));
  }
  select.value = value;
  select.dispatchEvent(new Event("change", { bubbles: true }));
}

function openSharedProductCatalog(context = "purchase", options = {}) {
  const invoiceKind = context === "invoice" ? document.querySelector("#invoice-form")?.dataset.kind || state.invoiceEditor?.kind || invoiceKindForPage() : "";
  const catalogContext = context === "invoice" ? (invoiceKind.startsWith("in_") ? "invoice-purchase" : "invoice-sales") : ["sales", "inventory-picker", "pos-picker"].includes(context) ? context : "purchase";
  const selectedVendor = catalogContext === "invoice-purchase"
    ? String(document.querySelector("#invoice-form [name='partner']")?.value || state.invoiceEditor?.partner || "").trim()
    : catalogContext === "purchase" ? purchaseCatalogVendorName() : "";
  const supplier = purchaseCatalogVendorOptions().find((item) => String(item.name).toLowerCase() === selectedVendor.toLowerCase());
  const parentModal = options.preserveModal ? modalRoot.firstElementChild : null;
  state.purchaseCatalog = { context: catalogContext, pickerOnly: Boolean(options.pickerOnly), onSelect: options.onSelect || null, returnFocusTo: options.returnFocusTo || null, parentModal, search: "", category: "all", supplierKey: supplier?.key || "all", suggest: false, page: 1, units: {}, vendorMenuOpen: false, vendorSearch: "", showAllVendors: false };
  renderPurchaseCatalogModal();
}

function openPurchaseCatalog() { openSharedProductCatalog("purchase"); }

function sharedCatalogLinePrice(product, unit) {
  if (purchaseCatalogFlow() === "purchase") return purchaseCatalogVendorPrice(product, unit);
  if (purchaseCatalogContext() === "invoice-sales") return productSalesUnitPrice(product, unit);
  const offer = salesProductOffer(product);
  return offer ? salesProductOfferPrice(product, offer, unit) : productUnitPrice(product, unit, "sale");
}

function sharedCatalogRecalculate() {
  if (purchaseCatalogIsInvoice()) updateInvoiceTotal();
  else if (purchaseCatalogContext() === "sales") updateSaleTotal();
  else updateOrderTotal();
}

function purchaseCatalogAdjustQuantity(productId, unit, delta) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  const salesContext = purchaseCatalogUsesSalesLines();
  const invoiceContext = purchaseCatalogIsInvoice();
  const kind = document.querySelector("#invoice-form")?.dataset.kind || "out_invoice";
  const tbody = document.querySelector(invoiceContext ? "#invoice-line-items" : salesContext ? "#sale-line-items" : "#order-line-items");
  if (!product || !tbody) return;
  const rows = purchaseCatalogOrderLines().filter((line) => Number(line.product.id) === Number(product.id) && String(line.unit).toLowerCase() === String(unit).toLowerCase());
  if (!rows.length && delta > 0) {
    if (!salesContext) tbody.querySelector(".purchase-empty-lines")?.remove();
    const line = { product: product.name, sku: product.sku, qty: delta, uom: unit, price: sharedCatalogLinePrice(product, unit) };
    tbody.insertAdjacentHTML("beforeend", invoiceContext ? invoiceLineMarkup(line, kind) : salesContext ? saleLineMarkup(line, false, currentSalesProductFlow(), nextSalesLineNumber()) : purchaseLineMarkup(line));
    if (salesContext) renumberSalesLines();
  } else if (rows.length) {
    const total = rows.reduce((sum, line) => sum + line.qty, 0);
    const next = Math.max(0, Math.round((total + delta) * 1000) / 1000);
    if (next <= 0) rows.forEach((line) => line.row.remove());
    else {
      const primary = rows[0];
      const quantity = primary.row.querySelector(invoiceContext ? "[data-invoice-qty]" : salesContext ? "[data-sale-qty]" : "[data-line-qty]");
      if (quantity) quantity.value = String(next);
      rows.slice(1).forEach((line) => line.row.remove());
    }
  }
  if (!salesContext && !invoiceContext) syncPurchaseEmptyLine();
  sharedCatalogRecalculate();
  refreshPurchaseCatalogResults();
}

function purchaseCatalogSetQuantity(productId, unit, quantity) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  const rows = purchaseCatalogOrderLines().filter((line) => Number(line.product.id) === Number(productId) && String(line.unit).toLowerCase() === String(unit).toLowerCase());
  const rawQuantity = Number(quantity);
  const allowsFraction = purchaseCatalogFlow() !== "purchase" ? salesUnitAllowsFraction(product, unit) : purchaseUnitAllowsFraction(unit, product);
  const next = product && !allowsFraction ? Math.trunc(rawQuantity) : rawQuantity;
  if (!product || !Number.isFinite(next)) return;
  if (!rows.length) {
    if (next > 0) purchaseCatalogAddProduct(productId, unit, next);
    return;
  }
  if (next <= 0) rows.forEach((line) => line.row.remove());
  else {
    const input = rows[0].row.querySelector(purchaseCatalogIsInvoice() ? "[data-invoice-qty]" : purchaseCatalogUsesSalesLines() ? "[data-sale-qty]" : "[data-line-qty]");
    if (input) input.value = String(Math.round(next * 1000) / 1000);
    rows.slice(1).forEach((line) => line.row.remove());
  }
  if (purchaseCatalogContext() === "purchase") syncPurchaseEmptyLine();
  sharedCatalogRecalculate();
  refreshPurchaseCatalogResults();
}

function purchaseCatalogAddProduct(productId, unit, quantity) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  const salesContext = purchaseCatalogUsesSalesLines();
  const invoiceContext = purchaseCatalogIsInvoice();
  const kind = document.querySelector("#invoice-form")?.dataset.kind || "out_invoice";
  const tbody = document.querySelector(invoiceContext ? "#invoice-line-items" : salesContext ? "#sale-line-items" : "#order-line-items");
  const rawQuantity = Number(quantity);
  const allowsFraction = purchaseCatalogFlow() !== "purchase" ? salesUnitAllowsFraction(product, unit) : purchaseUnitAllowsFraction(unit, product);
  const qty = product && !allowsFraction ? Math.trunc(rawQuantity) : rawQuantity;
  const factor = product && purchaseCatalogFlow() !== "purchase" ? productUnitFactor(product, unit) : product ? purchaseUnitFactor(product, unit) : null;
  if (!product || !tbody || !Number.isFinite(qty) || qty <= 0 || !factor) return;
  state.purchaseCatalog.units[product.id] = unit;
  const rows = purchaseCatalogOrderLines().filter((line) => Number(line.product.id) === Number(product.id) && String(line.unit).toLowerCase() === String(unit).toLowerCase());
  if (rows.length) {
    const primary = rows[0];
    const input = primary.row.querySelector(invoiceContext ? "[data-invoice-qty]" : salesContext ? "[data-sale-qty]" : "[data-line-qty]");
    if (input) input.value = String(Math.round((primary.qty + qty) * 1000) / 1000);
    rows.slice(1).forEach((line) => line.row.remove());
  } else {
    if (!invoiceContext && !salesContext) tbody.querySelector(".purchase-empty-lines")?.remove();
    const line = { product: product.name, sku: product.sku, qty, uom: unit, price: sharedCatalogLinePrice(product, unit) };
    tbody.insertAdjacentHTML("beforeend", invoiceContext ? invoiceLineMarkup(line, kind) : salesContext ? saleLineMarkup(line, false, currentSalesProductFlow(), nextSalesLineNumber()) : purchaseLineMarkup(line));
    if (salesContext) renumberSalesLines();
  }
  if (!salesContext && !invoiceContext) syncPurchaseEmptyLine();
  sharedCatalogRecalculate();
  refreshPurchaseCatalogResults();
}

function purchaseCatalogSetUnit(productId, unit) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  const salesContext = purchaseCatalogFlow() !== "purchase";
  const factor = product && salesContext ? productUnitFactor(product, unit) : product ? purchaseUnitFactor(product, unit) : null;
  if (!product || !factor) return;
  state.purchaseCatalog.units[product.id] = unit;
  const selected = purchaseCatalogProductSelection(product);
  if (selected?.lines?.length) {
    const row = selected.lines[0].row;
    const selector = row.querySelector(purchaseCatalogIsInvoice() ? "[data-invoice-uom]" : salesContext ? "[data-sale-uom]" : "[data-line-uom]");
    if (selector && [...selector.options].some((option) => option.value === unit)) {
      selector.value = unit;
      selector.dispatchEvent(new Event("change", { bubbles: true }));
    }
  }
  refreshPurchaseCatalogResults();
}

function renderSharedOrderDocumentTemplate({ pageClass = "", toolbarMarkup, actionMarkup, statusMarkup, formMarkup, chatterMarkup }) {
  return `<section class="sales-document-page purchase-document-page shared-order-document-page ${pageClass}">${toolbarMarkup}<div class="sales-document-actionbar"><div class="sales-document-buttons">${actionMarkup}</div>${statusMarkup}</div><div class="erp-finance-form-layout">${formMarkup}${chatterMarkup}</div></section>`;
}

function renderSharedOrderDocumentCard({ headingMarkup, fieldsMarkup, tabsMarkup = "", panelsMarkup, footerMarkup = "" }) {
  return `<article class="sales-document-card"><header class="purchase-document-heading">${headingMarkup}</header><section class="sales-document-fields purchase-document-fields">${fieldsMarkup}</section>${tabsMarkup}${panelsMarkup}${footerMarkup}</article>`;
}

function renderSharedOrderTabsToolbar({ ariaLabel, tabs, activeTab, tabAttribute, taxMode, taxModeAttribute, disabled = "" }) {
  const tabMarkup = tabs.map(({ key, label }) => `<button type="button" data-${tabAttribute}="${escapeHtml(key)}" class="${activeTab === key ? "is-active" : ""}" aria-selected="${activeTab === key}">${escapeHtml(label)}</button>`).join("");
  return `<div class="purchase-tabs-toolbar"><nav class="sales-document-tabs" aria-label="${escapeHtml(ariaLabel)}">${tabMarkup}</nav><div class="purchase-tax-switch sales-tax-switch" aria-label="Tax display"><button type="button" data-${taxModeAttribute}="excluded" class="${taxMode === "excluded" ? "is-active" : ""}" ${disabled}>Tax Excl.</button><button type="button" data-${taxModeAttribute}="included" class="${taxMode === "included" ? "is-active" : ""}" ${disabled}>Tax Incl.</button></div></div>`;
}

function renderPurchaseOrderForm() {
  const order = purchaseOrders.find((item) => item.id === Number(state.purchaseEditor?.id)) || null;
  const ref = order?.ref || "New";
  const status = order?.status || "RFQ";
  const orderStep = status === "Purchase Order" ? 1 : 0;
  const lines = order?.lines?.length ? order.lines.map((line) => purchaseLineMarkup(line)).join("") : state.purchaseEditor?.prefillLines?.length ? state.purchaseEditor.prefillLines.map((line) => purchaseLineMarkup(line)).join("") : state.purchaseEditor?.prefillLine ? purchaseLineMarkup(state.purchaseEditor.prefillLine) : purchaseEmptyLineMarkup();
  const rawDeadline = String(order?.deadlineDate || "");
  const deadline = rawDeadline
    ? (/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(rawDeadline) ? rawDeadline.slice(0, 16) : `${rawDeadline.slice(0, 10)}T15:00`)
    : inputLocalDateTime(new Date(Date.now() + 7 * 86400000));
  const rawArrival = String(order?.expectedArrival || "");
  const arrival = rawArrival.slice(0, 10);
  const defaultSupplierName = defaultPurchaseSupplier()?.name || "";
  const selectedSupplier = findPurchaseSupplier(order?.vendor || state.purchaseEditor?.vendor || defaultSupplierName);
  const paymentTerms = order?.paymentTerms || selectedSupplier?.paymentTerms || "Immediate";
  const paymentTermOptions = purchasePaymentTermOptions([paymentTerms]);
  const vendorReference = order?.vendorReference ?? selectedSupplier?.supplierReference ?? selectedSupplier?.reference ?? "";
  const company = order?.company || state.settings.companyName || "Arafat Chemica";
  const buyer = order?.buyer || state.userProfile.login || "purchase3";
  const alternativeGroup = order?.alternativeGroupId || "";
  const alternativeOrders = alternativeGroup
    ? purchaseOrders.filter((item) => item.id !== order?.id && item.alternativeGroupId === alternativeGroup)
    : [];
  const agreementOptions = [...new Set(purchaseOrders.map((item) => item.agreement).filter(Boolean))];
  const vendorNames = [...new Set([...vendors.map((item) => item.name), ...purchaseOrders.map((item) => item.vendor)].filter(Boolean))];
  const taxExcluded = order?.taxExcluded ?? order?.total ?? 0;
  const taxAmount = order?.taxAmount || 0;
  const total = order?.total || 0;
  const editable = !["Cancelled", "Purchase Order"].includes(status);
  const disabled = editable ? "" : "disabled";
  const linkedBill = order ? vendorBillForPurchaseOrder(order.id) : null;
  const billStatus = linkedBill ? invoiceDisplayStatus(linkedBill) : "";
  const actions = status === "Cancelled"
    ? `<button class="action-button secondary" type="button" data-action="print-purchase">Print</button>`
    : status === "Purchase Order"
      ? `<button class="action-button" type="button" data-purchase-action="receive">Receive</button>${linkedBill ? `<button class="action-button secondary" type="button" data-open-invoice="${linkedBill.id}">View Bill</button>` : `<button class="action-button secondary" type="button" data-purchase-action="create-bill">Create Bill</button>`}<button class="action-button secondary" type="button" data-purchase-action="upload-bill">Upload Bill</button><button class="action-button secondary" type="button" data-purchase-action="send-po">Send PO</button><button class="action-button secondary" type="button" data-purchase-action="acknowledge">Acknowledge</button><button class="action-button secondary" type="button" data-action="print-purchase">Print</button><button class="action-button secondary" type="button" data-purchase-action="cancel">Cancel</button>`
      : `<button class="action-button" type="button" data-purchase-action="send" ${disabled}>Send RFQ</button><button class="action-button secondary" type="button" data-purchase-action="confirm" ${disabled}>Confirm Order</button><button class="action-button secondary" type="button" data-action="print-purchase">Print</button><button class="action-button secondary" type="button" data-purchase-action="cancel" ${disabled}>Cancel</button>`;
  const statusbar = `<div class="sales-statusbar" aria-label="Purchase status"><span class="${orderStep === 0 ? "is-current" : "is-done"}">RFQ</span><span class="${orderStep === 1 ? "is-current" : ""}">Purchase Order</span></div>`;
  const receiptCount = state.purchaseReceipts.filter((receipt) => receipt.orderId === order?.id && receipt.status !== "Cancelled").length;
  const purchaseSmartPanel = order?.status === "Purchase Order" ? window.ERPSharedSmartPanel.render({
    className: "purchase-document-smart-panel", ariaLabel: "Purchase order smart buttons",
    items: [
      linkedBill
        ? { label: "Vendor Bill", value: billStatus, icon: "▧", className: "purchase-smart-button", attributes: { "data-open-invoice": linkedBill.id }, title: `${billStatus} · ${salesCurrency(linkedBill.amountDue || 0)} due` }
        : { label: "Create Bill", icon: "▧", className: "purchase-smart-button is-action", attributes: { "data-purchase-action": "create-bill" } },
      { label: "Receipt", value: String(receiptCount), icon: "▣", className: "purchase-smart-button", attributes: { "data-open-purchase-receipt": order.id } },
    ],
  }) : "";
  const toolbarMarkup = `<div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button secondary" data-purchase-editor-action="new">New</button><div><button type="button" class="sales-breadcrumb" data-purchase-editor-action="discard">Requests for Quotation</button><h1>${escapeHtml(ref)}</h1></div><button type="button" class="more-button purchase-form-more" data-action="toolbar-more" aria-label="More options">⋮</button></div><div class="sales-document-toolbar-right">${purchaseSmartPanel}<button type="button" class="soft-icon-button" data-action="purchase-cloud" aria-label="Save status">☁</button><button type="button" class="soft-icon-button" data-purchase-editor-action="discard" aria-label="Close">×</button></div></div>`;
  const headingMarkup = `<div><span>${status === "Purchase Order" ? "Purchase Order" : "Request for Quotation"}</span><h2><button type="button" class="purchase-favorite ${state.purchaseFavorite ? "is-active" : ""}" data-purchase-favorite aria-label="${state.purchaseFavorite ? "Remove from favorites" : "Add to favorites"}">${state.purchaseFavorite ? "★" : "☆"}</button>${escapeHtml(ref)}</h2></div>`;
  const fieldsMarkup = `<div class="sales-field-main">
        <div class="field sales-partner-field"><label for="order-vendor">Vendor <sup>?</sup></label><div class="purchase-vendor-input-wrap"><input id="order-vendor" name="vendor" aria-required="true" ${disabled} value="${escapeHtml(order?.vendor || state.purchaseEditor?.vendor || defaultSupplierName)}" placeholder="Name, TIN, Email, or Reference" autocomplete="off" aria-controls="purchase-vendor-dropdown" aria-expanded="false"><div id="purchase-vendor-dropdown" class="purchase-vendor-dropdown" role="listbox" hidden></div></div><small class="purchase-vendor-contact-hint">${selectedSupplier ? `Linked Contact · ${escapeHtml([selectedSupplier.email, selectedSupplier.phone].filter(Boolean).join(" · ") || "Vendor details from Contacts")}` : "Choose an approved Contact. Vendor Reference and Payment Terms fill automatically."}</small></div>
        <div class="field"><label for="order-vendor-reference">Vendor Reference <sup>?</sup></label><input id="order-vendor-reference" name="vendorReference" ${disabled} value="${escapeHtml(vendorReference)}"></div>
        <div class="field"><label for="order-agreement">Agreement</label><input id="order-agreement" name="agreement" list="purchase-agreement-options" autocomplete="off" ${disabled} value="${escapeHtml(order?.agreement || "")}"><datalist id="purchase-agreement-options">${agreementOptions.map((item) => `<option value="${escapeHtml(item)}">`).join("")}</datalist></div>
        <div class="field"><label for="order-payment-terms">Payment Terms</label><select id="order-payment-terms" name="paymentTerms" ${disabled}>${paymentTermOptions.map((item) => `<option ${paymentTerms === item ? "selected" : ""}>${escapeHtml(item)}</option>`).join("")}</select></div>
      </div><div class="sales-field-side">
        <div class="field"><label for="order-deadline">Order Deadline <sup>?</sup></label><input id="order-deadline" name="deadlineDate" type="datetime-local" autocomplete="off" ${disabled} value="${escapeHtml(deadline)}"></div>
        <div class="field"><label for="order-arrival">Expected Arrival <sup>?</sup></label><input id="order-arrival" name="expectedArrival" type="date" autocomplete="off" ${disabled} value="${escapeHtml(arrival)}"></div>
        <label class="purchase-arrival-check"><input type="checkbox" name="arrivalConfirmation" ${order?.arrivalConfirmation ? "checked" : ""} ${disabled}> Arrival Confirmation</label>
        <div class="field"><label for="order-destination">Deliver To <sup>?</sup></label><select id="order-destination" name="destination" ${disabled}>${["Arafat Chemica: Receipts", "Main Warehouse", "Depot Warehouse", ...(order?.destination && !["Arafat Chemica: Receipts", "Main Warehouse", "Depot Warehouse"].includes(order.destination) ? [order.destination] : [])].map((item) => `<option ${String(order?.destination || "Arafat Chemica: Receipts") === item ? "selected" : ""}>${escapeHtml(item)}</option>`).join("")}</select></div>
      </div>`;
  const tabsMarkup = renderSharedOrderTabsToolbar({ ariaLabel: "Purchase order details", tabs: [{ key: "products", label: "Products" }, { key: "other-info", label: "Other Info" }, { key: "alternatives", label: "Alternatives" }], activeTab: state.purchaseTab, tabAttribute: "purchase-tab", taxMode: state.purchaseTaxMode, taxModeAttribute: "purchase-tax-mode", disabled });
  const panelsMarkup = `<section class="sales-tab-panel ${state.purchaseTab === "products" ? "is-active" : ""}" data-purchase-panel="products"><div class="sale-lines-scroll"><table class="order-lines sales-native-lines purchase-native-lines"><thead><tr><th>Product</th><th>Quantity</th><th>Unit</th><th>Unit Price</th><th>Taxes</th><th class="money-cell">Amount</th><th><button type="button" class="purchase-line-settings" data-action="configure-columns" aria-label="Configure product columns" title="Configure product columns">${icon("sliders")}</button></th></tr></thead><tbody id="order-line-items">${lines}</tbody>${editable ? `<tfoot class="purchase-line-footer"><tr class="purchase-action-row"><td colspan="7"><div class="sales-line-actions"><button type="button" data-action="add-order-line">Add a product</button><button type="button" data-action="add-order-section">Add a section</button><button type="button" data-action="add-order-note">Add a note</button><button type="button" data-action="purchase-catalog">Catalog</button></div></td></tr><tr class="purchase-blank-line"><td colspan="7"></td></tr><tr class="purchase-blank-line"><td colspan="7"></td></tr><tr class="purchase-blank-line"><td colspan="7"></td></tr></tfoot>` : ""}</table></div><div class="purchase-order-summary"><label class="purchase-terms"><span>Terms and Conditions</span><textarea name="terms" ${disabled} placeholder="Define your terms and conditions ...">${escapeHtml(order?.terms || "")}</textarea></label><div class="sales-total-box purchase-total-box"><div><span>Untaxed Amount</span><strong id="order-subtotal">${salesCurrency(taxExcluded)}</strong></div><div class="purchase-tax-total-row${taxAmount > 0 ? "" : " is-hidden"}" data-purchase-tax-row><span>Tax</span><strong id="order-tax-total">${salesCurrency(taxAmount)}</strong></div><div class="sales-grand-total"><span>Total</span><strong id="order-total">${salesCurrency(total)}</strong></div></div></div></section>
      <section class="sales-tab-panel purchase-other-info-panel ${state.purchaseTab === "other-info" ? "is-active" : ""}" data-purchase-panel="other-info"><div class="purchase-other-info-grid"><div class="field"><label for="order-buyer">Buyer</label><input id="order-buyer" name="buyer" ${disabled} value="${escapeHtml(buyer)}" placeholder="Buyer"></div><div class="field"><label for="order-company">Company</label><input id="order-company" name="company" ${disabled} value="${escapeHtml(company)}" placeholder="Company"></div><div class="field"><label for="order-source-document">Source Document</label><input id="order-source-document" name="sourceDocument" ${disabled} value="${escapeHtml(order?.sourceDocument || "")}" placeholder="Source document"></div><div class="field"><label for="order-incoterm">Incoterm</label><input id="order-incoterm" name="incoterm" list="purchase-incoterm-options" ${disabled} value="${escapeHtml(order?.incoterm || "")}" placeholder="Select or type an Incoterm"><datalist id="purchase-incoterm-options">${["EXW", "FCA", "CPT", "CIP", "DAP", "DPU", "DDP", "FAS", "FOB", "CFR", "CIF"].map((item) => `<option value="${item}">`).join("")}</datalist></div><label class="purchase-other-info-notes"><span>Internal Notes</span><textarea name="notes" ${disabled} placeholder="Notes for the purchase team">${escapeHtml(order?.notes || "")}</textarea></label></div></section>
      <section class="sales-tab-panel purchase-alternatives-panel ${state.purchaseTab === "alternatives" ? "is-active" : ""}" data-purchase-panel="alternatives"><div class="purchase-alternatives-content"><header><div><h3>Alternative RFQs</h3><p>Compare supplier quotations for the same products.</p></div><button type="button" class="action-button secondary" data-purchase-action="create-alternative" ${!order || state.settings.purchaseAlternatives === false || ["Cancelled", "Purchase Order"].includes(status) ? "disabled" : ""}>Add Alternative</button></header>${alternativeOrders.length ? `<div class="table-wrap"><table class="data-table purchase-alternatives-table"><thead><tr><th>Reference</th><th>Vendor</th><th>Status</th><th class="money-cell">Total</th></tr></thead><tbody>${alternativeOrders.map((alternative) => `<tr><td><button type="button" class="reference-link" data-open-order="${alternative.id}">${escapeHtml(alternative.ref)}</button></td><td>${escapeHtml(alternative.vendor || "Supplier not selected")}</td><td><span class="status-pill ${statusClass(alternative.status)}">${escapeHtml(alternative.status)}</span></td><td class="money-cell">${salesCurrency(alternative.total || 0)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="purchase-alternatives-empty"><strong>${order ? "No alternative RFQs linked" : "Save this RFQ before adding alternatives"}</strong><p>${state.settings.purchaseAlternatives === false ? "Enable Purchase Alternative in Purchase settings to compare supplier quotations." : order ? "Add an alternative RFQ to compare another supplier's quotation for these products." : "Once saved, you can create and compare supplier quotations here."}</p></div>`}</div></section>`;
  const formMarkup = `<main><form id="order-form" data-id="${order?.id || ""}" data-status="${escapeHtml(status)}" autocomplete="off"><input id="order-reference" type="hidden" name="reference" value="${escapeHtml(ref)}">${renderSharedOrderDocumentCard({ headingMarkup, fieldsMarkup, tabsMarkup, panelsMarkup })}</form></main>`;
  const actionMarkup = actions;
  const chatterMarkup = `<aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button" data-action="purchase-message">Send message</button><button type="button" class="action-button secondary" data-action="purchase-note">Log note</button><button type="button" class="action-button secondary" data-action="purchase-activity">Activity</button></div><div class="purchase-chatter-day">Today</div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${order ? `${escapeHtml(status)} · ${escapeHtml(order.ref)}` : "Creating a new record..."}</p></div></div><p class="erp-chatter-note">Supplier communication and purchase history appear here.</p></aside>`;
  return renderSharedOrderDocumentTemplate({ toolbarMarkup, actionMarkup, statusMarkup: statusbar, formMarkup, chatterMarkup });
}

function purchaseSupplierOptions({ includeUnapproved = false } = {}) {
  const byName = new Map();
  const add = (supplier) => {
    const name = String(supplier?.name || "").trim();
    const key = name.toLocaleLowerCase();
    if (!key) return;
    const previous = byName.get(key) || {};
    byName.set(key, {
      ...previous,
      ...supplier,
      name,
      id: supplier.supplierId || supplier.linkedId || previous.id || supplier.id,
      contactId: supplier.contactId || (contactHasSupplierRole(supplier) ? supplier.id : "") || previous.contactId || "",
      approved: supplier.approved !== undefined ? supplier.approved : previous.approved,
    });
  };
  vendors.forEach(add);
  (state.contacts || []).filter(contactHasSupplierRole).forEach((contact) => add({
    ...contact,
    id: contact.supplierId || contact.linkedId || contact.id,
    contactId: contact.id,
  }));
  return [...byName.values()]
    .filter((supplier) => supplier.active !== false && (includeUnapproved || isSupplierApproved(supplier)))
    .sort((first, second) => first.name.localeCompare(second.name));
}

function findPurchaseSupplier(value, options = purchaseSupplierOptions({ includeUnapproved: true })) {
  const key = String(value || "").trim().toLocaleLowerCase();
  if (!key) return null;
  return options.find((supplier) => [supplier.name, supplier.id, supplier.contactId, supplier.supplierId, supplier.reference, supplier.taxId]
    .some((candidate) => String(candidate || "").trim().toLocaleLowerCase() === key)) || null;
}

function defaultPurchaseSupplier() {
  const options = purchaseSupplierOptions();
  const configured = findPurchaseSupplier(state.settings.defaultPurchaseVendor, options);
  return configured || options.find((supplier) => supplier.defaultPurchaseVendor) || null;
}

function setPurchaseVendor(vendor) {
  if (!vendor || !isSupplierApproved(vendor)) {
    showToast("Approve this supplier in Contacts before using it in Purchase.");
    return;
  }
  const linkedContact = (state.contacts || []).find((contact) => contactHasSupplierRole(contact) && [contact.id, contact.supplierId, contact.linkedId].some((id) => String(id || "") === String(vendor.contactId || vendor.id || ""))) || null;
  if (state.purchaseEditor) {
    state.purchaseEditor.vendor = vendor.name;
    state.purchaseEditor.vendorContactId = vendor.contactId || linkedContact?.id || null;
  }
  const input = document.querySelector("#order-vendor");
  const dropdown = document.querySelector("#purchase-vendor-dropdown");
  if (input && vendor) input.value = vendor.name;
  if (dropdown) dropdown.hidden = true;
  input?.setAttribute("aria-expanded", "false");
  const vendorReference = document.querySelector("#order-vendor-reference");
  if (vendorReference) vendorReference.value = vendor.supplierReference || linkedContact?.supplierReference || vendor.reference || linkedContact?.reference || "";
  const terms = document.querySelector("#order-payment-terms");
  const paymentTerms = String(vendor.paymentTerms || linkedContact?.paymentTerms || "Immediate").trim();
  if (terms) {
    if (![...terms.options].some((option) => option.value === paymentTerms)) {
      const option = document.createElement("option");
      option.value = paymentTerms;
      option.textContent = paymentTerms;
      terms.add(option);
    }
    terms.value = paymentTerms;
  }
  input?.focus({ preventScroll: true });
}

function updatePurchaseVendorDropdown(query = "") {
  const dropdown = document.querySelector("#purchase-vendor-dropdown");
  const input = document.querySelector("#order-vendor");
  if (!dropdown || !input || input.disabled) return;
  const term = String(query).trim().toLowerCase();
  const allMatches = purchaseSupplierOptions({ includeUnapproved: true }).filter((vendor) => [vendor.name, vendor.email, vendor.phone, vendor.reference, vendor.taxId].some((value) => String(value || "").toLowerCase().includes(term)));
  const matches = allMatches.filter(isSupplierApproved).slice(0, 8);
  const exact = findPurchaseSupplier(term, allMatches);
  const rows = matches.map((vendor) => `<button type="button" class="purchase-vendor-option" role="option" data-purchase-vendor-choice="select" data-vendor-id="${escapeHtml(vendor.contactId || vendor.id)}"><span class="purchase-vendor-avatar">${escapeHtml(initials(vendor.name))}</span><span><strong>${escapeHtml(vendor.name)}</strong><small>${escapeHtml([vendor.email, vendor.phone].filter(Boolean).join(" · ") || "Supplier contact")}</small></span></button>`).join("");
  const pendingHint = allMatches.some((vendor) => !isSupplierApproved(vendor)) ? `<div class="purchase-vendor-empty">A matching supplier is waiting for approval. Approve it in Contacts first.</div>` : "";
  const createActions = term && !exact ? `<div class="purchase-vendor-menu-divider"></div><button type="button" class="purchase-vendor-command" data-purchase-vendor-choice="quick-create">＋ <span>Register “${escapeHtml(query.trim())}” for approval</span></button><button type="button" class="purchase-vendor-command" data-purchase-vendor-choice="create-edit">＋ <span>Create and edit…</span></button>` : "";
  const searchAction = `<div class="purchase-vendor-menu-divider"></div><button type="button" class="purchase-vendor-command" data-purchase-vendor-choice="search-more">⌕ <span>Search more…</span></button>`;
  const emptyMessage = !matches.length && !pendingHint
    ? `<div class="purchase-vendor-empty">${term ? "No matching supplier contact found." : "No approved supplier contacts found. Set a Default Vendor in Purchase settings or approve a supplier in Contacts."}</div>`
    : "";
  dropdown.innerHTML = `${rows}${emptyMessage}${pendingHint}${createActions}${searchAction}`;
  dropdown.hidden = false;
  input.setAttribute("aria-expanded", "true");
}

function isSupplierApproved(vendor) { return vendor?.approved !== false; }

function productPrimarySupplierName(product) {
  const supplierFromId = vendors.find((item) => String(item.id) === String(product?.supplierId || ""))?.name;
  return String(product?.supplierName || product?.vendorPrices?.find((row) => row.vendor)?.vendor || supplierFromId || "").trim();
}

function selectableProductRecords(currentProduct = null, flow = "sales") {
  return salesProducts.filter((product) => (!product.archived && productChannelEnabled(product, flow)) || Number(product.id) === Number(currentProduct?.id));
}

function supplierFilterKey(supplier) {
  if (supplier && typeof supplier === "object") {
    const id = supplier.linkedId || supplier.supplierId || supplier.id;
    if (id !== undefined && id !== null && String(id).trim()) return String(id);
    const name = String(supplier.name || "").trim();
    return name ? `name:${name.toLowerCase()}` : "";
  }
  return String(supplier || "");
}

function productSupplierFilterKey(product) {
  if (product?.supplierId !== undefined && product?.supplierId !== null && String(product.supplierId).trim()) return String(product.supplierId);
  const name = productPrimarySupplierName(product);
  if (!name) return "";
  const supplier = vendors.find((item) => String(item.name || "").toLowerCase() === name.toLowerCase());
  return supplier ? String(supplier.id) : `name:${name.toLowerCase()}`;
}

function productsForSupplier(supplier) {
  const key = supplierFilterKey(supplier);
  return key ? salesProducts.filter((product) => productSupplierFilterKey(product) === key) : [];
}

function productSupplierOptions() {
  const options = new Map();
  vendors.forEach((supplier) => options.set(String(supplier.id), supplier.name));
  salesProducts.forEach((product) => {
    const name = productPrimarySupplierName(product);
    const key = productSupplierFilterKey(product);
    if (key && name && !options.has(key)) options.set(key, name);
  });
  return [...options].map(([key, name]) => ({ key, name })).sort((a, b) => a.name.localeCompare(b.name));
}

function productSupplierFilterMarkup() {
  const options = productSupplierOptions();
  return `<label class="product-category-filter"><span>Supplier</span><select aria-label="Filter products by supplier" data-product-supplier-filter><option value="all" ${state.productSupplierFilter === "all" ? "selected" : ""}>All suppliers</option>${options.map((supplier) => `<option value="${escapeHtml(supplier.key)}" ${state.productSupplierFilter === supplier.key ? "selected" : ""}>${escapeHtml(supplier.name)}</option>`).join("")}</select></label>`;
}

function productStatusFilterMarkup() {
  return `<label class="product-category-filter"><span>Status</span><select aria-label="Filter active products" data-product-status-filter><option value="active" ${state.productStatusFilter === "active" ? "selected" : ""}>Active</option><option value="inactive" ${state.productStatusFilter === "inactive" ? "selected" : ""}>Inactive</option><option value="all" ${state.productStatusFilter === "all" ? "selected" : ""}>All</option></select></label>`;
}

function inventoryProductGiftItems(product) {
  if (!product) return [];
  if (Array.isArray(product.consumerOffers) && product.consumerOffers.length) {
    const offerGiftIds = product.consumerOffers.flatMap((offer) => offer.giftItemIds || []);
    return [...new Map(offerGiftIds.map((id) => inventoryGiftItems().find((item) => String(item.id) === String(id))).filter(Boolean).map((item) => [String(item.id), item])).values()];
  }
  const rule = inventoryGiftConfigurationForProduct(product);
  if (rule && (rule.active === false || rule.promotionType !== "cp")) return [];
  if (!rule && salesProductPromotionType(product) !== "cp") return [];
  const ids = rule ? (rule.giftItemIds || []) : [];
  const fromIds = ids.map((id) => inventoryGiftItems().find((item) => String(item.id) === String(id))).filter(Boolean);
  if (rule) return [...new Map(fromIds.map((item) => [String(item.id), item])).values()];
  const legacyNames = Array.isArray(product.giftOffers) ? product.giftOffers : [];
  const fromNames = legacyNames.map((name) => inventoryGiftItems().find((item) => String(item.name || "").toLowerCase() === String(name || "").toLowerCase())).filter(Boolean);
  return [...new Map(fromNames.map((item) => [String(item.id), item])).values()];
}

function inventoryProductOfferSummaryMarkup(product) {
  const isCp = salesProductPromotionType(product) === "cp";
  const gifts = inventoryProductGiftItems(product);
  const summary = isCp ? (gifts.length ? gifts.map((item) => item.name).join(", ") : "Gift not configured") : "No gift offer";
  return `<span class="inventory-product-offer-summary ${isCp ? `is-cp ${gifts.length ? "" : "is-unconfigured"}` : "is-non-cp"}" title="${escapeHtml(summary)}"><strong>${isCp ? "CP" : "Non-CP"}</strong><span>${escapeHtml(summary)}</span></span>`;
}

function inventoryProductCardPackMarkup(product) {
  const stockUnit = product.stockUom || "Units";
  const conversions = productUnitConversions(product).filter((row) => {
    const unit = String(row.unit || "").trim();
    return unit
      && unit.toLowerCase() !== String(stockUnit).toLowerCase()
      && row.saleEnabled !== false
      && productUnitFactor(product, unit);
  });
  const packageRow = conversions.find((row) => /carton|sack/i.test(String(row.unit)))
    || conversions.find((row) => String(row.unit).toLowerCase() === String(product.purchaseUom || "").toLowerCase())
    || conversions[0]
    || null;
  const offers = inventoryProductConsumerOffers(product);
  if (!packageRow) {
    const label = `Per ${stockUnit}`;
    const price = offers.length > 1 ? "Multiple offer prices" : `Price ${salesCurrency(salesProductOfferPrice(product, offers[0], stockUnit))}`;
    const summary = `${label} = ${price}`;
    return `<span class="inventory-product-card-pack-summary" title="${escapeHtml(summary)}"><strong>${escapeHtml(label)}</strong><i aria-hidden="true">=</i><b>${escapeHtml(price)}</b></span>`;
  }

  const unit = String(packageRow.unit).trim();
  const quantity = Number(productUnitFactor(product, unit));
  const format = (value) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 3 }).format(value);
  const contentValue = Number(product.netContentValue);
  const contentUnit = String(product.netContentUnit || "").trim();
  const packageContents = Number.isFinite(contentValue) && contentValue > 0 && contentUnit
    ? `${format(quantity)} × ${format(contentValue)} ${contentUnit}`
    : String(stockUnit).toLowerCase() === "piece"
      ? `${format(quantity)} pcs`
      : `${format(quantity)} ${stockUnit}`;
  const label = `${unit} (${packageContents})`;
  const price = offers.length > 1 ? "Multiple offer prices" : `Price ${salesCurrency(salesProductOfferPrice(product, offers[0], unit))}`;
  const summary = `${label} = ${price}`;
  const unitPriceLabel = "Per Packet Price";
  const unitPriceDetails = offers.length > 1
    ? offers.map((offer) => `${offer.name}: ${salesCurrency(salesProductOfferPrice(product, offer, stockUnit))}`).join(" · ")
    : salesCurrency(salesProductOfferPrice(product, offers[0], stockUnit));
  const unitPriceSummary = `${unitPriceLabel} = ${unitPriceDetails}`;
  const unitPriceMarkup = String(stockUnit).toLowerCase() === "packet"
    ? `<span class="inventory-product-card-unit-price-summary" title="${escapeHtml(unitPriceSummary)}"><strong>${escapeHtml(unitPriceLabel)}</strong><i aria-hidden="true">=</i><b>${escapeHtml(unitPriceDetails)}</b></span>`
    : "";
  return `<span class="inventory-product-card-pack-summary" title="${escapeHtml(summary)}"><strong>${escapeHtml(label)}</strong><i aria-hidden="true">=</i><b>${escapeHtml(price)}</b></span>${unitPriceMarkup}`;
}

function inventoryProductCardGiftMarkup(product) {
  const offers = inventoryProductConsumerOffers(product);
  if (offers.length > 1) {
    const details = offers.map((offer) => {
      const gifts = offer.giftItemIds.map((id) => inventoryGiftItems().find((item) => String(item.id) === String(id) && item.archived !== true)?.name || "").filter(Boolean);
      return `${offer.name}: ${salesCurrency(offer.unitPrice)} / ${product.stockUom || "unit"}${gifts.length ? ` · ${offer.giftSelectionMode === "choose-one" ? "Choose one" : "Gift"}: ${gifts.join(", ")}` : " · no gift"}`;
    }).join("; ");
    return `<small class="inventory-product-card-gift" title="${escapeHtml(details)}"><strong>Offers:</strong> ${escapeHtml(details)}</small>`;
  }
  const gifts = inventoryProductGiftItems(product);
  if (!gifts.length) return "";
  const label = offers[0]?.giftSelectionMode === "choose-one" ? "Gift options" : "Gift";
  const names = gifts.map((item) => item.name).join(", ");
  return `<small class="inventory-product-card-gift" title="${escapeHtml(`${label}: ${names}`)}"><strong>${label}:</strong> ${escapeHtml(names)}</small>`;
}

function inventoryProductCardMarkup(product) {
  const label = String(product.name || "Product").replace(/^\[DEMO\]\s*/i, "");
  const selected = state.selected.has(Number(product.id));
  const forecast = Number(product.onHand || 0) + inventoryIncoming(product) - inventoryOutgoing(product);
  const actions = `<div class="shared-inventory-card-actions"><input class="inventory-product-select" type="checkbox" data-select-row="${escapeHtml(product.id)}" aria-label="Select ${escapeHtml(product.name)}" ${selected ? "checked" : ""}><button type="button" class="inventory-product-card-favorite star-button ${product.favorite ? "is-favorite" : ""}" data-catalog-product-favorite="${escapeHtml(product.id)}" aria-label="${product.favorite ? "Remove from" : "Add to"} favorites" aria-pressed="${Boolean(product.favorite)}">${product.favorite ? "★" : "☆"}</button></div>`;
  const details = `${inventoryProductCardGiftMarkup(product)}${product.archived ? '<span class="status-pill cancelled">Inactive</span>' : ""}`;
  const demand = product.monthlyDemand ?? product.demandPerMonth ?? product.averageMonthlyDemand;
  return renderSharedProductCatalogCardFrame(product, {
    isSelected: selected,
    topMarkup: actions,
    titleMarkup: `<button type="button" class="shared-catalog-title-button" data-edit-sales-product="${escapeHtml(product.id)}"><strong>${escapeHtml(label)}</strong></button>`,
    variant: product.variantLabel || product.variant || product.model || product.productClass || "",
    priceMarkup: `<strong class="purchase-catalog-price">${salesCurrency(product.price || 0)} <small>/ ${escapeHtml(product.stockUom || "Units")}</small></strong>`,
    packageMarkup: inventoryProductCardPackMarkup(product),
    stockMarkup: inventoryProductCardStockMarkup(product, forecast),
    demandMarkup: demand === undefined || demand === null || demand === "" ? "" : `<small class="purchase-catalog-demand">Demand: ${purchaseCatalogQuantity(demand)} ${escapeHtml(product.stockUom || "Units")} / month</small>`,
    detailsMarkup: details,
    footerMarkup: "",
  });
}

function inventoryProductListRowMarkup(product, options = {}) {
  const selected = state.selected.has(Number(product.id));
  const supplierName = productPrimarySupplierName(product);
  const forecast = Number(product.onHand || 0) + inventoryIncoming(product) - inventoryOutgoing(product);
  const selectCell = options.sortable ? "" : `<td class="check-cell"><input type="checkbox" data-select-row="${escapeHtml(product.id)}" aria-label="Select ${escapeHtml(product.name)}" ${selected ? "checked" : ""}></td>`;
  const productClass = product.productClass || (product.promotionType === "cp" ? "CP" : product.promotionType === "non-cp" ? "Non-CP" : "—");
  const productClassTone = productClass === "CP" ? "cp" : productClass === "Non-CP" ? "non-cp" : "other";
  const cartonPrice = product.cartonPrice ?? product.unitConversions?.find((row) => /^carton$/i.test(String(row.unit || "")))?.salePrice ?? (/^carton$/i.test(String(product.purchaseUom || "")) ? Number(product.price || 0) * Number(product.purchaseUnitQuantity || 0) : null);
  const cells = `${selectCell}<td class="star-cell"><button type="button" class="star-button ${product.favorite ? "is-favorite" : ""}" data-catalog-product-favorite="${product.id}" aria-label="${product.favorite ? "Remove from" : "Add to"} favorites" aria-pressed="${Boolean(product.favorite)}">${product.favorite ? "★" : "☆"}</button></td><td><button class="reference-link inventory-product-name-link" type="button" data-edit-sales-product="${product.id}">${escapeHtml(product.name)}</button></td><td>${escapeHtml(product.sku || "—")}</td><td>${escapeHtml(product.category || "—")}</td><td><span class="inventory-product-class-pill ${productClassTone}">${escapeHtml(productClass)}</span></td><td>${supplierName ? escapeHtml(supplierName) : '<span class="inventory-product-supplier-required">Required</span>'}</td><td class="money-cell">${salesCurrency(product.price || 0)}</td><td class="money-cell">${cartonPrice == null ? "—" : salesCurrency(cartonPrice)}</td><td class="money-cell">${salesCurrency(product.cost || 0)}</td><td>${money(product.onHand || 0)}</td><td>${money(forecast)}</td><td>${escapeHtml(product.stockUom || "Units")}</td><td>${inventoryProductOfferSummaryMarkup(product)}</td><td><span class="status-pill ${product.archived ? "cancelled" : "purchase"}">${product.archived ? "Inactive" : "Active"}</span></td><td>${escapeHtml(product.packNote || "—")}</td>`;
  return options.cellsOnly ? cells : `<tr class="${selected ? "is-selected" : ""}" data-product-row="${product.id}">${cells}</tr>`;
}

function inventoryProductFilterOptionsMarkup(title, filterKey, options, selectedValue) {
  const heading = title ? `<h3>${escapeHtml(title)}</h3>` : "";
  if (!options.length) return `<section class="inventory-product-filter-group">${heading}<span class="inventory-product-filter-empty">No options available</span></section>`;
  return `<section class="inventory-product-filter-group">${heading}<div class="inventory-product-filter-options">${options.map(({ value, label }) => {
    const active = selectedValue instanceof Set ? selectedValue.has(String(value)) : String(selectedValue) === String(value);
    return `<button type="button" class="inventory-product-filter-option ${active ? "is-active" : ""}" data-product-filter="${escapeHtml(filterKey)}" data-value="${escapeHtml(value)}" aria-pressed="${active}"><span>${escapeHtml(label)}</span>${active ? '<b aria-hidden="true">✓</b>' : ""}</button>`;
  }).join("")}</div></section>`;
}

function inventoryProductCustomFilterFields() {
  const productCategories = [...new Set([...categories.map((item) => item.name), ...salesProducts.map((item) => item.category)].filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const suppliers = productSupplierOptions().map((item) => ({ value: item.key, label: item.name }));
  const units = [...new Set(salesProducts.map((item) => item.stockUom).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const giftItems = inventoryGiftItems().filter((item) => item.archived !== true).map((item) => ({ value: String(item.id), label: item.name }));
  return [
    { id: "productType", label: "Product Type", type: "selection", options: [{ value: "goods", label: "Goods" }, { value: "service", label: "Service" }, { value: "combo", label: "Combo" }] },
    { id: "category", label: "Product Category", type: "selection", options: productCategories.map((name) => ({ value: name, label: name })) },
    { id: "supplier", label: "Supplier", type: "selection", options: suppliers },
    { id: "name", label: "Product Name", type: "text" },
    { id: "reference", label: "Internal Reference", type: "text" },
    { id: "barcode", label: "Barcode", type: "text" },
    { id: "status", label: "Status", type: "selection", options: [{ value: "active", label: "Active" }, { value: "inactive", label: "Archived" }] },
    { id: "salesPrice", label: "Sales Price", type: "number" },
    { id: "cost", label: "Cost", type: "number" },
    { id: "onHand", label: "On Hand", type: "number" },
    { id: "stockUnit", label: "Unit of Measure", type: "selection", options: units.map((name) => ({ value: name, label: name })) },
    { id: "favorite", label: "Favorite", type: "selection", options: [{ value: "true", label: "Yes" }, { value: "false", label: "No" }] },
    { id: "promotion", label: "Promotion Type", type: "selection", options: [{ value: "cp", label: "CP" }, { value: "non-cp", label: "Non-CP" }] },
    { id: "giftConfigured", label: "Gift Configuration", type: "selection", options: [{ value: "configured", label: "Configured" }, { value: "missing", label: "Not configured" }] },
    { id: "giftItem", label: "Gift Item", type: "selection", options: giftItems },
  ];
}

function inventoryProductCustomFilterField(fieldId) {
  return inventoryProductCustomFilterFields().find((field) => field.id === fieldId) || null;
}

function inventoryProductCustomFilterOperators(field) {
  const common = [["=", "is equal to"], ["!=", "is not equal to"], ["in", "is in"], ["not in", "is not in"], ["set", "is set"], ["not set", "is not set"]];
  if (field?.type === "number") return [...common.slice(0, 2), [">", "is greater than"], [">=", "is greater than or equal to"], ["<", "is less than"], ["<=", "is less than or equal to"], ...common.slice(2, 4), ...common.slice(4)];
  if (field?.type === "text") return [["=", "is equal to"], ["!=", "is not equal to"], ["contains", "contains"], ["not contains", "does not contain"], ...common.slice(2)];
  return common;
}

function inventoryProductCustomRuleValue(product, fieldId) {
  if (fieldId === "productType") return inventoryProductTypeValue(product);
  if (fieldId === "category") return String(product.category || "");
  if (fieldId === "supplier") return productSupplierFilterKey(product);
  if (fieldId === "name") return String(product.name || "");
  if (fieldId === "reference") return String(product.sku || "");
  if (fieldId === "barcode") return String(product.barcode || "");
  if (fieldId === "status") return product.archived ? "inactive" : "active";
  if (fieldId === "salesPrice") return Number(product.price || 0);
  if (fieldId === "cost") return Number(product.cost || 0);
  if (fieldId === "onHand") return Number(product.onHand || 0);
  if (fieldId === "stockUnit") return String(product.stockUom || "");
  if (fieldId === "favorite") return String(Boolean(product.favorite));
  if (fieldId === "promotion") return salesProductPromotionType(product);
  if (fieldId === "giftConfigured") return inventoryProductGiftItems(product).length ? "configured" : "missing";
  if (fieldId === "giftItem") return inventoryProductGiftItems(product).map((item) => String(item.id));
  return "";
}

function inventoryProductCustomRuleMatches(product, rule, fieldMap) {
  const field = fieldMap?.get(rule?.field) || inventoryProductCustomFilterField(rule?.field);
  if (!field) return true;
  const actual = inventoryProductCustomRuleValue(product, field.id);
  const operator = rule.operator || "=";
  const present = Array.isArray(actual) ? actual.length > 0 : actual !== null && actual !== undefined && String(actual).trim() !== "";
  if (operator === "set") return present;
  if (operator === "not set") return !present;
  const expectedValues = String(rule.value ?? "").split(",").map((value) => value.trim()).filter(Boolean);
  if (!expectedValues.length) return true;
  if (operator === "in" || operator === "not in") {
    const matches = Array.isArray(actual) ? actual.some((value) => expectedValues.includes(String(value))) : expectedValues.some((value) => String(actual).toLocaleLowerCase() === value.toLocaleLowerCase());
    return operator === "in" ? matches : !matches;
  }
  if (Array.isArray(actual)) {
    const matches = actual.some((value) => String(value).toLocaleLowerCase() === expectedValues[0].toLocaleLowerCase());
    if (operator === "=") return matches;
    if (operator === "!=") return !matches;
  }
  if (field.type === "number") {
    const left = Number(actual);
    const right = Number(expectedValues[0]);
    if (!Number.isFinite(left) || !Number.isFinite(right)) return false;
    if (operator === "=") return left === right;
    if (operator === "!=") return left !== right;
    if (operator === ">") return left > right;
    if (operator === ">=") return left >= right;
    if (operator === "<") return left < right;
    if (operator === "<=") return left <= right;
  }
  const left = String(actual ?? "").toLocaleLowerCase();
  const right = expectedValues[0].toLocaleLowerCase();
  if (operator === "=") return left === right;
  if (operator === "!=") return left !== right;
  if (operator === "contains") return left.includes(right);
  if (operator === "not contains") return !left.includes(right);
  return false;
}

function inventoryProductCustomFilterMatches(product, fieldMap) {
  const rules = (state.inventoryProductCustomFilters || []).filter((rule) => rule?.field);
  if (!rules.length) return true;
  const results = rules.map((rule) => inventoryProductCustomRuleMatches(product, rule, fieldMap));
  return state.inventoryProductCustomMatch === "any" ? results.some(Boolean) : results.every(Boolean);
}

function inventoryProductCustomFilterFacets() {
  return (state.inventoryProductCustomFilters || []).map((rule, index) => {
    const field = inventoryProductCustomFilterField(rule.field);
    if (!field) return null;
    const operatorLabels = Object.fromEntries(inventoryProductCustomFilterOperators(field));
    let valueLabel = String(rule.value ?? "");
    if (field.type === "selection") valueLabel = valueLabel.split(",").map((value) => field.options?.find((option) => String(option.value) === value)?.label || value).join(", ");
    const compactProductType = field.id === "productType" && rule.operator === "=" && valueLabel;
    return { key: `custom:${index}`, label: compactProductType ? valueLabel : `${field.label} ${operatorLabels[rule.operator] || "is equal to"}${["set", "not set"].includes(rule.operator) ? "" : ` ${valueLabel}`}` };
  }).filter(Boolean);
}

function inventoryProductCustomFilterDraftFromState() {
  const rules = (state.inventoryProductCustomFilters || []).map((rule) => ({ ...rule }));
  if (!rules.length) {
    if (state.productTypeFilter !== "all") rules.push({ field: "productType", operator: "=", value: state.productTypeFilter });
    if (state.productCategoryFilter !== "all") rules.push({ field: "category", operator: "=", value: state.productCategoryFilter });
    if (state.productSupplierFilter !== "all") rules.push({ field: "supplier", operator: "=", value: state.productSupplierFilter });
    if (state.productStatusFilter === "inactive") rules.push({ field: "status", operator: "=", value: "inactive" });
    if (state.productFavoriteFilter !== "all") rules.push({ field: "favorite", operator: "=", value: state.productFavoriteFilter === "favorites" ? "true" : "false" });
    if (state.productPromotionFilter !== "all") rules.push({ field: "promotion", operator: "=", value: state.productPromotionFilter });
    if (state.productGiftOfferFilter !== "all") rules.push({ field: "giftConfigured", operator: "=", value: state.productGiftOfferFilter === "configured" ? "configured" : "missing" });
    if (state.productGiftItemFilter !== "all") rules.push({ field: "giftItem", operator: "=", value: state.productGiftItemFilter });
  }
  return { match: state.inventoryProductCustomMatch || "all", includeArchived: Boolean(state.inventoryProductCustomIncludeArchived || state.productStatusFilter === "inactive" || state.productStatusFilter === "all"), rules };
}

function inventoryProductCustomFilterFieldOptionsMarkup(index) {
  const query = String(state.inventoryProductCustomFieldSearch || "").trim().toLocaleLowerCase();
  const fields = inventoryProductCustomFilterFields().filter((field) => !query || field.label.toLocaleLowerCase().includes(query));
  const options = fields.length ? fields.map((field) => `<button type="button" class="inventory-custom-filter-field-option" data-custom-filter-field="${escapeHtml(field.id)}" data-rule-index="${index}">${escapeHtml(field.label)}</button>`).join("") : '<span class="inventory-product-filter-empty">No fields match this search</span>';
  return `<div class="inventory-custom-filter-field-picker"><strong>Select a field</strong><input type="search" data-custom-field-search placeholder="Search..." value="${escapeHtml(state.inventoryProductCustomFieldSearch || "")}"><div class="inventory-custom-filter-field-options" data-custom-filter-field-options>${options}</div></div>`;
}

function inventoryProductCustomFilterRuleMarkup(rule, index) {
  const field = inventoryProductCustomFilterField(rule.field) || inventoryProductCustomFilterFields()[0];
  const operators = inventoryProductCustomFilterOperators(field);
  const operator = operators.some(([value]) => value === rule.operator) ? rule.operator : "=";
  const noValue = ["set", "not set"].includes(operator);
  const multiple = ["in", "not in"].includes(operator);
  let valueControl = '<span class="inventory-custom-filter-no-value">—</span>';
  if (!noValue && field.type === "selection") {
    if (multiple) valueControl = `<input type="text" data-custom-filter-value data-rule-index="${index}" placeholder="Values, separated by commas" value="${escapeHtml(rule.value || "")}">`;
    else valueControl = `<select data-custom-filter-value data-rule-index="${index}"><option value="">Select a value</option>${(field.options || []).map((item) => `<option value="${escapeHtml(item.value)}" ${String(rule.value) === String(item.value) ? "selected" : ""}>${escapeHtml(item.label)}</option>`).join("")}</select>`;
  } else if (!noValue) {
    valueControl = `<input type="${field.type === "number" ? "number" : "text"}" ${field.type === "number" ? 'step="any"' : ""} data-custom-filter-value data-rule-index="${index}" placeholder="${multiple ? "Values, separated by commas" : "Value"}" value="${escapeHtml(rule.value ?? "")}">`;
  }
  const picker = Number(state.inventoryProductCustomFieldPickerIndex) === index ? inventoryProductCustomFilterFieldOptionsMarkup(index) : "";
  return `<div class="inventory-custom-filter-rule" data-custom-filter-rule><div class="inventory-custom-filter-field-cell"><button type="button" class="inventory-custom-filter-field-button" data-custom-filter-field-toggle data-rule-index="${index}" aria-expanded="${picker ? "true" : "false"}"><span>${escapeHtml(field.label)}</span><b aria-hidden="true">⌄</b></button>${picker}</div><select class="inventory-custom-filter-operator" data-custom-filter-operator data-rule-index="${index}" aria-label="Operator">${operators.map(([value, label]) => `<option value="${escapeHtml(value)}" ${operator === value ? "selected" : ""}>${escapeHtml(label)}</option>`).join("")}</select><div class="inventory-custom-filter-value">${valueControl}</div><div class="inventory-custom-filter-rule-actions"><button type="button" data-custom-filter-duplicate="${index}" aria-label="Duplicate rule" title="Duplicate rule"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 8V4h12v12h-4M4 8h12v12H4z"/></svg></button><button type="button" data-custom-filter-delete="${index}" aria-label="Delete rule" title="Delete rule"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13M10 11v5m4-5v5"/></svg></button></div></div>`;
}

function openInventoryProductCustomFilter() {
  state.inventoryProductCustomFilterDraft = inventoryProductCustomFilterDraftFromState();
  state.inventoryProductCustomFieldPickerIndex = -1;
  state.inventoryProductCustomFieldSearch = "";
  renderInventoryProductCustomFilterModal();
}

function renderInventoryProductCustomFilterModal() {
  const draft = state.inventoryProductCustomFilterDraft;
  if (!draft) return;
  const rows = draft.rules.map((rule, index) => inventoryProductCustomFilterRuleMarkup(rule, index)).join("");
  const content = `<header class="inventory-custom-filter-header"><h2>Custom Filter</h2><button type="button" class="modal-close" data-custom-filter-close aria-label="Close">×</button></header><div class="inventory-custom-filter-body"><div class="inventory-custom-filter-topline"><label>Match <select data-custom-filter-match><option value="all" ${draft.match === "all" ? "selected" : ""}>all</option><option value="any" ${draft.match === "any" ? "selected" : ""}>any</option></select> of the following rules:</label><label class="inventory-custom-filter-archived"><input type="checkbox" data-custom-filter-archived ${draft.includeArchived ? "checked" : ""}><span></span>Include archived</label></div><div class="inventory-custom-filter-rules">${rows || '<p class="inventory-custom-filter-empty">Add a rule to filter products.</p>'}</div><button type="button" class="inventory-custom-filter-new-rule" data-custom-filter-new-rule>New Rule</button></div><footer class="inventory-custom-filter-footer"><button type="button" class="action-button" data-custom-filter-apply>Search</button><button type="button" class="action-button secondary" data-custom-filter-close>Discard</button></footer>`;
  openModal(content);
  modalRoot.querySelector(".modal-card")?.classList.add("inventory-custom-filter-modal-card");
}

function inventoryProductSearchFacets() {
  const facets = [];
  if (state.productCategoryFilter !== "all") facets.push({ key: "category", label: `Category: ${state.productCategoryFilter}` });
  if (state.productSupplierFilter !== "all") {
    const supplier = productSupplierOptions().find((item) => item.key === state.productSupplierFilter);
    facets.push({ key: "supplier", label: `Supplier: ${supplier?.name || state.productSupplierFilter}` });
  }
  if (state.productTypeFilter !== "all") facets.push({ key: "type", label: ({ goods: "Goods", service: "Services", combo: "Combo" })[state.productTypeFilter] || "Goods" });
  if (state.productFavoriteFilter !== "all") facets.push({ key: "favorite", label: "Favorites" });
  if (state.productGroupBy) facets.push({ key: "groupBy", label: state.productGroupBy });
  if (state.productPromotionFilter !== "all") facets.push({ key: "promotion", label: `Promotion: ${state.productPromotionFilter === "cp" ? "CP" : "Non-CP"}` });
  if (state.productGiftOfferFilter !== "all") facets.push({ key: "giftOffer", label: state.productGiftOfferFilter === "configured" ? "Gift offer: Configured" : "Gift offer: Not configured" });
  if (state.productGiftItemFilter !== "all") {
    const giftItem = inventoryGiftItems().find((item) => String(item.id) === String(state.productGiftItemFilter));
    facets.push({ key: "giftItem", label: `Gift item: ${giftItem?.name || "Selected"}` });
  }
  const appFilterLabels = { published: "Published", trackedStock: "Tracked Stock", sales: "Sales", purchase: "Purchase", subscriptions: "Subscriptions", rental: "Rental", pos: "Point of Sale", expenses: "Expenses", warnings: "Warnings" };
  for (const filter of state.inventoryProductAppFilters || []) {
    if (appFilterLabels[filter]) facets.push({ key: `app:${filter}`, label: appFilterLabels[filter] });
  }
  if (state.productStatusFilter === "inactive") facets.push({ key: "status", label: "Archived" });
  else if (state.productStatusFilter === "all") facets.push({ key: "status", label: "All products" });
  if (state.inventoryProductCustomIncludeArchived) facets.push({ key: "custom:includeArchived", label: "Include archived" });
  return [...facets, ...inventoryProductCustomFilterFacets()];
}

function inventoryProductSearchMarkup() {
  const facets = inventoryProductSearchFacets();
  const categoriesList = [...new Set(categories.map((item) => item.name).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const categoryOptions = categoriesList.map((name) => ({ value: name, label: name }));
  const supplierOptions = productSupplierOptions().map((item) => ({ value: item.key, label: item.name }));
  const statusOptions = [{ value: "inactive", label: "Archived" }];
  const typeOptions = [{ value: "goods", label: "Goods" }, { value: "service", label: "Services" }, { value: "combo", label: "Combo" }];
  const appFilterOptions = [
    { value: "published", label: "Published" }, { value: "trackedStock", label: "Tracked Stock" },
    { value: "sales", label: "Sales" }, { value: "purchase", label: "Purchase" },
    { value: "subscriptions", label: "Subscriptions" }, { value: "rental", label: "Rental" },
    { value: "pos", label: "Point of Sale" }, { value: "expenses", label: "Expenses" },
    { value: "warnings", label: "Warnings" },
  ];
  const promotionOptions = [{ value: "cp", label: "CP · Gift offer" }, { value: "non-cp", label: "Non-CP · No gift offer" }];
  const giftOfferOptions = [{ value: "configured", label: "Gift configured" }, { value: "missing", label: "Gift not configured" }];
  const giftItems = inventoryStoredListOrder("inventory-gift-items", inventoryGiftItems()).filter((item) => item.archived !== true);
  const giftItemOptions = giftItems.map((item) => ({ value: String(item.id), label: item.name }));
  const groupOptions = ["Product Type", "Product Category", "eCommerce Category", "Supplier", "Stock Unit", "Product Properties", "Gift Offer"].map((name) => ({ value: name, label: name }));
  const savedSearches = state.productSavedSearches || [];
  const savedSearchMarkup = savedSearches.length ? savedSearches.map((item) => `<button type="button" class="inventory-product-filter-option" data-product-saved-search="${escapeHtml(item.id)}"><span>${escapeHtml(item.name)}</span><b aria-hidden="true">›</b></button>`).join("") : '<span class="inventory-product-filter-empty">No saved searches</span>';
  const chipMarkup = facets.map((facet) => `<span class="inventory-product-filter-chip"><span class="inventory-product-filter-chip-label">${escapeHtml(facet.label)}</span><button type="button" class="inventory-product-filter-chip-remove" data-product-filter-clear="${escapeHtml(facet.key)}" title="Remove ${escapeHtml(facet.label)} filter" aria-label="Remove ${escapeHtml(facet.label)} filter">×</button></span>`).join("");
  const filterCount = facets.length;
  const favoriteSelection = state.productFavoriteFilter === "favorites" ? "favorites" : "";
  const customGroupOptions = `<div class="inventory-product-custom-group-options" ${state.inventoryProductGroupPickerOpen ? "" : "hidden"}>${inventoryProductFilterOptionsMarkup("", "groupBy", groupOptions, state.productGroupBy)}</div>`;
  const filterToggle = `<button type="button" class="inventory-product-filter-toggle is-facet-toggle ${filterCount ? "has-filters" : ""}" data-product-filter-toggle aria-expanded="${state.inventoryProductFiltersOpen ? "true" : "false"}" aria-controls="inventory-product-filter-menu" title="Filters">${icon("filter")}</button>`;
  return `<div class="inventory-product-search-anchor"><div class="search-box sales-search inventory-products-search" role="search">${icon("search")}${filterToggle}<div class="inventory-product-filter-chips">${chipMarkup}</div><input id="global-search" type="search" value="${escapeHtml(state.search)}" placeholder="Search..." autocomplete="off" aria-label="Search products"></div><div id="inventory-product-filter-menu" class="inventory-product-filter-menu inventory-product-search-filter-menu" data-product-filter-menu ${state.inventoryProductFiltersOpen ? "" : "hidden"}><div class="inventory-product-filter-columns inventory-product-search-columns"><div class="inventory-product-filter-column"><h2><span class="inventory-product-filter-heading-icon is-filters" aria-hidden="true">${icon("filter")}</span>Filters</h2>${inventoryProductFilterOptionsMarkup("", "type", typeOptions, state.productTypeFilter)}<div class="inventory-product-filter-divider"></div>${inventoryProductFilterOptionsMarkup("", "favorite", [{ value: "favorites", label: "Favorites" }], favoriteSelection)}${inventoryProductFilterOptionsMarkup("", "app", appFilterOptions, state.inventoryProductAppFilters)}${inventoryProductFilterOptionsMarkup("", "status", statusOptions, state.productStatusFilter)}<div class="inventory-product-filter-divider"></div>${inventoryProductFilterOptionsMarkup("Product Category", "category", categoryOptions, state.productCategoryFilter)}${inventoryProductFilterOptionsMarkup("Supplier", "supplier", supplierOptions, state.productSupplierFilter)}${inventoryProductFilterOptionsMarkup("Promotion Type", "promotion", promotionOptions, state.productPromotionFilter)}${inventoryProductFilterOptionsMarkup("Gift Configuration", "giftOffer", giftOfferOptions, state.productGiftOfferFilter)}${inventoryProductFilterOptionsMarkup("Gift Item", "giftItem", giftItemOptions, state.productGiftItemFilter)}<button type="button" class="inventory-product-custom-filter-launch" data-product-custom-filter-open>${icon("filter")}<span>Custom Filter...</span></button></div><div class="inventory-product-filter-column"><h2><span class="inventory-product-filter-heading-icon is-group-by" aria-hidden="true">${icon("group")}</span>Group By</h2>${inventoryProductFilterOptionsMarkup("", "groupBy", groupOptions, state.productGroupBy)}<button type="button" class="inventory-product-filter-option inventory-product-custom-group-toggle" data-product-group-picker-toggle aria-expanded="${state.inventoryProductGroupPickerOpen ? "true" : "false"}"><span>Custom Group</span><b aria-hidden="true">${state.inventoryProductGroupPickerOpen ? "⌃" : "⌄"}</b></button>${customGroupOptions}</div><div class="inventory-product-filter-column"><h2><span class="inventory-product-filter-heading-icon is-favorites" aria-hidden="true">★</span>Favorites</h2><button type="button" class="inventory-product-save-search" data-product-save-search><span>Save search</span><b aria-hidden="true">⌄</b></button><div class="inventory-product-saved-searches">${savedSearchMarkup}</div><div class="inventory-product-filter-divider"></div><button type="button" class="inventory-product-clear-search" data-product-filter-clear-all ${(facets.length || state.search) ? "" : "disabled"}>Clear all filters</button></div></div></div></div>`;
}

function inventoryProductGroupValue(product, groupBy = state.productGroupBy) {
  if (groupBy === "Product Type") {
    return ({ goods: "Goods", service: "Services", combo: "Combo" })[inventoryProductTypeValue(product)];
  }
  if (groupBy === "Product Category") return String(product.category || "Uncategorized");
  if (groupBy === "eCommerce Category") return String(product.websiteCategory || "Uncategorized");
  if (groupBy === "Supplier") return productPrimarySupplierName(product) || "No supplier";
  if (groupBy === "Stock Unit") return String(product.stockUom || "Units");
  if (groupBy === "Product Properties") return String(product.attributes || "No properties");
  if (groupBy === "Gift Offer") return salesProductPromotionType(product) === "cp" ? "CP" : "Non-CP";
  return "";
}

function inventoryProductGroups(products) {
  if (!state.productGroupBy) return [{ label: "", products }];
  const groups = new Map();
  products.forEach((product) => {
    const label = inventoryProductGroupValue(product);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(product);
  });
  return [...groups].sort(([left], [right]) => left.localeCompare(right)).map(([label, groupedProducts]) => ({ label, products: groupedProducts }));
}

function inventoryProductAppFilterMatches(product, filter) {
  const enabledIn = product.enabledIn || {};
  const featureValues = {
    published: Boolean(product.websitePublished),
    trackedStock: product.inventoryEnabled !== false && inventoryProductTypeValue(product) === "goods",
    sales: enabledIn.sales ?? product.salesEnabled ?? true,
    purchase: enabledIn.purchase ?? product.purchaseEnabled ?? true,
    subscriptions: enabledIn.subscriptions ?? product.subscriptionsEnabled ?? false,
    rental: Boolean(product.rentalPeriod && product.rentalPeriod !== "Not for Rent"),
    pos: enabledIn.pos ?? product.posEnabled ?? false,
    expenses: enabledIn.expenses ?? product.expensesEnabled ?? false,
    warnings: !productPrimarySupplierName(product),
  };
  return Boolean(featureValues[filter]);
}

function inventoryCatalogProducts() {
  const query = state.search.trim().toLowerCase();
  const customFilterFieldMap = new Map(inventoryProductCustomFilterFields().map((field) => [field.id, field]));
  const filtered = salesProducts.filter((product) => !query || [product.name, product.sku, product.category, product.stockUom, product.packNote, product.supplierName, productPrimarySupplierName(product), ...inventoryProductGiftItems(product).map((item) => item.name)].some((value) => String(value || "").toLowerCase().includes(query)))
    .filter((product) => state.productCategoryFilter === "all" || product.category === state.productCategoryFilter)
    .filter((product) => state.productSupplierFilter === "all" || productSupplierFilterKey(product) === state.productSupplierFilter)
    .filter((product) => state.inventoryProductCustomIncludeArchived && state.productStatusFilter === "active" ? true : state.productStatusFilter === "all" || (state.productStatusFilter === "inactive" ? Boolean(product.archived) : !product.archived))
    .filter((product) => state.productTypeFilter === "all" || inventoryProductTypeValue(product) === state.productTypeFilter)
    .filter((product) => state.productFavoriteFilter !== "favorites" || Boolean(product.favorite))
    .filter((product) => [...(state.inventoryProductAppFilters || [])].every((filter) => inventoryProductAppFilterMatches(product, filter)))
    .filter((product) => state.productPromotionFilter === "all" || salesProductPromotionType(product) === state.productPromotionFilter)
    .filter((product) => state.productGiftOfferFilter === "all" || (state.productGiftOfferFilter === "configured" ? inventoryProductGiftItems(product).length > 0 : inventoryProductGiftItems(product).length === 0))
    .filter((product) => state.productGiftItemFilter === "all" || inventoryProductGiftItems(product).some((item) => String(item.id) === String(state.productGiftItemFilter)))
    .filter((product) => inventoryProductCustomFilterMatches(product, customFilterFieldMap));
  if (state.productGroupBy) {
    const groupedProducts = state.inventoryProductSortMode === "manual"
      ? inventoryStoredListOrder("inventory-products", filtered)
      : filtered.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), undefined, { sensitivity: "base" }));
    return groupedProducts.sort((a, b) => inventoryProductGroupValue(a).localeCompare(inventoryProductGroupValue(b)));
  }
  if (state.inventoryProductSortMode === "manual") return inventoryStoredListOrder("inventory-products", filtered);
  return filtered.sort((a, b) => String(a.name || "").replace(/^\[DEMO\]\s*/i, "").localeCompare(String(b.name || "").replace(/^\[DEMO\]\s*/i, ""), undefined, { sensitivity: "base" }));
}

function persistSharedVendors() {
  try {
    localStorage.setItem("odooFmcgInvoiceVendors", JSON.stringify(vendors.filter((item) => item.id > 5)));
    return true;
  } catch {
    showToast("This browser could not save the vendor locally.");
    return false;
  }
}

function createPurchaseVendor(values, select = true) {
  const name = String(values.name || "").trim();
  if (!name) { showToast("Enter a vendor name."); return null; }
  let vendor = vendors.find((item) => item.name.toLowerCase() === name.toLowerCase());
  if (vendor) {
    if (isSupplierApproved(vendor)) { if (select) setPurchaseVendor(vendor); showToast(`${vendor.name} is already in the supplier directory.`); }
    else showToast(`${vendor.name} is pending approval in Contacts.`);
    return vendor;
  }
  const id = Date.now();
  const contact = { id, kind: "supplier", name, email: String(values.email || "").trim(), phone: String(values.phone || "").trim(), reference: String(values.reference || "").trim(), taxId: String(values.taxId || "").trim(), address: String(values.address || "").trim(), street: String(values.address || "").trim(), paymentTerms: String(values.paymentTerms || "Immediate"), notes: String(values.notes || "").trim(), orders: 0, amount: 0, approved: false };
  if (!persistPartnerContact(contact)) return null;
  vendor = vendors.find((item) => String(item.id) === String(contact.linkedId));
  closeModal();
  showToast(`${name} registered as a pending supplier. Approve it in Contacts before using it in Purchase.`);
  return vendor;
}

function openPurchaseVendorCreateModal(name = "") {
  openModal(`<header class="modal-header"><div><h2>Create Vendor</h2><p>Supplier contact shared with Purchase and Accounting</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="purchase-vendor-create-form"><div class="modal-body"><div class="form-grid"><div class="field wide"><label for="purchase-vendor-name">Vendor Name</label><input id="purchase-vendor-name" name="name" required maxlength="120" value="${escapeHtml(name)}" placeholder="Company or person"></div><div class="field"><label>Email</label><input name="email" type="email" maxlength="120" placeholder="supplier@example.com"></div><div class="field"><label>Phone</label><input name="phone" type="tel" maxlength="40" placeholder="+880"></div><div class="field"><label>Supplier Reference</label><input name="reference" maxlength="60" placeholder="Vendor code"></div><div class="field"><label>Tax ID / BIN</label><input name="taxId" maxlength="60" placeholder="Optional"></div><div class="field"><label>Payment Terms</label><select name="paymentTerms"><option>Immediate</option><option>Cash on delivery</option><option>Credit · 7 days</option><option>Credit · 15 days</option><option>Credit · 30 days</option></select></div><div class="field"><label>Address</label><input name="address" maxlength="180" placeholder="District, city"></div></div></div><footer class="modal-footer"><button class="action-button secondary" type="button" data-action="close-modal">Discard</button><button class="action-button" type="submit">Create Vendor</button></footer></form>`, true);
}

function renderPurchaseVendorPicker(query = "") {
  const list = document.querySelector("#purchase-vendor-picker-list");
  if (!list) return;
  const term = String(query).trim().toLowerCase();
  const all = purchaseSupplierOptions({ includeUnapproved: true }).filter((vendor) => [vendor.name, vendor.email, vendor.phone, vendor.reference, vendor.taxId].some((value) => String(value || "").toLowerCase().includes(term)));
  const matches = all.filter(isSupplierApproved);
  const pending = all.filter((vendor) => !isSupplierApproved(vendor));
  list.innerHTML = `${matches.length ? matches.map((vendor) => `<button type="button" class="purchase-vendor-option" role="option" data-purchase-vendor-choice="select" data-vendor-id="${escapeHtml(vendor.contactId || vendor.id)}"><span class="purchase-vendor-avatar">${escapeHtml(initials(vendor.name))}</span><span><strong>${escapeHtml(vendor.name)}</strong><small>${escapeHtml([vendor.email, vendor.phone].filter(Boolean).join(" · ") || "Supplier contact")}</small></span></button>`).join("") : `<p class="purchase-vendor-empty">${term ? "No matching approved supplier contact." : "No approved suppliers are available. Add or approve one in Contacts."}</p>`}${pending.length ? `<p class="purchase-vendor-empty">${pending.length} supplier${pending.length === 1 ? " is" : "s are"} pending approval in Contacts.</p>` : ""}`;
}

function openPurchaseVendorSearch() {
  openModal(`<header class="modal-header"><div><h2>Select a Vendor</h2><p>Search the shared supplier directory</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body"><label class="purchase-vendor-search">⌕ <input id="purchase-vendor-search" type="search" placeholder="Search vendors…" autocomplete="off"></label><div id="purchase-vendor-picker-list" class="purchase-vendor-picker-list" role="listbox"></div></div><footer class="modal-footer"><button class="action-button secondary" type="button" data-action="close-modal">Close</button><button class="action-button" type="button" data-purchase-vendor-choice="create-edit">Create Vendor</button></footer>`);
  renderPurchaseVendorPicker();
}

function persistPurchaseOrders() {
  try { localStorage.setItem("odooFmcgPurchaseOrders", JSON.stringify(purchaseOrders)); return true; }
  catch { showToast("This browser could not save purchase orders locally."); return false; }
}

function createPurchaseAlternative(source) {
  if (!source) { showToast("Save this RFQ before adding an alternative."); return; }
  if (["Cancelled", "Purchase Order"].includes(source.status)) { showToast("Create alternatives from an RFQ before confirming it as a Purchase Order."); return; }
  if (state.settings.purchaseAlternatives === false) { showToast("Enable Purchase Alternative in Purchase settings first."); return; }
  const previousGroup = source.alternativeGroupId;
  const group = previousGroup || `PURCHASE-ALT-${source.id}`;
  const sequence = purchaseOrders.reduce((max, item) => Math.max(max, Number(String(item.ref || "").replace(/\D/g, "")) || 0), 0) + 1;
  const now = new Date().toISOString();
  const alternative = {
    ...source,
    id: Date.now(),
    ref: `RFQ${String(sequence).padStart(4, "0")}`,
    vendor: "",
    vendorContactId: null,
    vendorReference: "",
    status: "RFQ",
    createdAt: now,
    confirmedAt: "",
    sentToVendor: false,
    sentAt: "",
    acknowledged: false,
    acknowledgedAt: "",
    receiptStatus: "Not Received",
    receiptIds: [],
    received: false,
    isReceived: false,
    late: false,
    lateReceipt: false,
    alternativeGroupId: group,
    lines: (source.lines || []).map((line) => ({ ...line, receivedQty: 0 })),
  };
  source.alternativeGroupId = group;
  purchaseOrders.push(alternative);
  if (!persistPurchaseOrders()) {
    purchaseOrders.pop();
    if (previousGroup) source.alternativeGroupId = previousGroup;
    else delete source.alternativeGroupId;
    return;
  }
  state.purchaseEditor = { id: alternative.id, returnPage: state.purchaseEditor?.returnPage || "rfq" };
  state.purchaseTab = "products";
  state.purchaseFavorite = false;
  render();
  showToast("Alternative RFQ created. Choose a supplier and review its quotation.");
}

function persistPurchaseReceipts() {
  try { localStorage.setItem("odooFmcgPurchaseReceipts", JSON.stringify(state.purchaseReceipts)); return true; }
  catch { showToast("This browser could not save receipt records locally."); return false; }
}

function openPurchaseReceipt(orderId, receiptId = null, forceNew = false) {
  const order = purchaseOrders.find((item) => item.id === Number(orderId));
  if (!order || order.status !== "Purchase Order") { showToast("Confirm the purchase order before receiving products."); return; }
  if (!(order.lines || []).some((line) => !line.type && line.sku)) { showToast("Add products to the purchase order before receiving stock."); return; }
  const latest = [...state.purchaseReceipts].filter((item) => item.orderId === order.id && item.status !== "Cancelled").sort((a, b) => Number(b.id) - Number(a.id))[0];
  const receipt = receiptId ? state.purchaseReceipts.find((item) => item.id === Number(receiptId)) : (!forceNew ? latest : null);
  state.purchaseEditor = null;
  state.receiptEditor = { orderId: order.id, id: receipt?.id || null, returnPage: state.page };
  state.receiptTab = "operations";
  closeModal();
  render();
}

function purchaseReceiptOutstanding(order, orderLine, exceptReceiptId = null) {
  const product = salesProducts.find((item) => item.sku === orderLine.sku || item.name === orderLine.product);
  const orderFactor = product ? purchaseUnitFactor(product, orderLine.uom || product.stockUom) : 1;
  if (!orderFactor) return Number(orderLine.qty || 0);
  const received = state.purchaseReceipts.filter((receipt) => receipt.orderId === order.id && receipt.id !== exceptReceiptId && receipt.status === "Done")
    .flatMap((receipt) => receipt.lines || [])
    .filter((line) => line.sku === orderLine.sku)
    .reduce((sum, line) => {
      const factor = product ? purchaseUnitFactor(product, line.uom || product.stockUom) : 1;
      return sum + (factor ? Number(line.qty || 0) * factor / orderFactor : 0);
    }, 0);
  return Math.max(0, Number(orderLine.qty || 0) - received);
}

function receiptLineMarkup(line = {}, readonly = false, order = null) {
  const selected = salesProducts.find((item) => item.name === line.product || item.sku === line.sku) || (line.blank ? null : salesProducts[0]);
  const selectedUnit = line.uom || selected?.stockUom || "Piece";
  const decimal = purchaseUnitAllowsFraction(selectedUnit);
  const units = selected ? purchaseUnits(selected) : [selectedUnit];
  const orderSkus = order ? new Set((order.lines || []).filter((item) => !item.type).map((item) => item.sku)) : null;
  const selectableProducts = salesProducts.filter((item) => inventoryStockProductType(item) === "Goods" && (!orderSkus || orderSkus.has(item.sku)));
  const disabled = readonly ? "disabled" : "";
  const productPicker = `<div class="inventory-delivery-product-picker"><select data-receipt-product aria-label="Receipt product" ${disabled}><option value="" ${selected ? "" : "selected"}>Select a product...</option>${selectableProducts.map((item) => `<option value="${item.id}" ${item.id === selected?.id ? "selected" : ""}>${escapeHtml(item.name)} · ${escapeHtml(item.sku)}</option>`).join("")}</select>${readonly || order ? "" : sharedProductCatalogPickerButton("receipt-row", "Catalog")}</div>`;
  return `<tr class="purchase-receipt-line"><td>${productPicker}<small>${escapeHtml(selected?.sku || selected?.packNote || "")}</small></td><td><input data-receipt-qty type="number" min="0" step="${decimal ? "0.001" : "1"}" value="${escapeHtml(line.qty ?? 0)}" aria-label="Quantity demanded" ${disabled}></td><td><select data-receipt-uom data-current-unit="${escapeHtml(selectedUnit)}" aria-label="Receipt unit" ${disabled}>${units.map((unit) => { const factor = selected && purchaseUnitFactor(selected, unit); return `<option value="${escapeHtml(unit)}" ${unit === selectedUnit ? "selected" : ""} ${factor || !selected ? "" : "disabled"}>${escapeHtml(unit)}${factor || !selected ? "" : " · configure pack"}</option>`; }).join("")}</select></td><td>${readonly ? "" : `<button type="button" class="soft-icon-button" data-action="remove-receipt-line" aria-label="Remove product">×</button>`}</td></tr>`;
}

function openStandaloneReceipt() {
  state.receiptEditor = { orderId: null, id: null, returnPage: "inventory-receipts" };
  state.receiptTab = "operations";
  render();
}

function saveStandaloneReceipt(action) {
  const form = document.querySelector("#receipt-form");
  if (!form) return;
  const editor = state.receiptEditor || {};
  const previous = state.purchaseReceipts.find((item) => item.id === Number(editor.id)) || null;
  if (previous && ["Done", "Cancelled"].includes(previous.status)) { showToast("Completed or cancelled receipts are read-only."); return; }
  if (action === "cancel") {
    if (previous) {
      const oldStatus = previous.status;
      previous.status = "Cancelled";
      if (!persistPurchaseReceipts()) { previous.status = oldStatus; return; }
    }
    state.receiptEditor = null; setPage("inventory-receipts"); showToast("Receipt cancelled; stock was not changed."); return;
  }
  const data = new FormData(form);
  const lines = [...form.querySelectorAll("#receipt-line-items .purchase-receipt-line")].map((row) => {
    const product = salesProducts.find((item) => item.id === Number(row.querySelector("[data-receipt-product]")?.value));
    return product ? { product: product.name, sku: product.sku, uom: row.querySelector("[data-receipt-uom]")?.value || product.stockUom, qty: Number(row.querySelector("[data-receipt-qty]")?.value || 0) } : null;
  }).filter((line) => line && line.qty > 0);
  if (!String(data.get("vendor") || "").trim()) { showToast("Choose who the receipt is coming from."); document.querySelector("#receipt-vendor")?.focus(); return; }
  if (!lines.length) { showToast("Add at least one product with a positive received quantity."); document.querySelector("[data-receipt-product]")?.focus(); return; }
  if (lines.some((line) => { const product = salesProducts.find((item) => item.sku === line.sku); return !product || inventoryStockProductType(product) !== "Goods" || !inventoryQuantityValid(line.qty, line.uom) || !purchaseUnitFactor(product, line.uom); })) { showToast("Choose storable Goods products and enter valid quantities using configured units."); return; }
  const location = String(data.get("destination") || "WH/Stock");
  if (!state.inventoryLocations.some((item) => item.name === location && String(item.usage || "Internal").toLowerCase() === "internal")) { showToast("Choose a configured internal destination location."); return; }
  const sequence = state.purchaseReceipts.reduce((max, item) => Math.max(max, Number(String(item.ref || "").replace(/\D/g, "")) || 0), 0) + (previous ? 0 : 1);
  const record = { ...(previous || {}), id: previous?.id || Date.now(), ref: previous?.ref || `WH/IN/${String(sequence).padStart(4, "0")}`, orderId: null, orderRef: "", vendor: String(data.get("vendor") || "").trim(), operationType: String(data.get("operationType") || "YourCompany: Receipts"), destination: location, scheduledDate: String(data.get("scheduledDate") || inputLocalDateTime()), sourceDocument: String(data.get("sourceDocument") || "").trim(), salesOrder: String(data.get("salesOrder") || "").trim(), carrier: String(data.get("carrier") || ""), trackingReference: String(data.get("trackingReference") || "").trim(), weight: Number(data.get("weight") || 0), shippingWeight: Number(data.get("shippingWeight") || 0), responsible: String(data.get("responsible") || state.userProfile.name), company: String(data.get("company") || "Arafat Chemica"), batchTransfer: String(data.get("batchTransfer") || "").trim(), project: String(data.get("project") || "").trim(), note: String(data.get("note") || ""), lines, status: action === "validate" ? "Done" : "Ready", dateDone: action === "validate" ? inputLocalDate() : previous?.dateDone || "" };
  const receiptSnapshot = state.purchaseReceipts.map((item) => ({ ...item, lines: (item.lines || []).map((line) => ({ ...line })) }));
  const stockSnapshot = action === "validate" ? inventorySnapshot() : null;
  if (action === "validate") {
    for (const line of lines) {
      const product = salesProducts.find((item) => item.sku === line.sku);
      const factor = purchaseUnitFactor(product, line.uom);
      if (!product || !factor || !inventoryAdjustQtyAt(product, location, line.qty * factor)) { inventoryRestore(stockSnapshot); showToast(`${line.product}: stock could not be updated at ${location}.`); return; }
    }
    if (!inventoryCommit(stockSnapshot)) return;
  }
  if (previous) Object.assign(previous, record); else state.purchaseReceipts.push(record);
  if (!persistPurchaseReceipts()) {
    state.purchaseReceipts.splice(0, state.purchaseReceipts.length, ...receiptSnapshot);
    if (stockSnapshot) inventoryRestore(stockSnapshot);
    return;
  }
  if (action === "mark-ready") {
    const task = createInventoryReceiptTodo(record);
    if (!task) { state.receiptEditor = { orderId: null, id: record.id, returnPage: "inventory-receipts" }; render(); showToast("Receipt is Ready, but its To-do summary could not be saved."); return; }
    state.receiptEditor = null; setPage("todo"); showToast(`${record.ref} marked Ready and added to To-dos with its receipt summary.`); return;
  }
  state.receiptEditor = { orderId: null, id: record.id, returnPage: editor.returnPage || "inventory-receipts" };
  render(); showToast(action === "validate" ? "Receipt validated and shared stock updated." : "Receipt marked Ready; stock remains unchanged until Validate.");
}

function renderPurchaseReceiptForm() {
  const editor = state.receiptEditor || {};
  const order = purchaseOrders.find((item) => item.id === Number(editor.orderId));
  const receipt = state.purchaseReceipts.find((item) => item.id === Number(editor.id)) || null;
  const manual = !order;
  const status = receipt?.status || "Draft";
  const readonly = ["Done", "Cancelled"].includes(status);
  const ref = receipt?.ref || "New Receipt";
  const lines = receipt?.lines?.length ? receipt.lines : (order?.lines || []).filter((line) => !line.type).map((line) => ({ product: line.product, sku: line.sku, uom: line.uom, qty: purchaseReceiptOutstanding(order, line) })).filter((line) => line.qty > 0);
  const rows = lines.length ? lines.map((line) => receiptLineMarkup(line, readonly, order)).join("") : (manual ? "" : receiptLineMarkup({ blank: true }, readonly, order));
  const actions = status === "Done" ? `<button type="button" class="action-button secondary" data-action="print-purchase">Print</button>` : status === "Cancelled" ? "" : `<button type="button" class="action-button secondary" data-receipt-action="mark-ready">Mark as To Do</button><button type="button" class="action-button" data-receipt-action="validate">Validate</button><button type="button" class="action-button secondary" data-receipt-action="cancel">Cancel</button>`;
  const step = status === "Done" ? 2 : status === "Ready" ? 1 : 0;
  const statusbar = `<div class="sales-statusbar purchase-receipt-statusbar" aria-label="Receipt status"><span class="${step === 0 ? "is-current" : "is-done"}">Draft</span><span class="${step === 1 ? "is-current" : step > 1 ? "is-done" : ""}">Ready</span><span class="${step === 2 ? "is-current" : ""}">Done</span></div>`;
  const vendor = receipt?.vendor || order?.vendor || "";
  const vendorNames = [...new Set([vendor, ...vendors.map((item) => item.name)].filter(Boolean))];
  const scheduledValue = receipt?.scheduledDate && /^\d{4}-\d\d-\d\dT/.test(receipt.scheduledDate) ? receipt.scheduledDate : inputLocalDateTime();
  const locations = state.inventoryLocations.filter((item) => String(item.usage || "Internal").toLowerCase() === "internal");
  const carrierOptions = ["Standard delivery", "The Poste", "Local Delivery", "Express Delivery", ...inventoryConfigRecords("inventory-delivery-methods").map((item) => item.name)].filter((item, index, all) => all.indexOf(item) === index);
  const linkedSalesOrders = state.salesOrders.filter((item) => ["Sales Order", "Delivered"].includes(item.status));
  const salesOrderOptions = [...new Set([receipt?.salesOrder, ...linkedSalesOrders.map((item) => item.ref)].filter(Boolean))].map((reference) => `<option value="${escapeHtml(reference)}" ${reference === (receipt?.salesOrder || "") ? "selected" : ""}>${escapeHtml(reference)}</option>`).join("");
  const salesOrderField = `<div class="field"><label for="receipt-sales-order">Sales Order</label><select id="receipt-sales-order" name="salesOrder" ${readonly ? "disabled" : ""}><option value="">Select a Sales Order...</option>${salesOrderOptions}</select></div>`;
  const locationOptions = locations.map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === (receipt?.destination || "WH/Stock") ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("");
  const vendorField = manual
    ? `<select id="receipt-vendor" name="vendor" ${readonly ? "disabled" : ""} required><option value="">Select a supplier...</option>${vendorNames.map((name) => `<option value="${escapeHtml(name)}" ${name === vendor ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}</select>`
    : `<input id="receipt-vendor" name="vendor" value="${escapeHtml(vendor)}" readonly>`;
  return `<section class="sales-document-page purchase-document-page purchase-receipt-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button class="action-button" type="button" disabled>New</button><div><button type="button" class="sales-breadcrumb" data-receipt-editor-action="back">Receipts</button><h1>${receipt ? escapeHtml(ref) : "New"}</h1><small>${escapeHtml(order?.ref || "")}</small></div></div><div class="sales-document-toolbar-right"><button type="button" class="action-button secondary" data-module-page="inventory-moves">Moves</button><button type="button" class="action-button secondary" data-inventory-action="operation-barcode" data-id="receipt">Barcode</button><button type="button" class="soft-icon-button" data-receipt-editor-action="back" aria-label="Close">×</button></div></div><div class="sales-document-actionbar"><div class="sales-document-buttons">${actions}</div>${statusbar}</div><div class="erp-finance-form-layout"><main><form id="receipt-form" data-id="${receipt?.id || ""}" autocomplete="off"><article class="sales-document-card"><header class="purchase-document-heading"><div><h2><button type="button" class="purchase-favorite" aria-hidden="true">☆</button>${escapeHtml(ref)}</h2></div></header><section class="sales-document-fields purchase-document-fields purchase-receipt-fields"><div class="sales-field-main"><div class="field"><label for="receipt-vendor">Receive From</label>${vendorField}</div><div class="field"><label for="receipt-operation">Operation Type</label><select id="receipt-operation" name="operationType" ${readonly ? "disabled" : ""}><option ${(!receipt?.operationType || receipt.operationType === "YourCompany: Receipts" || receipt.operationType === "Arafat Chemica: Receipts") ? "selected" : ""}>YourCompany: Receipts</option><option ${receipt?.operationType === "YourCompany: Dropship" ? "selected" : ""}>YourCompany: Dropship</option></select></div></div><div class="sales-field-side"><div class="field"><label for="receipt-date">Scheduled Date <sup>?</sup></label><input id="receipt-date" name="scheduledDate" type="datetime-local" value="${escapeHtml(scheduledValue)}" ${readonly ? "disabled" : ""}></div><div class="field"><label for="receipt-source">Source Document</label><input id="receipt-source" name="sourceDocument" value="${escapeHtml(receipt?.sourceDocument || order?.ref || "")}" ${readonly || order ? "readonly" : ""} placeholder="e.g. PO0032"></div><div class="field"><label for="receipt-destination">Destination</label><select id="receipt-destination" name="destination" ${readonly ? "disabled" : ""}>${locationOptions}</select></div></div></section><nav class="sales-document-tabs purchase-receipt-tabs" aria-label="Receipt details"><button type="button" data-receipt-tab="operations" class="${state.receiptTab === "operations" ? "is-active" : ""}">Operations</button><button type="button" data-receipt-tab="additional-info" class="${state.receiptTab === "additional-info" ? "is-active" : ""}">Additional Info</button><button type="button" data-receipt-tab="note" class="${state.receiptTab === "note" ? "is-active" : ""}">Note</button></nav><section class="sales-tab-panel ${state.receiptTab === "operations" ? "is-active" : ""}" data-receipt-panel="operations"><div class="sale-lines-scroll"><table class="order-lines sales-native-lines purchase-native-lines purchase-receipt-lines"><thead><tr><th>Product</th><th>Demand</th><th>Unit</th><th></th></tr></thead><tbody id="receipt-line-items">${rows}</tbody></table></div>${readonly ? "" : `<div class="sales-line-actions"><button type="button" data-action="add-receipt-line">Add a Product</button></div>`}</section><section class="sales-tab-panel ${state.receiptTab === "additional-info" ? "is-active" : ""}" data-receipt-panel="additional-info"><div class="sales-other-info-grid"><section><h3>Shipping Information</h3><div class="field"><label for="receipt-carrier">Carrier</label><select id="receipt-carrier" name="carrier" ${readonly ? "disabled" : ""}><option value="">Select a carrier...</option>${carrierOptions.map((name) => `<option value="${escapeHtml(name)}" ${receipt?.carrier === name ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}</select></div><div class="field"><label>Tracking Reference</label><input name="trackingReference" value="${escapeHtml(receipt?.trackingReference || "")}" ${readonly ? "readonly" : ""}></div><div class="field"><label>Weight · kg</label><input name="weight" type="number" min="0" step="0.01" value="${escapeHtml(receipt?.weight || 0)}" ${readonly ? "readonly" : ""}></div><div class="field"><label>Weight for shipping · kg</label><input name="shippingWeight" type="number" min="0" step="0.01" value="${escapeHtml(receipt?.shippingWeight || 0)}" ${readonly ? "readonly" : ""}></div></section><section><h3>Other Information</h3>${salesOrderField}<div class="field"><label>Responsible</label><input name="responsible" value="${escapeHtml(receipt?.responsible || state.userProfile.name)}" ${readonly ? "readonly" : ""}></div><div class="field"><label>Company</label><input name="company" value="${escapeHtml(receipt?.company || "Arafat Chemica")}" ${readonly ? "readonly" : ""}></div><div class="field"><label>Batch Transfer</label><input name="batchTransfer" value="${escapeHtml(receipt?.batchTransfer || "")}" ${readonly ? "readonly" : ""}></div><div class="field"><label>Project</label><input name="project" value="${escapeHtml(receipt?.project || "")}" ${readonly ? "readonly" : ""}></div></section></div></section><section class="sales-tab-panel ${state.receiptTab === "note" ? "is-active" : ""}" data-receipt-panel="note"><div class="purchase-receipt-note"><label for="receipt-note">Internal Note</label><textarea id="receipt-note" name="note" ${readonly ? "readonly" : ""} placeholder="Add an internal note that will be printed on the Picking Operations sheet">${escapeHtml(receipt?.note || "")}</textarea></div></section></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button" data-action="purchase-message">Send message</button><button type="button" class="action-button secondary" data-action="purchase-note">Log note</button><button type="button" class="action-button secondary" data-action="purchase-activity">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${receipt ? `${escapeHtml(status)} · ${escapeHtml(receipt.ref)}` : `Receiving ${escapeHtml(order?.ref || "supplier")}`}</p></div></div><p class="erp-chatter-note">Supplier order and receipt history stay linked.</p></aside></div></section>`;
}

function savePurchaseReceipt(action) {
  const form = document.querySelector("#receipt-form");
  if (!form) return;
  const editor = state.receiptEditor || {};
  const order = purchaseOrders.find((item) => item.id === Number(editor.orderId));
  if (!order) { saveStandaloneReceipt(action); return; }
  const previous = state.purchaseReceipts.find((item) => item.id === Number(editor.id)) || null;
  if (!order || order.status !== "Purchase Order") { showToast("This receipt is no longer linked to a confirmed purchase order."); return; }
  if (action === "cancel") {
    if (previous) { const oldStatus = previous.status; previous.status = "Cancelled"; if (!persistPurchaseReceipts()) { previous.status = oldStatus; return; } }
    openOrderModal(order.id); showToast("Receipt cancelled; no stock was changed."); return;
  }
  const data = new FormData(form);
  const receiptsSnapshot = state.purchaseReceipts.map((item) => ({ ...item, lines: (item.lines || []).map((line) => ({ ...line })) }));
  const inventoryBefore = inventorySnapshot();
  const orderSnapshot = { ...order, lines: (order.lines || []).map((line) => ({ ...line })), receiptIds: [...(order.receiptIds || [])] };
  const lines = [...form.querySelectorAll("#receipt-line-items .purchase-receipt-line")].map((row) => {
    const product = salesProducts.find((item) => item.id === Number(row.querySelector("[data-receipt-product]")?.value));
    return product ? { product: product.name, sku: product.sku, uom: row.querySelector("[data-receipt-uom]")?.value || product.stockUom, qty: Number(row.querySelector("[data-receipt-qty]")?.value || 0) } : null;
  }).filter((line) => line && line.qty > 0);
  if (!lines.length) { showToast("Add at least one product with a positive received quantity."); document.querySelector("[data-receipt-product]")?.focus(); return; }
  if (lines.some((line) => line.qty <= 0 || (!/[0-9]/.test(String(line.qty))) || (!purchaseUnitAllowsFraction(line.uom) && !Number.isInteger(line.qty)))) { showToast("Enter whole quantities for packs, cartons, bags, and pieces; use decimals only for weight or volume units."); return; }
  if (lines.some((line) => { const product = salesProducts.find((item) => item.sku === line.sku); return !product || !purchaseUnitFactor(product, line.uom); })) { showToast("Set the verified pack conversion for each selected unit before receiving it."); return; }
  const orderLines = (order.lines || []).filter((line) => !line.type);
  const receivedBySku = new Map();
  for (const line of lines) {
    const ordered = orderLines.find((item) => item.sku === line.sku);
    const product = salesProducts.find((item) => item.sku === line.sku);
    if (!ordered) { showToast(`${line.product} is not included on this Purchase Order.`); return; }
    if (ordered && purchaseUnitFactor(product, ordered.uom || product.stockUom)) {
      const lineFactor = purchaseUnitFactor(product, line.uom);
      const orderedFactor = purchaseUnitFactor(product, ordered.uom || product.stockUom);
      const qtyInOrderUnit = (receivedBySku.get(line.sku) || 0) + line.qty * lineFactor / orderedFactor;
      receivedBySku.set(line.sku, qtyInOrderUnit);
      const remaining = purchaseReceiptOutstanding(order, ordered, previous?.id || null);
      if (qtyInOrderUnit > remaining + 0.0001) { showToast(`${line.product}: combined received quantity is above the remaining purchase order quantity (${money(remaining)} ${ordered.uom}).`); return; }
    }
  }
  const sequence = state.purchaseReceipts.reduce((max, item) => Math.max(max, Number(String(item.ref || "").replace(/\D/g, "")) || 0), 0) + (previous ? 0 : 1);
  const record = { ...(previous || {}), id: previous?.id || Date.now(), ref: previous?.ref || `WH/IN/${String(sequence).padStart(4, "0")}`, orderId: order.id, orderRef: order.ref, vendor: String(data.get("vendor") || order.vendor), operationType: String(data.get("operationType") || "Arafat Chemica: Receipts"), destination: String(data.get("destination") || "WH/Stock"), scheduledDate: String(data.get("scheduledDate") || inputLocalDate()), sourceDocument: order.ref, salesOrder: String(data.get("salesOrder") || "").trim(), responsible: String(data.get("responsible") || ""), company: String(data.get("company") || "Arafat Chemica"), note: String(data.get("note") || ""), lines, status: action === "mark-ready" ? "Ready" : "Done", dateDone: action === "validate" ? inputLocalDate() : previous?.dateDone || "" };
  if (action === "validate" && previous?.status !== "Done") {
    for (const line of lines) {
      const product = salesProducts.find((item) => item.sku === line.sku);
      if (!inventoryAdjustQtyAt(product, record.destination, line.qty * purchaseUnitFactor(product, line.uom))) {
        inventoryRestore(inventoryBefore);
        showToast(`${line.product}: could not update stock at ${record.destination}.`);
        return;
      }
    }
    try {
      localStorage.setItem("odooFmcgSalesProducts", JSON.stringify(salesProducts));
      localStorage.setItem("odooFmcgInventoryBalances", JSON.stringify(state.inventoryBalances));
    } catch { inventoryRestore(inventoryBefore); showToast("Stock could not be saved locally; this receipt was not validated."); return; }
  }
  if (previous) Object.assign(previous, record); else state.purchaseReceipts.push(record);
  if (action === "validate") {
    order.lines = (order.lines || []).map((ordered) => {
      if (ordered.type) return ordered;
      const product = salesProducts.find((item) => item.sku === ordered.sku);
      const orderFactor = product ? purchaseUnitFactor(product, ordered.uom || product.stockUom) : null;
      const receivedInStock = state.purchaseReceipts.filter((item) => item.orderId === order.id && item.status === "Done").flatMap((item) => item.lines || []).filter((line) => line.sku === ordered.sku).reduce((sum, line) => sum + Number(line.qty || 0) * (product ? purchaseUnitFactor(product, line.uom) || 0 : 0), 0);
      return { ...ordered, receivedQty: orderFactor ? receivedInStock / orderFactor : Number(ordered.receivedQty || 0) };
    });
    const allReceived = order.lines.filter((line) => !line.type).every((line) => Number(line.receivedQty || 0) >= Number(line.qty || 0));
    order.receiptStatus = order.lines.some((line) => !line.type && Number(line.receivedQty || 0) > 0) ? (allReceived ? "Received" : "Partially Received") : "Not Received";
    order.receiptIds = [...new Set([...(order.receiptIds || []), record.id])];
  }
  if (!persistPurchaseReceipts() || !persistPurchaseOrders()) {
    inventoryRestore(inventoryBefore);
    state.purchaseReceipts.splice(0, state.purchaseReceipts.length, ...receiptsSnapshot);
    Object.keys(order).forEach((key) => delete order[key]);
    Object.assign(order, orderSnapshot);
    try {
      localStorage.setItem("odooFmcgPurchaseReceipts", JSON.stringify(state.purchaseReceipts));
      localStorage.setItem("odooFmcgPurchaseOrders", JSON.stringify(purchaseOrders));
      if (action === "validate") localStorage.setItem("odooFmcgSalesProducts", JSON.stringify(salesProducts));
    } catch { /* Preserve the in-memory rollback if browser storage is unavailable. */ }
    return;
  }
  if (action === "mark-ready") {
    const task = createInventoryReceiptTodo(record);
    if (!task) { state.receiptEditor = { orderId: order.id, id: record.id, returnPage: editor.returnPage || state.page }; render(); showToast("Receipt is Ready, but its To-do summary could not be saved."); return; }
    state.receiptEditor = null; setPage("todo"); showToast(`${record.ref} marked Ready and added to To-dos with its receipt summary.`); return;
  }
  state.receiptEditor = { orderId: order.id, id: record.id, returnPage: editor.returnPage || state.page };
  render();
  showToast(action === "validate" ? `Receipt validated. Stock updated for ${lines.length} product line${lines.length === 1 ? "" : "s"}.` : "Receipt marked Ready; stock remains unchanged until Validate.");
}

function salesProductGiftOfferNames(product, offerId = "") {
  const offer = salesProductOffer(product, offerId);
  if (Array.isArray(product?.consumerOffers)) {
    return [...new Set((offer?.giftItemIds || []).map((id) => inventoryGiftItems().find((item) => String(item.id) === String(id) && item.archived !== true)?.name || "").filter(Boolean))];
  }
  const rule = inventoryGiftConfigurationForProduct(product);
  if (!rule || rule.active === false || rule.promotionType !== "cp") return [];
  return [...new Set((offer?.giftItemIds || rule.giftItemIds || []).map((id) => inventoryGiftItems().find((item) => String(item.id) === String(id))?.name || "").filter(Boolean))];
}

function salesLineConsumerOfferSelectMarkup(product, selectedOfferId = "", disabled = false) {
  const offers = inventoryProductConsumerOffers(product);
  const selected = salesProductOffer(product, selectedOfferId);
  return `<select class="sale-consumer-offer-select" data-sale-consumer-offer aria-label="Consumer offer" ${disabled ? "disabled" : ""}>${offers.map((offer) => `<option value="${escapeHtml(offer.id)}" ${offer.id === selected?.id ? "selected" : ""}>${escapeHtml(offer.name)} · ${salesCurrency(offer.unitPrice)} / ${escapeHtml(product.stockUom || "unit")}</option>`).join("")}</select>`;
}

function salesLinePromotionGiftMarkup(product, selectedGift = "", disabled = false, offerId = "") {
  const offer = salesProductOffer(product, offerId);
  const gifts = salesProductGiftOfferNames(product, offer?.id);
  if (!gifts.length) return "";
  const mode = offer?.giftSelectionMode || salesProductGiftSelectionMode(product);
  if (mode !== "choose-one" || gifts.length === 1) {
    const gift = mode === "choose-one" ? gifts[0] : gifts.join(", ");
    return `<input type="hidden" data-sale-promotion-gift value="${escapeHtml(gift)}"><small class="sale-promotion-gift-fixed">Gift included · ${escapeHtml(gift)}</small>`;
  }
  const selection = gifts.includes(selectedGift) ? selectedGift : "";
  const options = gifts.map((gift) => `<option value="${escapeHtml(gift)}" ${gift === selection ? "selected" : ""}>${escapeHtml(gift)}</option>`).join("");
  return `<label class="sale-promotion-gift-choice"><span>Free gift · choose 1</span><select data-sale-promotion-gift aria-label="Choose one promotional gift" ${disabled ? "disabled" : ""} required><option value="">Select a gift</option>${options}</select></label>`;
}

function currentSalesProductFlow() {
  const order = state.salesOrders.find((item) => Number(item.id) === Number(state.salesEditor?.id));
  return (state.salesEditor?.channel || order?.salesChannel) === "Point of Sale" ? "pos" : "sales";
}

function saleLineMarkup(line = {}, readonly = false, flow = currentSalesProductFlow(), lineNumber = null) {
  const disabled = readonly ? "disabled" : "";
  const numberCell = state.salesSettings.showLineNumbers === true ? `<td class="sale-line-number" data-sale-line-number>${lineNumber || ""}</td>` : "";
  if (line.type === "section" || line.type === "note") {
    return `<tr class="sale-special-line sale-${line.type}" data-line-type="${line.type}">${numberCell}<td colspan="7"><input data-sale-description type="text" value="${escapeHtml(line.description || "")}" placeholder="${line.type === "section" ? "Section title" : "Add a note..."}" aria-label="${line.type === "section" ? "Section title" : "Order note"}" ${disabled}></td><td><button type="button" class="soft-icon-button" data-action="remove-sale-line" aria-label="Remove line" ${disabled}>×</button></td></tr>`;
  }
  const selected = salesProducts.find((item) => item.name === line.product || item.sku === line.sku) || selectableProductRecords(null, flow)[0] || salesProducts[0];
  const selectableProducts = selectableProductRecords(selected, flow);
  const units = selected.saleUnits;
  const selectedUnit = units.includes(line.uom) ? line.uom : units[0];
  const decimal = salesUnitAllowsFraction(selected, selectedUnit);
  const salesTax = line.taxId || selected.salesTaxId || null;
  const offer = salesProductOffer(selected, line.consumerOfferId);
  const priceForUnit = line.price ?? salesProductOfferPrice(selected, offer, selectedUnit);
  const offerMarkup = readonly && line.consumerOfferName
    ? `<small class="sale-consumer-offer-snapshot" data-sale-consumer-offer-snapshot="${escapeHtml(line.consumerOfferName)}">Consumer offer · ${escapeHtml(line.consumerOfferName)}</small>`
    : salesLineConsumerOfferSelectMarkup(selected, offer?.id, readonly);
  const giftMarkup = readonly && line.consumerOfferName
    ? (line.promotionGift ? `<small class="sale-promotion-gift-fixed" data-sale-promotion-gift-snapshot="${escapeHtml(line.promotionGift)}">Gift included · ${escapeHtml(line.promotionGift)}</small>` : "")
    : salesLinePromotionGiftMarkup(selected, line.promotionGift || "", readonly, offer?.id);
  const discountDisabled = readonly || state.salesSettings.lineDiscountsEnabled === false ? "disabled" : "";
  return `<tr class="sale-line">${numberCell}<td><select class="sale-product-select" data-sale-product aria-label="Sales product" ${disabled}>${selectableProducts.map((item) => `<option value="${item.id}" ${selected.id === item.id ? "selected" : ""}>${escapeHtml(item.name)} · ${escapeHtml(item.sku)}</option>`).join("")}</select><small class="sales-line-note">${escapeHtml(selected.sku)}</small>${offerMarkup}${giftMarkup}</td><td><input data-sale-qty type="number" min="${decimal ? "0.001" : "1"}" step="${decimal ? "0.001" : "1"}" value="${escapeHtml(line.qty ?? 1)}" aria-label="Quantity" ${disabled}></td><td><select data-sale-uom data-current-unit="${escapeHtml(selectedUnit)}" aria-label="Sales unit" ${disabled}>${units.map((unit) => `<option value="${escapeHtml(unit)}" ${unit === selectedUnit ? "selected" : ""} ${selected.unitFactors?.[unit] ? "" : "disabled"}>${escapeHtml(unit)}${selected.unitFactors?.[unit] ? "" : " · configure pack"}</option>`).join("")}</select><small class="sales-line-note">${escapeHtml(selected.packNote)}</small><small class="sales-line-conversion" data-sale-conversion-preview>${escapeHtml(productUnitConversionPreview(selected, Number(line.qty ?? 1), selectedUnit))}</small></td><td><input data-sale-price type="number" min="0" step="any" value="${escapeHtml(priceForUnit)}" aria-label="Unit price in taka" ${disabled}></td><td><select data-sale-tax aria-label="Sales tax" ${disabled}>${invoiceTaxOptions("out_invoice", salesTax)}</select></td><td><input class="sales-line-discount" data-sale-discount type="number" min="0" max="100" step="0.01" value="${escapeHtml(line.discount ?? 0)}" aria-label="Discount percentage" ${discountDisabled}></td><td class="sale-line-subtotal">${salesCurrency(line.amount || line.subtotal || 0)}</td><td><button type="button" class="soft-icon-button" data-action="remove-sale-line" aria-label="Remove line" ${disabled}>×</button></td></tr>`;
}

function nextSalesLineNumber() {
  return (document.querySelectorAll("#sale-line-items tr").length || 0) + 1;
}

function renumberSalesLines() {
  if (state.salesSettings.showLineNumbers !== true) return;
  document.querySelectorAll("#sale-line-items tr").forEach((row, index) => {
    const number = row.querySelector("[data-sale-line-number]");
    if (number) number.textContent = String(index + 1);
  });
}

function updateSaleTotal() {
  const form = document.querySelector("#sale-order-form");
  if (!form) return 0;
  let subtotal = 0;
  let taxTotal = 0;
  form.querySelectorAll(".sale-line").forEach((line) => {
    const qty = Number(line.querySelector("[data-sale-qty]")?.value || 0);
    const product = salesProducts.find((item) => item.id === Number(line.querySelector("[data-sale-product]")?.value));
    const unit = line.querySelector("[data-sale-uom]")?.value;
    const conversionPreview = line.querySelector("[data-sale-conversion-preview]");
    if (conversionPreview) conversionPreview.textContent = productUnitConversionPreview(product, qty, unit);
    const price = Number(line.querySelector("[data-sale-price]")?.value || 0);
    const taxId = Number(line.querySelector("[data-sale-tax]")?.value || 0);
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId && item.active);
    const discount = Math.min(100, Math.max(0, Number(line.querySelector("[data-sale-discount]")?.value || 0)));
    const amounts = calculateInvoiceLineAmounts(qty, price * (1 - discount / 100), tax);
    const gross = amounts.subtotal + amounts.taxAmount;
    subtotal += amounts.subtotal;
    taxTotal += amounts.taxAmount;
    const cell = line.querySelector(".sale-line-subtotal");
    if (cell) cell.textContent = salesCurrency(state.salesTaxMode === "included" ? gross : amounts.subtotal);
  });
  const total = subtotal + taxTotal;
  const excludedNode = form.querySelector("#sale-tax-excluded");
  const taxNode = form.querySelector("#sale-tax-total");
  const totalNode = form.querySelector("#sale-order-total");
  const taxRow = form.querySelector("[data-sale-tax-row]");
  if (excludedNode) excludedNode.textContent = salesCurrency(subtotal);
  if (taxNode) taxNode.textContent = salesCurrency(taxTotal);
  if (totalNode) totalNode.textContent = salesCurrency(total);
  taxRow?.classList.toggle("is-hidden", taxTotal <= 0);
  form.querySelectorAll("[data-sales-tax-mode]").forEach((button) => button.classList.toggle("is-active", button.dataset.salesTaxMode === state.salesTaxMode));
  return total;
}

function openSalesOrderModal(orderId = null, prefill = {}) {
  const order = state.salesOrders.find((item) => item.id === Number(orderId));
  state.salesEditor = { id: order?.id || null, ...(order ? {} : prefill), returnPage: prefill.returnPage || state.page };
  state.salesOrderTab = "order-lines";
  state.salesTaxMode = "excluded";
  render();
  if (!order) updateSaleTotal();
  if (!order && prefill.customer) {
    const customerInput = document.querySelector("#sale-customer");
    if (customerInput) customerInput.value = prefill.customer;
  }
}

function salesCustomerAddress(customerName) {
  const normalized = String(customerName || "").trim().toLowerCase();
  if (!normalized) return "";
  const customer = state.salesCustomers.find((item) => String(item.name || "").trim().toLowerCase() === normalized);
  const contact = state.contacts.find((item) => (customer?.contactId && String(item.id) === String(customer.contactId))
    || String(item.name || "").trim().toLowerCase() === normalized);
  return String(contact?.address || customer?.address || [contact?.street, contact?.street2, contact?.city, contact?.state, contact?.zip, contact?.country].filter(Boolean).join(", ") || "").trim();
}

function renderSalesDocumentForm() {
  const order = state.salesOrders.find((item) => item.id === Number(state.salesEditor?.id)) || null;
  const confirmed = order && !["Quotation", "Quotation Sent"].includes(order.status);
  const locked = Boolean(confirmed && state.salesSettings.lockConfirmedSales === true);
  const lineNumbers = state.salesSettings.showLineNumbers === true;
  const ref = order?.ref || `S${String(state.salesOrders.length + 1).padStart(5, "0")}`;
  const customerNames = [...new Set([...state.salesCustomers.map((item) => item.name), ...(state.contacts || []).filter(contactHasCustomerRole).map((item) => item.name), ...state.salesOrders.map((item) => item.customer), state.salesEditor?.customer].filter(Boolean))];
  const draftCustomerName = order?.customer || state.salesEditor?.customer || "";
  const draftCustomer = state.salesCustomers.find((item) => String(item.name || "").trim().toLowerCase() === draftCustomerName.trim().toLowerCase());
  const draftContact = state.contacts.find((item) => (draftCustomer?.contactId && String(item.id) === String(draftCustomer.contactId))
    || String(item.name || "").trim().toLowerCase() === draftCustomerName.trim().toLowerCase());
  const terms = order?.paymentTerms || draftContact?.paymentTerms || draftCustomer?.paymentTerms || state.salesSettings.defaultPaymentTerms || "Due on receipt";
  const paymentTermOptions = purchasePaymentTermOptions([terms]);
  const prefillProduct = state.salesEditor?.productId ? salesProducts.find((item) => Number(item.id) === Number(state.salesEditor.productId)) : null;
  const lines = order?.lines?.length ? order.lines.map((line, index) => saleLineMarkup(line, locked, currentSalesProductFlow(), index + 1)).join("") : prefillProduct ? saleLineMarkup({ product: prefillProduct.name, sku: prefillProduct.sku }, false, currentSalesProductFlow(), 1) : saleLineMarkup({}, false, currentSalesProductFlow(), 1);
  const stage = order?.status === "Delivered" ? 2 : ["Quotation", "Quotation Sent", "Sales Order"].indexOf(order?.status || "Quotation");
  const hasInvoice = Boolean(order?.invoiceId) || ["Invoice Draft", "Invoiced", "Paid", "Partial"].includes(order?.invoiceStatus);
  const statusBar = `<div class="sales-statusbar" aria-label="Document status">${["Quotation", "Quotation Sent", "Sales Order"].map((label, index) => `<span class="${index === stage ? "is-current" : index < stage ? "is-done" : ""}">${label}</span>`).join("")}</div>`;
  const salesSmartPanel = confirmed ? window.ERPSharedSmartPanel.render({
    className: "sales-document-smart-panel", ariaLabel: "Sales order smart buttons",
    items: [
      { label: "Invoice", value: order?.invoiceStatus || "To Invoice", icon: "▧", className: "purchase-smart-button", attributes: { "data-sale-state": "invoice" } },
      { label: "Delivery", value: order?.deliveryStatus || "To Deliver", icon: "▣", className: "purchase-smart-button", attributes: { "data-sale-state": "delivery" } },
    ],
  }) : "";
  const topActions = confirmed
    ? `${locked ? "" : `<button class="action-button" type="button" data-save-sale="Sales Order">Save Changes</button>`}<button class="action-button secondary" type="button" data-action="sales-preview">Preview</button>${order.invoiceId ? `<button class="action-button secondary" type="button" data-open-invoice="${order.invoiceId}">${escapeHtml(order.invoiceRef || "View Invoice")}</button>` : ""}<button class="action-button secondary" type="button" data-sale-state="delivery">${order.deliveryStatus === "Delivered" ? "View Delivery" : order.deliveryStatus === "Partially Delivered" ? "Continue Delivery" : "Validate Delivery"}</button><button class="action-button" type="button" data-sale-state="invoice" ${hasInvoice ? "disabled" : ""}>${hasInvoice ? escapeHtml(order.invoiceStatus || "Invoice Draft") : "Create Invoice"}</button>`
    : `<button class="action-button" type="button" data-save-sale="Quotation">Save</button><button class="action-button secondary" type="button" data-action="sales-download">Download</button><button class="action-button secondary" type="button" data-action="sales-preview">Preview</button><button class="action-button secondary" type="button" data-save-sale="Quotation Sent">Send</button><button class="action-button" type="button" data-save-sale="Sales Order">Confirm</button>`;
  const disabled = locked ? "disabled" : "";
  const salesCompany = order?.company || state.settings.companyName || "Arafat Chemica";
  const sourceDocument = order?.sourceDocument || order?.crmOpportunityRef || "";
  const customer = order?.customer || state.salesEditor?.customer || "";
  const customerAddress = salesCustomerAddress(customer);
  const invoiceAddress = order?.invoiceAddress ?? state.salesEditor?.invoiceAddress ?? customerAddress;
  const deliveryAddress = order?.deliveryAddress ?? state.salesEditor?.deliveryAddress ?? customerAddress;
  const orderLinesPanel = `<section class="sales-tab-panel sales-order-lines-panel ${state.salesOrderTab === "order-lines" ? "is-active" : ""}" data-sales-panel="order-lines"><div class="sale-lines-scroll"><table class="order-lines sale-order-lines sales-native-lines purchase-native-lines"><thead><tr>${lineNumbers ? "<th>#</th>" : ""}<th>Description</th><th>Quantity</th><th>Unit</th><th>Unit Price</th><th>Taxes</th><th>Disc.%</th><th class="money-cell">Amount</th><th></th></tr></thead><tbody id="sale-line-items">${lines}</tbody>${locked ? "" : `<tfoot class="purchase-line-footer"><tr class="purchase-action-row"><td colspan="${lineNumbers ? 9 : 8}"><div class="sales-line-actions"><button type="button" data-action="add-sale-line">Add Line</button><button type="button" data-action="add-sale-section">Add Section</button><button type="button" data-action="add-sale-note">Add Note</button><button type="button" data-action="sales-catalog">Catalog</button></div></td></tr><tr class="purchase-blank-line"><td colspan="${lineNumbers ? 9 : 8}"></td></tr><tr class="purchase-blank-line"><td colspan="${lineNumbers ? 9 : 8}"></td></tr><tr class="purchase-blank-line"><td colspan="${lineNumbers ? 9 : 8}"></td></tr></tfoot>`}</table></div><div class="purchase-order-summary"><label class="purchase-terms"><span>Terms &amp; Conditions</span><textarea name="terms" ${disabled} placeholder="Define your terms and conditions ...">${escapeHtml(order?.terms ?? order?.termsNote ?? "")}</textarea></label><div><div class="sales-promo-actions">${confirmed ? "" : `<button type="button" class="action-button secondary" data-sales-order-action="coupon">Coupon Code</button><button type="button" class="action-button secondary" data-sales-order-action="reward">Reward</button>${state.salesSettings.lineDiscountsEnabled === false ? "" : `<button type="button" class="action-button secondary" data-sales-order-action="discount">Discount</button>`}`}</div><div class="sales-total-box purchase-total-box"><div><span>Untaxed Amount</span><strong id="sale-tax-excluded">${salesCurrency(order?.taxExcluded ?? order?.total ?? 0)}</strong></div><div class="purchase-tax-total-row${order?.taxAmount > 0 ? "" : " is-hidden"}" data-sale-tax-row><span>Tax</span><strong id="sale-tax-total">${salesCurrency(order?.taxAmount || 0)}</strong></div><div class="sales-grand-total"><span>Total · BDT</span><strong id="sale-order-total">${salesCurrency(order?.total || 0)}</strong></div></div></div></div></section>`;
  const defaultDeliveryPolicy = order?.deliveryPolicy || state.salesSettings.defaultDeliveryPolicy || "partial";
  const otherInfoPanel = `<section class="sales-tab-panel purchase-other-info-panel ${state.salesOrderTab === "other-info" ? "is-active" : ""}" data-sales-panel="other-info"><div class="purchase-other-info-grid"><div class="field"><label for="sale-customer-reference">Customer Reference</label><input id="sale-customer-reference" name="customerRef" ${disabled} value="${escapeHtml(order?.customerRef || "")}" placeholder="Customer PO / reference"></div><div class="field"><label for="sale-order-date">Order Date</label><input id="sale-order-date" name="orderDate" type="date" ${disabled} value="${escapeHtml(order?.orderDate || inputLocalDate())}"></div><div class="field"><label for="sale-salesperson">Salesperson</label><input id="sale-salesperson" name="salesperson" ${disabled} value="${escapeHtml(order?.salesperson || state.salesSettings.defaultSalesperson || state.userProfile.name || "")}" placeholder="Assign salesperson"></div><div class="field"><label for="sale-company">Company</label><input id="sale-company" name="company" ${disabled} value="${escapeHtml(salesCompany)}" placeholder="Company"></div><div class="field"><label for="sale-delivery-policy">Delivery Policy</label><select id="sale-delivery-policy" name="deliveryPolicy" ${disabled}><option ${defaultDeliveryPolicy === "all" ? "selected" : ""} value="all">Deliver all products at once</option><option ${defaultDeliveryPolicy !== "all" ? "selected" : ""} value="partial">As soon as possible</option></select></div><div class="field"><label for="sale-source-document">Source Document</label><input id="sale-source-document" name="sourceDocument" ${disabled} value="${escapeHtml(sourceDocument)}" placeholder="Source document"></div><div class="field"><label>Invoice Status</label><input value="${escapeHtml(order?.invoiceStatus || "Nothing to Invoice")}" disabled></div><div class="field"><label>Delivery Status</label><input value="${escapeHtml(order?.deliveryStatus || "To Deliver")}" disabled></div></div></section>`;
  const notesPanel = `<section class="sales-tab-panel sales-notes-panel ${state.salesOrderTab === "notes" ? "is-active" : ""}" data-sales-panel="notes"><label class="purchase-other-info-notes"><span>Internal Notes</span><textarea name="notes" ${disabled} placeholder="Add an internal note for this sales order">${escapeHtml(order?.notes || order?.otherInfoNote || "")}</textarea></label></section>`;
  const toolbarMarkup = `<div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button secondary" data-sales-editor-action="discard">${order ? "Orders" : "New"}</button><div><button type="button" class="sales-breadcrumb" data-sales-editor-action="discard">${state.page === "sales-orders" ? "Sales Orders" : "Quotations"}</button><h1>${escapeHtml(ref)}</h1></div><button type="button" class="more-button purchase-form-more" data-action="toolbar-more" aria-label="More options">⋮</button></div><div class="sales-document-toolbar-right">${salesSmartPanel}<button type="button" class="soft-icon-button" data-sales-editor-action="discard" aria-label="Close">×</button></div></div>`;
  const headingMarkup = `<div><span>${order?.status === "Sales Order" || order?.status === "Delivered" ? "Sales Order" : "Quotation"}</span><h2><button type="button" class="purchase-favorite" aria-hidden="true">☆</button>${escapeHtml(order?.customer || "New")}</h2></div>`;
  const fieldsMarkup = `<div class="sales-field-main">
        <div class="field sales-partner-field"><label for="sale-customer">Customer <sup>?</sup></label><input id="sale-customer" name="customer" list="sale-customer-options" required ${disabled} value="${escapeHtml(customer)}" placeholder="Type to find a customer..." autocomplete="off"><datalist id="sale-customer-options">${customerNames.map((name) => `<option value="${escapeHtml(name)}">`).join("")}</datalist><small>Dealer or depot account</small></div>
        <div class="field"><label for="sale-invoice-address">Invoice Address</label><input id="sale-invoice-address" name="invoiceAddress" ${disabled} value="${escapeHtml(invoiceAddress)}" placeholder="Select an invoice address"></div>
        <div class="field"><label for="sale-delivery-address">Delivery Address</label><input id="sale-delivery-address" name="deliveryAddress" ${disabled} value="${escapeHtml(deliveryAddress)}" placeholder="Select a delivery address"></div>
      </div><div class="sales-field-side">
        <div class="field"><label for="sale-expiration-date">Expiration <sup>?</sup></label><input id="sale-expiration-date" name="expirationDate" type="date" ${disabled} value="${escapeHtml(order?.expirationDate || inputLocalDate(new Date(Date.now() + Number(state.salesSettings.quotationValidity || 7) * 86400000)))}"></div>
        <div class="field"><label for="sale-pricelist">Pricelist</label><input id="sale-pricelist" name="pricelist" ${disabled} value="${escapeHtml(order?.pricelist || state.salesEditor?.pricelist || draftContact?.pricelist || draftCustomer?.pricelist || "")}" placeholder="Select a pricelist"></div>
        <div class="field"><label for="sale-payment-terms">Payment Terms</label><select id="sale-payment-terms" name="paymentTerms" ${disabled}>${paymentTermOptions.map((option) => `<option value="${escapeHtml(option)}" ${terms === option ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}</select></div>
        <div class="field"><label for="sale-referrer">Referrer</label><input id="sale-referrer" name="referrer" ${disabled} value="${escapeHtml(order?.referrer || state.salesEditor?.referrer || "")}" placeholder="Referrer"></div>
        <div class="field"><label for="sale-delivery-date">Delivery Date <sup>?</sup></label><input id="sale-delivery-date" name="deliveryDate" type="date" ${disabled} value="${escapeHtml(order?.deliveryDate || "")}"></div>
      </div>`;
  const tabsMarkup = renderSharedOrderTabsToolbar({ ariaLabel: "Sales order details", tabs: [{ key: "order-lines", label: "Order Lines" }, { key: "other-info", label: "Other Info" }, { key: "notes", label: "Notes" }], activeTab: state.salesOrderTab, tabAttribute: "sales-tab", taxMode: state.salesTaxMode, taxModeAttribute: "sales-tax-mode", disabled });
  const panelsMarkup = `${orderLinesPanel}${otherInfoPanel}${notesPanel}`;
  const footerMarkup = `<footer class="sales-document-footer"><div class="sales-document-note">Prices and taxes use the configured Bangladesh accounting rules. Stock quantities stay linked to the shared Inventory product units.</div><div class="sales-document-buttons">${confirmed ? topActions : `<button class="action-button secondary" type="button" data-sales-editor-action="discard">Discard</button><button class="action-button" type="button" data-save-sale="Quotation">Save</button><button class="action-button secondary" type="button" data-save-sale="Quotation Sent">Send</button><button class="action-button" type="button" data-save-sale="Sales Order">Confirm</button>`}</div></footer>`;
  const formMarkup = `<main><form id="sale-order-form" data-id="${order?.id || ""}" autocomplete="off"><input type="hidden" name="reference" value="${escapeHtml(ref)}">${renderSharedOrderDocumentCard({ headingMarkup, fieldsMarkup, tabsMarkup, panelsMarkup, footerMarkup })}</form></main>`;
  const chatterMarkup = `<aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button" data-action="toast" data-message="Sales messaging will connect to the customer discussion timeline.">Send message</button><button type="button" class="action-button secondary" data-action="toast" data-message="An internal note can be added to this customer order.">Log note</button><button type="button" class="action-button secondary" data-action="toast" data-message="Sales activities can be scheduled for this customer order.">Activity</button></div><div class="purchase-chatter-day">Today</div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${order ? `${escapeHtml(order.status)} · ${escapeHtml(order.ref)}` : "Creating a new record..."}</p></div></div><p class="erp-chatter-note">Customer communication and sales history appear here.</p></aside>`;
  return renderSharedOrderDocumentTemplate({ pageClass: "sales-order-document-page", toolbarMarkup, actionMarkup: topActions, statusMarkup: statusBar, formMarkup, chatterMarkup });
}

function openSalesQuotationPreview(autoPrint = false) {
  const form = document.querySelector("#sale-order-form");
  if (!form) return;
  const data = new FormData(form);
  const lines = [...form.querySelectorAll("#sale-line-items tr")].map((row) => {
    if (row.classList.contains("sale-special-line")) return { type: row.dataset.lineType, description: row.querySelector("[data-sale-description]")?.value || "" };
    const product = salesProducts.find((item) => item.id === Number(row.querySelector("[data-sale-product]")?.value));
    const qty = Number(row.querySelector("[data-sale-qty]")?.value || 0);
    const price = Number(row.querySelector("[data-sale-price]")?.value || 0);
    const discount = Math.min(100, Math.max(0, Number(row.querySelector("[data-sale-discount]")?.value || 0)));
    const unit = row.querySelector("[data-sale-uom]")?.value || product?.stockUom || "";
    const offerSelect = row.querySelector("[data-sale-consumer-offer]");
    const offer = salesProductOffer(product, offerSelect?.value || "");
    const taxId = Number(row.querySelector("[data-sale-tax]")?.value || 0);
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId && item.active);
    const amount = calculateInvoiceLineAmounts(qty, price * (1 - discount / 100), tax);
    return { product, consumerOfferName: offerSelect ? offer?.name || "" : row.querySelector("[data-sale-consumer-offer-snapshot]")?.dataset.saleConsumerOfferSnapshot || "", uom: unit, promotionGift: row.querySelector("[data-sale-promotion-gift]")?.value || row.querySelector("[data-sale-promotion-gift-snapshot]")?.dataset.salePromotionGiftSnapshot || "", qty, price, discount, tax, ...amount };
  });
  const normalLines = lines.filter((line) => line.product);
  const subtotal = normalLines.reduce((sum, line) => sum + line.subtotal, 0);
  const taxTotal = normalLines.reduce((sum, line) => sum + line.taxAmount, 0);
  const layout = state.invoiceLayout;
  const lineNumbers = state.salesSettings.showLineNumbers === true;
  const includeProductImages = state.salesSettings.productImagesOnQuotation === true;
  const rows = lines.map((line, index) => {
    const numberCell = lineNumbers ? `<td class="invoice-preview-line-number">${index + 1}</td>` : "";
    if (line.type) return `<tr class="${line.type === "section" ? "invoice-preview-section" : "invoice-preview-note"}">${numberCell}<td colspan="7">${escapeHtml(line.description)}</td></tr>`;
    const productImage = includeProductImages && line.product?.image ? `<img class="invoice-preview-product-image" src="${escapeHtml(line.product.image)}" alt="">` : "";
    return `<tr>${numberCell}<td>${productImage}${escapeHtml(line.product?.name || "Product")}${line.product?.sku ? `<small>${escapeHtml(line.product.sku)}</small>` : ""}${line.consumerOfferName ? `<small>Consumer offer · ${escapeHtml(line.consumerOfferName)}</small>` : ""}${line.promotionGift ? `<small class="invoice-preview-gift">Promotional gift · ${escapeHtml(line.promotionGift)}</small>` : ""}</td><td>${line.qty}</td><td>${escapeHtml(line.uom || line.product?.stockUom || "")}</td><td>${salesCurrency(line.price)}</td><td>${line.tax ? `${escapeHtml(line.tax.name)} (${Number(line.tax.rate).toFixed(3)}%)` : "—"}</td><td>${line.discount ? `${line.discount}%` : "—"}</td><td class="money-cell">${salesCurrency(line.subtotal + line.taxAmount)}</td></tr>`;
  }).join("");
  const preview = `<article class="invoice-paper"><header class="invoice-paper-header"><div class="invoice-company-mark">${escapeHtml(initials(layout.companyName || "BD"))}</div><div class="invoice-company-details"><h2>${escapeHtml(layout.companyName || "Company name not set")}</h2><span>${escapeHtml(layout.address || "Company address not set")}</span><span>${escapeHtml(layout.phone || "")}${layout.email ? ` · ${escapeHtml(layout.email)}` : ""}</span>${layout.bin ? `<span>BIN: ${escapeHtml(layout.bin)}</span>` : ""}</div><div class="invoice-paper-meta"><strong>Quotation</strong><span>${escapeHtml(form.querySelector("[name='reference']")?.value || "New")}</span><span>Order date · ${escapeHtml(data.get("orderDate") || "—")}</span><span>Delivery · ${escapeHtml(data.get("deliveryDate") || "—")}</span></div></header><section class="invoice-bill-to"><span>Customer / Dealer</span><strong>${escapeHtml(data.get("customer") || "Customer")}</strong>${data.get("invoiceAddress") ? `<small>Invoice address · ${escapeHtml(data.get("invoiceAddress"))}</small>` : ""}${data.get("deliveryAddress") ? `<small>Delivery address · ${escapeHtml(data.get("deliveryAddress"))}</small>` : ""}${data.get("customerRef") ? `<small>Customer reference · ${escapeHtml(data.get("customerRef"))}</small>` : ""}</section><div class="invoice-preview-table-wrap"><table class="invoice-preview-table"><thead><tr>${lineNumbers ? "<th>#</th>" : ""}<th>Product / Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Tax</th><th>Disc.%</th><th class="money-cell">Amount</th></tr></thead><tbody>${rows || `<tr><td colspan="${lineNumbers ? 8 : 7}" class="invoice-preview-empty">No products added</td></tr>`}</tbody></table></div><div class="invoice-total-panel"><div><span>Untaxed Amount</span><strong>${salesCurrency(subtotal)}</strong></div><div><span>Tax</span><strong>${salesCurrency(taxTotal)}</strong></div><div class="grand-total"><span>Total · BDT</span><strong>${salesCurrency(subtotal + taxTotal)}</strong></div><div><span>Payment Terms</span><strong>${escapeHtml(data.get("paymentTerms") || "Due on receipt")}</strong></div></div><footer class="invoice-paper-footer">${escapeHtml(layout.footerNote || "Payment and delivery terms are as agreed in this quotation.")}</footer></article>`;
  openModal(`<header class="modal-header"><div><h2>Quotation Preview</h2><p>Shared company header · BDT</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><div class="modal-body sales-preview-body">${preview}</div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Back to Quotation</button><button type="button" class="action-button" data-action="print-invoice">Print / Save PDF</button></footer>`);
  if (autoPrint) window.setTimeout(() => window.print(), 100);
}

function openSalesCustomerModal() {
  openPartnerContactForm("dealer");
}

function openPartnerContactForm(kind = "contact", id = null) {
  const contactId = id === undefined || id === null || id === "" ? null : id;
  state.contactEditor = { type: "partner", kind, id: contactId, returnPage: state.page };
  render();
}

function openInvoiceVendorModal() {
  openPartnerContactForm("supplier");
}

function renderPartnerContactFormPageLegacy() {
  const editor = state.contactEditor || {};
  const contact = state.contacts.find((item) => String(item.id) === String(editor.id)) || null;
  const kind = contact?.kind || editor.kind || "contact";
  const kindLabel = kind === "supplier" ? "Supplier" : kind === "dealer" ? "Dealer" : "Contact";
  const returnPage = editor.returnPage || "contacts";
  const returnLabel = pageLabels[returnPage] || "Contacts";
  const input = (label, name, value = "", attrs = "") => `<div class="erp-contact-field"><label for="partner-${name}">${label}</label><input id="partner-${name}" name="${name}" value="${escapeHtml(value)}" ${attrs}></div>`;
  const existing = Boolean(contact);
  const avatarMarkup = `<label class="erp-contact-avatar-upload" title="Upload contact image" aria-label="Upload contact image"><span class="erp-contact-avatar contacts-record-avatar" data-contact-avatar-preview aria-hidden="true">${contact?.image ? `<img src="${escapeHtml(contact.image)}" alt="">` : escapeHtml(initials(contact?.name || "C"))}</span><span class="erp-contact-avatar-action" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h3l1.4-2h7.2L17 7h3v12H4z"/><circle cx="12" cy="13" r="4"/><path d="M12 9v8M8 13h8"/></svg></span><input type="file" accept="image/*" data-contact-image aria-label="Choose contact image"></label><input type="hidden" name="image" value="${escapeHtml(contact?.image || "")}">`;
  const typeControl = existing
    ? `<input type="hidden" name="kind" value="${escapeHtml(kind)}"><span class="contacts-record-kind">${kindLabel}</span>`
    : `<select id="partner-kind" name="kind" data-partner-kind aria-label="Record Type">${[["contact", "Contact"], ["supplier", "Supplier"], ["dealer", "Dealer"]].map(([value, label]) => `<option value="${value}" ${kind === value ? "selected" : ""}>${label}</option>`).join("")}</select>`;
  const supplierStatus = contact && isSupplierApproved(contact) ? `<span class="status-pill purchase">Approved supplier</span>` : `<span class="status-pill approval">Pending supplier approval</span>`;
  const roleTabFields = `<div class="erp-contact-tab-grid" data-partner-kind-panel="supplier" ${kind !== "supplier" ? "hidden" : ""}>${input("Supplier Reference", "reference", contact?.reference || "", 'placeholder="Supplier code"')}${input("Payment Terms", "paymentTerms", contact?.paymentTerms || "Immediate", 'placeholder="Immediate, 15 days..."')}<div class="erp-contact-field"><label>Supplier Approval</label><div class="contacts-approval-state">${kind === "supplier" ? supplierStatus : "Approval is required before this supplier can be selected in Purchase."}</div></div><div class="erp-contact-field"><label>Purchase Currency</label><input value="BDT · Bangladeshi Taka" disabled></div></div><div class="erp-contact-tab-grid" data-partner-kind-panel="dealer" ${kind !== "dealer" ? "hidden" : ""}>${input("Area / Territory", "area", contact?.area || contact?.city || "", 'placeholder="District, upazila, or route"')}${input("Credit Limit · BDT", "creditLimit", contact?.creditLimit ?? 0, 'type="number" min="0" step="0.01"')}<div class="erp-contact-field"><label for="partner-dealerType">Channel</label><select id="partner-dealerType" name="dealerType">${["Dealer", "Depot", "Retailer", "Other wholesale"].map((item) => `<option ${String(contact?.dealerType || contact?.type || "Dealer") === item ? "selected" : ""}>${item}</option>`).join("")}</select></div><div class="erp-contact-field"><label>Sales Currency</label><input value="BDT · Bangladeshi Taka" disabled></div></div><div class="erp-contact-tab-grid" data-partner-kind-panel="contact" ${kind !== "contact" ? "hidden" : ""}>${input("Job Position", "jobTitle", contact?.jobTitle || "", 'placeholder="e.g. Sales Director"')}<div class="erp-contact-field"><label>Related To</label><input name="company" value="${escapeHtml(contact?.company || "")}" placeholder="Company or parent contact"></div></div>`;
  const addressLines = contact?.street ? contact.street : contact?.address || "";
  return `<section class="sales-document-page erp-finance-record-page erp-contact-record-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button secondary" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><div><button type="button" class="sales-breadcrumb" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><h1>${existing ? escapeHtml(contact.name) : `New ${kindLabel}`}</h1><small>${kind === "supplier" ? "Supplier · approved suppliers are shared with Purchase" : kind === "dealer" ? "Dealer · shared with Sales quotations and Invoicing" : "Business contact · shared in the Contacts directory"}</small></div></div><button type="button" class="soft-icon-button" data-contact-editor-action="discard" aria-label="Close">×</button></div><div class="sales-document-actionbar"><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" class="action-button" form="partner-contact-form">Save</button></div><div class="sales-statusbar invoice-statusbar"><span class="is-current">${kindLabel}</span><span>${kind === "supplier" ? (contact && isSupplierApproved(contact) ? "Approved" : "Approval needed") : kind === "dealer" ? "Sales contact" : "Contact"}</span></div></div><div class="erp-finance-form-layout"><main><form id="partner-contact-form" data-id="${contact?.id || ""}"><article class="sales-document-card erp-contact-card"><div class="erp-contact-identity">${avatarMarkup}<div class="erp-contact-primary"><input name="name" aria-label="Name" required maxlength="120" placeholder="Name (company or person)" value="${escapeHtml(contact?.name || "")}"><div class="erp-contact-meta"><label class="contacts-kind-wrap">▦ ${typeControl}</label><label>✉ <input name="email" aria-label="Email" type="email" maxlength="120" placeholder="Email" value="${escapeHtml(contact?.email || "")}"></label><label>☎ <input name="phone" aria-label="Phone" type="tel" maxlength="40" placeholder="Phone" value="${escapeHtml(contact?.phone || "")}"></label></div></div></div><section class="erp-contact-details"><div><h3>Address</h3><input name="street" placeholder="Street..." value="${escapeHtml(addressLines)}"><input name="street2" placeholder="Street 2..." value="${escapeHtml(contact?.street2 || "")}"><div class="erp-contact-address-row"><input name="city" placeholder="City" aria-label="City" value="${escapeHtml(contact?.city || contact?.area || "")}"><input name="state" placeholder="State" aria-label="State" value="${escapeHtml(contact?.state || "")}"><input name="zip" placeholder="ZIP" aria-label="ZIP" value="${escapeHtml(contact?.zip || "")}"></div><input name="country" placeholder="Country" value="${escapeHtml(contact?.country || "Bangladesh")}"></div><div class="erp-contact-extra">${input("Website", "website", contact?.website || "", 'type="url" placeholder="https://"')}${input("Tags", "tags", contact?.tags || "", 'placeholder="B2B, VIP, Wholesale"')}</div></section><nav class="sales-document-tabs erp-contact-tabs" aria-label="Contact details"><button type="button" class="is-active" data-contact-tab="details">Contacts</button><button type="button" data-contact-tab="sales">Sales &amp; Purchase</button><button type="button" data-contact-tab="accounting">Accounting</button><button type="button" data-contact-tab="notes">Notes</button></nav><section class="sales-tab-panel is-active" data-contact-panel="details"><div class="erp-contact-related"><strong>Related Contacts</strong><p>Store each supplier, dealer and other contact in this shared directory. Contact links and extra records can be added in a later step.</p></div></section><section class="sales-tab-panel" data-contact-panel="sales">${roleTabFields}<p class="erp-contact-help" data-partner-kind-note>${kind === "supplier" ? "Only approved suppliers appear in Purchase order vendor choices." : kind === "dealer" ? "Dealer details are shared with Sales customers." : "Add this record as a supplier or dealer from the Record Type selector."}</p></section><section class="sales-tab-panel" data-contact-panel="accounting"><div class="erp-contact-tab-grid">${input("Tax ID / BIN", "taxId", contact?.taxId || "", 'placeholder="BIN / TIN"')}<div class="erp-contact-field"><label>Ledger Account</label><input value="${kind === "supplier" ? "2000 · Accounts Payable" : "1100 · Accounts Receivable"}" disabled></div><p class="erp-contact-help">Bills, invoices, payments and balances can be linked to this contact.</p></div></section><section class="sales-tab-panel" data-contact-panel="notes"><div class="erp-contact-field"><label for="partner-notes">Internal Notes</label><textarea id="partner-notes" name="notes" placeholder="Notes for your team...">${escapeHtml(contact?.notes || "")}</textarea></div></section><footer class="sales-document-footer"><span class="sales-document-note">Contacts are saved in this browser and shared with the relevant Sales and Purchase lists.</span><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" form="partner-contact-form" class="action-button">Save</button></div></footer></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button" data-action="toast" data-message="Contact messaging will connect to the Odoo Discuss service.">Send message</button><button type="button" class="action-button secondary" data-action="toast" data-message="An internal note can be added in a later step.">Log note</button><button type="button" class="action-button secondary" data-action="toast" data-message="Contact activities can be added in a later step.">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${existing ? "Updating contact details" : `Creating a new ${kindLabel.toLowerCase()}...`}</p></div></div><p class="erp-chatter-note">Supplier approval and shared sales details are managed from this contact.</p></aside></div></section>`;
}

function contactRecordMatchesPartner(contact, record, idKeys, nameKeys) {
  const contactId = String(contact?.id || "");
  if (!contactId) return false;
  const contactIds = new Set([contactId, contact?.linkedId, contact?.customerId, contact?.supplierId].filter((value) => value !== undefined && value !== null && value !== "").map(String));
  const linkedIds = idKeys.map((key) => record?.[key]).filter((value) => value !== undefined && value !== null && value !== "").map(String);
  if (linkedIds.length) return linkedIds.some((id) => contactIds.has(id));
  const names = [contact.name, contact.company].map((value) => String(value || "").trim().toLowerCase()).filter(Boolean);
  return names.some((name) => nameKeys.some((key) => String(record?.[key] || "").trim().toLowerCase() === name));
}

function contactRelatedRecords(contact) {
  const crm = window.crmModule?.getWorkspace?.() || {};
  const opportunities = (crm.opportunities || []).filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "partnerId"], ["contactName", "company"]));
  const opportunityIds = new Set(opportunities.map((item) => String(item.id)));
  return {
    opportunities,
    sales: state.salesOrders.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "customerId", "partnerId"], ["customer", "partner"])),
    invoices: state.invoices.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "partnerContactId", "customerId", "vendorContactId"], ["partner", "customer", "vendor"])),
    subscriptions: state.inventoryProductSubscriptions.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "customerContactId", "partnerId"], ["customer", "partner"])),
    purchaseOrders: purchaseOrders.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "vendorContactId", "supplierId"], ["vendor", "supplier"])),
    receipts: state.purchaseReceipts.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "vendorContactId", "supplierId"], ["vendor", "supplier"])),
    deliveries: state.inventoryDeliveries.filter((item) => contactRecordMatchesPartner(contact, item, ["contactId", "customerId", "partnerId"], ["customer", "partner"])),
    tasks: (crm.activities || []).filter((item) => opportunityIds.has(String(item.recordId))),
  };
}

function openContactRelatedRecords(contactId, section = "all") {
  const contact = state.contacts.find((item) => String(item.id) === String(contactId));
  if (!contact) { showToast("Save this contact before opening linked records."); return; }
  const related = contactRelatedRecords(contact);
  const titleBySection = { opportunities: "Opportunities", sales: "Sales Orders & Quotations", invoices: "Invoices & Vendor Bills", subscriptions: "Subscriptions", purchaseOrders: "Purchase Orders", receipts: "Purchase Receipts", deliveries: "Inventory Deliveries", tasks: "Activities" };
  const groups = Object.entries(titleBySection).filter(([key]) => section === "all" || key === section).map(([key, title]) => {
    const rows = related[key] || [];
    const buttons = rows.map((record) => {
      const id = record.id;
      const ref = record.ref || record.name || record.summary || title;
      const detail = key === "opportunities" ? `${record.stage || "New"} · ${salesCurrency(record.expectedRevenue || 0)}`
        : key === "sales" ? `${record.customer || ""} · ${record.status || "Quotation"} · ${salesCurrency(record.total || 0)}`
        : key === "invoices" ? `${record.partner || ""} · ${invoiceLabel(record.kind)} · ${record.status || "Draft"} · ${salesCurrency(record.total || 0)}`
        : key === "subscriptions" ? `${record.customer || ""} · ${record.interval || "Monthly"} · ${record.status || "Draft"} · ${salesCurrency(record.recurringAmount || 0)}`
        : key === "purchaseOrders" ? `${record.vendor || ""} · ${record.status || "RFQ"} · ${salesCurrency(record.total || 0)}`
        : key === "receipts" ? `${record.vendor || ""} · ${record.status || "Waiting"}`
        : key === "deliveries" ? `${record.customer || ""} · ${record.status || "Draft"}`
        : `${record.type || "Activity"} · ${record.dueDate || ""}`;
      const actionKey = key === "purchaseOrders" ? "purchase" : key === "receipts" ? "receipt" : key === "deliveries" ? "delivery" : key === "invoices" ? "invoice" : key === "subscriptions" ? "subscription" : key === "opportunities" ? "opportunity" : key === "tasks" ? "opportunity" : "sale";
      const targetId = key === "tasks" ? record.recordId : id;
      return `<button type="button" class="erp-contact-related-record" data-contact-related-open="${actionKey}" data-id="${escapeHtml(targetId)}"><strong>${escapeHtml(ref)}</strong><span>${escapeHtml(detail)}</span><span aria-hidden="true">›</span></button>`;
    }).join("");
    return `<section class="erp-contact-related-group"><h3>${escapeHtml(title)} <span>${rows.length}</span></h3>${buttons || `<p class="erp-contact-related-empty">No linked ${escapeHtml(title.toLowerCase())} yet.</p>`}</section>`;
  }).join("");
  const heading = section === "all" ? "Related Records" : titleBySection[section] || "Related Records";
  const createActions = `<button type="button" class="action-button secondary" data-contact-related-create="opportunity" data-id="${escapeHtml(contact.id)}">New Opportunity</button>${contactHasCustomerRole(contact) ? `<button type="button" class="action-button" data-contact-related-create="sale" data-id="${escapeHtml(contact.id)}">New Quotation</button>` : ""}${contactHasSupplierRole(contact) && isSupplierApproved(contact) ? `<button type="button" class="action-button secondary" data-contact-related-create="purchase" data-id="${escapeHtml(contact.id)}">New RFQ</button>` : ""}`;
  openModal(`<header class="modal-header"><div><h2>${escapeHtml(heading)}</h2><p>${escapeHtml(contact.name)} · shared business partner</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body erp-contact-related-list">${groups}</div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Close</button>${section === "all" ? "" : `<button type="button" class="action-button secondary" data-contact-related-open="all" data-id="${escapeHtml(contact.id)}">View all related records</button>`}${createActions}</footer>`);
}

function contactSmartPanelMarkup({ contact = null, related = null, salesCount = 0, invoiced = 0, taskCount = 0 } = {}) {
  const icons = {
    "★": `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3 6.4 20.2l1.1-6.2L3 9.6l6.2-.9L12 3Z"/></svg>`,
    "🛒": `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2.3 11.1a2 2 0 0 0 2 1.6h8.5a2 2 0 0 0 1.9-1.5L21 8H6"/><circle cx="10" cy="20" r="1"/><circle cx="18" cy="20" r="1"/></svg>`,
    "▣": `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7M9 16h7"/></svg>`,
    "◷": `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.6 8.4A8 8 0 0 1 18 5l2 2"/><path d="M20 3v4h-4M19.4 15.6A8 8 0 0 1 6 19l-2-2"/><path d="M4 21v-4h4"/></svg>`,
    "▦": `<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16"/></svg>`,
    "◎": `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 3v5m0 8v5M3 12h5m8 0h5"/></svg>`,
    "✓": `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 12 5 5L20 6"/></svg>`,
  };
  const counts = related || (contact ? contactRelatedRecords(contact) : {});
  const savedAttributes = (section) => contact ? { "data-contact-related": section || "all", "data-id": contact.id } : {};
  const unsaved = !contact;
  const items = [
    ["opportunities", "★", "Opportunities", String(counts.opportunities?.length || 0), "opportunities"],
    ["sales", "🛒", "Sales", String(salesCount || counts.sales?.length || 0), "sales"],
    ["invoices", "▣", "Invoiced", salesCurrency(invoiced), "invoices"],
    ["subscriptions", "◷", "Subscriptions", String(counts.subscriptions?.length || 0), "subscriptions"],
    ["meetings", "▦", "No Meetings", "0", "all"],
    ["tickets", "◎", "Tickets", "0", "all"],
    ["tasks", "✓", "Tasks", String(taskCount || counts.tasks?.length || 0), "tasks"],
  ].map(([key, icon, label, value, section]) => ({
    iconHtml: icons[icon] || escapeHtml(icon), label, value,
    className: "erp-contact-smart-button",
    attributes: { "data-contact-smart": key, ...savedAttributes(section) },
    disabled: unsaved,
    title: unsaved ? "Save this contact to open related records" : "",
  }));
  items.push({
    contentHtml: `More<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 6 4.5 4 4.5-4"/></svg>`, className: "erp-contact-smart-more", ariaLabel: "More contact records",
    attributes: { "data-contact-related": contact ? "all" : undefined, "data-id": contact?.id },
    disabled: unsaved, title: unsaved ? "Save this contact to open related records" : "",
  });
  return window.ERPSharedSmartPanel.render({ className: "erp-contact-smartbar", ariaLabel: "Related contact records", items });
}

function openContactChatterComposer(type) {
  const contact = state.contacts.find((item) => String(item.id) === String(state.contactEditor?.id));
  if (!contact) { showToast("Save the contact before adding a message, note, or activity."); return; }
  const labels = { message: "Send Message", note: "Log Note", activity: "Schedule Activity" };
  const label = labels[type];
  if (!label) return;
  const activityFields = type === "activity" ? `<div class="field"><label for="contact-chatter-title">Activity Type</label><select id="contact-chatter-title" name="title"><option>To-do</option><option>Call</option><option>Meeting</option><option>Email</option><option>Upload Document</option></select></div><div class="field"><label for="contact-chatter-due">Due Date</label><input id="contact-chatter-due" name="dueDate" type="date"></div>` : "";
  const bodyLabel = type === "activity" ? "Summary / Instructions" : type === "note" ? "Internal Note" : "Message";
  openModal(`<header class="modal-header"><div><h2>${label}</h2><p>${escapeHtml(contact.name)} · saved in this workspace</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="contact-chatter-form" data-contact-id="${escapeHtml(contact.id)}" data-type="${type}"><div class="modal-body"><div class="form-grid">${activityFields}<div class="field"><label for="contact-chatter-body">${bodyLabel}</label><textarea id="contact-chatter-body" name="body" required rows="5" placeholder="Write here..."></textarea></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Cancel</button><button type="submit" class="action-button">${type === "activity" ? "Schedule" : type === "note" ? "Save Note" : "Send"}</button></footer></form>`, true);
  modalRoot.querySelector("#contact-chatter-body")?.focus();
}

function openContactFollowersModal() {
  const contact = state.contacts.find((item) => String(item.id) === String(state.contactEditor?.id));
  if (!contact) { showToast("Save the contact before managing followers."); return; }
  const followers = Array.isArray(contact.followers) ? contact.followers : [];
  openModal(`<header class="modal-header"><div><h2>Followers</h2><p>${escapeHtml(contact.name)} · visible to the contact team</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="contact-followers-form" data-contact-id="${escapeHtml(contact.id)}"><div class="modal-body"><div class="field"><label for="contact-followers-list">Follower names</label><textarea id="contact-followers-list" name="followers" rows="4" placeholder="One name per line">${escapeHtml(followers.join("\n"))}</textarea><small>Enter one team member per line. Names are saved on this contact record.</small></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Cancel</button><button type="submit" class="action-button">Save Followers</button></footer></form>`, true);
  modalRoot.querySelector("#contact-followers-list")?.focus();
}

function renderPartnerContactFormPage() {
  const editor = state.contactEditor || {};
  const contact = state.contacts.find((item) => String(item.id) === String(editor.id)) || null;
  const kind = contact?.kind || editor.kind || "contact";
  const kindLabel = kind === "supplier" ? "Supplier" : kind === "dealer" ? "Dealer" : "Contact";
  const returnPage = editor.returnPage || "contacts";
  const returnLabel = pageLabels[returnPage] || "Contacts";
  const value = (key, fallback = "") => contact?.[key] ?? fallback;
  const isSupplierRole = contact ? contactHasSupplierRole(contact) : kind === "supplier";
  const isCustomerRole = contact ? contactHasCustomerRole(contact) : kind === "dealer";
  const contactRoleSummary = [isCustomerRole ? "Customer" : "", isSupplierRole ? "Supplier" : ""].filter(Boolean).join(" · ") || "Contact";
  const field = (label, name, current = "", attrs = "") => `<div class="erp-contact-field"><label for="partner-${name}">${label}</label><input id="partner-${name}" name="${name}" value="${escapeHtml(current)}" ${attrs}></div>`;
  const select = (label, name, options, selected = "") => `<div class="erp-contact-field"><label for="partner-${name}">${label}</label><select id="partner-${name}" name="${name}"><option value="">Select ${escapeHtml(label.toLowerCase())}</option>${options.map((item) => { const [option, title] = Array.isArray(item) ? item : [item, item]; return `<option value="${escapeHtml(option)}" ${String(selected) === String(option) ? "selected" : ""}>${escapeHtml(title)}</option>`; }).join("")}</select></div>`;
  const cell = (name, current = "", type = "text", placeholder = "") => `<input data-contact-field="${name}" type="${type}" ${type === "number" ? 'min="0" step="0.01"' : ""} value="${escapeHtml(current)}" placeholder="${escapeHtml(placeholder)}" aria-label="${escapeHtml(placeholder || name)}">`;
  const table = (key, headings, rows, rowMarkup) => `<div class="erp-contact-table-wrap"><table class="erp-contact-table"><thead><tr>${headings.map((item) => `<th>${item}</th>`).join("")}<th aria-label="Actions"></th></tr></thead><tbody data-contact-rows="${key}">${(rows?.length ? rows : [{}]).map(rowMarkup).join("")}</tbody></table><template data-contact-row-template="${key}">${rowMarkup({})}</template><button type="button" class="erp-contact-add-line" data-contact-add-line="${key}">${key === "related" ? "+ Add Related Contacts" : "+ Add a line"}</button></div>`;
  const inputOptions = (key, options, selected) => `<select data-contact-field="${key}" aria-label="${key}">${options.map((item) => `<option ${String(selected || item) === item ? "selected" : ""}>${item}</option>`).join("")}</select>`;
  const existing = Boolean(contact);
  const avatar = `<label class="erp-contact-avatar-upload" title="Upload contact image" aria-label="Upload contact image"><span class="erp-contact-avatar contacts-record-avatar" data-contact-avatar-preview aria-hidden="true">${contact?.image ? `<img src="${escapeHtml(contact.image)}" alt="">` : escapeHtml(initials(contact?.name || "C"))}</span><span class="erp-contact-avatar-action" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h3l1.4-2h7.2L17 7h3v12H4z"/><circle cx="12" cy="13" r="4"/><path d="M12 9v8M8 13h8"/></svg></span><input type="file" accept="image/*" data-contact-image aria-label="Choose contact image"></label><input type="hidden" name="image" value="${escapeHtml(contact?.image || "")}">`;
  const kindSelect = existing ? `<input type="hidden" name="kind" value="${kind}"><span class="contacts-record-kind">${kindLabel}</span>` : `<select name="kind" data-partner-kind aria-label="Record Type">${[["contact", "Contact"], ["supplier", "Supplier"], ["dealer", "Dealer"]].map(([key, label]) => `<option value="${key}" ${kind === key ? "selected" : ""}>${label}</option>`).join("")}</select>`;
  const employers = state.contacts.filter((item) => item.id !== contact?.id && (item.isCompany || item.companyType === "company" || item.recordType === "company"));
  const employerOptions = employers.length ? employers : state.contacts.filter((item) => item.id !== contact?.id);
  const countryOptions = ["Bangladesh", "India", "Pakistan", "United States", "United Kingdom", "United Arab Emirates", "Saudi Arabia", "China", "Singapore"];
  const planOptions = (state.contactCommissionPlans || []).map((plan) => [plan.id, plan.name]);
  const supplierStatus = isSupplierRole && contact && isSupplierApproved(contact) ? `<span class="status-pill purchase">Approved supplier</span>` : `<span class="status-pill approval">Pending supplier approval</span>`;
  const createPurchaseRfqButton = contact && isSupplierRole && isSupplierApproved(contact) ? `<button type="button" class="action-button secondary" data-contact-related-create="purchase" data-id="${escapeHtml(contact.id)}">Create Purchase RFQ</button>` : "";
  const bankAccountRows = value("bankAccounts", []);
  const hasBankAccounts = Array.isArray(bankAccountRows) && bankAccountRows.some((row) => Object.values(row || {}).some((entry) => String(entry || "").trim()));
  const relatedRows = table("related", ["Contact Name", "Job Position", "Email", "Phone", "Contact Type"], value("relatedContacts", []), (row = {}) => `<tr data-contact-line="related"><td>${cell("name", row.name, "text", "Name")}</td><td>${cell("jobTitle", row.jobTitle, "text", "Job position")}</td><td>${cell("email", row.email, "email", "Email")}</td><td>${cell("phone", row.phone, "tel", "Phone")}</td><td>${inputOptions("type", ["Contact", "Invoice Address", "Delivery Address", "Other"], row.type || "Contact")}</td><td><button type="button" class="erp-contact-remove-line" data-contact-remove-line aria-label="Remove line">×</button></td></tr>`);
  const bankRows = table("bank", ["Bank", "Account Number", "Account Holder", "Currency"], bankAccountRows, (row = {}) => `<tr data-contact-line="bank"><td>${cell("bank", row.bank, "text", "Bank name")}</td><td>${cell("accountNumber", row.accountNumber, "text", "Account number")}</td><td>${cell("accountHolder", row.accountHolder, "text", "Account holder")}</td><td>${cell("currency", row.currency || "BDT", "text", "Currency")}</td><td><button type="button" class="erp-contact-remove-line" data-contact-remove-line aria-label="Remove line">×</button></td></tr>`);
  const bankAccountsMarkup = `<section class="erp-contact-bank-section"><button type="button" class="erp-contact-bank-toggle" data-contact-bank-toggle aria-expanded="${hasBankAccounts ? "true" : "false"}"><span>Bank accounts</span><span class="erp-contact-bank-arrow" aria-hidden="true">›</span></button><div id="partner-bank-account-details" class="erp-contact-bank-content" data-contact-bank-content ${hasBankAccounts ? "" : "hidden"}>${bankRows}</div></section>`;
  const ownerRows = table("ubo", ["Name", "Control Method", "Ownership %", "Voting Rights %", "Control Start Date"], value("beneficialOwners", []), (row = {}) => `<tr data-contact-line="ubo"><td>${cell("name", row.name, "text", "Name")}</td><td>${inputOptions("controlMethod", ["Ownership", "Voting rights", "Other means"], row.controlMethod || "Ownership")}</td><td>${cell("ownership", row.ownership, "number", "0.00")}</td><td>${cell("votingRights", row.votingRights, "number", "0.00")}</td><td><input data-contact-field="controlStartDate" type="date" value="${escapeHtml(row.controlStartDate || "")}" aria-label="Control start date"></td><td><button type="button" class="erp-contact-remove-line" data-contact-remove-line aria-label="Remove line">×</button></td></tr>`);
  const related = contact ? contactRelatedRecords(contact) : { opportunities: [], sales: [], invoices: [], purchaseOrders: [], deliveries: [], tasks: [] };
  const chatterEntries = [...(Array.isArray(contact?.chatter) ? contact.chatter : [])].reverse();
  const attachments = Array.isArray(contact?.attachments) ? contact.attachments : [];
  const chatterMarkup = chatterEntries.length ? chatterEntries.map((entry) => {
    const author = entry.author || state.userProfile.name;
    const typeLabel = entry.type === "activity" ? `${entry.title || "Activity"} scheduled` : entry.type === "note" ? "Logged an internal note" : "Sent a message";
    const timestamp = entry.createdAt ? new Date(entry.createdAt).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" }) : "";
    const due = entry.dueDate ? ` · Due ${entry.dueDate}` : "";
    return `<div class="erp-chatter-entry ${entry.type === "note" ? "is-note" : ""}"><span>${escapeHtml(initials(author))}</span><div><strong>${escapeHtml(author)}</strong><p>${escapeHtml(typeLabel)}${timestamp ? ` · ${escapeHtml(timestamp)}` : ""}${escapeHtml(due)}</p>${entry.body ? `<p>${escapeHtml(entry.body)}</p>` : ""}</div></div>`;
  }).join("") : `<div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${existing ? "Contact record opened" : `Creating a new ${kindLabel.toLowerCase()}...`}</p></div></div>`;
  const attachmentMarkup = attachments.length ? `<section class="erp-contact-attachments"><strong>Attachments <small>${attachments.length}</small></strong>${attachments.map((file) => `<a href="${escapeHtml(file.data || "#")}" download="${escapeHtml(file.name || "attachment")}">${escapeHtml(file.name || "Attachment")}</a>`).join("")}</section>` : "";
  const invoiceReminderSchedules = (state.invoiceConfig?.collections?.["invoice-reminders"] || []).filter((item) => item && item.active !== false);
  const invoiceFollowUpsMarkup = invoiceReminderSchedules.length
    ? `<label class="erp-contact-check"><input type="checkbox" name="invoiceFollowUpsEnabled" value="1" ${value("invoiceFollowUpsEnabled") ? "checked" : ""}> Enable automatic invoice reminders</label><p class="erp-contact-help">Reminder schedules follow the company Accounting configuration. <button type="button" class="text-link" data-module-page="invoice-reminders">Manage reminders</button></p>`
    : `<input type="hidden" name="invoiceFollowUpsEnabled" value="${value("invoiceFollowUpsEnabled") ? "1" : "0"}"><p class="erp-contact-help erp-contact-reminders-disabled">“Automatic Invoice Reminders” is currently disabled. <button type="button" class="text-link" data-module-page="invoice-reminders">Open settings</button> to enable them.</p>`;
  const totalInvoiced = related.invoices.filter((item) => item.kind === "out_invoice").reduce((sum, item) => sum + Number(item.total || item.amountTotal || 0), 0);
  const salesCount = related.sales.length;
  const userAccessButton = contact?.userId || contact?.linkedUserId ? `<button type="button" class="action-button secondary settings-contact-user-access" data-open-settings-user="${escapeHtml(contact.userId || contact.linkedUserId)}">User Access</button>` : "";
  const address = contact?.street || contact?.address || "";
  const selectedTags = Array.isArray(value("tags")) ? value("tags").join(", ") : value("tags");
  const additionalTaxIds = (Array.isArray(contact?.taxIds) ? contact.taxIds : []).filter((item) => String(item || "").trim() && String(item).trim() !== String(contact?.taxId || "").trim());
  const additionalTaxIdFields = additionalTaxIds.map((taxId) => `<div class="erp-contact-tin-extra"><input name="additionalTaxIds[]" value="${escapeHtml(taxId)}" aria-label="Additional tax identifier" placeholder="Additional TIN"><button type="button" data-contact-remove-tax-id aria-label="Remove tax identifier" title="Remove tax identifier">×</button></div>`).join("");
  return `<section class="sales-document-page erp-finance-record-page erp-contact-record-page">
    <div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button secondary" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><div><button type="button" class="sales-breadcrumb" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><h1>${existing ? escapeHtml(contact.name) : `New ${kindLabel}`}</h1><small>${kindLabel} · shared across your business records</small></div></div>${userAccessButton}${contactSmartPanelMarkup({ contact, related, salesCount, invoiced: totalInvoiced, taskCount: related.tasks.length })}<button type="button" class="soft-icon-button" data-contact-editor-action="discard" aria-label="Close">×</button></div>
    <div class="sales-document-actionbar"><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" class="action-button" form="partner-contact-form">Save</button></div><div class="sales-statusbar invoice-statusbar"><span class="is-current">${kindLabel}</span><span>${isSupplierRole ? (contact && isSupplierApproved(contact) ? "Approved" : "Approval needed") : contactRoleSummary}</span></div></div>
    <div class="erp-finance-form-layout"><main><form id="partner-contact-form" data-id="${contact?.id ?? ""}"><article class="sales-document-card erp-contact-card">
      <div class="erp-contact-identity">${avatar}<div class="erp-contact-primary"><input name="name" aria-label="Name" required maxlength="120" placeholder="Name (company or person)" value="${escapeHtml(contact?.name || "")}"><div class="erp-contact-meta"><label class="contacts-kind-wrap">▦ ${kindSelect}</label><label>✉ <input name="email" aria-label="Email" type="email" maxlength="120" placeholder="Email" value="${escapeHtml(contact?.email || "")}"></label><label>☎ <input name="phone" aria-label="Phone" type="tel" maxlength="40" placeholder="Phone" value="${escapeHtml(contact?.phone || "")}"></label></div></div></div>
      <section class="erp-contact-details"><div><h3>Address</h3><input name="street" placeholder="Street..." value="${escapeHtml(address)}"><input name="street2" placeholder="Street 2..." value="${escapeHtml(contact?.street2 || "")}"><div class="erp-contact-address-row"><input name="city" placeholder="City" aria-label="City" value="${escapeHtml(contact?.city || contact?.area || "")}"><input name="state" placeholder="State" aria-label="State" value="${escapeHtml(contact?.state || "")}"><input name="zip" placeholder="ZIP" aria-label="ZIP" value="${escapeHtml(contact?.zip || "")}"></div><div class="erp-contact-address-row"><label class="erp-contact-country">Country<input name="country" list="partner-country-options" value="${escapeHtml(contact?.country || "Bangladesh")}" placeholder="Country"><datalist id="partner-country-options">${countryOptions.map((item) => `<option>${item}</option>`).join("")}</datalist></label><div class="erp-contact-tin-fields">${field("TIN", "taxId", value("taxId"), 'placeholder="Tax Identification Number"')}${additionalTaxIdFields}</div></div></div><div class="erp-contact-extra">${field("Company Employer", "company", value("company"), 'placeholder="Company or parent contact" list="partner-company-options"')}<datalist id="partner-company-options">${employerOptions.map((item) => `<option value="${escapeHtml(item.name)}"></option>`).join("")}</datalist>${field("Job Position", "jobTitle", value("jobTitle"), 'placeholder="e.g. Sales Director"')}${field("Website", "website", value("website"), 'type="url" placeholder="https://www.example.com"')}${select("Partner Level", "partnerLevel", ["Gold", "Silver", "Bronze", "Members"], value("partnerLevel"))}${select("Language", "language", [["en_US", "English (US)"], ["bn_BD", "Bengali / Bangla"], ["en_GB", "English (UK)"], ["ar_001", "Arabic"]], value("language", "en_US"))}${field("Tags", "tags", selectedTags, 'placeholder="B2B, VIP, Consulting"')}${select("Contact Type", "recordType", [["person", "Individual"], ["company", "Company"], ["invoice", "Invoice Address"], ["delivery", "Delivery Address"], ["other", "Other Address"]], value("recordType", "person"))}${field("Area / Territory", "area", value("area", contact?.city || ""), 'placeholder="District, upazila, or route"')}</div></section>
      <nav class="sales-document-tabs erp-contact-tabs" aria-label="Contact details"><button type="button" class="is-active" data-contact-tab="details">Contacts</button><button type="button" data-contact-tab="sales">Sales &amp; Purchase</button><button type="button" data-contact-tab="accounting">Accounting</button><button type="button" data-contact-tab="partner-assignment">Partner Assignment</button><button type="button" data-contact-tab="notes">Notes</button><button type="button" data-contact-tab="ubo">UBO</button></nav>
      <section class="sales-tab-panel is-active" data-contact-panel="details"><div class="erp-contact-tab-section"><h3>RELATED CONTACTS</h3><p class="erp-contact-help">Add the people and invoice or delivery addresses linked to this company.</p>${relatedRows}</div></section>
      <section class="sales-tab-panel" data-contact-panel="sales"><fieldset class="erp-contact-role-controls"><legend>Contact Roles</legend><label><input type="checkbox" name="isCustomer" value="1" data-partner-role="customer" ${isCustomerRole ? "checked" : ""}> Customer <small>Sales and customer documents</small></label><label><input type="checkbox" name="isSupplier" value="1" data-partner-role="supplier" ${isSupplierRole ? "checked" : ""}> Supplier <small>Purchases and vendor bills</small></label></fieldset><section class="erp-contact-tab-section erp-contact-purchase-link"><h3>PURCHASE LINK</h3><p class="erp-contact-help">Mark this Contact as a Supplier, save it, and approve it. Purchase will use this same Contact record.</p><div data-partner-kind-panel="supplier" ${isSupplierRole ? "" : "hidden"}>${field("Supplier Reference", "supplierReference", value("supplierReference", value("reference")), 'placeholder="Supplier reference"')}${select("Payment Terms", "paymentTerms", purchasePaymentTermOptions([value("paymentTerms")]), value("paymentTerms", "Immediate"))}<label class="erp-contact-check"><input type="checkbox" name="defaultPurchaseVendor" value="1" ${value("defaultPurchaseVendor") ? "checked" : ""}> Default Purchase Vendor</label><div class="erp-contact-field"><label>Approval</label><div class="contacts-approval-state">${supplierStatus}</div></div>${createPurchaseRfqButton}</div></section></section><section class="sales-tab-panel" data-contact-panel="accounting"><div class="erp-contact-columns"><section class="erp-contact-tab-section"><h3>GENERAL</h3>${bankAccountsMarkup}${field("Account Receivable", "receivableAccount", value("receivableAccount", "121000 Accounts Receivable"))}${field("Account Payable", "payableAccount", value("payableAccount", "211000 Accounts Payable"))}${select("Auto-post bills", "autoPostBills", ["Always", "Ask after 3 validations without edits", "Ask each time", "Never"], value("autoPostBills", "Ask after 3 validations without edits"))}</section><section class="erp-contact-tab-section"><h3>INVOICE FOLLOW-UPS</h3>${invoiceFollowUpsMarkup}<h3 class="erp-contact-subhead">CUSTOMER INVOICES</h3><input type="hidden" name="peppolStatus" value="${escapeHtml(value("peppolStatus", "Unchecked"))}"><div class="erp-contact-peppol"><span>Peppol status</span><strong data-peppol-status>${escapeHtml(value("peppolStatus", "Unchecked"))}</strong><button type="button" class="action-button secondary" data-contact-verify-peppol>Verify</button></div><p class="erp-contact-help">Bills, invoices, payments and balances remain linked to this contact.</p></section></div></section>
      <section class="sales-tab-panel" data-contact-panel="partner-assignment"><div class="erp-contact-columns"><section class="erp-contact-tab-section"><h3>PARTNER ACTIVATION</h3><div class="erp-contact-plan-select">${select("Commission Plan", "commissionPlanId", planOptions, value("commissionPlanId"))}<button type="button" class="action-button secondary" data-contact-create-plan>Create</button></div>${select("Activation", "activation", ["Fully Operational", "Ramp-up", "First Contact"], value("activation"))}${field("Level Weight", "levelWeight", value("levelWeight", 0), 'type="number" min="0" step="0.01"')}</section><section class="erp-contact-tab-section"><h3>PARTNER REVIEW</h3>${field("Latest Review", "latestReview", value("latestReview"), 'type="date"')}${field("Next Review", "nextReview", value("nextReview"), 'type="date"')}${field("Partnership Date", "partnershipDate", value("partnershipDate"), 'type="date"')}</section></div><section class="erp-contact-tab-section erp-contact-geolocation"><h3>GEOLOCATION</h3><div class="erp-contact-columns">${field("Latitude", "latitude", value("latitude", "0.0000000"), 'type="number" step="0.0000001"')}${field("Longitude", "longitude", value("longitude", "0.0000000"), 'type="number" step="0.0000001"')}</div><button type="button" class="action-button secondary" data-contact-compute-location>⚙ Compute based on address</button></section></section>
      <section class="sales-tab-panel" data-contact-panel="notes"><div class="erp-contact-tab-section"><h3>NOTES</h3><div class="erp-contact-field"><label for="partner-notes">Internal Notes</label><textarea id="partner-notes" name="notes" placeholder="Notes for your team...">${escapeHtml(value("notes"))}</textarea></div><div class="erp-contact-field"><label for="partner-comment">Contact Notes</label><textarea id="partner-comment" name="comment" placeholder="Additional contact information...">${escapeHtml(value("comment"))}</textarea></div></div></section>
      <section class="sales-tab-panel" data-contact-panel="ubo"><div class="erp-contact-columns"><section class="erp-contact-tab-section"><h3>LEGAL ENTITY</h3>${select("Legal Form", "legalForm", ["Company", "Corporation", "Partnership", "Limited Liability Company", "Sole Proprietorship", "Non-profit", "Other"], value("legalForm"))}</section><section class="erp-contact-tab-section">${field("Formation Date", "formationDate", value("formationDate"), 'type="date"')}</section></div><section class="erp-contact-tab-section"><h3>BENEFICIAL OWNERS</h3>${ownerRows}</section></section>
      <footer class="sales-document-footer"><span class="sales-document-note">This contact is shared with connected Sales, Purchase, Accounting, dealer and supplier records.</span><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" form="partner-contact-form" class="action-button">Save</button></div></footer>
    </article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button" data-contact-chatter="message">Send message</button><button type="button" class="action-button secondary" data-contact-chatter="note">Log note</button><button type="button" class="action-button secondary" data-contact-whatsapp>WhatsApp</button><button type="button" class="action-button secondary" data-contact-chatter="activity">Activity</button></div><label class="erp-contact-chatter-search" hidden><span>Search messages</span><input type="search" data-contact-chatter-search placeholder="Search messages..."></label><input type="file" data-contact-chatter-attachment accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx,.csv" hidden>${chatterMarkup}${attachmentMarkup}<p class="erp-chatter-note">Messages, notes, activities, followers and attachments are saved with this contact.</p></aside></div></section>`;
}

function alignPartnerContactFormToOdoo() {
  const form = pageContent.querySelector("#partner-contact-form");
  if (!form) return;
  const page = form.closest(".erp-contact-record-page");
  const meta = form.querySelector(".erp-contact-meta");
  const kindControl = form.querySelector("[name='kind']");
  if (kindControl && meta) {
    const hiddenKind = document.createElement("input");
    hiddenKind.type = "hidden";
    hiddenKind.name = "kind";
    hiddenKind.value = kindControl.value || state.contactEditor?.kind || "contact";
    kindControl.closest(".contacts-kind-wrap")?.replaceWith(hiddenKind);
  }

  const employerField = form.querySelector("#partner-company")?.closest(".erp-contact-field");
  if (employerField && meta) {
    employerField.classList.add("erp-contact-company-employer");
    meta.prepend(employerField);
  }
  const recordTypeField = form.querySelector("#partner-recordType")?.closest(".erp-contact-field");
  if (recordTypeField) recordTypeField.hidden = true;
  const territoryField = form.querySelector("#partner-area")?.closest(".erp-contact-field");
  const salesPanel = form.querySelector('[data-contact-panel="sales"] .erp-contact-tab-section');
  if (territoryField && salesPanel) {
    const dealerArea = document.createElement("div");
    dealerArea.dataset.partnerKindPanel = "dealer";
    dealerArea.hidden = (form.querySelector('[name="kind"]')?.value || state.contactEditor?.kind) !== "dealer";
    dealerArea.className = "erp-contact-dealer-area";
    dealerArea.append(territoryField);
    salesPanel.append(dealerArea);
  }

  const avatar = form.querySelector("[data-contact-avatar-preview]");
  if (avatar && !avatar.querySelector("img")) {
    avatar.innerHTML = `<svg class="erp-contact-building-icon" viewBox="0 0 100 100" aria-hidden="true"><path fill="#f4cfc8" d="M18 27 54 8l29 15v57L48 94 18 76Z"/><path fill="#fff" stroke="#455f86" stroke-width="2" d="m18 27 36-19 29 15v57L48 94 18 76Z"/><path fill="#d7e7f6" stroke="#455f86" stroke-width="2" d="m54 8 29 15v57L48 94V36Z"/><path fill="#b7d6f0" d="m21 28 31-16v8L21 37Z"/><g fill="#fff" stroke="#59759b" stroke-width="1.5"><path d="m30 41 9-5v10l-9 5z"/><path d="m46 33 8-4v10l-8 4z"/><path d="m62 28 8 4v10l-8-4z"/><path d="m30 58 9-5v10l-9 5z"/><path d="m46 50 8-4v10l-8 4z"/><path d="m62 45 8 4v10l-8-4z"/><path d="m30 74 9-5v10l-9 5z"/><path d="m46 67 8-4v10l-8 4z"/><path d="m62 62 8 4v10l-8-4z"/></g></svg>`;
  }

  const tinField = form.querySelector("#partner-taxId")?.closest(".erp-contact-field");
  if (tinField && !tinField.querySelector(".erp-contact-tin-control")) {
    const label = tinField.querySelector("label");
    const help = document.createElement("span");
    help.className = "erp-contact-help-icon";
    help.title = "Tax Identification Number";
    help.textContent = "?";
    label?.append(" ", help);
    const input = tinField.querySelector("input");
    if (input) {
      const controls = document.createElement("div");
      controls.className = "erp-contact-tin-control";
      const add = document.createElement("button");
      add.type = "button";
      add.className = "erp-contact-tin-add";
      add.setAttribute("aria-label", "Add another tax identifier");
      add.title = "Add another tax identifier";
      add.textContent = "+";
      add.addEventListener("click", () => {
        const row = document.createElement("div");
        row.className = "erp-contact-tin-extra";
        const extra = document.createElement("input");
        extra.name = "additionalTaxIds[]";
        extra.maxLength = 80;
        extra.placeholder = "Additional TIN";
        extra.setAttribute("aria-label", "Additional tax identifier");
        const remove = document.createElement("button");
        remove.type = "button";
        remove.dataset.contactRemoveTaxId = "true";
        remove.setAttribute("aria-label", "Remove tax identifier");
        remove.title = "Remove tax identifier";
        remove.textContent = "×";
        row.append(extra, remove);
        tinField.append(row);
        extra.focus();
      });
      input.replaceWith(controls);
      controls.append(input, add);
    }
  }

  const relatedSection = form.querySelector('[data-contact-panel="details"] .erp-contact-tab-section');
  const relatedWrap = relatedSection?.querySelector('[data-contact-rows="related"]')?.closest(".erp-contact-table-wrap");
  if (relatedSection && relatedWrap && !relatedSection.querySelector("[data-contact-open-related]")) {
    relatedSection.querySelector("h3")?.remove();
    relatedSection.querySelector(".erp-contact-help")?.remove();
    const hasRelated = (state.contacts.find((item) => String(item.id) === String(state.contactEditor?.id))?.relatedContacts || []).some((item) => item.name || item.email || item.phone);
    const addRelated = document.createElement("button");
    addRelated.type = "button";
    addRelated.className = "erp-contact-related-add";
    addRelated.dataset.contactOpenRelated = "true";
    addRelated.innerHTML = "<span aria-hidden='true'>＋</span> Add Related Contacts";
    relatedSection.prepend(addRelated);
    relatedWrap.hidden = !hasRelated;
    addRelated.hidden = hasRelated;
  }

  const toolbar = page.querySelector(".sales-document-toolbar");
  const title = toolbar?.querySelector(".sales-document-title");
  if ((state.contactEditor?.id === null || state.contactEditor?.id === undefined) && title) {
    const newButton = title.querySelector("button[data-contact-editor-action='discard']");
    if (newButton) {
      newButton.textContent = "New";
      newButton.classList.remove("secondary");
      newButton.removeAttribute("data-contact-editor-action");
      newButton.dataset.contactNew = "true";
    }
    const heading = title.querySelector("h1");
    if (heading) heading.textContent = "New";
  }
  const actionbar = page.querySelector(".sales-document-actionbar");
  const saveButton = actionbar?.querySelector('button[type="submit"]');
  if (saveButton && title) {
    saveButton.classList.add("erp-contact-save-cloud");
    saveButton.innerHTML = "<svg viewBox='0 0 24 24' aria-hidden='true'><path d='M7 18a4 4 0 0 1-.5-7.97A5.5 5.5 0 0 1 17 8.5a4.75 4.75 0 0 1 .25 9.5H7Z'/><path d='M12 17V11m0 0-2.5 2.5M12 11l2.5 2.5'/></svg>";
    saveButton.title = "Save contact";
    saveButton.setAttribute("aria-label", "Save contact");
    title.append(saveButton);
  }
  if (title && !title.querySelector("[data-contact-more]") && saveButton) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "erp-contact-more";
    more.dataset.contactMore = "true";
    more.setAttribute("aria-label", "More contact actions");
    more.title = "More contact actions";
    more.textContent = "⋮";
    title.insertBefore(more, saveButton);
  }
  actionbar?.remove();
  page.querySelector(".sales-document-footer")?.remove();
  page.querySelector(".sales-document-title small")?.remove();
  const chatterActions = page.querySelector(".erp-chatter-actions");
  if (chatterActions && !page.querySelector(".erp-contact-chatter-tools")) {
    const tools = document.createElement("div");
    tools.className = "erp-contact-chatter-tools";
    const contact = state.contacts.find((item) => String(item.id) === String(state.contactEditor?.id));
    const followerCount = Array.isArray(contact?.followers) ? contact.followers.length : 0;
    tools.innerHTML = `<button type="button" data-contact-chatter-tool="search" aria-label="Search messages" title="Search messages"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.2"/><path d="m15.5 15.5 4.2 4.2"/></svg></button><button type="button" data-contact-chatter-tool="attachment" aria-label="Attachments" title="Attachments"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 12.5 6.7-6.7a3.5 3.5 0 0 1 5 5l-9.2 9.2a5 5 0 0 1-7.1-7.1l9-9"/></svg></button><button type="button" data-contact-chatter-tool="followers" aria-label="Followers" title="Followers"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.2"/><path d="M5.5 20a6.5 6.5 0 0 1 13 0"/></svg><sup>${followerCount}</sup></button>`;
    chatterActions.append(tools);
  }
}

function openContactCommissionPlanModal() {
  const products = salesProducts.map((product) => `<option value="${escapeHtml(product.id)}">${escapeHtml(product.name)}</option>`).join("");
  const ruleRow = () => `<tr data-contact-line="commission-rule"><td><input data-contact-field="productCategory" placeholder="Product category"></td><td><select data-contact-field="product"><option value="">Any product</option>${products}</select></td><td><input data-contact-field="saleOrderTemplate" placeholder="Sale order template"></td><td><input data-contact-field="pricelist" placeholder="Pricelist"></td><td><input data-contact-field="rate" type="number" min="0" step="0.01" placeholder="Rate"></td><td><input data-contact-field="capped" type="checkbox" aria-label="Capped"></td><td><input data-contact-field="maxCommission" type="number" min="0" step="0.01" placeholder="Max commission"></td><td><button type="button" class="erp-contact-remove-line" data-contact-remove-line aria-label="Remove rule">×</button></td></tr>`;
  openModal(`<header class="modal-header"><div><h2>Create Commission Plan</h2></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="contact-commission-plan-form"><div class="modal-body"><div class="erp-contact-plan-fields"><label>Name<input name="name" required maxlength="120" placeholder="Commission plan name"></label><label>Purchase Default Product<select name="purchaseDefaultProduct"><option value="">Select product</option>${products}</select></label><label>Company<input name="company" value="${escapeHtml(state.companySettings?.name || "Arafat Chemica")}" placeholder="Company"></label></div><nav class="sales-document-tabs erp-contact-tabs"><button type="button" class="is-active">Rules</button></nav><div class="erp-contact-table-wrap"><table class="erp-contact-table"><thead><tr><th>Product Category</th><th>Product</th><th>Sale Order Template</th><th>Pricelist</th><th>Rate</th><th>Capped</th><th>Max Commission</th><th></th></tr></thead><tbody data-contact-rows="commission-rule">${ruleRow()}</tbody></table><template data-contact-row-template="commission-rule">${ruleRow()}</template><button type="button" class="erp-contact-add-line" data-contact-add-line="commission-rule">+ Add a line</button></div></div><footer class="modal-footer"><button type="submit" class="action-button">Save</button><button type="button" class="action-button secondary" data-action="close-modal">Discard</button></footer></form>`);
}

function renderContactFormPage() {
  const editor = state.contactEditor || { type: "customer", returnPage: state.page };
  const isVendor = editor.type === "vendor";
  const title = isVendor ? "New Vendor" : "New Customer";
  const formId = isVendor ? "invoice-vendor-form" : "sales-customer-form";
  const returnLabel = pageLabels[editor.returnPage] || (isVendor ? "Vendors" : "Customers");
  const mainFields = isVendor
    ? ""
    : `<div class="erp-contact-field"><label>Area / Territory</label><input name="area" placeholder="District, upazila, or route"></div>`;
  const commercialFields = isVendor
    ? `<div class="erp-contact-field"><label>Supplier Reference</label><input name="reference" placeholder="Supplier code"></div><div class="erp-contact-field"><label>Payment Terms</label><select name="paymentTerms"><option>Immediate</option><option>7 days</option><option>15 days</option><option>30 days</option></select></div>`
    : `<div class="erp-contact-field"><label>Channel</label><select name="type"><option>Dealer</option><option>Depot</option><option>Retailer</option><option>Other wholesale</option></select></div><div class="erp-contact-field"><label>Credit Limit · BDT</label><input name="creditLimit" type="number" min="0" step="0.01" value="0"></div>`;
  return `<section class="sales-document-page erp-finance-record-page erp-contact-record-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><div><button type="button" class="sales-breadcrumb" data-contact-editor-action="discard">${escapeHtml(returnLabel)}</button><h1>${title}</h1><small>${isVendor ? "Supplier · shared with Purchase and Accounting" : "Customer · shared with Sales and Invoicing"}</small></div></div>${contactSmartPanelMarkup()}<button type="button" class="soft-icon-button" data-contact-editor-action="discard" aria-label="Close">×</button></div><div class="sales-document-actionbar"><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" class="action-button" form="${formId}">Save</button></div><div class="sales-statusbar invoice-statusbar"><span class="is-current">Contact</span><span>${isVendor ? "Vendor" : "Customer"}</span></div></div><div class="erp-finance-form-layout"><main><form id="${formId}"><article class="sales-document-card erp-contact-card"><div class="erp-contact-identity"><div class="erp-contact-avatar" aria-hidden="true">▧</div><div class="erp-contact-primary"><input name="name" aria-label="Name" required placeholder="Name (company or person)"><div class="erp-contact-meta"><span>▦ ${isVendor ? "Supplier" : "Customer"}</span><label>✉ <input name="email" aria-label="Email" type="email" placeholder="Email"></label><label>☎ <input name="phone" aria-label="Phone" type="tel" placeholder="Phone"></label></div></div></div><section class="erp-contact-details"><div><h3>Address</h3><input name="address" placeholder="Street..."><input name="street2" placeholder="Street 2..."><div class="erp-contact-address-row"><input name="city" placeholder="City"><input name="state" placeholder="State"><input name="zip" placeholder="ZIP"></div><input name="country" value="Bangladesh" aria-label="Country"></div><div class="erp-contact-extra">${mainFields}<div class="erp-contact-field"><label>Website</label><input name="website" type="url" placeholder="https://"></div><div class="erp-contact-field"><label>Tags</label><input name="tags" placeholder="B2B, VIP, Wholesale"></div></div></section><nav class="sales-document-tabs erp-contact-tabs"><button type="button" class="is-active" data-contact-tab="contacts">Contacts</button><button type="button" data-contact-tab="sales">Sales &amp; Purchase</button><button type="button" data-contact-tab="accounting">Accounting</button><button type="button" data-contact-tab="notes">Notes</button></nav><section class="sales-tab-panel is-active" data-contact-panel="contacts"><div class="erp-contact-related"><strong>Related Contacts</strong><p>Additional people and delivery addresses can be added to this business record.</p></div></section><section class="sales-tab-panel" data-contact-panel="sales"><div class="erp-contact-tab-grid">${commercialFields}<div class="erp-contact-field"><label>${isVendor ? "Purchase Currency" : "Sales Currency"}</label><input value="BDT · Bangladeshi Taka" disabled></div></div></section><section class="sales-tab-panel" data-contact-panel="accounting"><div class="erp-contact-tab-grid"><div class="erp-contact-field"><label>Tax ID / BIN</label><input name="taxId" placeholder="BIN / TIN"></div><div class="erp-contact-field"><label>${isVendor ? "Payable Account" : "Receivable Account"}</label><input value="${isVendor ? "2000 · Accounts Payable" : "1100 · Accounts Receivable"}" disabled></div><p class="erp-contact-help">Posted bills, invoices, payments and balances are linked to this contact in Accounting.</p></div></section><section class="sales-tab-panel" data-contact-panel="notes"><div class="erp-contact-field"><label>Internal Notes</label><textarea name="notes" placeholder="Notes for your team..."></textarea></div></section><footer class="sales-document-footer"><span class="sales-document-note">This contact is shared across Sales, Purchase, Invoicing and Accounting.</span><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-contact-editor-action="discard">Discard</button><button type="submit" form="${formId}" class="action-button">Save</button></div></footer></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button">Send message</button><button type="button" class="action-button secondary">Log note</button><button type="button" class="action-button secondary">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>Creating a new ${isVendor ? "supplier" : "customer"}...</p></div></div><p class="erp-chatter-note">Messages, internal notes and scheduled activities for this contact appear here.</p></aside></div></section>`;
}

function openSalesProductModal(productId = null) {
  state.salesProductEditor = {
    id: productId ? Number(productId) : null,
    returnPage: state.module === "inventory" ? "inventory-products" : (state.page || "sales-products"),
    tab: "configuration",
  };
  state.salesProductImageData = null;
  persistLastRoute();
  render();
  if (productId) showToast("Already saved. Save is inactive until you make a change.");
}

function renderSalesProductForm() {
  const product = salesProducts.find((item) => item.id === Number(state.salesProductEditor?.id)) || null;
  const productConfigurations = inventoryProductConfigurations({ migrateLegacy: true });
  const selectedConfigurationId = String(state.salesProductEditor?.pendingConfigurationId || product?.productConfigurationId || "");
  const selectedConfiguration = productConfigurations.find((item) => String(item.id) === selectedConfigurationId) || null;
  const selectedConfigurationDefaults = !product && selectedConfiguration ? salesProductConfigurationDefaults(selectedConfiguration) : null;
  const configurationSource = selectedConfiguration || product;
  const purchaseUom = String(configurationSource?.purchaseUom || readLastProductPurchaseUnit() || configurationSource?.stockUom || "Piece");
  const savedStockUnit = configurationSource?.stockUom || "Piece";
  const packetizedSack = isSackPurchaseUnit(purchaseUom) && normalizeProductIdentity(savedStockUnit) !== "packet";
  const stockUnit = isSackPurchaseUnit(purchaseUom) ? "Packet" : savedStockUnit;
  const basePurchasePrice = configurationSource ? Number(configurationSource.cost ?? configurationSource.purchasePrice ?? 0) : "";
  const baseSalesPrice = configurationSource ? Number(configurationSource.price || 0) : "";
  const conversions = configurationSource ? productUnitConversions(configurationSource) : [];
  const selectedConversion = conversions.find((row) => String(row.unit || "").toLowerCase() === purchaseUom.toLowerCase());
  const purchaseQuantityValue = packetizedSack ? "" : (normalizeProductIdentity(purchaseUom) === normalizeProductIdentity(stockUnit) ? 1 : (selectedConversion?.quantity ?? configurationSource?.purchaseUnitQuantity ?? ""));
  const purchaseQuantity = Number(purchaseQuantityValue) > 0 ? Number(purchaseQuantityValue) : "";
  const rawPackagePrice = selectedConversion?.purchasePrice;
  const purchaseUnitPrice = rawPackagePrice !== undefined && rawPackagePrice !== null && String(rawPackagePrice).trim() !== ""
    ? Number(rawPackagePrice)
    : configurationSource ? (Number(purchaseQuantity) > 0 ? Number(basePurchasePrice || 0) * Number(purchaseQuantity) : packetizedSack ? "" : Number(basePurchasePrice || 0)) : "";
  const rawSalePackagePrice = selectedConversion?.salePrice;
  const salePackagePrice = rawSalePackagePrice !== undefined && rawSalePackagePrice !== null && String(rawSalePackagePrice).trim() !== ""
    ? Number(rawSalePackagePrice)
    : configurationSource ? (Number(purchaseQuantity) > 0 ? Number(baseSalesPrice || 0) * Number(purchaseQuantity) : packetizedSack ? "" : Number(baseSalesPrice || 0)) : "";
  const onHand = Number(product?.onHand || 0);
  const incoming = product && typeof inventoryIncoming === "function" ? inventoryIncoming(product) : 0;
  const outgoing = product && typeof inventoryOutgoing === "function" ? inventoryOutgoing(product) : 0;
  const initialCategory = product?.category || "";
  const includeCategoryInTitle = product?.includeCategoryInTitle !== false;
  const productCategoryOptions = [...new Set([...categories.map((item) => item.name), initialCategory].filter(Boolean))];
  const initialBaseName = salesProductBaseName(product);
  const productImageVariant = Number(product?.imageVariant || 0);
  const legacyGeneratedVector = product?.image?.startsWith("data:image/svg+xml") && product.imageAutoGenerated == null;
  const savedManualImage = product?.image && product.imageAutoGenerated !== true && !legacyGeneratedVector ? product.image : "";
  const initialImageMode = state.salesProductImageData || savedManualImage ? "manual" : "auto";
  const image = state.salesProductImageData || savedManualImage || autoSalesProductImage(initialBaseName, initialCategory, productImageVariant);
  const enabledIn = product?.enabledIn || {};
  const vendorNames = [...new Set([
    ...vendors.filter(isSupplierApproved).map((vendor) => vendor.name),
    ...(product?.vendorPrices || []).map((row) => row.vendor),
    ...(selectedConfigurationDefaults?.vendorPrices || []).map((row) => row.vendor),
    selectedConfigurationDefaults?.supplierName,
    product?.supplierName,
  ].filter(Boolean))];
  const initialProductTitle = salesProductTitle(product);
  const stockUnitOptions = [...new Set(["Piece", "Packet", "Bottle", "kg", "g", "L", "ml", stockUnit])];
  const purchaseUnitOptions = productPurchaseUnitOptions([
    stockUnit,
    purchaseUom,
    ...productConfigurations.flatMap((configuration) => [configuration.purchaseUom, ...(configuration.unitConversions || []).map((row) => row.unit)]),
    ...conversions.map((row) => row.unit),
  ]);
  const configurationOptions = productConfigurations.filter((configuration) => configuration.active || String(configuration.id) === selectedConfigurationId).map((configuration) => `<option value="${escapeHtml(configuration.id)}" ${String(configuration.id) === selectedConfigurationId ? "selected" : ""}>${escapeHtml(configuration.name)}${configuration.active ? "" : " · Needs review"}</option>`).join("");
  const consumerOffers = inventoryProductConsumerOffers(product, Number(baseSalesPrice || 0));
  const initialPromotionType = product
    ? (product.promotionType === "cp" || consumerOffers.some((offer) => offer.giftItemIds.length) ? "cp" : "non-cp")
    : "cp";
  const consumerOfferRowsMarkup = consumerOffers.map((offer, index) => inventoryConsumerOfferEditorRowMarkup({ ...offer, stockUom: stockUnit }, index, Number(baseSalesPrice || 0), initialPromotionType === "cp")).join("");
  const selectedPackage = selectedConversion || { unit: purchaseUom, quantity: purchaseQuantity, purchaseEnabled: true, saleEnabled: true };
  const packageRows = [
    { ...selectedPackage, unit: purchaseUom, quantity: purchaseQuantity, purchaseEnabled: true, purchasePrice: purchaseUnitPrice },
    ...conversions.filter((row) => row.unit && String(row.unit).toLowerCase() !== purchaseUom.toLowerCase() && String(row.unit).toLowerCase() !== stockUnit.toLowerCase()),
  ];
  const purchaseRows = product?.vendorPrices?.length
    ? product.vendorPrices
    : (product?.supplierName ? [{ vendor: product.supplierName, quantity: 1, unit: purchaseUom, unitPrice: purchaseUnitPrice, leadTime: product.vendorLeadTime || 0 }] : selectedConfigurationDefaults?.vendorPrices?.length ? selectedConfigurationDefaults.vendorPrices : (selectedConfigurationDefaults?.supplierName ? [{ vendor: selectedConfigurationDefaults.supplierName, quantity: 1, unit: purchaseUom, unitPrice: selectedConfigurationDefaults.supplierUnitPrice, leadTime: 0 }] : []));
  const approvedSuppliers = vendors.filter(isSupplierApproved);
  const linkedProductSupplier = vendors.find((item) => isSupplierApproved(item) && String(item.id) === String(product?.supplierId || ""))
    || vendors.find((item) => isSupplierApproved(item) && String(item.name || "").toLowerCase() === String(product?.supplierName || "").toLowerCase());
  const configuredSupplier = vendors.find((item) => isSupplierApproved(item) && String(item.id) === String(selectedConfigurationDefaults?.supplierId || ""))
    || vendors.find((item) => isSupplierApproved(item) && String(item.name || "").toLowerCase() === String(selectedConfigurationDefaults?.supplierName || "").toLowerCase());
  const soleApprovedSupplier = approvedSuppliers.length === 1 ? approvedSuppliers[0] : null;
  const fallbackPurchaseSupplier = vendors.find((item) => isSupplierApproved(item) && String(item.name || "").toLowerCase() === String(purchaseRows[0]?.vendor || "").toLowerCase());
  const supplierMaster = linkedProductSupplier || soleApprovedSupplier || configuredSupplier || fallbackPurchaseSupplier || null;
  const supplierMasterName = String(supplierMaster?.name || product?.supplierName || selectedConfigurationDefaults?.supplierName || purchaseRows[0]?.vendor || "");
  const supplierMasterRow = purchaseRows.find((row) => String(row.vendor || "").toLowerCase() === supplierMasterName.toLowerCase());
  const supplierMasterPrice = supplierMasterRow?.unitPrice ?? "";
  const initialNetContentValue = selectedConfiguration?.netContentValue ?? product?.netContentValue ?? selectedConfigurationDefaults?.netContentValue ?? "";
  const initialNetContentUnit = selectedConfiguration?.netContentUnit || product?.netContentUnit || selectedConfigurationDefaults?.netContentUnit || "g";
  const initialVariantTitle = salesProductVariantTitle(initialProductTitle, initialNetContentValue, initialNetContentUnit);
  const existingSku = String(product?.sku || "").trim();
  const initialSkuGenerated = !existingSku || product?.skuAutoGenerated === true || (product?.skuAutoGenerated !== false && /^AUTO-/i.test(existingSku) && !productHasHistory(product));
  const initialSku = initialSkuGenerated
    ? generateSalesProductSku({ supplierName: supplierMasterName, name: initialBaseName, category: initialCategory, netContentValue: initialNetContentValue, netContentUnit: initialNetContentUnit, stockUom: stockUnit, purchaseUom, purchaseUnitQuantity: purchaseQuantity, packUom: product?.packUom || "", packQuantity: product?.packQuantity ?? "" }, product?.id)
    : existingSku;
  const savedBarcode = String(product?.barcode || "").trim().toUpperCase();
  const initialBarcodeGenerated = product?.barcodeAutoGenerated === true || (product?.barcodeAutoGenerated !== false && (!savedBarcode || (existingSku && normalizeProductIdentity(savedBarcode) === normalizeProductIdentity(existingSku)) || !isCode39ValueSupported(savedBarcode)));
  const initialBarcode = initialBarcodeGenerated ? initialSku.toUpperCase() : savedBarcode;
  const productConfigRowMarkup = (row = {}) => `<tr data-product-config-row><td><input data-product-config-row-field="unit" value="${escapeHtml(row.unit || "")}" placeholder="Carton, Bag, packet"></td><td><input data-product-config-row-field="quantity" type="number" min="0.001" step="0.001" value="${escapeHtml(row.quantity ?? "")}" placeholder="e.g. 30"></td><td><input data-product-config-row-field="purchasePrice" type="number" min="0" step="0.01" value="${escapeHtml(row.purchasePrice ?? "")}" placeholder="Auto"></td><td><input data-product-config-row-field="salePrice" type="number" min="0" step="0.01" value="${escapeHtml(row.salePrice ?? "")}" placeholder="Auto"></td><td><label><input data-product-config-row-field="purchaseEnabled" type="checkbox" ${row.purchaseEnabled !== false ? "checked" : ""}> Purchase</label></td><td><label><input data-product-config-row-field="saleEnabled" type="checkbox" ${row.saleEnabled !== false ? "checked" : ""}> Sales</label></td><td><button type="button" class="reference-link danger-link" data-product-config-remove-row aria-label="Remove unit">×</button></td></tr>`;
  const productConfigExtraRows = conversions.filter((row) => row.unit && String(row.unit).toLowerCase() !== purchaseUom.toLowerCase() && String(row.unit).toLowerCase() !== stockUnit.toLowerCase());
  const productConfigRows = productConfigExtraRows.length ? productConfigExtraRows.map(productConfigRowMarkup).join("") : productConfigRowMarkup();
  const options = (items, selected) => items.map((item) => `<option value="${escapeHtml(item)}" ${String(item) === String(selected) ? "selected" : ""}>${escapeHtml(item)}</option>`).join("");
  const field = (label, name, value = "", attrs = "", help = "") => `<div class="erp-product-field"><label for="product-${name}">${label}</label><input id="product-${name}" name="${name}" value="${escapeHtml(value)}" ${attrs}>${help ? `<small>${help}</small>` : ""}</div>`;
  const selectField = (label, name, values, selected, attrs = "") => `<div class="erp-product-field"><label for="product-${name}">${label}</label><select id="product-${name}" name="${name}" ${attrs}>${options(values, selected)}</select></div>`;
  const section = (title, body) => `<section class="erp-product-detail-section"><h3>${title}</h3>${body}</section>`;
  const table = (key, columns, rows = []) => {
    const rowMarkup = (row = {}) => `<tr data-product-row="${key}">${columns.map(([label, name, type = "text", values = null]) => `<td>${values ? `<select data-row-field="${name}" aria-label="${label}">${options(values, row[name] || values[0])}</select>` : `<input data-row-field="${name}" data-last-vendor="${name === "vendor" ? escapeHtml(row[name] || "") : ""}" aria-label="${label}" type="${type}" ${type === "number" ? 'min="0" step="0.001"' : ""} value="${escapeHtml(row[name] ?? "")}" placeholder="${escapeHtml(label)}">`}</td>`).join("")}<td class="erp-product-row-remove"><button type="button" data-product-remove-row aria-label="Remove line">×</button></td></tr>`;
    return `<div class="erp-product-table-wrap"><table class="erp-product-table"><thead><tr>${columns.map(([label]) => `<th>${escapeHtml(label)}</th>`).join("")}<th aria-label="Actions"></th></tr></thead><tbody data-product-rows="${key}">${(rows.length ? rows : [{}]).map(rowMarkup).join("")}</tbody></table><button type="button" class="erp-product-add-line" data-product-add-row="${key}">+ Add a line</button><template data-product-row-template="${key}">${rowMarkup()}</template></div>`;
  };
  const rowMarkup = (row = {}, primary = false) => {
    const quantity = Number(row.quantity || 0);
    const purchaseAmount = row.purchasePrice !== undefined && row.purchasePrice !== null && String(row.purchasePrice).trim() !== "" ? Number(row.purchasePrice) : basePurchasePrice * quantity;
    const saleAmount = row.salePrice !== undefined && row.salePrice !== null && String(row.salePrice).trim() !== "" ? Number(row.salePrice) : baseSalesPrice * quantity;
    const unitName = row.unit || purchaseUom;
    const priceSummary = quantity > 0 ? `${salesCurrency(purchaseAmount)} / ${escapeHtml(unitName)} · ${salesCurrency(purchaseAmount / quantity)} / ${escapeHtml(stockUnit)}` : "Enter a verified quantity";
    const saleSummary = quantity > 0 ? `${salesCurrency(saleAmount)} / ${escapeHtml(unitName)}` : "—";
    return `<tr data-product-row="unitConversions" data-primary-package="${primary ? "true" : "false"}"><td><input data-row-field="unit" aria-label="Package name" value="${escapeHtml(row.unit || "")}" placeholder="Carton, Bag / বস্তা, pack" ${primary ? "readonly" : ""}></td><td><input data-row-field="quantity" type="number" min="0" step="0.001" aria-label="Base units per package" value="${escapeHtml(row.quantity ?? "")}" placeholder="e.g. 30" ${primary ? "readonly" : ""}></td><td><label class="erp-product-row-check"><input data-row-field="purchaseEnabled" type="checkbox" aria-label="Use for purchase" ${row.purchaseEnabled !== false ? "checked" : ""} ${primary ? "disabled" : ""}> Purchase</label></td><td><label class="erp-product-row-check"><input data-row-field="saleEnabled" type="checkbox" aria-label="Use for sales" ${row.saleEnabled !== false ? "checked" : ""} ${primary ? "disabled" : ""}> Sales</label></td><td><input data-row-field="purchasePrice" type="number" min="0" step="0.01" aria-label="Purchase package price" value="${escapeHtml(row.purchasePrice ?? "")}" placeholder="Auto" ${primary ? "readonly" : ""}></td><td><input data-row-field="salePrice" type="number" min="0" step="0.01" aria-label="Selling price override" value="${escapeHtml(row.salePrice ?? "")}" placeholder="Auto"></td><td class="erp-product-row-preview"><span data-pack-purchase-preview>${priceSummary}</span><span data-pack-sale-preview>${saleSummary}</span></td><td class="erp-product-row-remove">${primary ? "" : `<button type="button" data-product-remove-row aria-label="Remove package">×</button>`}</td></tr>`;
  };
  const conversionTable = (rows) => `<div class="erp-product-table-wrap"><table class="erp-product-table erp-product-pack-table"><thead><tr><th>Package / Unit</th><th>Base units per package</th><th>Purchase</th><th>Sales</th><th>Purchase price</th><th>Selling price override</th><th>Calculated package and unit price</th><th aria-label="Actions"></th></tr></thead><tbody data-product-rows="unitConversions">${rows.map((row, index) => rowMarkup(row, index === 0)).join("")}</tbody></table><button type="button" class="erp-product-add-line" data-product-add-row="unitConversions">+ Add another package</button><template data-product-row-template="unitConversions">${rowMarkup()}</template></div>`;
  const imagePreview = image ? `<img src="${escapeHtml(image)}" alt="Product image">` : `<span class="erp-product-camera" aria-hidden="true"><svg viewBox="0 0 64 52"><path d="M8 12h12l4-7h16l5 7h11a5 5 0 0 1 5 5v27a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5V17a5 5 0 0 1 5-5Z"/><circle cx="32" cy="30" r="12"/><circle class="erp-product-camera-lens" cx="32" cy="30" r="7"/></svg><i>+</i></span>`;
  const tabButton = (key, title, active = false) => `<button type="button" class="${active ? "is-active" : ""}" data-product-tab="${key}" aria-selected="${active}">${title}</button>`;
  const smartQuantity = (value) => Number(value || 0).toLocaleString("en-BD", { maximumFractionDigits: 3 });
  const smartRules = state.inventoryRules.filter((rule) => rule.sku === product?.sku).length;
  const productSmartbar = window.ERPSharedSmartPanel.render({
    className: "erp-product-smartbar-shell", itemsClass: "erp-product-smartbar-scroll", ariaLabel: "Product smart buttons",
    moreClass: "erp-product-smartbar-more", moreButtonClass: "erp-product-smartbar-more-button", menuClass: "erp-product-smartbar-dropdown",
    items: [
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg>', contentHtml: "Go to<br>Website", className: "erp-product-smartbar-button", attributes: { "data-product-smart": "website" }, ariaLabel: "Go to Website" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10l-1.5 4H8.5L7 3ZM9 7v5l-3 8h12l-3-8V7M10 12h4"/></svg>', contentHtml: `Bill of Materials<br><small>${Number(product?.bomCount || 0)}</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "bom" }, ariaLabel: "Bill of Materials" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 2h10l4 4v16H5zM15 2v5h5M8 11h8M8 15h8M8 19h5"/></svg>', contentHtml: `Documents<br><small>${Number(product?.documentCount || 0)}</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "documents" }, ariaLabel: "Documents" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V12M9 20V7M14 20V4M19 20v-9M2 20h20"/></svg>', contentHtml: `<strong>${smartQuantity(outgoing)} ${escapeHtml(stockUnit)}</strong><small>${smartQuantity(outgoing)} Outgoing</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "outgoing" }, ariaLabel: "Units Outgoing" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 7h18v13H3zM3 11h18M8 3h8l2 4H6l2-4Z"/></svg>', contentHtml: `<strong>${smartQuantity(incoming)} ${escapeHtml(stockUnit)}</strong><small>${smartQuantity(incoming)} Incoming</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "incoming" }, ariaLabel: "Units Incoming" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7V3l-3 3a8 8 0 0 0-13 3M4 17v4l3-3a8 8 0 0 0 13-3"/><path d="M4 9V6M20 15v3"/></svg>', contentHtml: `ECOs<br><small>${Number(product?.ecoCount || 0)}</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "ecos" }, ariaLabel: "ECOs" },
      { iconHtml: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7V3l-3 3a8 8 0 0 0-13 3M4 17v4l3-3a8 8 0 0 0 13-3M4 9V6M20 15v3"/></svg>', contentHtml: `Reordering Rules<br><small>${smartRules}</small>`, className: "erp-product-smartbar-button", attributes: { "data-product-smart": "reordering" }, ariaLabel: "Reordering Rules" },
    ],
    moreItems: [
      { iconHtml: '<span class="erp-product-smartbar-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 7V3l-3 3a8 8 0 0 0-13 3M4 17v4l3-3a8 8 0 0 0 13-3M4 9V6M20 15v3"/></svg></span>', contentHtml: `Reordering Rules<br><b>${smartRules}</b>`, className: "erp-product-smartbar-overflow-reordering", attributes: { "data-product-smart": "reordering" } },
      { iconHtml: '<span class="erp-product-smartbar-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 7h17m0 0-3-3m3 3-3 3M21 17H4m0 0 3-3m-3 3 3 3"/></svg></span>', contentHtml: `<span class="erp-product-smartbar-inout-values"><span><span class="erp-product-smartbar-inout-label">In:</span><b>${smartQuantity(incoming)}</b></span><span><span class="erp-product-smartbar-inout-label">Out:</span><b>${smartQuantity(outgoing)}</b></span></span>`, attributes: { "data-product-smart": "incoming" } },
      { iconHtml: '<span class="erp-product-smartbar-menu-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle class="erp-product-smartbar-icon-dot" cx="5" cy="6" r="1.4"/><path d="M9 6h12"/><circle class="erp-product-smartbar-icon-dot" cx="5" cy="12" r="1.4"/><path d="M9 12h12"/><circle class="erp-product-smartbar-icon-dot" cx="5" cy="18" r="1.4"/><path d="M9 18h12"/></svg></span>', contentHtml: `Quality Points<br><b>${Number(product?.qualityPointCount || 0)}</b>`, attributes: { "data-product-smart": "quality" } },
    ],
  });
  return `<section class="erp-product-page">
    <div class="erp-product-toolbar"><div class="erp-product-header-left"><button type="button" class="action-button erp-product-new-record" data-sales-new-product>New</button><div class="erp-product-record-title"><div class="erp-product-breadcrumbs"><button class="erp-product-breadcrumb" type="button" data-sales-editor-action="discard">Products</button><strong data-product-live-title>${escapeHtml(initialVariantTitle || "New")}</strong></div><div class="erp-product-header-menu-wrap"><button type="button" class="erp-product-header-menu-button" data-product-header-menu aria-label="More" aria-expanded="false" title="More">⋮</button></div><button type="submit" form="sales-product-form" class="erp-product-cloud" title="Save product" aria-label="Save product">☁</button></div><button class="erp-product-close" type="button" data-sales-editor-action="discard" aria-label="Close">×</button></div>${productSmartbar}</div>
    <div class="erp-product-layout"><main><form id="sales-product-form" data-id="${product?.id || ""}" data-return-page="${escapeHtml(state.salesProductEditor?.returnPage || "inventory-products")}" data-image-mode="${initialImageMode}" data-image-variant="${productImageVariant}" data-product-title-size="${escapeHtml(salesProductTitleSizeText(initialNetContentValue, initialNetContentUnit))}" novalidate><article class="erp-product-card">
      <header class="erp-product-identity"><button type="button" class="erp-product-favorite ${product?.favorite ? "is-favorite" : ""}" data-product-favorite aria-label="Toggle favorite">${product?.favorite ? "★" : "☆"}</button><div class="erp-product-identity-main"><input name="name" class="erp-product-name-input" data-product-name required value="${escapeHtml(initialVariantTitle)}" placeholder="e.g. Boss Mega Mosquito Coil · 100 g" aria-label="Product Title"><small class="erp-product-name-help">Product title combines product name, variant/model and category. Package size is included automatically.</small><div class="erp-product-app-flags"><label><input type="checkbox" name="salesEnabled" ${enabledIn.sales !== false ? "checked" : ""}> Sales</label><label><input type="checkbox" name="purchaseEnabled" ${enabledIn.purchase !== false ? "checked" : ""}> Purchase</label><label><input type="checkbox" name="subscriptionsEnabled" ${enabledIn.subscriptions ? "checked" : ""}> Subscriptions</label><label><input type="checkbox" name="expensesEnabled" ${enabledIn.expenses ? "checked" : ""}> Expenses</label><label><input type="checkbox" name="posEnabled" ${enabledIn.pos ? "checked" : ""}> Point of Sale</label></div></div><div class="erp-product-image-actions"><label class="erp-product-image-box" title="Upload product image"><input type="file" accept="image/*" data-product-image><span data-product-image-preview>${imagePreview}</span><small>Product image</small></label><button type="button" class="product-image-generate" data-product-image-generate title="Generate another automatic product illustration">↻ Auto Image</button></div></header>
       <nav class="erp-product-tabs" aria-label="Product details">${tabButton("configuration", "General Information", true)}${tabButton("promotional-offer", "Promotional Offer")}${tabButton("purchase", "Purchase")}${tabButton("inventory", "Inventory")}${tabButton("unit-pricing", "Unit & Purchasing Price")}</nav>
      <section class="erp-product-panel is-active" data-product-panel="configuration">
        <section class="product-general-information">
          <div class="product-general-grid">
            <div class="product-general-column">
              <fieldset class="product-general-type"><legend>Product Type</legend><div class="product-general-type-options"><label><input type="radio" name="productType" value="goods" required ${inventoryProductTypeValue(product) === "goods" ? "checked" : ""}><span>Goods</span></label><label><input type="radio" name="productType" value="service" ${inventoryProductTypeValue(product) === "service" ? "checked" : ""}><span>Service</span></label><label><input type="radio" name="productType" value="combo" ${inventoryProductTypeValue(product) === "combo" ? "checked" : ""}><span>Combo</span></label></div></fieldset>
              <div class="erp-product-field"><label for="product-invoicePolicy">Invoicing Policy</label><select id="product-invoicePolicy" name="invoicePolicy"><option value="Ordered quantities" ${(product?.invoicePolicy || state.salesSettings.invoicePolicy || "Ordered quantities") === "Ordered quantities" ? "selected" : ""}>Ordered quantities</option><option value="Delivered quantities" ${(product?.invoicePolicy || state.salesSettings.invoicePolicy) === "Delivered quantities" ? "selected" : ""}>Delivered quantities</option></select></div>
              <div class="product-general-tracking-row"><span class="product-general-tracking-label">Track Inventory <i>?</i></span><label class="product-general-tracking-mode"><input type="checkbox" name="inventoryEnabled" ${product?.inventoryEnabled !== false ? "checked" : ""}><select id="product-tracking" name="tracking" aria-label="Inventory tracking method" ${product?.inventoryEnabled === false ? "disabled" : ""}>${[["By Quantity", "By Quantity"], ["By Lots", "By Lots"], ["By Unique Serial Number", "By Unique Serial Number"]].map(([value, label]) => `<option value="${value}" ${(product?.tracking || "By Quantity") === value ? "selected" : ""}>${label}</option>`).join("")}</select></label></div>
            </div>
            <div class="product-general-column product-general-commercial-fields">
              <div class="erp-product-field"><label for="product-general-sales-price">Sales Price <small data-general-sales-price-unit>per ${escapeHtml(stockUnit)}</small></label><div class="product-general-money"><span>৳</span><input id="product-general-sales-price" data-general-sales-price type="number" min="0" step="0.01" value="${escapeHtml(roundAccounting(Number(purchaseQuantity) > 0 && salePackagePrice !== "" ? Number(salePackagePrice) / Number(purchaseQuantity) : Number(baseSalesPrice || 0)))}"></div></div>
              <div class="erp-product-field"><label for="product-salesTaxId">Sales Taxes</label><select id="product-salesTaxId" name="salesTaxId">${invoiceTaxOptions("out_invoice", product?.salesTaxId)}</select></div>
              <div class="erp-product-field"><label for="product-avataxCategory">Avatax Category</label><input id="product-avataxCategory" name="avataxCategory" value="${escapeHtml(product?.avataxCategory || "")}" placeholder="Optional external tax category"></div>
              <div class="erp-product-field"><label>Cost <small>per ${escapeHtml(stockUnit)}</small></label><output class="product-general-readonly" data-general-cost>${basePurchasePrice !== "" ? salesCurrency(basePurchasePrice) : salesCurrency(0)}</output></div>
              <div class="erp-product-field"><label for="product-purchaseTaxId">Purchase Taxes</label><select id="product-purchaseTaxId" name="purchaseTaxId">${invoiceTaxOptions("in_invoice", product?.purchaseTaxId)}</select></div>
               <div class="erp-product-field product-category-title-field"><label for="product-category">Category</label><div class="product-category-title-control"><select id="product-category" name="category" data-product-category data-last-category="${escapeHtml(initialCategory)}"><option value="">Select a product category</option>${productCategoryOptions.map((category) => `<option value="${escapeHtml(category)}" ${category === initialCategory ? "selected" : ""}>${escapeHtml(category)}</option>`).join("")}</select><label class="product-category-title-toggle" title="Include the selected category in the product and invoice title"><input type="checkbox" name="includeCategoryInTitle" data-product-include-category ${includeCategoryInTitle ? "checked" : ""}><span>Include category in title</span></label></div></div>
              <div class="erp-product-field"><label for="product-variantLabel">Variant / Model</label><input id="product-variantLabel" name="variantLabel" data-last-variant="${escapeHtml(product?.variantLabel || "")}" value="${escapeHtml(product?.variantLabel || "")}" placeholder="e.g. Mega, Red, Green" autocomplete="off"><small>Added after the product name; category visibility follows the checkbox above.</small></div>
              <div class="erp-product-field"><label for="product-sku-display">Reference</label><input id="product-sku-display" name="sku" class="product-general-reference-output" data-product-sku-display value="${escapeHtml(initialSku)}" data-sku-generated="${initialSkuGenerated ? "true" : "false"}" autocomplete="off"></div>
              <div class="erp-product-field"><label for="product-barcode">Barcode</label><input id="product-barcode" name="barcode" value="${escapeHtml(initialBarcode)}" data-barcode-generated="${initialBarcodeGenerated ? "true" : "false"}" autocomplete="off"></div>
              <div class="erp-product-field"><label for="product-company">Company</label><input id="product-company" name="company" value="${escapeHtml(product?.company || "Arafat Chemica · Visible to all")}"></div>
            </div>
          </div>
          <section class="product-general-notes"><h3>INTERNAL NOTES</h3><textarea class="erp-product-description" name="description" placeholder="This note is only for internal purposes.">${escapeHtml(product?.description || "")}</textarea></section>
        </section>
      </section>
      <section class="erp-product-panel" data-product-panel="promotional-offer">
        <div class="erp-product-panel-title"><h2>Promotional Offer</h2><span>Set the offer type and gift for this product size.</span></div>
        <div class="product-promotion-layout">
          <section class="product-promotion-type-panel"><h3>Promotion Type</h3><fieldset class="promotional-offer-choice-group product-promotion-type-choices"><legend>Promotion Type</legend><label><input type="radio" name="promotionType" value="cp" ${initialPromotionType === "cp" ? "checked" : ""}><span><strong>CP</strong><small>Gift offer</small></span></label><label><input type="radio" name="promotionType" value="non-cp" ${initialPromotionType === "non-cp" ? "checked" : ""}><span><strong>Non-CP</strong><small>No gift offer</small></span></label></fieldset></section>
          <section class="gift-offer-configuration-card"><header><div><h3>Gift Offer Configuration</h3><p>Set a price for each offer and select its linked gift products.</p></div></header><p class="gift-offer-non-cp-message" data-promotion-noncp-help ${initialPromotionType === "cp" ? "hidden" : ""}>Non-CP offers keep their consumer price and do not include a gift.</p><div class="inventory-consumer-offers-list" data-consumer-offers-list>${consumerOfferRowsMarkup}</div><button type="button" class="action-button secondary inventory-consumer-offer-add" data-consumer-offer-add>+ Add consumer offer</button></section>
        </div>
      </section>
      <section class="erp-product-panel" data-product-panel="purchase"><div class="erp-product-panel-title"><h2>Purchase</h2><span>Supplier prices are linked to the shared supplier register.</span></div><div class="product-purchase-supplier-field"><div class="erp-product-field"><label class="product-identity-section-title" for="product-supplierName">Supplier Name <span aria-hidden="true">*</span></label><input id="product-supplierName" name="supplierName" aria-required="true" value="${escapeHtml(supplierMasterName)}" data-last-supplier="${escapeHtml(supplierMasterName)}" list="product-supplier-list" data-approved-supplier placeholder="Choose an approved supplier" autocomplete="off"><datalist id="product-supplier-list">${vendorNames.map((vendor) => `<option value="${escapeHtml(vendor)}">`).join("")}</datalist><small class="product-supplier-required-hint">Required · select an approved supplier.</small></div></div>${table("vendors", [["Supplier Name", "vendor"], ["Minimum Quantity", "quantity", "number"], ["Purchase Unit", "unit", "text", purchaseUnitOptions], ["Unit Price", "unitPrice", "number"], ["Lead Time (days)", "leadTime", "number"]], purchaseRows)}<div class="erp-product-columns">${section("VENDOR BILL CONTROL", `<div class="erp-product-radios"><label><input type="radio" name="vendorBillControl" value="ordered" ${product?.vendorBillControl === "ordered" ? "checked" : ""}> On ordered quantities</label><label><input type="radio" name="vendorBillControl" value="received" ${!product || product.vendorBillControl !== "ordered" ? "checked" : ""}> On received quantities</label></div>`)}${section("PURCHASE DESCRIPTION", `<textarea class="erp-product-description" name="purchaseDescription" placeholder="Notes shown on purchase orders">${escapeHtml(product?.purchaseDescription || "")}</textarea>`)}</div></section>
       <section class="erp-product-panel" data-product-panel="inventory"><div class="erp-product-columns"><div>${section("OPERATIONS", `<label class="erp-product-check"><input type="checkbox" name="routeDropship" ${product?.routeDropship ? "checked" : ""}> Dropship</label>${field("Responsible", "inventoryResponsible", product?.inventoryResponsible || "", 'placeholder="Responsible user"')}`)}</div>${section("LOGISTICS", `${field("Weight", "weight", product?.weight ?? 0, 'type="number" min="0" step="0.001"')}<span class="erp-product-unit-hint">kg</span>${field("Volume", "volume", product?.volume ?? 0, 'type="number" min="0" step="0.001"')}<span class="erp-product-unit-hint">m³</span>${field("Delivery Time", "deliveryTime", product?.deliveryTime ?? 0, 'type="number" min="0" step="1"')}<span class="erp-product-unit-hint">days</span>`)}</div><div class="erp-product-columns">${section("DESCRIPTION FOR RECEIPTS", `<textarea class="erp-product-description" name="receiptDescription" placeholder="Storage instructions">${escapeHtml(product?.receiptDescription || "")}</textarea>`)}${section("DESCRIPTION FOR DELIVERY", `<textarea class="erp-product-description" name="deliveryDescription" placeholder="Delivery instructions">${escapeHtml(product?.deliveryDescription || "")}</textarea>`)}</div>${section("DESCRIPTION FOR INTERNAL TRANSFERS", `<textarea class="erp-product-description" name="transferDescription" placeholder="Picking instructions">${escapeHtml(product?.transferDescription || "")}</textarea>`)}</section>
      <section class="erp-product-panel inventory-config-panel" data-product-panel="unit-pricing"><div class="erp-product-field product-configuration-selector"><label for="product-productConfigurationId">Saved Product Configuration</label><select id="product-productConfigurationId" name="productConfigurationId" data-product-configuration><option value="">Create from current setup when saved</option>${configurationOptions}</select><small>Select a saved setup to fill these fields, or edit the package details below.</small></div><div class="inventory-config-editor-grid product-config-advanced-fields">
        <section class="inventory-config-editor-section">
          <h2>SIZE &amp; PACKAGING</h2><h3>UNIT OF MEASURE</h3>
          <div class="erp-product-field"><label for="product-config-purchase-uom">Unit of Measurement</label><div class="product-category-select-actions"><select id="product-config-purchase-uom" name="configPurchaseUom" data-product-config-purchase-uom>${purchaseUnitOptions.map((unit) => `<option value="${escapeHtml(unit)}" ${unit === purchaseUom ? "selected" : ""}>${escapeHtml(unit)}</option>`).join("")}</select><button type="button" class="action-button secondary product-category-new" data-product-uom-add>+ Add Unit</button></div></div>
          <div class="erp-product-field"><label for="product-config-stock-uom">Stock Base Unit</label><select id="product-config-stock-uom" name="configStockUom" data-product-config-stock-uom>${stockUnitOptions.map((unit) => `<option value="${escapeHtml(unit)}" ${unit === stockUnit ? "selected" : ""}>${escapeHtml(unit)}</option>`).join("")}</select></div>
          <div class="erp-product-field"><label for="product-config-package-quantity"><span data-config-purchase-unit-label>${escapeHtml(purchaseUom)}</span> contains</label><div class="product-config-number-with-unit"><input id="product-config-package-quantity" name="configPurchaseUnitQuantity" data-product-config-quantity type="number" min="0.001" step="0.001" value="${escapeHtml(purchaseQuantity)}" placeholder="${isSackPurchaseUnit(purchaseUom) && normalizeProductIdentity(stockUnit) === "packet" ? "e.g. 432" : "e.g. 30"}"><span data-config-stock-unit-label>${escapeHtml(stockUnit)}</span></div></div>
          <div class="erp-product-field product-net-content-field"><label for="product-net-content-value"><span data-net-content-input-label>${isSackPurchaseUnit(purchaseUom) && normalizeProductIdentity(stockUnit) === "packet" ? "Weight per Packet" : `Net content per ${escapeHtml(stockUnit)}`}</span></label><div class="product-net-content-inputs"><input id="product-net-content-value" name="netContentValue" type="number" min="0.001" step="0.001" value="${escapeHtml(initialNetContentValue)}" placeholder="e.g. 40"><select id="product-net-content-unit" name="netContentUnit" aria-label="Net content unit">${["g", "kg", "ml", "L"].map((unit) => `<option value="${unit}" ${unit === initialNetContentUnit ? "selected" : ""}>${unit}</option>`).join("")}</select></div></div>
          <p class="inventory-config-hint" data-package-conversion-help>${isSackPurchaseUnit(purchaseUom) && normalizeProductIdentity(stockUnit) === "packet" ? `Enter how many packets are in 1 ${escapeHtml(purchaseUom)}, then enter the weight of each packet. Total net content is calculated automatically.` : `Enter the net content per ${escapeHtml(stockUnit)}. The quantity below is how many ${escapeHtml(stockUnit)} units are in one ${escapeHtml(purchaseUom)}.`}</p>
          <div class="product-net-content-total" data-net-content-total>${salesProductNetContentTotal(initialNetContentValue, initialNetContentUnit, purchaseQuantity, purchaseUom, stockUnit)}</div>
          <p class="inventory-config-hint">Inventory is stored in the base unit. The same package conversion is available from Product Configuration.</p>
        </section>
        <section class="inventory-config-editor-section">
          <h2 class="product-pricing-title">PRICING <span data-pricing-context>${escapeHtml(salesProductPricingContext(purchaseUom, purchaseQuantity, stockUnit, initialNetContentValue, initialNetContentUnit))}</span></h2>
          <div class="inventory-config-pricing-group"><h3>PURCHASE</h3><div class="inventory-config-pricing-fields">
            <div class="erp-product-field"><label class="product-pricing-line-label" for="product-config-purchase-price">Purchase price per <span data-config-purchase-unit-label>${escapeHtml(purchaseUom)}</span><small data-package-price-context>${Number(purchaseQuantity).toLocaleString("en-BD", { maximumFractionDigits: 3 })} ${escapeHtml(stockUnit)} per ${escapeHtml(purchaseUom)}</small></label><div class="inventory-config-money-field"><span>৳</span><input id="product-config-purchase-price" name="configPurchaseUnitPrice" data-product-config-purchase-price type="number" min="0" step="0.01" value="${escapeHtml(purchaseUnitPrice)}"></div></div>
            <div class="erp-product-field"><label class="product-pricing-line-label">Calculated cost per <span data-config-stock-unit-label>${escapeHtml(stockUnit)}</span><small data-net-content-context>${initialNetContentValue !== "" ? `${escapeHtml(initialNetContentValue)} ${escapeHtml(initialNetContentUnit)} per ${escapeHtml(stockUnit)}` : `Set net content per ${escapeHtml(stockUnit)}`}</small></label><div class="inventory-config-calculated-field"><strong data-config-calculated-cost>${purchaseUnitPrice !== "" && Number(purchaseQuantity) > 0 ? salesCurrency(Number(purchaseUnitPrice) / Number(purchaseQuantity)) : "—"}</strong></div></div>
          </div></div>
          <div class="inventory-config-pricing-group inventory-config-sales-pricing"><h3>SALES</h3><div class="inventory-config-pricing-fields">
            <div class="erp-product-field"><label class="product-pricing-line-label" for="product-config-sales-package-price">Selling price per <span data-config-purchase-unit-label>${escapeHtml(purchaseUom)}</span><small data-package-price-context>${Number(purchaseQuantity).toLocaleString("en-BD", { maximumFractionDigits: 3 })} ${escapeHtml(stockUnit)} per ${escapeHtml(purchaseUom)}</small></label><div class="inventory-config-money-field"><span>৳</span><input id="product-config-sales-package-price" name="configMainSalePrice" data-product-config-package-sale-price type="number" min="0" step="0.01" value="${escapeHtml(salePackagePrice)}"></div></div>
            <div class="erp-product-field"><label class="product-pricing-line-label">Calculated selling price per <span data-config-stock-unit-label>${escapeHtml(stockUnit)}</span><small data-net-content-context>${initialNetContentValue !== "" ? `${escapeHtml(initialNetContentValue)} ${escapeHtml(initialNetContentUnit)} per ${escapeHtml(stockUnit)}` : `Set net content per ${escapeHtml(stockUnit)}`}</small></label><div class="inventory-config-calculated-field"><strong data-config-calculated-sales>${salePackagePrice !== "" && Number(purchaseQuantity) > 0 ? salesCurrency(Number(salePackagePrice) / Number(purchaseQuantity)) : "—"}</strong></div><input type="hidden" name="configPrice" data-product-config-base-sale-price value="${escapeHtml(baseSalesPrice)}"></div>
          </div></div><p class="inventory-config-tax-note">Taxes are not used for this product setup.</p>
          <section class="product-config-conversions inventory-config-conversions"><header><div><h2>PACKAGING &amp; UNIT CONVERSIONS</h2><p>Extra package sizes are saved to the same shared Product Configuration.</p></div><button type="button" class="action-button secondary" data-product-config-add-row>+ Add a unit</button></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Package / Unit</th><th>Base units per package</th><th>Purchase price override</th><th>Selling price override</th><th>Purchase</th><th>Sales</th><th></th></tr></thead><tbody data-product-config-rows>${productConfigRows}</tbody></table></div><template data-product-config-row-template>${productConfigRowMarkup()}</template></section>
        </section>
      </div>
      <input type="hidden" name="onHand" value="${onHand}"><input type="hidden" name="image" value="${escapeHtml(image)}">
      <footer class="erp-product-footer"><span class="erp-product-footer-status"><span>Product name and verified units are shared with Purchase, Sales and printed invoices.</span><small data-product-save-status role="status" aria-live="polite" hidden></small></span><div><button type="button" class="action-button secondary" data-sales-editor-action="discard">Discard</button><button type="submit" class="action-button" data-product-footer-save>Save Product</button></div></footer>
    </article></form></main><aside class="erp-product-chatter" aria-label="Product activity"><div class="erp-product-chatter-actions"><button type="button" class="action-button erp-product-chatter-send">Send message</button><button type="button" class="action-button secondary">Log note</button><button type="button" class="action-button secondary">Activity</button></div><div class="erp-product-chatter-timeline"><span>Today</span></div><div class="erp-product-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${product ? "Product record opened." : "Creating a new record..."}</p></div></div></aside></div>
  </section>`;
}

function syncProductPurchaseSummary(form, { unitChanged = false, stockChanged = false } = {}) {
  if (!form) return;
  const unitSelect = form.querySelector("[data-product-purchase-uom]");
  const stockSelect = form.querySelector("[data-product-stock-uom]");
  const quantityInput = form.querySelector("[data-product-purchase-quantity]");
  const packagePriceInput = form.querySelector("[data-product-purchase-price]");
  const basePriceInput = form.querySelector("[data-base-purchase-price]");
  const salePackagePriceInput = form.querySelector("[data-sale-package-price]");
  const tbody = form.querySelector('[data-product-rows="unitConversions"]');
  if (!unitSelect || !stockSelect || !quantityInput || !packagePriceInput || !basePriceInput || !salePackagePriceInput || !tbody) return;
  const unit = unitSelect.value || stockSelect.value;
  const stockUnit = stockSelect.value || "Piece";
  let rows = [...tbody.querySelectorAll("tr[data-product-row]")];
  let primary = rows.find((row) => row.dataset.primaryPackage === "true") || rows[0];
  if (unitChanged) {
    const matching = rows.find((row) => String(row.querySelector('[data-row-field="unit"]')?.value || "").toLowerCase() === unit.toLowerCase());
    if (matching) {
      if (primary && primary !== matching) primary.dataset.primaryPackage = "false";
      primary = matching;
      primary.dataset.primaryPackage = "true";
      if (primary !== tbody.firstElementChild) tbody.prepend(primary);
      const savedQuantity = primary.querySelector('[data-row-field="quantity"]')?.value || defaultProductPurchaseQuantity(unit, stockUnit);
      quantityInput.value = savedQuantity;
      const savedPrice = primary.querySelector('[data-row-field="purchasePrice"]')?.value;
      packagePriceInput.value = savedPrice !== undefined && savedPrice !== "" ? savedPrice : (Number(savedQuantity) > 0 ? (Number(basePriceInput.value || 0) * Number(savedQuantity)).toFixed(2) : "");
    } else {
      if (primary) primary.dataset.primaryPackage = "false";
      const template = form.querySelector('template[data-product-row-template="unitConversions"]');
      const next = template?.content.firstElementChild?.cloneNode(true);
      if (next) {
        next.dataset.primaryPackage = "true";
        tbody.prepend(next);
        primary = next;
        const unitField = primary.querySelector('[data-row-field="unit"]');
        if (unitField) unitField.value = unit;
      } else {
        primary = rows[0];
        if (primary) primary.dataset.primaryPackage = "true";
      }
      const defaultQuantity = defaultProductPurchaseQuantity(unit, stockUnit);
      quantityInput.value = defaultQuantity;
      packagePriceInput.value = Number(defaultQuantity) > 0 ? (Number(basePriceInput.value || 0) * Number(defaultQuantity)).toFixed(2) : "";
    }
    unitSelect.dataset.currentUnit = unit;
    rows = [...tbody.querySelectorAll("tr[data-product-row]")];
  }
  if (stockChanged) {
    const defaultQuantity = defaultProductPurchaseQuantity(unit, stockUnit);
    quantityInput.value = defaultQuantity;
    packagePriceInput.value = Number(defaultQuantity) > 0 ? (Number(basePriceInput.value || 0) * Number(defaultQuantity)).toFixed(2) : "";
  }
  if (!primary) return;
  rows.forEach((row) => {
    const isPrimary = row === primary;
    row.dataset.primaryPackage = isPrimary ? "true" : "false";
    const unitField = row.querySelector('[data-row-field="unit"]');
    const quantityField = row.querySelector('[data-row-field="quantity"]');
    const purchaseToggle = row.querySelector('[data-row-field="purchaseEnabled"]');
    const salesToggle = row.querySelector('[data-row-field="saleEnabled"]');
    const priceField = row.querySelector('[data-row-field="purchasePrice"]');
    if (isPrimary) {
      if (unitField) { unitField.value = unit; unitField.readOnly = true; }
      if (quantityField) { quantityField.value = quantityInput.value; quantityField.readOnly = true; }
      if (purchaseToggle) { purchaseToggle.checked = true; purchaseToggle.disabled = true; }
      if (salesToggle) { salesToggle.checked = true; salesToggle.disabled = true; }
      if (priceField) { priceField.value = packagePriceInput.value; priceField.readOnly = true; }
    } else {
      [unitField, quantityField, priceField].forEach((field) => { if (field) field.readOnly = false; });
      [purchaseToggle, salesToggle].forEach((field) => { if (field) field.disabled = false; });
    }
  });
  const ratio = Number(quantityInput.value);
  const packagePrice = Number(packagePriceInput.value);
  const computedBasePrice = Number.isFinite(ratio) && ratio > 0 && Number.isFinite(packagePrice) ? packagePrice / ratio : null;
  basePriceInput.value = computedBasePrice === null ? "" : computedBasePrice.toFixed(2);
  const saleBasePrice = Number(form.querySelector("[data-base-sale-price]")?.value || 0);
  const saleOverride = primary?.querySelector('[data-row-field="salePrice"]')?.value;
  const computedSalePackagePrice = String(saleOverride ?? "").trim() !== "" ? Number(saleOverride) : saleBasePrice * ratio;
  salePackagePriceInput.value = Number.isFinite(computedSalePackagePrice) && ratio > 0 ? computedSalePackagePrice.toFixed(2) : "";
  form.querySelectorAll("[data-purchase-unit-label]").forEach((label) => { label.textContent = unit; });
  form.querySelectorAll("[data-stock-unit-label]").forEach((label) => { label.textContent = stockUnit; });
  rows.forEach((row) => {
    const isPrimary = row === primary;
    const rowUnit = String(row.querySelector('[data-row-field="unit"]')?.value || "").trim();
    const rowQuantity = Number(row.querySelector('[data-row-field="quantity"]')?.value || 0);
    const rowPurchaseRaw = isPrimary ? packagePriceInput.value : row.querySelector('[data-row-field="purchasePrice"]')?.value;
    const rowPurchase = rowPurchaseRaw !== undefined && String(rowPurchaseRaw).trim() !== "" ? Number(rowPurchaseRaw) : Number(basePriceInput.value || 0) * rowQuantity;
    const rowSaleRaw = row.querySelector('[data-row-field="salePrice"]')?.value;
    const rowSale = rowSaleRaw !== undefined && String(rowSaleRaw).trim() !== "" ? Number(rowSaleRaw) : Number(form.querySelector("[data-base-sale-price]")?.value || 0) * rowQuantity;
    const purchasePreview = row.querySelector("[data-pack-purchase-preview]");
    const salePreview = row.querySelector("[data-pack-sale-preview]");
    if (purchasePreview) purchasePreview.textContent = rowQuantity > 0 ? `${salesCurrency(rowPurchase)} / ${rowUnit} · ${salesCurrency(rowPurchase / rowQuantity)} / ${stockUnit}` : "Enter a verified quantity";
    if (salePreview) salePreview.textContent = rowQuantity > 0 ? `${salesCurrency(rowSale)} / ${rowUnit}` : "—";
  });
}

function openSalesConfigModal() {
  const labels = { "sales-teams": "Sales Team", "sales-payments": "Payment Method", "sales-templates": "Quotation Template" };
  const label = labels[state.page] || "Sales Configuration";
  openModal(`<header class="modal-header"><div><h2>${escapeHtml(label)}</h2><p>Sales configuration</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form id="sales-config-form" data-config-page="${state.page}"><div class="modal-body"><div class="form-grid"><div class="field wide"><label>${escapeHtml(label)} Name</label><input name="name" required placeholder="${escapeHtml(label)}"></div>${state.page === "sales-teams" ? `<div class="field wide"><label>Territory / depot</label><input name="territory" placeholder="Area or depot"></div>` : ""}</div></div><footer class="modal-footer"><button class="action-button secondary" type="button" data-action="close-modal">Discard</button><button class="action-button" type="submit">Save</button></footer></form>`, true);
}

function defaultInvoiceTax(kind) {
  const scope = kind.startsWith("in_") ? "purchase" : "sales";
  const id = state.invoiceConfig[scope === "sales" ? "defaultSalesTaxId" : "defaultPurchaseTaxId"];
  return (state.invoiceConfig.taxes || []).find((tax) => tax.id === Number(id) && tax.active);
}

function invoiceTaxOptions(kind, selectedId = null) {
  const scope = kind.startsWith("in_") ? "purchase" : "sales";
  const taxes = (state.invoiceConfig.taxes || []).filter((tax) => tax.scope === scope && tax.active);
  const defaultTax = defaultInvoiceTax(kind);
  const active = selectedId ?? defaultTax?.id ?? "";
  return `<option value="" ${active ? "" : "selected"}>No tax mapped · 0%</option>${taxes.map((tax) => `<option value="${tax.id}" ${Number(active) === tax.id ? "selected" : ""}>${escapeHtml(tax.name)} · ${Number(tax.rate).toFixed(3)}%</option>`).join("")}`;
}

function defaultCreditNoteAccountCode(type = "income") {
  const salesJournalCode = accountingUsableJournals().find((journal) => journal.type === "sales")?.accountCode;
  const candidates = state.accountingAccounts.filter((account) => account.active !== false);
  return candidates.find((account) => salesJournalCode && String(account.code) === String(salesJournalCode))?.code
    || candidates.find((account) => String(account.type || "").toLowerCase() === type)?.code
    || "";
}

function defaultCreditNoteReceivableCode() {
  const accounts = state.accountingAccounts.filter((account) => account.active !== false);
  return accounts.find((account) => /accounts receivable/i.test(String(account.name || "")))?.code
    || "";
}

function defaultCreditNoteTaxAccountCode() {
  const accounts = state.accountingAccounts.filter((account) => account.active !== false);
  return accounts.find((account) => /output\s*vat|vat\s*payable|sales tax payable/i.test(String(account.name || "")))?.code || "";
}

function creditNoteAccountLabel(code) {
  return code ? `${code} ${accountingAccountName(code)}` : "Select an account";
}

function calculateInvoiceLineAmounts(qty, unitPrice, tax) {
  const enteredAmount = Math.max(0, Number(qty || 0) * Number(unitPrice || 0));
  const rate = Number(tax?.rate || 0);
  if (rate > 0 && tax?.priceInclude) {
    const taxAmount = enteredAmount - (enteredAmount / (1 + rate / 100));
    return { subtotal: enteredAmount - taxAmount, taxAmount };
  }
  return { subtotal: enteredAmount, taxAmount: enteredAmount * rate / 100 };
}

function invoiceLineMarkup(line = {}, kind = "out_invoice") {
  if (kind === "out_refund") return creditNoteInvoiceLineMarkup(line);
  const flow = kind.startsWith("in_") ? "purchase" : "sales";
  const selectedProduct = salesProducts.find((product) => product.sku === line.sku || product.name === line.product) || selectableProductRecords(null, flow)[0] || salesProducts[0];
  const selectableProducts = selectableProductRecords(selectedProduct, flow);
  const selectedUom = line.uom || selectedProduct.stockUom;
  const units = kind.startsWith("in_") ? [...new Set([...purchaseUnits(selectedProduct), selectedUom])] : [...new Set([...(selectedProduct.saleUnits || [selectedProduct.stockUom]), selectedUom])];
  const allowsFraction = kind.startsWith("in_") ? purchaseUnitAllowsFraction(selectedUom, selectedProduct) : salesUnitAllowsFraction(selectedProduct, selectedUom);
  const stockFactor = purchaseUnitFactor(selectedProduct, selectedUom) || 1;
  const unitPrice = line.price ?? (kind.startsWith("in_") ? Number(selectedProduct.purchasePrice ?? selectedProduct.cost ?? 0) * stockFactor : productSalesUnitPrice(selectedProduct, selectedUom));
  const category = categories.find((item) => String(item.name || "").toLowerCase() === String(selectedProduct.category || "").toLowerCase());
  const accountCode = line.accountCode || (kind.startsWith("in_") ? category?.expenseAccount || "5000" : category?.incomeAccount || accountingUsableJournals().find((item) => item.type === "sales")?.accountCode || "4000");
  const productCell = `<td><select data-invoice-product aria-label="Invoice product">${selectableProducts.map((product) => `<option value="${product.id}" ${product.id === selectedProduct.id ? "selected" : ""}>${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</option>`).join("")}</select><small class="invoice-line-note">${escapeHtml(line.description || selectedProduct.packNote || "")}</small>${line.consumerOfferName ? `<small class="invoice-preview-offer">Consumer offer · ${escapeHtml(line.consumerOfferName)}</small>` : ""}${line.promotionGift ? `<small class="invoice-preview-gift">Promotional gift · ${escapeHtml(line.promotionGift)}</small>` : ""}</td>`;
  const accountCell = `<td><span class="invoice-account-reference">${escapeHtml(accountCode)} ${escapeHtml(accountingAccountName(accountCode))}</span></td>`;
  const analyticCell = `<td><input data-invoice-analytic value="${escapeHtml(line.analytic || "")}" placeholder="Analytic Distribution" aria-label="Analytic Distribution"></td>`;
  const quantityCell = `<td><input data-invoice-qty type="number" min="${allowsFraction ? "0.001" : "1"}" step="${allowsFraction ? "0.001" : "1"}" value="${escapeHtml(line.qty ?? 1)}" aria-label="Invoice quantity"></td>`;
  const unitCell = `<td><select data-invoice-uom data-current-unit="${escapeHtml(selectedUom)}" aria-label="Unit of measure">${units.map((unit) => { const factor = purchaseUnitFactor(selectedProduct, unit); return `<option value="${escapeHtml(unit)}" ${unit === selectedUom ? "selected" : ""} ${factor ? "" : "disabled"}>${escapeHtml(unit)}</option>`; }).join("")}</select>${kind.startsWith("in_") ? "" : `<small class="invoice-line-conversion" data-invoice-conversion-preview>${escapeHtml(productUnitConversionPreview(selectedProduct, Number(line.qty ?? 1), selectedUom))}</small>`}</td>`;
  const priceCell = `<td><input data-invoice-price type="number" min="0" step="any" value="${escapeHtml(unitPrice)}" aria-label="Unit price in BDT"></td>`;
  const taxCell = `<td><select data-invoice-tax aria-label="Tax">${invoiceTaxOptions(kind, line.taxId)}</select></td>`;
  const removeCell = `<td><button type="button" class="soft-icon-button" data-action="remove-invoice-line" aria-label="Remove line">×</button></td>`;
  return `<tr class="invoice-line" data-consumer-offer-id="${escapeHtml(line.consumerOfferId || "")}" data-consumer-offer-name="${escapeHtml(line.consumerOfferName || "")}" data-promotion-gift="${escapeHtml(line.promotionGift || "")}">${productCell}${accountCell}${analyticCell}${quantityCell}${unitCell}${priceCell}${taxCell}<td class="invoice-line-subtotal">${salesCurrency(line.subtotal || 0)}</td>${removeCell}</tr>`;
}
function creditNoteInvoiceLineMarkup(line = {}, index = 0) {
  const product = salesProducts.find((item) => item.sku === line.sku || item.name === line.product) || null;
  const productOptions = selectableProductRecords(product, "sales");
  const units = product ? [...new Set([...(product.saleUnits || [product.stockUom]), line.uom].filter(Boolean))] : [line.uom || "Units"];
  const unit = line.uom || product?.stockUom || "Units";
  const salesAccountCode = line.accountCode || defaultCreditNoteAccountCode();
  const tax = line.taxId || defaultInvoiceTax("out_refund")?.id || "";
  return `<tr class="invoice-line credit-note-invoice-line" data-credit-row-index="${index}"><td><select data-invoice-product aria-label="Product"><option value="">Select a product or enter an account line</option>${productOptions.map((item) => `<option value="${item.id}" ${product?.id === item.id ? "selected" : ""}>${escapeHtml(item.name)} · ${escapeHtml(item.sku)}</option>`).join("")}</select><small class="invoice-line-note">${escapeHtml(line.description || product?.packNote || "")}</small></td><td><button type="button" class="credit-note-account-link" data-credit-account-picker="line" data-line-index="${index}" aria-label="Select account">${escapeHtml(creditNoteAccountLabel(salesAccountCode))}</button><input type="hidden" data-credit-account-code value="${escapeHtml(salesAccountCode)}"></td><td><input data-credit-analytic value="${escapeHtml(line.analytic || "")}" placeholder="Analytic distribution" aria-label="Analytic distribution"></td><td><input data-invoice-qty type="number" min="0.001" step="any" value="${escapeHtml(line.qty ?? 1)}" aria-label="Quantity"></td><td><select data-invoice-uom data-current-unit="${escapeHtml(unit)}" aria-label="Unit of measure">${units.map((value) => `<option value="${escapeHtml(value)}" ${unit === value ? "selected" : ""}>${escapeHtml(value)}</option>`).join("")}</select></td><td><input data-invoice-price type="number" min="0" step="any" value="${escapeHtml(line.price ?? 0)}" aria-label="Unit price in BDT"></td><td><select data-invoice-tax aria-label="Tax">${invoiceTaxOptions("out_refund", tax)}</select></td><td class="invoice-line-subtotal">${salesCurrency(line.subtotal || 0)}</td><td><button type="button" class="soft-icon-button credit-note-remove-line" data-action="remove-invoice-line" aria-label="Remove line"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9 7V4.5h6V7m-8.5 0 1 13h9l1-13M10 10.5v6m4-6v6"/></svg></button></td></tr>`;
}

function creditNoteSpecialLineMarkup(type, index) {
  const label = type === "section" ? "Section title" : "Add a note";
  return `<tr class="invoice-special-line ${type === "section" ? "invoice-section-line" : "invoice-note-line"}" data-credit-special-type="${type}" data-credit-row-index="${index}"><td colspan="9"><input data-credit-special-description aria-label="${label}" placeholder="${label}"><button type="button" class="soft-icon-button credit-note-remove-line" data-action="remove-invoice-line" aria-label="Remove line"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9 7V4.5h6V7m-8.5 0 1 13h9l1-13M10 10.5v6m4-6v6"/></svg></button></td></tr>`;
}

function readInvoiceEditorLines(form) {
  const kind = form?.dataset.kind || "out_invoice";
  return [...(form?.querySelectorAll("#invoice-line-items tr") || [])].map((line) => {
    const specialType = line.dataset.creditSpecialType;
    if (specialType) return { type: specialType, description: String(line.querySelector("[data-credit-special-description]")?.value || "").trim() };
    const product = salesProducts.find((item) => item.id === Number(line.querySelector("[data-invoice-product]")?.value));
    const qty = Number(line.querySelector("[data-invoice-qty]")?.value || 0);
    const price = Number(line.querySelector("[data-invoice-price]")?.value || 0);
    const uom = line.querySelector("[data-invoice-uom]")?.value || "";
    const taxId = Number(line.querySelector("[data-invoice-tax]")?.value || 0);
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId);
    const amounts = calculateInvoiceLineAmounts(qty, price, tax);
    const taxRate = Number(tax?.rate || 0);
    const stockFactor = product ? (kind.startsWith("in_") ? purchaseUnitFactor(product, uom) : (product.unitFactors?.[uom] ?? (uom === product.stockUom ? 1 : null))) : (kind === "out_refund" ? 1 : null);
    if (kind === "out_refund") {
      const accountCode = String(line.querySelector("[data-credit-account-code]")?.value || "").trim();
      if (!product && !accountCode) return null;
      return { type: "product", ...(product ? { product: product.name, sku: product.sku } : {}), description: String(line.querySelector(".invoice-line-note")?.textContent || product?.name || "Credit note line").trim(), uom, qty, price, accountCode, analytic: String(line.querySelector("[data-credit-analytic]")?.value || "").trim(), stockFactor, taxId: tax?.id || null, taxRate, subtotal: amounts.subtotal, taxAmount: amounts.taxAmount };
    }
    return product ? { type: "product", product: product.name, sku: product.sku, description: product.name, accountCode: String(line.querySelector(".invoice-account-reference")?.textContent || "").trim().split(" ")[0], analytic: String(line.querySelector("[data-invoice-analytic]")?.value || "").trim(), uom, qty, price, consumerOfferId: line.dataset.consumerOfferId || "", consumerOfferName: line.dataset.consumerOfferName || "", promotionGift: line.dataset.promotionGift || "", stockFactor, taxId: tax?.id || null, taxRate, subtotal: amounts.subtotal, taxAmount: amounts.taxAmount } : null;
  }).filter(Boolean);
}

function readCreditNoteJournalItems(form) {
  return [...(form?.querySelectorAll("[data-credit-journal-row]") || [])].map((row) => ({
    accountCode: String(row.querySelector("[data-credit-journal-account]")?.value || "").trim(),
    label: String(row.querySelector("[data-credit-journal-label]")?.value || "").trim(),
    analytic: String(row.querySelector("[data-credit-journal-analytic]")?.value || "").trim(),
    debit: roundAccounting(row.querySelector("[data-credit-journal-debit]")?.value || 0),
    credit: roundAccounting(row.querySelector("[data-credit-journal-credit]")?.value || 0),
    taxGrids: String(row.querySelector("[data-credit-journal-tax-grid]")?.value || "").trim(),
  })).filter((line) => line.accountCode);
}

function creditNoteJournalRowsMarkup(lines, taxAmount, total, partner = "", ref = "Draft") {
  const productLines = (lines || []).filter((line) => line && line.type !== "section" && line.type !== "note");
  const grouped = new Map();
  productLines.forEach((line) => {
    const code = String(line.accountCode || defaultCreditNoteAccountCode());
    const item = grouped.get(code) || { accountCode: code, label: line.description || line.product || ref, analytic: line.analytic || "", debit: 0, credit: 0, taxGrids: "" };
    item.debit += Number(line.subtotal || 0);
    if (!item.analytic && line.analytic) item.analytic = line.analytic;
    grouped.set(code, item);
  });
  if (!grouped.size) {
    const code = String(defaultCreditNoteAccountCode());
    grouped.set(code, { accountCode: code, label: ref, analytic: "", debit: Math.max(0, Number(total || 0) - Number(taxAmount || 0)), credit: 0, taxGrids: "" });
  }
  const rows = [...grouped.values()];
  if (Number(taxAmount || 0)) rows.push({ accountCode: defaultCreditNoteTaxAccountCode(), label: `Output VAT reversal · ${ref}`, analytic: "", debit: Number(taxAmount), credit: 0, taxGrids: "Sales VAT" });
  const receivableCode = defaultCreditNoteReceivableCode();
  rows.push({ accountCode: receivableCode, label: ref, analytic: "", debit: 0, credit: Number(total || 0), taxGrids: "" });
  return rows.map((line, index) => `<tr data-credit-journal-row data-journal-index="${index}"><td><button type="button" class="credit-note-account-link" data-credit-account-picker="journal" data-line-index="${index}">${escapeHtml(creditNoteAccountLabel(line.accountCode))}</button><input type="hidden" data-credit-journal-account value="${escapeHtml(line.accountCode || "")}"></td><td><input data-credit-journal-label value="${escapeHtml(line.label || "")}" aria-label="Label"></td><td><input data-credit-journal-analytic value="${escapeHtml(line.analytic || "")}" aria-label="Analytic Distribution"></td><td><input data-credit-journal-debit type="number" min="0" step="0.01" value="${Number(line.debit || 0).toFixed(2)}" aria-label="Debit"></td><td><input data-credit-journal-credit type="number" min="0" step="0.01" value="${Number(line.credit || 0).toFixed(2)}" aria-label="Credit"></td><td><input data-credit-journal-tax-grid value="${escapeHtml(line.taxGrids || "")}" aria-label="Tax Grids"></td><td><button type="button" class="soft-icon-button credit-note-remove-line" data-action="remove-credit-journal-line" aria-label="Remove journal line"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9 7V4.5h6V7m-8.5 0 1 13h9l1-13M10 10.5v6m4-6v6"/></svg></button></td></tr>`).join("");
}

function creditNoteBlankJournalRowMarkup(index) {
  const accountCode = defaultCreditNoteAccountCode();
  return `<tr data-credit-journal-row data-journal-index="${index}"><td><button type="button" class="credit-note-account-link" data-credit-account-picker="journal" data-line-index="${index}">${escapeHtml(creditNoteAccountLabel(accountCode))}</button><input type="hidden" data-credit-journal-account value="${escapeHtml(accountCode)}"></td><td><input data-credit-journal-label aria-label="Label"></td><td><input data-credit-journal-analytic aria-label="Analytic Distribution"></td><td><input data-credit-journal-debit type="number" min="0" step="0.01" value="0.00" aria-label="Debit"></td><td><input data-credit-journal-credit type="number" min="0" step="0.01" value="0.00" aria-label="Credit"></td><td><input data-credit-journal-tax-grid aria-label="Tax Grids"></td><td><button type="button" class="soft-icon-button credit-note-remove-line" data-action="remove-credit-journal-line" aria-label="Remove journal line"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9 7V4.5h6V7m-8.5 0 1 13h9l1-13M10 10.5v6m4-6v6"/></svg></button></td></tr>`;
}

function openCreditNoteAccountPicker(context, index) {
  const accounts = state.accountingAccounts.filter((account) => account.active !== false).sort((a, b) => String(a.code).localeCompare(String(b.code), undefined, { numeric: true }));
  const options = accounts.map((account) => `<button type="button" class="credit-account-option" data-credit-account-select data-code="${escapeHtml(account.code)}" data-name="${escapeHtml(account.name)}"><span>${escapeHtml(account.code)}</span><strong>${escapeHtml(account.name)}</strong></button>`).join("");
  openModal(`<header class="modal-header"><div><h2>Search: Account</h2><p>Choose an account for this credit note line.</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body credit-account-picker"><label class="credit-account-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input type="search" data-credit-account-search placeholder="Search accounts…" autocomplete="off"></label><div class="credit-account-options" data-credit-account-options>${options || `<p class="empty-state">No active accounts found.</p>`}</div></div><footer class="modal-footer"><button type="button" class="action-button" data-credit-account-create>Create New</button><button type="button" class="action-button secondary" data-action="close-modal">Close</button></footer>`, false);
  const card = modalRoot.querySelector(".modal-card");
  card?.classList.add("credit-account-picker-modal");
  card.dataset.creditAccountContext = context;
  card.dataset.creditAccountIndex = String(index);
}

function openCreditNoteAccountCreate(context = "line", index = 0) {
  const codeOptions = [...new Set(state.accountingAccounts.map((account) => account.type))];
  const defaultType = context === "line" ? "income" : "asset";
  openModal(`<header class="modal-header"><div><h2>Create Account</h2><p>New account · Accounting</p></div><button class="modal-close" type="button" data-action="close-modal" aria-label="Close">×</button></header><form id="credit-note-account-create-form" data-context="${escapeHtml(context)}" data-line-index="${Number(index) || 0}"><div class="modal-body"><div class="credit-account-create-tabs"><button type="button" class="is-active">Accounting</button><button type="button" disabled>Consolidation</button></div><div class="credit-account-form-grid"><div class="field"><label>Code</label><input name="code" required maxlength="12" inputmode="numeric"></div><div class="field"><label>Account Name</label><input name="name" required maxlength="100"></div><div class="field"><label>Type</label><select name="type">${[...new Set(["asset", "liability", "equity", "income", "expense", ...codeOptions])].map((type) => `<option value="${escapeHtml(type)}" ${type === defaultType ? "selected" : ""}>${escapeHtml(type[0].toUpperCase() + type.slice(1))}</option>`).join("")}</select></div><div class="field"><label>Default Taxes</label><select name="defaultTax"><option value="">None</option>${(state.invoiceConfig.taxes || []).filter((tax) => tax.active).map((tax) => `<option value="${tax.id}">${escapeHtml(tax.name)}</option>`).join("")}</select></div><div class="field"><label>Tags</label><input name="tags" placeholder="Comma-separated tags"></div><div class="field"><label>Currency</label><select name="currency"><option value="">Any currency</option><option value="BDT">BDT</option><option value="USD">USD</option></select></div><label class="credit-account-checkbox"><input type="checkbox" name="reconcile"> Allow reconciliation</label><label class="credit-account-checkbox"><input type="checkbox" name="active" checked> Active</label><div class="field"><label>Parent Account</label><select name="parentCode"><option value="">None</option>${state.accountingAccounts.map((account) => `<option value="${escapeHtml(account.code)}">${escapeHtml(account.code)} ${escapeHtml(account.name)}</option>`).join("")}</select></div><div class="field"><label>Company</label><input value="${escapeHtml(state.settings.companyName || "Arafat Chemica")}" disabled></div><div class="field credit-account-wide"><label>Description</label><textarea name="description" rows="3"></textarea></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save</button></footer></form>`, false);
  modalRoot.querySelector(".modal-card")?.classList.add("credit-account-create-modal");
}

function updateInvoiceTotal() {
  let subtotal = 0;
  let taxTotal = 0;
  const form = document.querySelector("#invoice-form");
  const journalLines = [];
  form?.querySelectorAll("#invoice-line-items .invoice-line").forEach((line) => {
    const qty = Number(line.querySelector("[data-invoice-qty]")?.value || 0);
    const product = salesProducts.find((item) => item.id === Number(line.querySelector("[data-invoice-product]")?.value));
    const unit = line.querySelector("[data-invoice-uom]")?.value;
    const conversionPreview = line.querySelector("[data-invoice-conversion-preview]");
    if (conversionPreview) conversionPreview.textContent = productUnitConversionPreview(product, qty, unit);
    const price = Number(line.querySelector("[data-invoice-price]")?.value || 0);
    const taxId = Number(line.querySelector("[data-invoice-tax]")?.value || 0);
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId);
    const amounts = calculateInvoiceLineAmounts(qty, price, tax);
    subtotal += amounts.subtotal;
    taxTotal += amounts.taxAmount;
    const cell = line.querySelector(".invoice-line-subtotal");
    if (cell) cell.textContent = salesCurrency(amounts.subtotal);
    if (form.dataset.kind === "out_refund") journalLines.push({
      product: salesProducts.find((item) => item.id === Number(line.querySelector("[data-invoice-product]")?.value))?.name || "",
      description: line.querySelector(".invoice-line-note")?.textContent || "",
      accountCode: line.querySelector("[data-credit-account-code]")?.value || defaultCreditNoteAccountCode(),
      analytic: line.querySelector("[data-credit-analytic]")?.value || "",
      subtotal: amounts.subtotal,
    });
    else journalLines.push({
      accountCode: line.querySelector(".invoice-account-reference")?.textContent.trim().split(" ")[0] || "",
      subtotal: amounts.subtotal,
    });
  });
  const subtotalNode = form?.querySelector("#invoice-subtotal");
  const taxNode = form?.querySelector("#invoice-tax-total");
  const totalNode = form?.querySelector("#invoice-total");
  if (subtotalNode) subtotalNode.textContent = salesCurrency(subtotal);
  if (taxNode) taxNode.textContent = salesCurrency(taxTotal);
  if (totalNode) totalNode.textContent = salesCurrency(subtotal + taxTotal);
  const journalPreview = form?.querySelector("#invoice-journal-preview");
  if (journalPreview && form?.dataset.kind === "out_refund") {
    journalPreview.innerHTML = creditNoteJournalRowsMarkup(journalLines, taxTotal, subtotal + taxTotal, form.querySelector("[name='partner']")?.value || "", form.querySelector("[name='ref']")?.value || "Draft");
  } else if (journalPreview) {
    const draft = { kind: form.dataset.kind || "out_invoice", partner: form.querySelector("[name='partner']")?.value || "", ref: form.querySelector("[name='ref']")?.value || "Draft", lines: journalLines };
    journalPreview.innerHTML = invoicePostingPreview(draft, subtotal, taxTotal, subtotal + taxTotal);
  }
  return { taxExcluded: subtotal, taxAmount: taxTotal, total: subtotal + taxTotal };
}

function renderInvoiceHeaderPreview(invoice, compact = false) {
  const layout = state.invoiceLayout;
  const lines = invoice.lines || [];
  return `<article class="invoice-paper ${compact ? "compact" : ""}"><header class="invoice-paper-header"><div class="invoice-company-mark">${escapeHtml(initials(layout.companyName || "BD"))}</div><div class="invoice-company-details"><h2>${escapeHtml(layout.companyName || "Company name not set")}</h2><span>${escapeHtml(layout.address || "Company address not set")}</span><span>${escapeHtml(layout.phone || "")}${layout.email ? ` · ${escapeHtml(layout.email)}` : ""}</span>${layout.bin ? `<span>BIN: ${escapeHtml(layout.bin)}</span>` : ""}</div><div class="invoice-paper-meta"><strong>${escapeHtml(invoiceLabel(invoice.kind || "out_invoice"))}</strong><span>${escapeHtml(invoice.ref || "Draft")}</span><span>Invoice date · ${invoiceDateText(invoice.invoiceDate)}</span><span>Due date · ${invoiceDateText(invoice.dueDate)}</span></div></header><section class="invoice-bill-to"><span>Bill To</span><strong>${escapeHtml(invoice.partner || "Customer / vendor")}</strong>${invoice.origin ? `<small>Source · ${escapeHtml(invoice.origin)}</small>` : ""}</section><div class="invoice-preview-table-wrap"><table class="invoice-preview-table"><thead><tr><th>Product / Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Tax</th><th class="money-cell">Amount</th></tr></thead><tbody>${lines.length ? lines.map((line) => `<tr><td>${escapeHtml(line.description || line.product || line.sku || "Item")}${line.sku ? `<small>${escapeHtml(line.sku)}</small>` : ""}</td><td>${escapeHtml(line.qty)}</td><td>${escapeHtml(line.uom)}</td><td>${salesCurrency(line.price)}</td><td>${Number(line.taxRate || 0).toFixed(3)}%</td><td class="money-cell">${salesCurrency(Number(line.subtotal || 0) + Number(line.taxAmount || 0))}</td></tr>`).join("") : `<tr><td colspan="6" class="invoice-preview-empty">Invoice lines preview</td></tr>`}</tbody></table></div><div class="invoice-total-panel"><div><span>Tax Excluded</span><strong>${salesCurrency(invoice.taxExcluded || 0)}</strong></div><div><span>Tax</span><strong>${salesCurrency(invoice.taxAmount || 0)}</strong></div><div class="grand-total"><span>Total · BDT</span><strong>${salesCurrency(invoice.total || 0)}</strong></div>${invoice.amountDue !== undefined ? `<div><span>Amount Due</span><strong>${salesCurrency(invoice.amountDue)}</strong></div>` : ""}</div><footer class="invoice-paper-footer">${escapeHtml(layout.footerNote || "Payment and delivery terms are as agreed in the sales document.")}</footer></article>`;
}

function createInvoiceFromSaleOrder(order) {
  const kind = "out_invoice";
  const defaultTax = defaultInvoiceTax(kind);
  const lines = (order.lines || []).filter((line) => line.type === "product" || (!line.type && line.product)).map((line) => {
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === Number(line.taxId) && item.active) || defaultTax;
    const discount = Math.min(100, Math.max(0, Number(line.discount || 0)));
    const discountedPrice = Number(line.price || 0) * (1 - discount / 100);
    const amounts = calculateInvoiceLineAmounts(line.qty, discountedPrice, tax);
    return { ...line, price: discountedPrice, discount, description: line.description || line.product, taxId: tax?.id || null, taxRate: Number(tax?.rate || 0), subtotal: amounts.subtotal, taxAmount: amounts.taxAmount };
  });
  const taxExcluded = lines.reduce((sum, line) => sum + line.subtotal, 0);
  const taxAmount = lines.reduce((sum, line) => sum + line.taxAmount, 0);
  const total = taxExcluded + taxAmount;
  return { id: Date.now(), ref: nextInvoiceReference(kind), kind, partner: order.customer, customerId: order.customerId || state.salesCustomers.find((customer) => customer.name === order.customer)?.id || null, contactId: order.contactId || null, origin: order.ref, salesOrderId: order.id, invoiceDate: inputLocalDate(), dueDate: invoiceDueDate(inputLocalDate(), order.paymentTerms), reminderDate: "", paymentTerms: order.paymentTerms || "Due on receipt", lines, taxExcluded, taxAmount, total, amountDue: total, status: "Draft", currency: "BDT" };
}

function invoiceDueDate(dateValue, terms) {
  const match = String(terms || "").match(/(\d+)\s*days?/i);
  const dueDate = new Date(`${dateValue || inputLocalDate()}T00:00:00`);
  if (/receipt|delivery|cash/i.test(String(terms || ""))) return dateValue || inputLocalDate();
  if (match) dueDate.setDate(dueDate.getDate() + Number(match[1]));
  return inputLocalDate(dueDate);
}

function invoicePostingPreview(invoice, taxExcluded, taxAmount, total) {
  const customer = invoice.kind.startsWith("out_");
  const refund = invoice.kind.endsWith("refund");
  const salesCode = accountingUsableJournals().find((journal) => journal.type === "sales")?.accountCode || "4000";
  const purchaseCode = accountingUsableJournals().find((journal) => journal.type === "purchase")?.accountCode || "6000";
  const lineAccounts = new Map();
  (invoice.lines || []).filter((line) => line && line.type !== "section" && line.type !== "note").forEach((line) => {
    const code = String(line.accountCode || (customer ? salesCode : purchaseCode));
    lineAccounts.set(code, Number(lineAccounts.get(code) || 0) + Number(line.subtotal || 0));
  });
  const accountRows = [...lineAccounts].map(([code, amount]) => customer
    ? [code, accountingAccountName(code), 0, amount]
    : [code, accountingAccountName(code), amount, 0]);
  if (!accountRows.length) {
    const code = customer ? salesCode : purchaseCode;
    accountRows.push(customer
      ? [code, accountingAccountName(code), 0, taxExcluded]
      : [code, accountingAccountName(code), taxExcluded, 0]);
  }
  let rows;
  if (customer && !refund) rows = [["1100", "Accounts Receivable", total, 0], ...accountRows, ...(taxAmount ? [["2100", "Output VAT Payable", 0, taxAmount]] : [])];
  else if (customer) rows = [["4010", "Sales Returns", taxExcluded, 0], ...(taxAmount ? [["2100", "Output VAT Payable", taxAmount, 0]] : []), ["1100", "Accounts Receivable", 0, total]];
  else if (!refund) rows = [...accountRows, ...(taxAmount ? [["1300", "Input VAT Recoverable", taxAmount, 0]] : []), ["2000", "Accounts Payable", 0, total]];
  else rows = [["2000", "Accounts Payable", total, 0], ...accountRows.map(([code, name, debit, credit]) => [code, name, credit, debit]), ...(taxAmount ? [["1300", "Input VAT Recoverable", 0, taxAmount]] : [])];
  return rows.map(([code, name, debit, credit]) => `<tr><td>${escapeHtml(code)}</td><td>${escapeHtml(name)}</td><td>${escapeHtml(invoice.partner || "—")}</td><td>${escapeHtml(invoice.ref || "Draft")}</td><td class="money-cell">${accountingAmount(debit)}</td><td class="money-cell">${accountingAmount(credit)}</td></tr>`).join("");
}

function syncInvoiceOtherInfoForm() {
  const form = document.querySelector("#invoice-form");
  const panel = form?.querySelector('[data-invoice-panel="other-info"] .sales-other-info-grid');
  if (!form || !panel) return;
  const editor = state.invoiceEditor || {};
  const record = state.invoices.find((invoice) => invoice.id === Number(editor.id)) || null;
  const kind = record?.kind || editor.kind || invoiceKindForPage();
  if (kind === "out_refund") return;
  const editable = !record || record.status === "Draft";
  const purchaseOrderId = Number(record?.purchaseOrderId || editor.purchaseOrderId) || null;
  const purchaseOrder = purchaseOrders.find((order) => Number(order.id) === purchaseOrderId) || null;
  const salesOrderId = Number(record?.salesOrderId || editor.salesOrderId) || null;
  const salesOrder = state.salesOrders.find((order) => Number(order.id) === salesOrderId) || null;
  const partner = record?.partner || editor.partner || "";
  const contact = state.contacts.find((item) => String(item.id) === String(record?.contactId || editor.contactId || "")) ||
    state.contacts.find((item) => String(item.name || "").trim().toLowerCase() === String(partner).trim().toLowerCase());
  const field = (label, control, help) => '<div class="field"><label>' + escapeHtml(label) + '</label>' + control + (help ? '<small>' + escapeHtml(help) + '</small>' : '') + '</div>';
  const input = (name, value, type, readonly) => '<input name="' + name + '" type="' + (type || 'text') + '" value="' + escapeHtml(value || '') + '"' + (readonly ? ' readonly' : '') + '>';
  const option = (value, label, selected) => '<option value="' + escapeHtml(value) + '"' + (selected ? ' selected' : '') + '>' + escapeHtml(label) + '</option>';
  const select = (name, values, current, disabled, emptyLabel) => {
    const unique = [...new Set([...(values || []), current].filter(Boolean))];
    return '<select name="' + name + '"' + (disabled ? ' disabled' : '') + '>' +
      option('', emptyLabel || 'Select an option', !current) +
      unique.map((value) => option(value, value, value === current)).join('') + '</select>';
  };
  const salespersonNames = [...new Set([state.userProfile?.name, ...(state.salesOrders || []).map((order) => order.salesperson), ...(state.invoices || []).map((invoice) => invoice.salesperson)].filter(Boolean))];
  const salesperson = record?.salesperson || salesOrder?.salesperson || state.userProfile?.name || '';
  const teamNames = [...new Set([...(state.salesConfig?.['sales-teams'] || []), record?.salesTeam, salesOrder?.salesTeam].filter(Boolean))];
  const bankNames = [...new Set((Array.isArray(contact?.bankAccounts) ? contact.bankAccounts : []).map((bank) => {
    const bankName = String(bank?.bank || bank?.name || '').trim() || 'Bank account';
    const account = String(bank?.accountNumber || '').replace(/\s+/g, '');
    const holder = String(bank?.accountHolder || '').trim();
    return [bankName, account ? '•••• ' + account.slice(-4) : '', holder].filter(Boolean).join(' · ');
  }).filter(Boolean))];
  const fiscalNames = [...new Set([...(state.invoiceConfig.collections?.['invoice-fiscal-positions'] || []).map((item) => typeof item === 'string' ? item : item?.name), record?.fiscalPosition].filter(Boolean))];
  const paymentNames = [...new Set(['Manual', ...(state.salesConfig?.['sales-payments'] || []), record?.paymentMethod].filter(Boolean))];
  const incotermNames = ['EXW · Ex Works', 'FCA · Free Carrier', 'CPT · Carriage Paid To', 'CIP · Carriage and Insurance Paid To', 'DAP · Delivered at Place', 'DPU · Delivered at Place Unloaded', 'DDP · Delivered Duty Paid', 'FAS · Free Alongside Ship', 'FOB · Free on Board', 'CFR · Cost and Freight', 'CIF · Cost, Insurance and Freight'];
  const currentIncoterm = record?.incoterm ?? purchaseOrder?.incoterm ?? '';
  const incotermValues = [...new Set([...(currentIncoterm ? [currentIncoterm] : []), ...incotermNames])];
  const fiscalPosition = record?.fiscalPosition || '';
  const paymentMethod = record?.paymentMethod || 'Manual';
  const displayStatus = record ? invoiceDisplayStatus(record) : 'Draft';
  const due = record?.amountDue ?? record?.total ?? 0;
  const sourceDocument = purchaseOrder?.ref || record?.origin || editor.origin || salesOrder?.ref || '—';
  const linkedSource = purchaseOrder?.ref || salesOrder?.ref || (record?.sourceId ? state.invoices.find((item) => item.id === record.sourceId)?.ref : '') || '—';
  const company = record?.company || state.settings.companyName || 'Arafat Chemica';
  const referrer = record?.referrer ?? salesOrder?.referrer ?? '';
  const journal = accountingUsableJournals().find((item) => item.type === (kind.startsWith('out_') ? 'sales' : 'purchase'));
  const customerReference = record?.customerReference ?? salesOrder?.customerRef ?? '';
  const paymentReference = record?.paymentReference || record?.ref || editor.ref || nextInvoiceReference(kind);
  const deliveryDate = record?.deliveryDate ?? salesOrder?.deliveryDate ?? '';
  const originLabel = form.querySelector('[name="origin"]')?.closest('.field')?.querySelector('label');
  if (originLabel) originLabel.textContent = kind.startsWith('in_') ? 'Bill Reference' : 'Source Document';
  const salesPersonControl = '<input name="salesperson" list="invoice-salesperson-options" value="' + escapeHtml(salesperson) + '"' + (editable ? '' : ' readonly') + '><datalist id="invoice-salesperson-options">' + salespersonNames.map((name) => '<option value="' + escapeHtml(name) + '"></option>').join('') + '</datalist>';
  const teamControl = select('salesTeam', teamNames, record?.salesTeam ?? salesOrder?.salesTeam ?? '', !editable, 'Select a team');
  const bankControl = select('recipientBank', bankNames, record?.recipientBank || '', !editable, bankNames.length ? 'Select a bank account' : 'No bank account configured');
  const fiscalControl = select('fiscalPosition', fiscalNames, fiscalPosition, !editable, 'None');
  const paymentControl = select('paymentMethod', paymentNames, paymentMethod, !editable, 'Select a payment method');
  const incotermControl = '<select name="incoterm"' + (!editable ? ' disabled' : '') + '>' + option('', 'Select an Incoterm', !currentIncoterm) + incotermValues.map((value) => option(value, value, value === currentIncoterm)).join('') + '</select>';
  const autoPostControl = '<select aria-label="Auto-post" disabled><option selected>No</option><option>At Date</option><option>Monthly</option><option>Quarterly</option><option>Yearly</option></select>';
  panel.innerHTML = '<section><h3>Invoice</h3>' +
    field('Customer Reference', input('customerReference', customerReference, 'text', !editable)) +
    field('Salesperson', salesPersonControl) +
    field('Sales Team', teamControl) +
    field('Recipient Bank', bankControl) +
    field('Payment Reference', input('paymentReference', paymentReference, 'text', !editable)) +
    field('Delivery Date', input('deliveryDate', deliveryDate, 'date', !editable)) +
    field('Referrer', input('referrer', referrer, 'text', !editable)) +
    '</section><section><h3>Accounting</h3>' +
    field('Company', input('company', company, 'text', true)) +
    field('Incoterm', incotermControl) +
    field('Incoterm Location', input('incotermLocation', record?.incotermLocation ?? purchaseOrder?.incotermLocation ?? '', 'text', !editable)) +
    field('Fiscal Position', fiscalControl) +
    field('Payment Method', paymentControl) +
    field('Auto-post', autoPostControl, 'Scheduled posting is unavailable in this local prototype.') +
    field('Source Document', '<input value="' + escapeHtml(sourceDocument) + '" readonly>') +
    field('Linked Source', '<input value="' + escapeHtml(linkedSource) + '" readonly>') +
    field('Payment Status', '<input value="' + escapeHtml(displayStatus + ' · ' + salesCurrency(due) + ' due') + '" readonly>') +
    field('Accounting Date', '<input value="' + escapeHtml(record?.postedDate || record?.invoiceDate || inputLocalDate()) + '" readonly>') +
    field('Journal', '<input value="' + escapeHtml(journal?.name || 'No journal configured') + '" disabled>') +
    field('Currency', '<input value="' + escapeHtml(record?.currency || 'BDT') + '" disabled>') +
    '</section>';
  if (record?.status === 'Draft') {
    document.querySelectorAll('.sales-document-buttons').forEach((container) => {
      const postButton = container.querySelector('[data-invoice-action="post"]');
      if (postButton) {
        postButton.removeAttribute('data-invoice-action');
        postButton.dataset.saveInvoice = 'Posted';
        postButton.type = 'button';
      }
      if (!container.querySelector('[data-save-invoice="Draft"]')) {
        const saveButton = document.createElement('button');
        saveButton.className = 'action-button secondary';
        saveButton.type = 'button';
        saveButton.dataset.saveInvoice = 'Draft';
        saveButton.textContent = 'Save';
        const nextAction = container.querySelector('[data-save-invoice="Posted"]');
        container.insertBefore(saveButton, nextAction || container.firstChild);
      }
    });
  }
}
function renderCreditNoteDocumentForm(record, editor) {
  const editable = !record || record.status === "Draft";
  const ref = record?.ref || nextInvoiceReference("out_refund");
  const status = record ? invoiceDisplayStatus(record) : "Draft";
  const partner = record?.partner || editor.partner || "";
  const date = record?.invoiceDate || inputLocalDate();
  const termsValue = record?.paymentTerms || state.salesSettings.defaultPaymentTerms || "Due on receipt";
  const terms = [...new Set([termsValue, "Due on receipt", "Cash on delivery", "Credit · 7 days", "Credit · 15 days", "Credit · 30 days", ...(state.invoiceConfig.collections?.["invoice-payment-terms"] || []).map((term) => term.name)])];
  const lines = record?.lines?.length ? record.lines.map((line, index) => line.type === "section" || line.type === "note" ? creditNoteSpecialLineMarkup(line.type, index).replace('placeholder="' + (line.type === "section" ? "Section title" : "Add a note") + '"', 'value="' + escapeHtml(line.description || "") + '" placeholder="' + (line.type === "section" ? "Section title" : "Add a note") + '"') : creditNoteInvoiceLineMarkup(line, index)).join("")
    : editor.lines?.length ? editor.lines.map((line, index) => creditNoteInvoiceLineMarkup(line, index)).join("") : creditNoteInvoiceLineMarkup({}, 0);
  const journal = accountingUsableJournals().find((item) => item.type === "sales");
  const journalOptions = accountingUsableJournals().filter((item) => item.type === "sales").map((item) => `<option value="${escapeHtml(item.name)}" ${item.name === (record?.journal || journal?.name) ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("");
  const original = record?.sourceId ? state.invoices.find((item) => item.id === Number(record.sourceId)) : editor.sourceId ? state.invoices.find((item) => item.id === Number(editor.sourceId)) : null;
  const deliveryAddress = record?.deliveryAddress || editor.deliveryAddress || (partner ? salesCustomerAddress(partner) : "") || "";
  const carriedLines = record?.lines || editor.lines || [];
  const taxExcluded = record?.taxExcluded ?? carriedLines.filter((line) => line.type !== "section" && line.type !== "note").reduce((sum, line) => sum + Number(line.subtotal || 0), 0);
  const taxAmount = record?.taxAmount ?? carriedLines.filter((line) => line.type !== "section" && line.type !== "note").reduce((sum, line) => sum + Number(line.taxAmount || 0), 0);
  const total = record?.total ?? taxExcluded + taxAmount;
  const defaultJournalRows = record?.journalItems?.length
    ? record.journalItems.map((line, index) => `<tr data-credit-journal-row data-journal-index="${index}"><td><button type="button" class="credit-note-account-link" data-credit-account-picker="journal" data-line-index="${index}">${escapeHtml(line.accountCode)} ${escapeHtml(accountingAccountName(line.accountCode))}</button><input type="hidden" data-credit-journal-account value="${escapeHtml(line.accountCode)}"></td><td><input data-credit-journal-label value="${escapeHtml(line.label || "")}" aria-label="Label"></td><td><input data-credit-journal-analytic value="${escapeHtml(line.analytic || "")}" aria-label="Analytic Distribution"></td><td><input data-credit-journal-debit type="number" min="0" step="0.01" value="${Number(line.debit || 0).toFixed(2)}" aria-label="Debit"></td><td><input data-credit-journal-credit type="number" min="0" step="0.01" value="${Number(line.credit || 0).toFixed(2)}" aria-label="Credit"></td><td><input data-credit-journal-tax-grid value="${escapeHtml(line.taxGrids || "")}" aria-label="Tax Grids"></td><td><button type="button" class="soft-icon-button credit-note-remove-line" data-action="remove-credit-journal-line" aria-label="Remove journal line"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9 7V4.5h6V7m-8.5 0 1 13h9l1-13M10 10.5v6m4-6v6"/></svg></button></td></tr>`).join("")
    : creditNoteJournalRowsMarkup(record?.lines || editor.lines || [], taxAmount, total, partner, ref);
  const saveDraft = editable ? `<button class="credit-note-cloud-save" type="button" data-save-invoice="Draft" aria-label="Save" title="Save"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.5 18.5h10a4 4 0 0 0 .4-8 6 6 0 0 0-11.3-1.3A4.4 4.4 0 0 0 7.5 18.5Z"/><path d="m8.5 12.5 3.5 3.5 3.5-3.5M12 16v-7"/></svg></button>` : "";
  const actionButtons = editable ? `<button class="action-button" type="button" data-save-invoice="Posted">Confirm</button><button class="action-button secondary" type="button" data-invoice-editor-action="discard">Cancel</button>` : `<button class="action-button secondary" type="button" data-action="print-invoice">Print</button>`;
  const statusbar = `<div class="sales-statusbar invoice-statusbar" aria-label="Credit note status"><span class="${status === "Draft" ? "is-current" : "is-done"}">Draft</span><span class="${status === "Posted" ? "is-current" : ""}">Posted</span></div>`;
  return `<section class="sales-document-page erp-finance-record-page erp-credit-note-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button">New <span class="credit-note-caret">▾</span></button><div><button type="button" class="sales-breadcrumb" data-invoice-editor-action="discard">Credit Notes</button><h1>${escapeHtml(record?.ref || "New")}</h1><small>Draft Credit Note${partner ? ` · ${escapeHtml(partner)}` : ""}</small></div>${saveDraft}<button type="button" class="soft-icon-button" data-invoice-editor-action="discard" aria-label="Close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="sales-document-toolbar-right">${original ? `<button type="button" class="credit-note-smart-link" data-open-invoice="${original.id}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3.5h7l4 4v13H7zM14 3.5v4h4M9.5 12h6M9.5 15.5h6"/></svg>Draft Invoice <strong>${escapeHtml(original.ref)}</strong></button>` : ""}<button type="button" class="credit-note-smart-link" data-credit-journal-tab><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h14M5 12h14M5 18h14M2.5 6h.01M2.5 12h.01M2.5 18h.01"/></svg>Journal Items</button></div></div><div class="sales-document-actionbar"><div class="sales-document-buttons">${actionButtons}</div>${statusbar}</div><div class="erp-finance-form-layout"><main><form id="invoice-form" ${editable ? "" : "inert"} data-id="${record?.id || ""}" data-kind="out_refund" data-source="${record?.sourceId || editor.sourceId || ""}" data-return-page="${escapeHtml(editor.returnPage || state.page)}"><article class="sales-document-card"><header class="sales-document-heading"><div><span class="settings-eyebrow">CUSTOMER CREDIT NOTE</span><h2>Draft Credit Note</h2><small class="sales-document-ref">${escapeHtml(ref)}</small></div><span class="sales-currency-tag">Bangladesh · BDT ৳</span></header><section class="sales-document-fields credit-note-header-fields"><div class="sales-field-main"><div class="field sales-partner-field"><label>Customer</label><input name="partner" list="invoice-partner-options" value="${escapeHtml(partner)}" required ${editable ? "" : "disabled"} placeholder="Name, Tax ID, Email, or Reference"><datalist id="invoice-partner-options">${state.salesCustomers.map((customer) => `<option value="${escapeHtml(customer.name)}">`).join("")}</datalist></div><div class="field credit-note-delivery-field"><label>Delivery Address</label><input name="deliveryAddress" value="${escapeHtml(deliveryAddress)}" ${editable ? "" : "disabled"} placeholder="Delivery address"></div></div><div class="sales-field-side"><div class="field"><label>Invoice Date</label><input name="invoiceDate" type="date" value="${escapeHtml(date)}" required ${editable ? "" : "disabled"}></div><div class="field"><label>Due Date</label><input name="dueDate" type="date" value="${escapeHtml(record?.dueDate || invoiceDueDate(date, termsValue))}" ${editable ? "" : "disabled"}></div><div class="field credit-note-terms-field"><label>Payment Terms</label><select name="paymentTerms" ${editable ? "" : "disabled"}>${terms.map((term) => `<option ${term === termsValue ? "selected" : ""}>${escapeHtml(term)}</option>`).join("")}</select></div><div class="field"><label>Journal</label><select name="journal" ${editable ? "" : "disabled"}>${journalOptions || `<option>${escapeHtml(journal?.name || "No sales journal")}</option>`}</select></div><div class="field"><label>Currency</label><input value="${escapeHtml(record?.currency || "BDT")}" disabled></div></div></section><nav class="sales-document-tabs erp-finance-tabs" aria-label="Credit note details"><button type="button" data-invoice-tab="invoice-lines" class="${state.invoiceTab === "invoice-lines" ? "is-active" : ""}">Invoice Lines</button><button type="button" data-invoice-tab="journal-items" class="${state.invoiceTab === "journal-items" ? "is-active" : ""}">Journal Items</button><button type="button" data-invoice-tab="other-info" class="${state.invoiceTab === "other-info" ? "is-active" : ""}">Other Info</button></nav><section class="sales-tab-panel ${state.invoiceTab === "invoice-lines" ? "is-active" : ""}" data-invoice-panel="invoice-lines"><div class="sales-lines-toolbar"><div><strong>Invoice Lines</strong><small>Choose the account and product or enter the credit directly.</small></div><div class="sales-tax-switch"><button type="button" class="is-active" disabled>Tax Excl.</button><button type="button" disabled>Tax Incl.</button></div></div><div class="sale-lines-scroll"><table class="order-lines invoice-entry-lines credit-note-lines"><thead><tr><th>Product</th><th>Account</th><th>Analytic Distribution</th><th>Quantity</th><th>Unit</th><th>Price</th><th>Taxes</th><th class="money-cell">Amount</th><th></th></tr></thead><tbody id="invoice-line-items">${lines}</tbody></table></div>${editable ? `<div class="sales-line-actions"><button type="button" data-action="add-invoice-line">Add a line</button><button type="button" data-action="add-credit-section">Add a section</button><button type="button" data-action="add-credit-note">Add a note</button><button type="button" data-action="invoice-catalog">Catalog</button></div>` : ""}<div class="invoice-totals-edit"><span>Untaxed Amount<strong id="invoice-subtotal">${salesCurrency(taxExcluded)}</strong></span><span>Tax<strong id="invoice-tax-total">${salesCurrency(taxAmount)}</strong></span><span>Total<strong id="invoice-total">${salesCurrency(total)}</strong></span></div></section><section class="sales-tab-panel ${state.invoiceTab === "journal-items" ? "is-active" : ""}" data-invoice-panel="journal-items"><div class="sales-lines-toolbar"><div><strong>Journal Items</strong><small>Review the balanced accounting entries created by this credit note.</small></div><button type="button" class="action-button secondary" data-credit-add-journal-line>Add a line</button></div><div class="sale-lines-scroll"><table class="order-lines erp-journal-preview credit-note-journal-items"><thead><tr><th>Account</th><th>Label</th><th>Analytic Distribution</th><th class="money-cell">Debit</th><th class="money-cell">Credit</th><th>Tax Grids</th><th></th></tr></thead><tbody id="invoice-journal-preview">${defaultJournalRows}</tbody></table></div></section><section class="sales-tab-panel ${state.invoiceTab === "other-info" ? "is-active" : ""}" data-invoice-panel="other-info"><div class="sales-other-info-grid"><section><h3>Invoice</h3><div class="field"><label>Source Document</label><input value="${escapeHtml(original?.ref || record?.origin || editor.origin || "—")}" readonly></div><div class="field"><label>Payment Terms</label><input value="${escapeHtml(termsValue)}" readonly></div></section><section><h3>Accounting</h3><div class="field"><label>Journal</label><input value="${escapeHtml(record?.journal || journal?.name || "No sales journal configured")}" readonly></div><div class="field"><label>Currency</label><input value="${escapeHtml(record?.currency || "BDT")}" readonly></div><div class="field"><label>Accounting Date</label><input value="${escapeHtml(record?.postedDate || date)}" readonly></div></section></div></section><footer class="sales-document-footer"><div class="sales-document-note">Terms &amp; Conditions: <a href="#" data-action="toast" data-message="Configure company terms in Accounting settings.">Configure terms</a></div><div class="invoice-totals-edit"><span>Untaxed Amount<strong>${salesCurrency(taxExcluded)}</strong></span><span>Total<strong>${salesCurrency(total)}</strong></span></div></footer></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button">Send message</button><button type="button" class="action-button secondary">Log note</button><button type="button" class="action-button secondary"><svg class="credit-note-whatsapp-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.7a8.3 8.3 0 0 1-12.2 7.4L4 20l.9-3.5A8.3 8.3 0 1 1 20 11.7Z"/><path d="M9 8.3c.3-.5.6-.5.9-.5l.6 1.5c.1.2.1.4-.1.6l-.5.5c.5 1 1.3 1.8 2.3 2.3l.6-.5c.2-.2.4-.2.6-.1l1.5.7c.2.1.3.3.2.6-.1.5-.5 1-1 1.2-.6.2-1.5.1-2.8-.6-1.4-.7-2.8-2.1-3.5-3.5-.6-1.3-.7-2.2-.4-2.7Z"/></svg>WhatsApp</button><button type="button" class="action-button secondary">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${record ? `${escapeHtml(status)} · ${escapeHtml(record.ref)}` : "Creating a new record..."}</p></div></div></aside></div></section>`;
}

function renderInvoiceDocumentForm() {
  const editor = state.invoiceEditor || {};
  const record = state.invoices.find((invoice) => invoice.id === Number(editor.id)) || null;
  const kind = record?.kind || editor.kind || invoiceKindForPage();
  if (kind === "out_refund") return renderCreditNoteDocumentForm(record, editor);
  const purchaseOrderId = Number(record?.purchaseOrderId || editor.purchaseOrderId) || null;
  const purchaseOrder = purchaseOrders.find((order) => Number(order.id) === purchaseOrderId) || null;
  const editable = !record || record.status === "Draft";
  const date = record?.invoiceDate || inputLocalDate();
  const defaultTerms = record?.paymentTerms || state.salesSettings.defaultPaymentTerms || "Due on receipt";
  const terms = [...new Set([defaultTerms, "Cash on delivery", "Credit · 7 days", "Credit · 15 days", "Credit · 30 days", ...(state.invoiceConfig.collections?.["invoice-payment-terms"] || []).map((term) => term.name)])];
  const partners = kind.startsWith("in_") ? vendors.map((vendor) => vendor.name) : state.salesCustomers.map((customer) => customer.name);
  const ref = record?.ref || nextInvoiceReference(kind);
  const lines = record?.lines?.length ? record.lines.map((line) => invoiceLineMarkup(line, kind)).join("") : (editor.lines?.length ? editor.lines.map((line) => invoiceLineMarkup(line, kind)).join("") : invoiceLineMarkup({}, kind));
  const taxExcluded = record?.taxExcluded ?? 0;
  const taxAmount = record?.taxAmount ?? 0;
  const total = record?.total ?? 0;
  const due = record?.amountDue ?? total;
  const title = record ? invoiceLabel(kind) : (kind.startsWith("in_") ? "Draft Bill" : "Draft Invoice");
  const displayStatus = record ? invoiceDisplayStatus(record) : "Draft";
  const statusSteps = ["Draft", "Posted", "Paid"];
  const activeStep = displayStatus === "Draft" ? 0 : displayStatus === "Paid" ? 2 : 1;
  const statusbar = `<div class="sales-statusbar invoice-statusbar" aria-label="Document status">${statusSteps.map((step, index) => `<span class="${index === activeStep ? "is-current" : index < activeStep ? "is-done" : ""}">${step}</span>`).join("")}</div>`;
  const actions = record
    ? `<button class="action-button secondary" type="button" data-action="print-invoice">Print / PDF</button>${record.status === "Draft" ? `<button class="action-button" type="button" data-invoice-action="post" data-id="${record.id}">Confirm</button>` : ""}${record.amountDue > 0 && ["Posted", "Partial", "Overdue"].includes(displayStatus) ? `<button class="action-button" type="button" data-invoice-action="payment" data-id="${record.id}">${kind.startsWith("in_") ? "Register Payment" : "Register Payment"}</button>` : ""}${["out_invoice", "in_invoice"].includes(kind) && record.status !== "Draft" ? `<button class="action-button secondary" type="button" data-invoice-action="credit" data-id="${record.id}">Create ${kind === "out_invoice" ? "Credit Note" : "Vendor Refund"}</button>` : ""}`
    : `<button class="action-button secondary" type="button" data-invoice-editor-action="discard">Discard</button><button class="action-button secondary" type="button" data-save-invoice="Draft">Save</button><button class="action-button" type="button" data-save-invoice="Posted">Confirm</button>`;
  const readOnly = editable ? "" : "disabled";
  const journal = accountingUsableJournals().find((item) => item.type === (kind.startsWith("out_") ? "sales" : "purchase"));
  const sourceInvoice = record?.sourceId ? state.invoices.find((item) => item.id === record.sourceId) : null;
  const initialJournalRows = invoicePostingPreview(record || { kind, partner: editor.partner, ref }, taxExcluded, taxAmount, total);
  const purchaseOrderLink = purchaseOrder ? window.ERPSharedSmartPanel.render({
    className: "invoice-source-smart-panel", ariaLabel: "Invoice source smart buttons",
    items: [{ label: "Purchase Order", value: purchaseOrder.ref, icon: "▰", className: "purchase-smart-button", attributes: { "data-open-purchase-order": purchaseOrder.id } }],
  }) : "";
  return `<section class="sales-document-page erp-finance-record-page erp-odoo-invoice-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button" data-invoice-editor-action="discard">${record ? pageLabels[state.page] || "Invoices" : "New"}</button><div><button type="button" class="sales-breadcrumb" data-invoice-editor-action="discard">${escapeHtml(pageLabels[state.page] || "Accounting")}</button><h1>${escapeHtml(record?.ref || title)}</h1><small>${escapeHtml(invoiceLabel(kind))}${record?.partner ? ` · ${escapeHtml(record.partner)}` : ""}</small></div></div><div class="sales-document-toolbar-right">${purchaseOrderLink}<button type="button" class="credit-note-smart-link invoice-journal-smart-link" data-invoice-tab="journal-items"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h14M5 12h14M5 18h14M2.5 6h.01M2.5 12h.01M2.5 18h.01"/></svg>Journal Items</button><button class="soft-icon-button" type="button" data-action="print-invoice" aria-label="Print or download">⇩</button><button class="soft-icon-button" type="button" data-invoice-editor-action="discard" aria-label="Close">×</button></div></div><div class="sales-document-actionbar"><div class="sales-document-buttons">${actions}</div>${statusbar}</div><div class="erp-finance-form-layout"><main><form id="invoice-form" data-id="${record?.id || ""}" data-kind="${kind}" data-source="${record?.sourceId || editor.sourceId || ""}" data-purchase-order="${purchaseOrder?.id || ""}" data-return-page="${escapeHtml(editor.returnPage || state.page)}"><article class="sales-document-card"><header class="sales-document-heading"><div><span class="settings-eyebrow">${kind.startsWith("in_") ? "SUPPLIER BILL" : "CUSTOMER INVOICE"}</span><h2>${record ? escapeHtml(ref) : "Draft"}</h2><small class="sales-document-ref">${escapeHtml(ref)}</small></div><span class="sales-currency-tag">Bangladesh · BDT ৳</span></header><section class="sales-document-fields"><div class="sales-field-main"><div class="field sales-partner-field"><label>${kind.startsWith("in_") ? "Vendor" : "Customer"}</label><input name="partner" list="invoice-partner-options" value="${escapeHtml(record?.partner || editor.partner || "")}" required ${readOnly} placeholder="Search a name or Tax ID..."><datalist id="invoice-partner-options">${partners.map((name) => `<option value="${escapeHtml(name)}">`).join("")}</datalist><small>${kind.startsWith("in_") ? "Supplier account · shared with Purchase" : "Customer / dealer account · shared with Sales"}</small></div><div class="field invoice-reference-field"><label>${kind.startsWith("in_") ? "Bill Reference" : "Customer Reference"}</label><input name="origin" value="${escapeHtml(record?.origin || editor.origin || "")}" ${readOnly} placeholder="Customer or supplier reference"></div><div class="field invoice-delivery-field"><label>Delivery Address</label><input name="deliveryAddress" value="${escapeHtml(record?.deliveryAddress || editor.deliveryAddress || (record?.partner || editor.partner ? salesCustomerAddress(record?.partner || editor.partner) : ""))}" ${readOnly} placeholder="Delivery address"></div></div><div class="sales-field-side"><div class="field"><label>${kind.startsWith("in_") ? "Bill Date" : "Invoice Date"}</label><input name="invoiceDate" type="date" value="${escapeHtml(date)}" required ${readOnly}></div><div class="invoice-due-terms-row"><div class="field"><label>Due Date</label><input name="dueDate" type="date" value="${escapeHtml(record?.dueDate || invoiceDueDate(date, defaultTerms))}" ${readOnly}></div><span class="invoice-or">or</span><div class="field"><label>Payment Terms</label><select name="paymentTerms" ${readOnly}>${terms.map((term) => `<option ${term === defaultTerms ? "selected" : ""}>${escapeHtml(term)}</option>`).join("")}</select></div></div><div class="field"><label>Journal</label><input value="${escapeHtml(journal?.name || "No journal configured")}" disabled></div><div class="field"><label>Currency</label><input value="${escapeHtml(record?.currency || "BDT")}" disabled></div></div></section><nav class="sales-document-tabs erp-finance-tabs" aria-label="Accounting document details"><button type="button" data-invoice-tab="invoice-lines" class="${state.invoiceTab === "invoice-lines" ? "is-active" : ""}">Invoice Lines</button><button type="button" data-invoice-tab="journal-items" class="${state.invoiceTab === "journal-items" ? "is-active" : ""}">Journal Items</button><button type="button" data-invoice-tab="other-info" class="${state.invoiceTab === "other-info" ? "is-active" : ""}">Other Info</button></nav><section class="sales-tab-panel ${state.invoiceTab === "invoice-lines" ? "is-active" : ""}" data-invoice-panel="invoice-lines"><div class="sales-lines-toolbar"><div><strong>Products</strong><small>Choose a SKU and bill in pieces, packets, cartons, bags or kg.</small></div><div class="sales-tax-switch"><button type="button" class="is-active" disabled>Tax Excl.</button><button type="button" disabled>Tax Incl.</button></div></div><div class="sale-lines-scroll"><table class="order-lines invoice-entry-lines"><thead><tr><th>Product</th><th>Account</th><th>Analytic Distribution</th><th>Quantity</th><th>Unit</th><th>Price</th><th>Taxes</th><th class="money-cell">Amount</th><th></th></tr></thead><tbody id="invoice-line-items">${lines}</tbody></table></div>${editable ? `<div class="sales-line-actions"><button type="button" data-action="add-invoice-line">Add a line</button><button type="button" data-action="invoice-catalog">Catalog</button></div>` : ""}${state.invoiceConfig.taxes?.length ? "" : `<div class="sales-tax-note compact"><strong>Tax mapping is not configured</strong><p>Tax remains 0% until verified tax rules are added. Confirm Bangladesh VAT treatment before posting.</p></div>`}<div class="invoice-totals-edit"><span>Untaxed Amount<strong id="invoice-subtotal">${salesCurrency(taxExcluded)}</strong></span><span>Tax<strong id="invoice-tax-total">${salesCurrency(taxAmount)}</strong></span><span>Total<strong id="invoice-total">${salesCurrency(total)}</strong></span><span>Amount Due<strong>${salesCurrency(due)}</strong></span></div></section><section class="sales-tab-panel ${state.invoiceTab === "journal-items" ? "is-active" : ""}" data-invoice-panel="journal-items"><p class="erp-accounting-explainer">These balanced journal lines are generated from this document when it is posted.</p><div class="sale-lines-scroll"><table class="order-lines erp-journal-preview"><thead><tr><th>Account</th><th>Partner</th><th>Label</th><th class="money-cell">Debit · BDT</th><th class="money-cell">Credit · BDT</th></tr></thead><tbody id="invoice-journal-preview">${initialJournalRows}</tbody></table></div></section><section class="sales-tab-panel ${state.invoiceTab === "other-info" ? "is-active" : ""}" data-invoice-panel="other-info"><div class="sales-other-info-grid"><div class="field"><label>Journal</label><input value="${escapeHtml(journal?.name || "No journal configured")}" disabled></div><div class="field"><label>Currency</label><input value="${escapeHtml(record?.currency || "BDT")}" disabled></div><div class="field"><label>Source Document</label><input value="${escapeHtml(purchaseOrder?.ref || record?.origin || editor.origin || "—")}" readonly></div><div class="field"><label>Linked Source</label><input value="${escapeHtml(purchaseOrder?.ref || sourceInvoice?.ref || (record?.salesOrderId ? state.salesOrders.find((order) => order.id === record.salesOrderId)?.ref : "—") || "—")}" readonly></div><div class="field"><label>Payment Status</label><input value="${escapeHtml(displayStatus)} · ${salesCurrency(due)} due" readonly></div><div class="field"><label>Accounting Date</label><input value="${escapeHtml(record?.postedDate || date)}" readonly></div></div></section><footer class="sales-document-footer"><div class="sales-document-note">Posting adds this document to the shared Accounts Receivable/Payable and sales/purchase ledger. Values stay in this browser prototype.</div><div class="sales-document-buttons">${actions}</div></footer></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button">Send message</button><button type="button" class="action-button secondary">Log note</button><button type="button" class="action-button secondary">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>${record ? `${escapeHtml(displayStatus)} · ${escapeHtml(record.ref)}` : "Creating a new record..."}</p></div></div><p class="erp-chatter-note">Document history and partner communications appear here.</p></aside></div></section>`;
}

function openInvoiceModal(invoiceId = null, options = {}) {
  const record = invoiceId ? state.invoices.find((invoice) => invoice.id === Number(invoiceId)) : null;
  state.invoicePaymentEditor = null;
  state.invoiceEditor = record ? { id: record.id, contactId: record.contactId || null, returnPage: state.page } : {
    kind: options.kind || invoiceKindForPage(), lines: options.lines || [], partner: options.partner || "", contactId: options.contactId || null, origin: options.origin || "", sourceId: options.sourceId || "", purchaseOrderId: options.purchaseOrderId || "", title: options.title || "", returnPage: options.returnPage || state.page,
  };
  state.invoiceTab = "invoice-lines";
  render();
  if (!record) updateInvoiceTotal();
}

function createVendorBillFromPurchaseOrder(orderId) {
  const order = purchaseOrders.find((item) => Number(item.id) === Number(orderId));
  if (!order || order.status !== "Purchase Order") { showToast("Confirm the purchase order before creating its vendor bill."); return; }
  const existingBill = vendorBillForPurchaseOrder(order.id);
  const returnPage = state.purchaseEditor?.returnPage || "orders";
  if (existingBill) {
    setPage("invoice-vendor-bills");
    openInvoiceModal(existingBill.id);
    state.invoiceEditor.returnPage = returnPage;
    render();
    return;
  }
  const lines = (order.lines || []).filter((line) => !line.type).map((line) => {
    const product = salesProducts.find((item) => item.sku === line.sku || item.name === line.product);
    return { product: product?.name || line.product, sku: product?.sku || line.sku, description: product?.name || line.product, uom: line.uom || product?.stockUom || "Piece", qty: Number(line.qty) || 0, price: Number(line.price) || 0, taxId: line.taxId || product?.purchaseTaxId || null, stockFactor: product ? purchaseUnitFactor(product, line.uom || product.stockUom) : null };
  });
  if (!lines.length) { showToast("Add purchase order product lines before creating a vendor bill."); return; }
  setPage("invoice-vendor-bills");
  openInvoiceModal(null, { kind: "in_invoice", partner: order.vendor, contactId: order.vendorContactId || null, origin: order.vendorReference || "", purchaseOrderId: order.id, lines, returnPage });
}

function openPaymentModal(invoiceId = null) {
  const invoice = invoiceId ? state.invoices.find((row) => row.id === Number(invoiceId)) : null;
  if (invoice && !["Posted", "Partial", "Overdue"].includes(invoice.status)) { showToast("Post this invoice or bill before registering a payment."); return; }
  const vendor = invoice ? invoice.kind.startsWith("in_") : ["invoice-vendor-payments", "accounting-vendor-payments"].includes(state.page);
  const returnPage = state.page.startsWith("accounting-") ? state.page : "";
  state.invoiceEditor = null;
  state.invoicePaymentEditor = { invoiceId: invoice?.id || null, vendor, returnPage };
  render();
}

function renderInvoicePaymentPage() {
  const editor = state.invoicePaymentEditor || {};
  const invoice = state.invoices.find((row) => row.id === Number(editor.invoiceId)) || null;
  const vendor = invoice ? invoice.kind.startsWith("in_") : Boolean(editor.vendor);
  const candidates = state.invoices.filter((row) => row.kind.startsWith(vendor ? "in_" : "out_") && Number(row.amountDue) > 0 && ["Posted", "Partial", "Overdue"].includes(row.status));
  const paymentJournals = accountingUsableJournals().filter((journal) => ["cash", "bank", "card"].includes(journal.type));
  const options = candidates.map((row) => `<option value="${row.id}" data-due="${row.amountDue}" ${invoice?.id === row.id ? "selected" : ""}>${escapeHtml(row.ref)} · ${escapeHtml(row.partner)} · Due ${salesCurrency(row.amountDue)}</option>`).join("");
  const choice = invoice ? `<input name="invoiceId" type="hidden" value="${invoice.id}"><div class="field wide"><label>${vendor ? "Vendor Bill" : "Customer Invoice"}</label><input value="${escapeHtml(invoice.ref)} · ${escapeHtml(invoice.partner)} · Due ${salesCurrency(invoice.amountDue)}" readonly></div>` : `<div class="field wide"><label>Open ${vendor ? "Vendor Bill" : "Customer Invoice"}</label><select name="invoiceId" required><option value="">Select an open document</option>${options}</select></div>`;
  const title = vendor ? "Register Vendor Payment" : "Register Customer Receipt";
  return `<section class="sales-document-page erp-finance-record-page"><div class="sales-document-toolbar"><div class="sales-document-title"><button type="button" class="action-button" data-invoice-editor-action="discard">${escapeHtml(pageLabels[state.page] || "Accounting")}</button><div><button type="button" class="sales-breadcrumb" data-invoice-editor-action="discard">${escapeHtml(pageLabels[state.page] || "Accounting")}</button><h1>${title}</h1><small>Payment · BDT</small></div></div><button type="button" class="soft-icon-button" data-invoice-editor-action="discard" aria-label="Close">×</button></div><div class="sales-document-actionbar"><div class="sales-document-buttons"><button type="submit" form="invoice-payment-form" class="action-button">Register Payment</button><button type="button" class="action-button secondary" data-invoice-editor-action="discard">Discard</button></div><div class="sales-statusbar invoice-statusbar"><span class="is-current">Draft</span><span>Posted</span></div></div><div class="erp-finance-form-layout"><main><form id="invoice-payment-form" data-vendor="${vendor}" data-return-page="${escapeHtml(editor.returnPage || state.page)}"><article class="sales-document-card"><header class="sales-document-heading"><div><span class="settings-eyebrow">${vendor ? "SUPPLIER PAYMENT" : "CUSTOMER RECEIPT"}</span><h2>${title}</h2></div><span class="sales-currency-tag">Bangladesh · BDT ৳</span></header><section class="sales-document-fields"><div class="sales-field-main"><div class="sales-other-info-grid">${choice}<div class="field"><label>Payment Date</label><input name="date" type="date" value="${inputLocalDate()}" required></div><div class="field"><label>Amount · BDT</label><input name="amount" type="number" min="0.01" step="0.01" value="${invoice ? Number(invoice.amountDue).toFixed(2) : ""}" required></div><div class="field"><label>Journal</label><select name="journal">${paymentJournals.map((journal) => `<option value="${escapeHtml(journal.name)}" ${journal.type === "cash" ? "selected" : ""}>${escapeHtml(journal.name)}</option>`).join("")}</select></div><div class="field"><label>Payment Reference</label><input name="reference" placeholder="Receipt / bank transaction reference"></div></div></div><div class="sales-field-side"><div class="erp-payment-summary"><span>Open balance</span><strong>${salesCurrency(invoice?.amountDue || 0)}</strong><span>Payment reduces ${vendor ? "Accounts Payable" : "Accounts Receivable"}.</span></div></div></section><section class="sales-tab-panel is-active"><p class="erp-accounting-explainer">Registering the payment updates the linked invoice balance and creates a payment line in Accounting. Use Reconcile after matching the bank or cash statement.</p></section><footer class="sales-document-footer"><div class="sales-document-note">The invoice, partner balance and payment journal share the same local accounting records.</div><div class="sales-document-buttons"><button type="button" class="action-button secondary" data-invoice-editor-action="discard">Discard</button><button type="submit" class="action-button">Register Payment</button></div></footer></article></form></main><aside class="erp-finance-chatter"><div class="erp-chatter-actions"><button type="button" class="action-button">Send message</button><button type="button" class="action-button secondary">Log note</button><button type="button" class="action-button secondary">Activity</button></div><div class="erp-chatter-entry"><span>${escapeHtml(initials(state.userProfile.name))}</span><div><strong>${escapeHtml(state.userProfile.name)}</strong><p>Creating a new payment...</p></div></div></aside></div></section>`;
}

