function updateOrderTotal() {
  let subtotal = 0;
  let taxTotal = 0;
  const form = document.querySelector("#order-form");
  if (!form) return 0;
  form.querySelectorAll(".purchase-line").forEach((line) => {
    const qty = Number(line.querySelector("[data-line-qty]")?.value || 0);
    const price = Number(line.querySelector("[data-line-price]")?.value || 0);
    const taxId = Number(line.querySelector("[data-line-tax]")?.value || 0);
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId && item.active);
    const amounts = calculateInvoiceLineAmounts(qty, price, tax);
    subtotal += amounts.subtotal;
    taxTotal += amounts.taxAmount;
    const cell = line.querySelector(".line-subtotal");
    if (cell) cell.textContent = salesCurrency(state.purchaseTaxMode === "included" ? amounts.subtotal + amounts.taxAmount : amounts.subtotal);
  });
  const total = subtotal + taxTotal;
  const subtotalNode = form.querySelector("#order-subtotal");
  const taxNode = form.querySelector("#order-tax-total");
  const totalNode = form.querySelector("#order-total");
  const taxRow = form.querySelector("[data-purchase-tax-row]");
  if (subtotalNode) subtotalNode.textContent = salesCurrency(subtotal);
  if (taxNode) taxNode.textContent = salesCurrency(taxTotal);
  if (totalNode) totalNode.textContent = salesCurrency(total);
  taxRow?.classList.toggle("is-hidden", taxTotal <= 0);
  return { taxExcluded: subtotal, taxAmount: taxTotal, total };
}

function savePurchaseOrder(action) {
  const form = document.querySelector("#order-form");
  if (!form) return;
  const data = new FormData(form);
  const vendor = String(data.get("vendor") || "").trim();
  const registeredSupplier = purchaseSupplierOptions({ includeUnapproved: true })
    .find((supplier) => supplier.name.toLocaleLowerCase() === vendor.toLocaleLowerCase()) || null;
  if (action !== "cancel" && !vendor) { document.querySelector("#order-vendor")?.focus(); showToast("Choose a vendor before saving this RFQ."); return; }
  if (action !== "cancel") {
    if (!registeredSupplier || !isSupplierApproved(registeredSupplier)) { document.querySelector("#order-vendor")?.focus(); showToast("Choose an approved supplier from Contacts before saving this RFQ."); return; }
  }
  const lines = [...form.querySelectorAll("#order-line-items tr")].map((row) => {
    if (row.dataset.lineType) return { type: row.dataset.lineType, description: String(row.querySelector("[data-purchase-description]")?.value || "").trim() };
    const product = salesProducts.find((item) => item.id === Number(row.querySelector("[data-purchase-product]")?.value));
    const qty = Number(row.querySelector("[data-line-qty]")?.value || 0);
    const price = Number(row.querySelector("[data-line-price]")?.value || 0);
    const taxId = Number(row.querySelector("[data-line-tax]")?.value || 0) || null;
    const tax = (state.invoiceConfig.taxes || []).find((item) => item.id === taxId && item.active);
    const amounts = calculateInvoiceLineAmounts(qty, price, tax);
    return { product: product?.name || "", sku: product?.sku || "", uom: row.querySelector("[data-line-uom]")?.value || product?.stockUom || "Piece", qty, price, taxId, taxAmount: amounts.taxAmount, amount: amounts.subtotal + amounts.taxAmount };
  }).filter((line) => line.type ? line.description : line.product && line.qty > 0);
  const productLines = lines.filter((line) => !line.type);
  if (["send", "confirm"].includes(action) && !productLines.length) { showToast("Add at least one product before sending or confirming this order."); document.querySelector("[data-purchase-product]")?.focus(); return; }
  const sums = updateOrderTotal();
  const previous = purchaseOrders.find((item) => item.id === Number(state.purchaseEditor?.id)) || null;
  const previousSnapshot = previous ? { ...previous, lines: (previous.lines || []).map((line) => ({ ...line })) } : null;
  const editorSupplierMatches = String(state.purchaseEditor?.vendor || "").toLowerCase() === vendor.toLowerCase();
  if (action === "cancel" && !previous) { state.purchaseEditor = null; render(); return; }
  if (action === "cancel" && previous) {
    const oldStatus = previous.status;
    previous.status = "Cancelled";
    if (!persistPurchaseOrders()) { previous.status = oldStatus; return; }
    state.purchaseEditor = { id: previous.id, returnPage: state.purchaseEditor?.returnPage || state.page };
    render(); showToast("Purchase Order cancelled."); return;
  }
  const nextStatus = action === "send" ? "RFQ Sent" : action === "confirm" ? "Purchase Order" : action === "cancel" ? "Cancelled" : previous?.status || "RFQ";
  const sequence = purchaseOrders.reduce((max, item) => Math.max(max, Number(String(item.ref || "").replace(/\D/g, "")) || 0), 0) + 1;
  const ref = previous?.ref || `RFQ${String(sequence).padStart(4, "0")}`;
  const record = {
    ...(previous || {}), id: previous?.id || Date.now(), ref, vendor: vendor || previous?.vendor || "", vendorContactId: registeredSupplier?.contactId || (editorSupplierMatches ? state.purchaseEditor?.vendorContactId : null) || state.contacts.find((item) => contactHasSupplierRole(item) && String(item.name || "").toLowerCase() === vendor.toLowerCase())?.id || (String(previous?.vendor || "").toLowerCase() === vendor.toLowerCase() ? previous?.vendorContactId : null) || null,
    vendorReference: String(data.get("vendorReference") || "").trim(), agreement: String(data.get("agreement") || "").trim(), buyer: String(data.get("buyer") || state.userProfile.login || "purchase3").trim(),
    createdAt: previous?.createdAt || new Date().toISOString(),
    confirmedAt: action === "confirm" ? (previous?.confirmedAt || new Date().toISOString()) : (previous?.confirmedAt || ""),
    deadlineDate: String(data.get("deadlineDate") || ""), deadline: purchaseDeadlineLabel(data.get("deadlineDate")), expectedArrival: String(data.get("expectedArrival") || ""),
    arrivalConfirmation: data.get("arrivalConfirmation") === "on", paymentTerms: String(data.get("paymentTerms") || "Immediate"),
    company: String(data.get("company") || "Arafat Chemica"), currency: "BDT", destination: String(data.get("destination") || "Arafat Chemica: Receipts"),
    sourceDocument: String(data.get("sourceDocument") || ""), incoterm: String(data.get("incoterm") || ""), favorite: state.purchaseFavorite,
    notes: String(data.get("notes") || ""), terms: String(data.get("terms") || ""), lines,
    taxExcluded: sums.taxExcluded, taxAmount: sums.taxAmount, total: sums.total, status: nextStatus,
    dateRank: previous?.dateRank ?? 3, activity: previous?.activity || "", late: false,
  };
  if (previous) Object.assign(previous, record); else purchaseOrders.push(record);
  if (!persistPurchaseOrders()) {
    if (previous) { Object.keys(previous).forEach((key) => delete previous[key]); Object.assign(previous, previousSnapshot); }
    else purchaseOrders.splice(purchaseOrders.findIndex((item) => item.id === record.id), 1);
    return;
  }
  if (state.purchaseEditor?.cartPrefill) {
    state.purchaseProductCart = [];
    persistPurchaseProductCart();
  }
  state.purchaseEditor = { id: record.id, returnPage: state.purchaseEditor?.returnPage || state.page };
  render();
  showToast(action === "send" ? "RFQ sent to the selected supplier." : action === "confirm" ? "Purchase Order confirmed." : action === "cancel" ? "Purchase Order cancelled." : "RFQ saved as draft.");
}

