function downloadCsv(filename, rows) {
  const csv = rows.map((row) => row.map((cell) => {
    let value = String(cell ?? "");
    const formulaCandidate = value.replace(/^[\s\u0000\u000b\ufeff]+/u, "");
    if (/^[=+\-@]/.test(formulaCandidate) && !/^-?\d+(?:\.\d+)?$/.test(formulaCandidate)) value = `'${value}`;
    return `"${value.replaceAll('"', '""')}"`;
  }).join(",")).join("\r\n");
  const blob = new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
  URL.revokeObjectURL(link.href);
}

function duplicateInventoryProducts(products) {
  const snapshot = inventorySnapshot();
  const usedReferences = new Set(salesProducts.map((product) => String(product.sku || "").trim().toLowerCase()).filter(Boolean));
  const giftRules = inventoryGiftConfigurations();
  let nextId = Math.max(Date.now(), ...salesProducts.map((product) => Number(product.id) || 0)) + 1;
  const copies = products.map((source) => {
    const copy = inventoryClone(source);
    copy.id = nextId++;
    copy.name = `${String(source.name || "Product").replace(/\s*\(copy(?:\s+\d+)?\)$/i, "")} (copy)`;
    copy.baseName = `${String(source.baseName || source.name || "Product").replace(/\s*\(copy(?:\s+\d+)?\)$/i, "")} (copy)`;
    const referenceBase = String(source.sku || source.name || "PRODUCT").trim().replace(/\s+/g, "-").slice(0, 64);
    let reference = `${referenceBase}-COPY`;
    let suffix = 2;
    while (usedReferences.has(reference.toLowerCase())) reference = `${referenceBase}-COPY-${suffix++}`;
    usedReferences.add(reference.toLowerCase());
    copy.sku = reference;
    copy.barcode = "";
    copy.barcodeAutoGenerated = false;
    copy.skuAutoGenerated = false;
    copy.onHand = 0;
    copy.favorite = false;
    copy.archived = false;
    salesProducts.push(copy);
    const sourceRule = giftRules.find((rule) => String(rule.productId) === String(source.id));
    if (sourceRule) giftRules.push({ ...inventoryClone(sourceRule), id: `GIFT-${copy.id}-${Math.random().toString(36).slice(2, 7)}`, productId: String(copy.id), name: copy.name });
    return copy;
  });
  if (!inventoryCommit(snapshot, { config: true })) return;
  state.selected = new Set(copies.map((product) => Number(product.id)));
  render();
  showToast(`${copies.length} product${copies.length === 1 ? "" : "s"} duplicated with new SKU references and no opening stock.`);
}

function printInventoryProductLabels(products) {
  const labels = products.map((product) => {
    const code = String(product.barcode || product.sku || "").trim().toUpperCase();
    const barcode = code39BarcodeSvg(code);
    return `<article class="product-label"><strong>${escapeHtml(product.name || "Product")}</strong>${barcode || `<div class="label-reference">${escapeHtml(code || "No reference")}</div>`}<span>${escapeHtml(code || "No reference")}</span><small>${salesCurrency(product.price || 0)} · ${escapeHtml(product.stockUom || "Units")}</small></article>`;
  }).join("");
  const printWindow = window.open("", "_blank", "width=860,height=680");
  if (!printWindow) { showToast("Allow pop-ups to print the selected product labels."); return; }
  printWindow.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Product Labels</title><style>@page{margin:10mm}.sheet{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8mm}.product-label{min-width:0;display:grid;justify-items:center;align-content:center;gap:5px;padding:8px;border:1px solid #cbd5dc;text-align:center;font:12px Arial,sans-serif;break-inside:avoid}.product-label strong{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.product-label svg{max-width:100%;height:auto}.product-label span{font-size:10px;letter-spacing:.06em}.product-label small{color:#66717b}.label-reference{font:700 18px monospace;overflow-wrap:anywhere}</style></head><body><main class="sheet">${labels}</main><script>window.addEventListener('load',()=>window.print(),{once:true})<\/script></body></html>`);
  printWindow.document.close();
}

function openContactBulkEditModal(chosen) {
  openModal(`<header class="modal-header"><div><h2>Edit selected contacts</h2><p>Update shared fields for ${chosen.length} selected contact${chosen.length === 1 ? "" : "s"}.</p></div><button class="modal-close" type="button" data-action="close-modal">×</button></header><form id="contacts-bulk-edit-form"><div class="modal-body"><div class="form-grid"><div class="field"><label for="contacts-bulk-country">Country</label><input id="contacts-bulk-country" name="country" maxlength="80" placeholder="Leave blank to keep current value"></div><div class="field"><label for="contacts-bulk-tags">Tags</label><input id="contacts-bulk-tags" name="tags" maxlength="200" placeholder="Leave blank to keep current value"></div></div><p class="form-hint">Only non-empty fields will replace values on the selected contacts.</p></div><footer class="modal-footer"><button class="action-button secondary" type="button" data-action="close-modal">Cancel</button><button class="action-button" type="submit">Update ${chosen.length} contact${chosen.length === 1 ? "" : "s"}</button></footer></form>`, true);
}

function deleteSelectedContacts(chosen) {
  const ids = new Set(chosen.map((contact) => String(contact.id)));
  const removed = state.contacts.filter((contact) => ids.has(String(contact.id)));
  const keys = ["odooContacts", "odooFmcgInvoiceVendors", "odooFmcgSalesCustomers", "odooDeletedSampleVendors"];
  let storage;
  try { storage = Object.fromEntries(keys.map((key) => [key, localStorage.getItem(key)])); }
  catch { showToast("This browser could not read the shared contact directory."); return false; }
  const previousContacts = state.contacts.map((item) => ({ ...item }));
  const previousVendors = vendors.map((item) => ({ ...item }));
  const previousCustomers = state.salesCustomers.map((item) => ({ ...item }));
  const previousDeletedSampleVendorIds = new Set(deletedSampleVendorIds);
  const supplierContacts = removed.filter((contact) => contact.kind === "supplier");
  const dealerContacts = removed.filter((contact) => contact.kind === "dealer");
  const matchesPartner = (partner, contact) => String(partner.contactId || "") === String(contact.id)
    || (String(partner.id) === String(contact.linkedId || contact.id) && String(partner.name || "").toLowerCase() === String(contact.name || "").toLowerCase());
  supplierContacts.forEach((contact) => {
    const vendor = vendors.find((item) => matchesPartner(item, contact));
    if (vendor?.seedId || (vendor && Number(vendor.id) <= 5)) deletedSampleVendorIds.add(String(vendor.seedId || vendor.id));
  });
  state.contacts.splice(0, state.contacts.length, ...state.contacts.filter((contact) => !ids.has(String(contact.id))));
  for (let index = vendors.length - 1; index >= 0; index -= 1) if (supplierContacts.some((contact) => matchesPartner(vendors[index], contact))) vendors.splice(index, 1);
  for (let index = state.salesCustomers.length - 1; index >= 0; index -= 1) if (dealerContacts.some((contact) => matchesPartner(state.salesCustomers[index], contact))) state.salesCustomers.splice(index, 1);
  try {
    localStorage.setItem("odooContacts", JSON.stringify(state.contacts));
    localStorage.setItem("odooFmcgInvoiceVendors", JSON.stringify(vendors));
    localStorage.setItem("odooFmcgSalesCustomers", JSON.stringify(state.salesCustomers));
    localStorage.setItem("odooDeletedSampleVendors", JSON.stringify([...deletedSampleVendorIds]));
    return true;
  } catch {
    state.contacts.splice(0, state.contacts.length, ...previousContacts);
    vendors.splice(0, vendors.length, ...previousVendors);
    state.salesCustomers.splice(0, state.salesCustomers.length, ...previousCustomers);
    deletedSampleVendorIds.clear();
    previousDeletedSampleVendorIds.forEach((id) => deletedSampleVendorIds.add(id));
    keys.forEach((key) => { try { storage[key] === null ? localStorage.removeItem(key) : localStorage.setItem(key, storage[key]); } catch { /* Keep the in-memory contacts if storage is unavailable. */ } });
    showToast("This browser could not save the contact changes.");
    return false;
  }
}

function selectedRecords() {
  if (state.page === "contacts") return state.contacts.filter((item) => state.selected.has(String(item.id)));
  if (["inventory-products", "inventory-stock", "products", "sales-products", "invoice-products"].includes(state.page)) return salesProducts.filter((item) => state.selected.has(Number(item.id)));
  if (state.page === "inventory-categories") return categories.filter((item) => state.selected.has(String(item.id)));
  if (state.page === "inventory-return-reasons") return inventoryConfigRecords(state.page).filter((item) => state.selected.has(String(item.id)));
  if (state.page === "inventory-gift-configurations") return inventoryGiftItems().filter((item) => state.selected.has(String(item.id)));
  if (state.page === "inventory-units") return inventoryUoms.filter((item) => state.selected.has(String(item.id)));
  const list = state.page === "categories" ? categories : purchaseOrders;
  return list.filter((item) => state.selected.has(item.id));
}

function inventoryCategoryDeleteReason(category) {
  if (!category) return "";
  const name = String(category.name || "").toLowerCase();
  if (salesProducts.some((product) => String(product.category || "").toLowerCase() === name)) return "products";
  if (categories.some((item) => String(item.id) !== String(category.id) && String(item.parent || "").toLowerCase() === name)) return "child categories";
  return "";
}

function openInventoryCategoryBulkDeleteConfirmation(records) {
  const selected = records.filter((record) => state.selected.has(String(record.id)));
  const safe = selected.filter((record) => !inventoryCategoryDeleteReason(record));
  const blocked = selected.filter((record) => inventoryCategoryDeleteReason(record));
  state.pendingInventoryCategoryDeleteIds = selected.map((record) => String(record.id));
  const safeList = safe.length ? `<ul class="delete-confirm-list">${safe.map((record) => `<li>${escapeHtml(record.name)}</li>`).join("")}</ul>` : "";
  const blockedList = blocked.length ? `<section class="delete-blocked-products"><strong>Kept because they are still in use</strong><ul>${blocked.map((record) => `<li><b>${escapeHtml(record.name)}</b><span>${escapeHtml(inventoryCategoryDeleteReason(record))}</span></li>`).join("")}</ul></section>` : "";
  const message = safe.length
    ? `${safe.length} selected categor${safe.length === 1 ? "y" : "ies"} will be deleted. Categories used by products or child categories will be kept.`
    : "None of the selected categories can be deleted because products or child categories use them.";
  const buttons = safe.length
    ? `<button type="button" class="delete-confirm-button" data-action="confirm-inventory-category-delete">Delete</button><button type="button" class="action-button secondary" data-action="close-modal">Cancel</button>`
    : `<button type="button" class="action-button secondary" data-action="close-modal">Close</button>`;
  openModal(`<header class="modal-header delete-confirm-header"><div><h2>${safe.length ? "Delete selected categories?" : "Categories still in use"}</h2></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body delete-confirm-body"><p>${message}</p>${safeList}${blockedList}</div><footer class="modal-footer delete-confirm-footer">${buttons}</footer>`, true);
  modalRoot.querySelector(safe.length ? "[data-action='confirm-inventory-category-delete']" : "[data-action='close-modal']")?.focus({ preventScroll: true });
}

function deleteInventoryCategories(ids) {
  const selected = ids.map((id) => categories.find((record) => String(record.id) === String(id))).filter(Boolean);
  const blocked = selected.filter((record) => inventoryCategoryDeleteReason(record));
  const removable = selected.filter((record) => !inventoryCategoryDeleteReason(record));
  if (!removable.length) {
    state.selected = new Set(blocked.map((record) => String(record.id)));
    render();
    showToast("No selected category was deleted because each is still in use.");
    return;
  }
  const snapshot = categories.map((record) => inventoryClone(record));
  let previousStorage;
  try { previousStorage = localStorage.getItem(productCategoryStorageKey); }
  catch { showToast("This browser could not read the saved product categories."); return; }
  const idsToDelete = new Set(removable.map((record) => String(record.id)));
  for (let index = categories.length - 1; index >= 0; index -= 1) if (idsToDelete.has(String(categories[index].id))) categories.splice(index, 1);
  if (!persistProductCategories()) {
    categories.splice(0, categories.length, ...snapshot);
    try { previousStorage === null ? localStorage.removeItem(productCategoryStorageKey) : localStorage.setItem(productCategoryStorageKey, previousStorage); } catch { /* Keep the restored in-memory categories if storage cannot be restored. */ }
    showToast("This browser could not save the category changes.");
    return;
  }
  state.selected = new Set(blocked.map((record) => String(record.id)));
  render();
  showToast(blocked.length
    ? `${removable.length} categor${removable.length === 1 ? "y" : "ies"} deleted; ${blocked.length} kept because they are in use.`
    : `${removable.length} categor${removable.length === 1 ? "y" : "ies"} deleted.`);
}

function productHistoryReasons(product) {
  const sku = String(product?.sku || "");
  const productId = Number(product?.id);
  const lineMatches = (line) => (sku && String(line?.sku || "") === sku) || (Number.isFinite(productId) && Number(line?.productId) === productId);
  const hasLinkedProduct = (record) => (sku && String(record?.sku || "") === sku)
    || (Array.isArray(record?.lines) && record.lines.some(lineMatches));
  const reasons = [];
  const hasStock = Number(product?.onHand || 0) > 0
    || (sku && state.inventoryBalances.some((item) => String(item.sku || "") === sku && Number(item.qty || 0) !== 0));
  if (hasStock) reasons.push("on-hand stock");
  if (state.inventoryMoves.some(hasLinkedProduct)) reasons.push("inventory movements");
  if (state.inventoryCounts.some(hasLinkedProduct)) reasons.push("inventory counts");
  if (purchaseOrders.some(hasLinkedProduct)) reasons.push("purchase orders");
  if (state.purchaseReceipts.some(hasLinkedProduct)) reasons.push("purchase receipts");
  if (state.salesOrders.some(hasLinkedProduct)) reasons.push("sales orders");
  const linkedInvoices = state.invoices.filter(hasLinkedProduct);
  if (linkedInvoices.some((invoice) => String(invoice.kind || "").startsWith("in_"))) reasons.push("vendor bills");
  if (linkedInvoices.some((invoice) => String(invoice.kind || "").startsWith("out_"))) reasons.push("customer invoices");
  return reasons;
}

function productDocumentLineMatches(line, product) {
  if (!line || !product) return false;
  return (product.sku && String(line.sku || "") === String(product.sku))
    || (Number(product.id) && Number(line.productId) === Number(product.id))
    || String(line.product || line.productName || line.name || "").trim().toLowerCase() === String(product.name || "").trim().toLowerCase();
}

function productChannelEnabled(product, channel) {
  const key = ({ sales: "sales", purchase: "purchase", subscriptions: "subscriptions", expenses: "expenses", pos: "pos" })[channel];
  if (!product || !key) return false;
  if (channel === "sales" || channel === "purchase") return product.enabledIn?.[key] !== false;
  return Boolean(product.enabledIn?.[key]);
}

function productChannelRecords(product, channel) {
  if (!product) return [];
  const hasProduct = (record) => productDocumentLineMatches(record, product)
    || (Array.isArray(record?.lines) && record.lines.some((line) => productDocumentLineMatches(line, product)));
  if (channel === "sales") return state.salesOrders.filter(hasProduct);
  if (channel === "purchase") return purchaseOrders.filter(hasProduct);
  if (channel === "subscriptions") return state.inventoryProductSubscriptions.filter((record) => Number(record.productId) === Number(product.id) || String(record.productSku || "") === String(product.sku));
  if (channel === "expenses") return state.invoiceExpenses.filter((record) => Number(record.productId) === Number(product.id) || String(record.productSku || "") === String(product.sku));
  if (channel === "pos") return state.salesOrders.filter((record) => record.salesChannel === "Point of Sale" && hasProduct(record));
  return [];
}

function productChannelTitle(channel) {
  return ({ sales: "Sales", purchase: "Purchase", subscriptions: "Subscriptions", expenses: "Expenses", pos: "Point of Sale" })[channel] || "Product Links";
}

function openInventoryProductChannel(productId, channel) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  if (!product) { showToast("Save this product before opening its linked records."); return; }
  const title = productChannelTitle(channel);
  const rows = productChannelRecords(product, channel);
  const createAction = productChannelEnabled(product, channel)
    ? `<button type="button" class="action-button" data-product-channel-create="${channel}" data-product-id="${product.id}">New ${channel === "sales" ? "Quotation" : channel === "purchase" ? "RFQ" : channel === "pos" ? "POS Order" : channel === "subscriptions" ? "Subscription" : "Expense"}</button>`
    : `<span class="product-channel-disabled-note">Enable ${escapeHtml(title)} on the product to create new records.</span>`;
  let body = "";
  if (channel === "sales" || channel === "pos") {
    body = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th class="money-cell">Total · BDT</th></tr></thead><tbody>${rows.map((row) => `<tr><td><button type="button" class="reference-link" data-open-sale="${row.id}">${escapeHtml(row.ref || "Sales Order")}</button></td><td>${escapeHtml(row.customer || "—")}</td><td>${escapeHtml(row.orderDate || "—")}</td><td>${escapeHtml(row.status || "Quotation")}</td><td class="money-cell">${salesCurrency(row.total || 0)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty-state"><h2>No ${title.toLowerCase()} records linked</h2><p>${channel === "pos" ? "POS orders made from this product are linked to the shared sales and inventory flow." : "New quotations and confirmed orders using this SKU will appear here."}</p></div>`;
  } else if (channel === "purchase") {
    body = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Vendor</th><th>Deadline</th><th>Status</th><th class="money-cell">Total · BDT</th></tr></thead><tbody>${rows.map((row) => `<tr><td><button type="button" class="reference-link" data-open-order="${row.id}">${escapeHtml(row.ref || "RFQ")}</button></td><td>${escapeHtml(row.vendor || "—")}</td><td>${escapeHtml(row.deadlineDate || row.deadline || "—")}</td><td>${escapeHtml(row.status || "RFQ")}</td><td class="money-cell">${salesCurrency(row.total || 0)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty-state"><h2>No purchase records linked</h2><p>RFQs and Purchase Orders using this SKU will appear here.</p></div>`;
  } else if (channel === "subscriptions") {
    body = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Subscription</th><th>Customer</th><th>Recurring</th><th>Start Date</th><th>Status</th></tr></thead><tbody>${rows.map((row) => `<tr><td>${escapeHtml(row.ref)}</td><td>${escapeHtml(row.customer)}</td><td>${salesCurrency(row.recurringAmount)} / ${escapeHtml(row.interval)}</td><td>${escapeHtml(row.startDate)}</td><td>${escapeHtml(row.status)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty-state"><h2>No subscriptions linked</h2><p>Create a recurring subscription line for this product. The record stays linked to the shared product SKU.</p></div>`;
  } else {
    body = rows.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Expense</th><th>Date</th><th>Vendor</th><th>Description</th><th class="money-cell">Amount · BDT</th><th>Status</th></tr></thead><tbody>${rows.map((row) => `<tr><td>${escapeHtml(row.ref || "Expense")}</td><td>${invoiceDateText(row.date)}</td><td>${escapeHtml(row.vendor || "—")}</td><td>${escapeHtml(row.description || product.name)}</td><td class="money-cell">${salesCurrency(row.amount || 0)}</td><td>${escapeHtml(row.status || "Draft")}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty-state"><h2>No expenses linked</h2><p>Expenses recorded against this product are also available in Invoicing → Expenses.</p></div>`;
  }
  openModal(`<header class="modal-header"><div><h2>${escapeHtml(title)} · ${escapeHtml(product.name)}</h2><p>${escapeHtml(product.sku)} · ${rows.length} linked record${rows.length === 1 ? "" : "s"}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body product-channel-records">${body}</div><footer class="modal-footer">${createAction}<button type="button" class="action-button secondary" data-action="close-modal">Close</button></footer>`, true);
}

function openInventoryProductChannelForm(productId, channel) {
  const product = salesProducts.find((item) => Number(item.id) === Number(productId));
  if (!product || !productChannelEnabled(product, channel)) { showToast(`Enable ${productChannelTitle(channel)} on this product first.`); return; }
  const date = inputLocalDate();
  if (channel === "subscriptions") {
    const intervals = ["Monthly", "Quarterly", "Yearly"];
    const contactOptions = state.contacts.map((contact) => `<option value="${escapeHtml(contact.id)}">${escapeHtml(contact.name)}${contact.email ? ` · ${escapeHtml(contact.email)}` : ""}</option>`).join("");
    openModal(`<header class="modal-header"><div><h2>New Subscription</h2><p>${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="inventory-product-subscription-form" data-product-id="${product.id}"><div class="modal-body"><div class="form-grid"><div class="field wide"><label>Customer</label><select name="contactId" required ${state.contacts.length ? "" : "disabled"}><option value="">${state.contacts.length ? "Select a Contact" : "No Contact records available"}</option>${contactOptions}</select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="1" step="1" value="1" required></div><div class="field"><label>Recurring Unit Price · BDT</label><input name="unitPrice" type="number" min="0" step="0.01" value="${Number(product.price || 0)}" required></div><div class="field"><label>Interval</label><select name="interval">${intervals.map((item) => `<option>${item}</option>`).join("")}</select></div><div class="field"><label>Start Date</label><input name="startDate" type="date" value="${date}" required></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Create Subscription</button></footer></form>`, true);
    return;
  }
  if (channel === "expenses") {
    openModal(`<header class="modal-header"><div><h2>New Product Expense</h2><p>${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="inventory-product-expense-form" data-product-id="${product.id}"><div class="modal-body"><div class="form-grid"><div class="field"><label>Date</label><input name="date" type="date" value="${date}" required></div><div class="field"><label>Category</label><input name="category" value="Product Expense" required></div><div class="field"><label>Vendor</label><input name="vendor" value="${escapeHtml(product.supplierName || "")}" placeholder="Supplier / vendor"></div><div class="field"><label>Amount · BDT</label><input name="amount" type="number" min="0" step="0.01" value="${Number(product.cost || 0)}" required></div><div class="field wide"><label>Description</label><input name="description" value="${escapeHtml(`Expense for ${product.name}`)}" required></div></div></div><footer class="modal-footer"><button type="button" class="action-button secondary" data-action="close-modal">Discard</button><button type="submit" class="action-button">Save Expense</button></footer></form>`, true);
  }
}

function openInventoryPosProductChooser() {
  openSharedProductCatalog("pos-picker", { pickerOnly: true, onSelect: (product) => { setPage("sales-orders"); openSalesOrderModal(null, { productId: Number(product.id), channel: "Point of Sale", returnPage: "inventory-pos-orders" }); } });
}

function productHasHistory(product) {
  return productHistoryReasons(product).length > 0;
}

function productDeleteReasons(product) {
  const reasons = productHistoryReasons(product).filter((reason) => reason !== "on-hand stock");
  const sku = String(product?.sku || "");
  const productId = Number(product?.id);
  if (state.inventoryProductSubscriptions.some((record) => Number(record.productId) === productId || (sku && String(record.productSku || "") === sku))) reasons.push("subscriptions");
  if (state.invoiceExpenses.some((record) => Number(record.productId) === productId || (sku && String(record.productSku || "") === sku))) reasons.push("expenses");
  if (inventoryGiftConfigurations().some((rule) => String(rule.productId) === String(product?.id))) reasons.push("gift offer configuration");
  return reasons;
}

function commitProductRemoval(products) {
  if (!products.length) return true;
  const snapshot = inventorySnapshot();
  const ids = new Set(products.map((product) => Number(product.id)));
  const skus = new Set(products.map((product) => String(product.sku || "")).filter(Boolean));
  products.forEach((product) => salesProductDeletedIdentities.add(salesProductPersistentIdentity(product)));
  for (let index = salesProducts.length - 1; index >= 0; index -= 1) {
    if (ids.has(Number(salesProducts[index].id))) salesProducts.splice(index, 1);
  }
  state.inventoryBalances.splice(0, state.inventoryBalances.length, ...state.inventoryBalances.filter((balance) => !skus.has(String(balance.sku || ""))));
  state.inventoryRules.splice(0, state.inventoryRules.length, ...state.inventoryRules.filter((rule) => !skus.has(String(rule.sku || ""))));
  if (!inventoryCommit(snapshot, { rules: true })) return false;
  ids.forEach((id) => state.desktopProductIds.delete(id));
  persistDesktopProductShortcuts();
  ids.forEach((id) => state.selected.delete(id));
  return true;
}

function purgeLegacyDemoProducts() {
  if (isFreshCompanyStart) return;
  const cleanupKey = "odooFmcgLegacyDemoProductsRemovedV1";
  try { if (localStorage.getItem(cleanupKey) === "done") return; } catch { return; }
  const isLegacyDemo = (product) => /^\[DEMO\]/i.test(String(product?.name || ""))
    || /^DEMO-/i.test(String(product?.sku || ""));
  const candidates = salesProducts.filter(isLegacyDemo);
  const deletable = candidates.filter((product) => productDeleteReasons(product).length === 0);
  const protectedCount = candidates.length - deletable.length;
  if (deletable.length && !commitProductRemoval(deletable)) return;
  try { localStorage.setItem(cleanupKey, "done"); } catch { /* Keep the cleanup retryable when storage is unavailable. */ }
  if (deletable.length) showToast(`${deletable.length} unused demo product${deletable.length === 1 ? "" : "s"} removed.`);
  if (protectedCount) showToast(`${protectedCount} demo product${protectedCount === 1 ? "" : "s"} with linked records kept.`);
}

function openProductDeleteConfirmation(deletable, blocked) {
  state.pendingProductDeleteIds = deletable.map((product) => Number(product.id));
  state.pendingProductArchiveIds = blocked.map((product) => Number(product.id));
  const productNames = deletable.length > 1
    ? `<ul class="delete-confirm-list">${deletable.map((product) => `<li>${escapeHtml(product.name)}</li>`).join("")}</ul>`
    : deletable.length ? `<strong class="delete-confirm-single">${escapeHtml(deletable[0].name)}</strong>` : "";
  const blockedList = blocked.length
    ? `<section class="delete-blocked-products"><strong>${deletable.length ? "Kept because linked entries exist" : "These products are still in use"}</strong><ul>${blocked.map((product) => `<li><b>${escapeHtml(product.name)}</b><span>${escapeHtml(productDeleteReasons(product).join(", "))}</span></li>`).join("")}</ul></section>`
    : "";
  const message = deletable.length
    ? `Are you sure you want to delete ${deletable.length} product${deletable.length === 1 ? "" : "s"}? This cannot be undone.`
    : "Products with linked transactions, subscriptions, expenses, or gift configurations cannot be permanently deleted. Remove those links first, or mark the product inactive to keep its history.";
  const buttons = `${deletable.length ? '<button type="button" class="delete-confirm-button" data-action="confirm-product-delete">Delete eligible</button>' : ""}${blocked.length ? '<button type="button" class="action-button secondary" data-action="archive-blocked-products">Mark inactive</button>' : ""}<button type="button" class="action-button secondary" data-action="close-modal">${deletable.length || blocked.length ? "Cancel" : "Close"}</button>`;
  openModal(`<header class="modal-header delete-confirm-header"><div><h2>${deletable.length ? "Delete selected products?" : "Products still in use"}</h2></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body delete-confirm-body"><p>${message}</p>${productNames}${blockedList}</div><footer class="modal-footer delete-confirm-footer">${buttons}</footer>`, true);
  modalRoot.querySelector(deletable.length ? "[data-action='confirm-product-delete']" : blocked.length ? "[data-action='archive-blocked-products']" : "[data-action='close-modal']")?.focus({ preventScroll: true });
}

function openInventoryUomBulkDeleteConfirmation(units) {
  const selected = units.filter((unit) => state.selected.has(String(unit.id)));
  const safe = selected.filter((unit) => !inventoryUomDeleteReason(unit));
  const blocked = selected.filter((unit) => inventoryUomDeleteReason(unit));
  state.pendingInventoryUomDeleteIds = selected.map((unit) => String(unit.id));
  const safeList = safe.length ? `<ul class="delete-confirm-list">${safe.map((unit) => `<li>${escapeHtml(unit.name)}</li>`).join("")}</ul>` : "";
  const blockedList = blocked.length ? `<section class="delete-blocked-products"><strong>Kept because these units are still in use</strong><ul>${blocked.map((unit) => `<li><b>${escapeHtml(unit.name)}</b><span>${escapeHtml(inventoryUomDeleteReason(unit))}</span></li>`).join("")}</ul></section>` : "";
  const message = safe.length
    ? `${safe.length} selected unit${safe.length === 1 ? "" : "s"} will be permanently deleted. Units used by a product or another conversion will be kept.`
    : "None of the selected units can be removed because they are used by products or other unit conversions.";
  const buttons = safe.length
    ? `<button type="button" class="delete-confirm-button" data-action="confirm-uom-delete">Continue</button><button type="button" class="action-button secondary" data-action="close-modal">Cancel</button>`
    : `<button type="button" class="action-button secondary" data-action="close-modal">Close</button>`;
  openModal(`<header class="modal-header delete-confirm-header"><div><h2>${safe.length ? "Remove selected units?" : "Units still in use"}</h2></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body delete-confirm-body"><p>${message}</p>${safeList}${blockedList}</div><footer class="modal-footer delete-confirm-footer">${buttons}</footer>`, true);
  modalRoot.querySelector(safe.length ? "[data-action='confirm-uom-delete']" : "[data-action='close-modal']")?.focus({ preventScroll: true });
}

function deleteInventoryUoms(ids) {
  const chosen = ids.map((id) => inventoryUoms.find((unit) => String(unit.id) === String(id))).filter(Boolean);
  const blocked = chosen.filter((unit) => inventoryUomDeleteReason(unit));
  const removable = chosen.filter((unit) => !inventoryUomDeleteReason(unit));
  if (!removable.length) {
    state.selected = new Set(blocked.map((unit) => String(unit.id)));
    render();
    showToast("No selected unit was removed because each is still in use.");
    return;
  }
  const snapshot = inventoryClone(inventoryUoms), deletedSnapshot = new Set(inventoryUomDeletedIds);
  let previousStorage, previousDeletedStorage;
  try { previousStorage = localStorage.getItem(inventoryUomStorageKey); previousDeletedStorage = localStorage.getItem(inventoryUomDeletedStorageKey); }
  catch { showToast("This browser could not read the saved unit configuration."); return; }
  let deleted = 0;
  removable.forEach((unit) => {
    if (defaultInventoryUoms.some((item) => String(item.id) === String(unit.id))) inventoryUomDeletedIds.add(String(unit.id));
    inventoryUoms.splice(inventoryUoms.indexOf(unit), 1);
    deleted += 1;
  });
  if (!persistInventoryUoms() || !persistInventoryUomDeletedIds()) {
    inventoryUoms.splice(0, inventoryUoms.length, ...snapshot);
    inventoryUomDeletedIds.clear(); deletedSnapshot.forEach((id) => inventoryUomDeletedIds.add(id));
    try { previousStorage === null ? localStorage.removeItem(inventoryUomStorageKey) : localStorage.setItem(inventoryUomStorageKey, previousStorage); previousDeletedStorage === null ? localStorage.removeItem(inventoryUomDeletedStorageKey) : localStorage.setItem(inventoryUomDeletedStorageKey, previousDeletedStorage); } catch { /* Keep the restored in-memory list if storage cannot be restored. */ }
    return;
  }
  state.selected = new Set(blocked.map((unit) => String(unit.id)));
  render();
  const parts = [];
  if (deleted) parts.push(`${deleted} deleted`);
  if (blocked.length) parts.push(`${blocked.length} kept because they are in use`);
  showToast(parts.join("; ") + ".");
}

function deleteProducts(ids) {
  const selectedProducts = ids.map((id) => salesProducts.find((product) => Number(product.id) === Number(id))).filter(Boolean);
  const deletable = selectedProducts.filter((product) => productDeleteReasons(product).length === 0);
  const blocked = selectedProducts.filter((product) => productDeleteReasons(product).length > 0);
  if (!deletable.length) {
    state.selected = new Set(blocked.map((product) => Number(product.id)));
    render();
    if (blocked.length) showToast("No products deleted. Products with stock or linked records were kept.");
    return;
  }
  if (!commitProductRemoval(deletable)) return;
  state.selected = new Set(blocked.map((product) => Number(product.id)));
  render();
  showToast(blocked.length
    ? `${deletable.length} product${deletable.length === 1 ? "" : "s"} deleted; ${blocked.length} kept because linked records still reference them.`
    : `${deletable.length} product${deletable.length === 1 ? "" : "s"} deleted.`);
}

function applyBulkAction(action) {
  const chosen = selectedRecords();
  if (!chosen.length) return;
  if (state.page === "inventory-return-reasons") {
    if (action === "export") {
      downloadCsv("inventory-return-reasons.csv", [["Reason", "Sequence"], ...chosen.map((reason) => [reason.name, Number(reason.sequence ?? 10)])]);
      showToast(`${chosen.length} return reason${chosen.length === 1 ? "" : "s"} exported.`);
      return;
    }
    if (action === "delete") {
      const linked = chosen.filter((reason) => state.inventoryReturnRequests.some((request) => String(request.reasonId) === String(reason.id)));
      const deletable = chosen.filter((reason) => !linked.includes(reason));
      if (!deletable.length) { showToast("Selected reasons are linked to customer return requests and cannot be deleted."); return; }
      if (!window.confirm(`${deletable.length} selected return reason${deletable.length === 1 ? "" : "s"} will be deleted.${linked.length ? ` ${linked.length} linked reason${linked.length === 1 ? " was" : "s were"} kept.` : ""}`)) return;
      const snapshot = inventorySnapshot();
      const records = inventoryConfigRecords(state.page);
      deletable.forEach((reason) => records.splice(records.indexOf(reason), 1));
      if (!inventoryCommit(snapshot, { config: true })) return;
      state.selected = new Set(linked.map((reason) => String(reason.id)));
      render();
      showToast(`${deletable.length} return reason${deletable.length === 1 ? "" : "s"} deleted${linked.length ? `; ${linked.length} linked ${linked.length === 1 ? "reason was" : "reasons were"} kept` : ""}.`);
      return;
    }
    return;
  }
  if (state.page === "inventory-gift-configurations") {
    const linkedCount = (gift) => inventoryGiftConfigurations().filter((rule) => (rule.giftItemIds || []).some((giftId) => String(giftId) === String(gift.id))).length;
    if (action === "edit") {
      if (chosen.length !== 1 || state.selected.size !== 1) { showToast("Select exactly one gift item to edit."); return; }
      inventoryGiftItemForm(chosen[0]);
      return;
    }
    if (action === "archive-gifts" || action === "unarchive-gifts") {
      const snapshot = inventorySnapshot();
      const archived = action === "archive-gifts";
      chosen.forEach((gift) => { gift.archived = archived; });
      if (!inventoryCommit(snapshot, { config: true })) return;
      state.selected.clear();
      render();
      showToast(`${chosen.length} gift item${chosen.length === 1 ? "" : "s"} ${archived ? "archived" : "unarchived"}.`);
      return;
    }
    if (action === "export") {
      downloadCsv("inventory-gift-items.csv", [["Gift Item", "Notes", "Linked Product Rules"], ...chosen.map((gift) => [gift.name, gift.notes || "", linkedCount(gift)])]);
      showToast(`${chosen.length} gift item${chosen.length === 1 ? "" : "s"} exported.`);
      return;
    }
    if (action === "delete") {
      const deletable = chosen.filter((gift) => linkedCount(gift) === 0);
      const linked = chosen.filter((gift) => linkedCount(gift) > 0);
      if (!deletable.length) { showToast("Selected gift items are linked to product offers and cannot be deleted."); return; }
      const message = `${deletable.length} selected gift item${deletable.length === 1 ? "" : "s"} will be deleted.${linked.length ? ` ${linked.length} linked item${linked.length === 1 ? "" : "s"} will be kept because a product offer uses it.` : ""}`;
      if (!window.confirm(message)) return;
      const snapshot = inventorySnapshot();
      const records = inventoryGiftItems();
      deletable.forEach((gift) => records.splice(records.indexOf(gift), 1));
      if (!inventoryCommit(snapshot, { config: true })) return;
      state.selected = new Set(linked.map((gift) => String(gift.id)));
      render();
      showToast(`${deletable.length} gift item${deletable.length === 1 ? "" : "s"} deleted${linked.length ? `; ${linked.length} linked item${linked.length === 1 ? " was" : "s were"} kept` : ""}.`);
      return;
    }
    return;
  }
  if (state.page === "inventory-categories") {
    if (action === "export") {
      openInventoryCategoryExportModal(chosen);
      return;
    }
    if (action === "spreadsheet") { showToast("Spreadsheet insertion is unavailable until a spreadsheet service is connected. Export is ready to use now."); return; }
    if (action === "send-campaign") { showToast("Campaign sending is unavailable until a marketing campaign service is connected."); return; }
    if (action === "duplicate") {
      const snapshotLength = categories.length;
      const existingIds = new Set(categories.map((item) => String(item.id)));
      const existingNames = new Set(categories.map((item) => String(item.name || "").trim().toLocaleLowerCase()));
      let nextId = Date.now();
      const copies = chosen.map((category) => {
        let name = `${category.name} (Copy)`;
        let suffix = 2;
        while (existingNames.has(name.toLocaleLowerCase())) name = `${category.name} (Copy ${suffix++})`;
        existingNames.add(name.toLocaleLowerCase());
        while (existingIds.has(String(nextId))) nextId += 1;
        const copy = inventoryClone(category);
        copy.id = nextId;
        existingIds.add(String(nextId));
        nextId += 1;
        copy.name = name;
        copy.chatter = [];
        return copy;
      });
      categories.push(...copies);
      if (!persistProductCategories()) {
        categories.splice(snapshotLength, copies.length);
        showToast("This browser could not save the duplicated categories.");
        return;
      }
      state.selected.clear();
      render();
      showToast(`${copies.length} categor${copies.length === 1 ? "y" : "ies"} duplicated.`);
      return;
    }
    if (action === "delete") { openInventoryCategoryBulkDeleteConfirmation(chosen); return; }
    return;
  }
  if (state.page === "inventory-units") {
    if (action === "export") {
      downloadCsv("inventory-units.csv", [["Unit Name", "Category", "Type", "Contains", "Reference Unit", "Rounding Precision", "UNSPSC Category"], ...chosen.map((unit) => [unit.name, unit.category, unit.uomType, unit.quantity, unit.referenceUnit, unit.rounding, unit.unspscCategory])]);
      showToast(`${chosen.length} unit${chosen.length === 1 ? "" : "s"} exported.`);
      return;
    }
    if (action === "delete") { openInventoryUomBulkDeleteConfirmation(chosen); return; }
    return;
  }
  if (state.page === "inventory-stock") {
    if (action === "export") {
      const customColumns = state.inventoryStockCustomColumns || [];
      downloadCsv("inventory-stock.csv", [["Product", "Reference", "Product Category", "Cost Method", "Unit Cost", "Total Value", "On Hand", "Carton", "Piece", "Free to Use", "Incoming", "Outgoing", "Forecasted", "Unit", ...customColumns.map((field) => field.name)], ...chosen.map((product) => {
        const onHand = inventoryStockHistoricalQty(product, state.inventoryStockReportDate);
        const incoming = inventoryIncoming(product), outgoing = inventoryOutgoing(product);
        const category = categories.find((item) => String(item.name) === String(product.category));
        const breakdown = inventoryStockCartonBreakdown(product, onHand);
        return [product.name, product.sku, product.category, category?.costingMethod || "standard", product.cost || 0, onHand * Number(product.cost || 0), onHand, breakdown.cartons, breakdown.pieces, Math.max(0, onHand - outgoing), incoming, outgoing, Math.max(0, onHand + incoming - outgoing), product.stockUom || "Units", ...customColumns.map((field) => inventoryStockCustomExportValue(product, field))];
      })]);
      showToast(`${chosen.length} stock row${chosen.length === 1 ? "" : "s"} exported.`);
      return;
    }
    if (action === "spreadsheet") { showToast("Spreadsheet insertion is unavailable until a spreadsheet service is connected. Export is ready to use now."); return; }
    if (action === "send-campaign") { showToast("Campaign sending is unavailable until a marketing campaign service is connected."); return; }
    if (action === "archive-products" || action === "unarchive-products") {
      const snapshot = inventorySnapshot();
      const archived = action === "archive-products";
      chosen.forEach((item) => { item.archived = archived; });
      if (!inventoryCommit(snapshot)) return;
      state.selected.clear(); render(); showToast(`${chosen.length} product${chosen.length === 1 ? "" : "s"} ${archived ? "archived" : "unarchived"}.`);
      return;
    }
    if (action === "delete") {
      const protectedProducts = chosen.filter((product) => productDeleteReasons(product).length > 0);
      const deletableProducts = chosen.filter((product) => productDeleteReasons(product).length === 0);
      openProductDeleteConfirmation(deletableProducts, protectedProducts);
    }
    return;
  }
  if (["inventory-products", "products", "sales-products", "invoice-products"].includes(state.page)) {
    if (action === "export") {
      openInventoryProductExportModal(chosen);
      return;
    }
    if (action === "duplicate") { duplicateInventoryProducts(chosen); return; }
    if (action === "print-labels") { printInventoryProductLabels(chosen); return; }
    if (action === "pricelist-report") {
      downloadCsv("product-pricelist.csv", [["Product", "Internal Reference", "Pricelist", "Minimum Quantity", "Unit Price", "Unit", "Supplier"], ...chosen.flatMap((product) => {
        const prices = Array.isArray(product.pricelistItems) && product.pricelistItems.length ? product.pricelistItems : [{ name: "Sales Price", minimumQuantity: 1, unitPrice: product.price || 0 }];
        return prices.map((price) => [product.name, product.sku, price.name || price.pricelist || "Sales Price", price.minimumQuantity || 1, price.unitPrice ?? product.price ?? 0, product.stockUom || "Units", productPrimarySupplierName(product)]);
      })]);
      showToast("Pricelist report downloaded.");
      return;
    }
    if (action === "spreadsheet") { showToast("Spreadsheet insertion is unavailable until a spreadsheet service is connected. Export is ready to use now."); return; }
    if (action === "barcode-pictures") { showToast("Barcode Lookup is not connected. Product images can still be added from each product form."); return; }
    if (action === "compute-bom-price") { showToast("Bill of Materials price computation is not configured in this inventory workspace yet."); return; }
    if (action === "desktop-products") {
      const previous = new Set(state.desktopProductIds);
      chosen.forEach((item) => state.desktopProductIds.add(Number(item.id)));
      if (!persistDesktopProductShortcuts()) { state.desktopProductIds = previous; return; }
      state.selected.clear(); render(); showToast(`${chosen.length} product shortcut${chosen.length === 1 ? "" : "s"} added to My Desktop.`);
      return;
    }
    if (action === "archive-products" || action === "unarchive-products") {
      const snapshot = inventorySnapshot();
      const archived = action === "archive-products";
      chosen.forEach((item) => { item.archived = archived; });
      if (!inventoryCommit(snapshot)) return;
      state.selected.clear(); render(); showToast(`${chosen.length} product${chosen.length === 1 ? "" : "s"} ${archived ? "archived" : "unarchived"}.`);
      return;
    }
    if (action === "delete") {
      const protectedProducts = chosen.filter((product) => productDeleteReasons(product).length > 0);
      const deletableProducts = chosen.filter((product) => productDeleteReasons(product).length === 0);
      openProductDeleteConfirmation(deletableProducts, protectedProducts);
    }
    return;
  }
  if (state.page === "contacts") {
    if (action === "edit") { openContactBulkEditModal(chosen); return; }
    if (action === "export") {
      downloadCsv("contacts-export.csv", [["Name", "Type", "Email", "Phone", "City / Area", "Country", "Tags", "Approval"], ...chosen.map((item) => [item.name, item.kind, item.email, item.phone, item.city || item.area, item.country, item.tags, item.kind === "supplier" ? (isSupplierApproved(item) ? "Approved" : "Pending") : ""]) ]);
      showToast(`${chosen.length} contact${chosen.length === 1 ? "" : "s"} exported.`);
      return;
    }
    if (action === "delete") {
      if (!window.confirm(`Delete ${chosen.length} selected contact${chosen.length === 1 ? "" : "s"}? Linked suppliers and dealers will also be removed from Purchase and Sales choices. Existing transaction records will remain.`)) return;
      if (!deleteSelectedContacts(chosen)) return;
      state.selected.clear();
      render();
      showToast(`${chosen.length} contact${chosen.length === 1 ? "" : "s"} deleted.`);
    }
    return;
  }
  if (action === "export") {
    const rows = state.page === "categories"
      ? [["Category", "Parent", "Type"], ...chosen.map((item) => [item.name, item.parent, item.type])]
      : [["Reference", "Vendor", "Buyer", "Deadline", "Total", "Status"], ...chosen.map((item) => [item.ref, item.vendor, item.buyer, item.deadline, item.total, item.status])];
    downloadCsv(`${state.page}-export.csv`, rows);
    showToast(`${chosen.length} record${chosen.length === 1 ? "" : "s"} exported.`);
  } else if (action === "spreadsheet") {
    showToast("Spreadsheet integration is not connected in this prototype.");
  } else if (action === "duplicate") {
    if (state.page === "categories") {
      chosen.forEach((item) => categories.push({ ...item, id: Date.now() + Math.random(), name: `${item.name} (copy)` }));
    } else {
      chosen.forEach((item) => purchaseOrders.push({ ...item, id: Date.now() + Math.random(), ref: `RFQ${String(purchaseOrders.length + 1).padStart(4, "0")}`, status: "RFQ" }));
    }
    state.selected.clear();
    render();
    showToast(`${chosen.length} record${chosen.length === 1 ? "" : "s"} duplicated.`);
  } else if (action === "delete") {
    if (!window.confirm(`Delete ${chosen.length} selected record${chosen.length === 1 ? "" : "s"}?`)) return;
    const ids = new Set(chosen.map((item) => item.id));
    if (state.page === "categories") {
      for (let index = categories.length - 1; index >= 0; index -= 1) if (ids.has(categories[index].id)) categories.splice(index, 1);
    } else {
      for (let index = purchaseOrders.length - 1; index >= 0; index -= 1) if (ids.has(purchaseOrders[index].id)) purchaseOrders.splice(index, 1);
    }
    state.selected.clear();
    render();
    showToast("Selected records deleted from this demo session.");
  }
}

function importCsv(file) {
  const reader = new FileReader();
  reader.onload = () => {
    const lines = String(reader.result || "").split(/\r?\n/).filter(Boolean);
    if (lines.length < 2) { showToast("The CSV has no rows to import."); return; }
    const parseLine = (line) => line.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)?.map((item) => item.replace(/,$/, "").replace(/^"|"$/g, "").replaceAll('""', '"')) || line.split(",");
    const headers = parseLine(lines[0]).map((value) => value.trim().toLowerCase());
    let imported = 0;
    for (const line of lines.slice(1)) {
      const cells = parseLine(line);
      const get = (key, fallback = "") => cells[headers.indexOf(key)] || fallback;
      const rawTotal = Number(get("total", "0").replace(/[,$]/g, "")) || 0;
      const ref = get("reference", `RFQ${String(purchaseOrders.length + 1).padStart(4, "0")}`);
      purchaseOrders.push({ id: Date.now() + imported, ref, vendor: get("vendor", "New Vendor"), buyer: get("buyer", "purchase3"), deadline: get("deadline", "Not set"), dateRank: 3, activity: "", total: rawTotal, status: get("status", "RFQ"), late: false });
      imported += 1;
    }
    closeModal();
    setPage("rfq");
    showToast(`${imported} request${imported === 1 ? "" : "s"} imported for this session.`);
  };
  reader.onerror = () => showToast("The selected CSV could not be read.");
  reader.readAsText(file);
}

