    if (!state.inventoryStockFilters) state.inventoryStockFilters = new Set();
    if (state.inventoryStockFilters.has(key)) state.inventoryStockFilters.delete(key);
    else {
      const exclusive = { goods: "services", services: "goods", cp: "noncp", noncp: "cp", giftConfigured: "giftMissing", giftMissing: "giftConfigured" };
      if (exclusive[key]) state.inventoryStockFilters.delete(exclusive[key]);
      state.inventoryStockFilters.add(key);
    }
    state.inventoryStockFiltersOpen = true;
    state.selected.clear();
