    state.inventoryStockSavedSearches.push(record);
    try { localStorage.setItem("odooFmcgStockSavedSearches", JSON.stringify(state.inventoryStockSavedSearches)); }
    catch { state.inventoryStockSavedSearches.pop(); showToast("Saved search could not be stored in this browser."); return; }
    state.inventoryStockFiltersOpen = true;
