    state.inventoryProductPage = 0;
    state.productTypeFilter = "goods";
    state.productFavoriteFilter = "all";
    state.productGroupBy = "";
    state.productPromotionFilter = "all";
    state.productGiftOfferFilter = "all";
    state.productGiftItemFilter = "all";
    state.inventoryProductAppFilters = new Set();
    state.inventoryProductCustomFilters = [];
    state.inventoryProductCustomMatch = "all";
    state.inventoryProductCustomIncludeArchived = false;
