    const template = document.querySelector(`#sales-product-form template[data-product-row-template="${key}"]`);
    const body = document.querySelector(`#sales-product-form [data-product-rows="${key}"]`);
    if (template && body) { body.append(template.content.cloneNode(true)); body.lastElementChild?.querySelector("input,select")?.focus(); }
