      const promotionEnabled = form.querySelector('[name="promotionType"]:checked')?.value === "cp";
      list.insertAdjacentHTML("beforeend", inventoryConsumerOfferEditorRowMarkup({ name: `Offer ${list.children.length + 1}`, unitPrice: price }, list.children.length, price, promotionEnabled));
      list.lastElementChild?.querySelector("[data-consumer-offer-name]")?.focus();
      updateSalesProductConfigurationOverview(form);
      syncSalesProductSaveState(form);
