    if (list?.children.length <= 1) { showToast("Keep at least one consumer offer for this product."); return; }
    const offerId = String(removeConsumerOffer.closest("[data-consumer-offer-row]")?.dataset.offerId || "");
    const productId = Number(form?.dataset.id || 0);
    const product = salesProducts.find((item) => Number(item.id) === productId);
    const referenced = offerId && product && state.salesOrders.some((order) => (order.lines || []).some((line) => !line.type && line.sku === product.sku && String(line.consumerOfferId || "") === offerId));
    if (referenced) { showToast("This consumer offer is used by a saved quotation or sales order. Keep it to preserve the offer history."); return; }
    removeConsumerOffer.closest("[data-consumer-offer-row]")?.remove();
    updateSalesProductConfigurationOverview(form);
    syncSalesProductSaveState(form);
    return;
