  const creditAccountSelect = event.target.closest("[data-credit-account-select]");
  if (creditAccountSelect) {
    const picker = modalRoot.querySelector(".credit-account-picker-modal");
    const context = picker?.dataset.creditAccountContext || "line";
    const index = picker?.dataset.creditAccountIndex || "0";
    const code = String(creditAccountSelect.dataset.code || "");
    const name = String(creditAccountSelect.dataset.name || "");
    const selector = context === "journal" ? "[data-credit-journal-row]" : ".credit-note-invoice-line";
    const indexAttribute = context === "journal" ? "data-journal-index" : "data-credit-row-index";
    const targetRow = [...document.querySelectorAll(selector)].find((row) => String(row.dataset[indexAttribute === "data-journal-index" ? "journalIndex" : "creditRowIndex"]) === String(index));
    const accountInput = targetRow?.querySelector(context === "journal" ? "[data-credit-journal-account]" : "[data-credit-account-code]");
    const accountButton = targetRow?.querySelector("[data-credit-account-picker]");
    if (accountInput) accountInput.value = code;
    if (accountButton) accountButton.textContent = `${code} ${name}`;
    closeModal();
    if (context === "line") updateInvoiceTotal();
    return;
  }
  const createCreditAccount = event.target.closest("[data-credit-account-create]");
