function inventoryXlsxBytesFromRows(rows) {
  const encoder = new TextEncoder();
  const xml = (value) => String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&apos;");
  const columnName = (index) => {
    let name = "";
    for (let value = index + 1; value > 0; value = Math.floor((value - 1) / 26)) name = String.fromCharCode(65 + ((value - 1) % 26)) + name;
    return name;
  };
  const worksheetRows = rows.map((row, rowIndex) => `<row r="${rowIndex + 1}">${row.map((value, columnIndex) => {
    const reference = `${columnName(columnIndex)}${rowIndex + 1}`;
    if (typeof value === "number" && Number.isFinite(value)) return `<c r="${reference}"><v>${value}</v></c>`;
    if (typeof value === "boolean") return `<c r="${reference}" t="b"><v>${value ? 1 : 0}</v></c>`;
    return `<c r="${reference}" t="inlineStr"><is><t xml:space="preserve">${xml(value)}</t></is></c>`;
  }).join("")}</row>`).join("");
  const files = [
    ["[Content_Types].xml", '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],
    ["_rels/.rels", '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
    ["xl/workbook.xml", '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Products" sheetId="1" r:id="rId1"/></sheets></workbook>'],
    ["xl/_rels/workbook.xml.rels", '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],
    ["xl/worksheets/sheet1.xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${worksheetRows}</sheetData></worksheet>`],
  ].map(([name, contents]) => ({ name: encoder.encode(name), contents: encoder.encode(contents) }));
  const crcTable = new Uint32Array(256);
  for (let n = 0; n < 256; n += 1) { let value = n; for (let bit = 0; bit < 8; bit += 1) value = (value & 1) ? (0xedb88320 ^ (value >>> 1)) : (value >>> 1); crcTable[n] = value >>> 0; }
  const crc32 = (bytes) => { let crc = 0xffffffff; for (const byte of bytes) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8); return (crc ^ 0xffffffff) >>> 0; };
  const localRecords = [];
  const centralRecords = [];
  let localOffset = 0;
  let centralSize = 0;
  files.forEach(({ name, contents }) => {
    const crc = crc32(contents);
    const local = new Uint8Array(30 + name.length);
    const localView = new DataView(local.buffer);
    localView.setUint32(0, 0x04034b50, true); localView.setUint16(4, 20, true); localView.setUint16(6, 0, true); localView.setUint16(8, 0, true);
    localView.setUint16(10, 0, true); localView.setUint16(12, 33, true); localView.setUint32(14, crc, true); localView.setUint32(18, contents.length, true);
    localView.setUint32(22, contents.length, true); localView.setUint16(26, name.length, true); localView.setUint16(28, 0, true); local.set(name, 30);
    localRecords.push(local, contents);
    const central = new Uint8Array(46 + name.length);
    const centralView = new DataView(central.buffer);
    centralView.setUint32(0, 0x02014b50, true); centralView.setUint16(4, 20, true); centralView.setUint16(6, 20, true); centralView.setUint16(8, 0, true);
    centralView.setUint16(10, 0, true); centralView.setUint16(12, 0, true); centralView.setUint16(14, 33, true); centralView.setUint32(16, crc, true);
    centralView.setUint32(20, contents.length, true); centralView.setUint32(24, contents.length, true); centralView.setUint16(28, name.length, true);
    centralView.setUint16(30, 0, true); centralView.setUint16(32, 0, true); centralView.setUint16(34, 0, true); centralView.setUint16(36, 0, true);
    centralView.setUint32(38, 0, true); centralView.setUint32(42, localOffset, true); central.set(name, 46);
    centralRecords.push(central); centralSize += central.length; localOffset += local.length + contents.length;
  });
  const centralOffset = localOffset;
  const end = new Uint8Array(22);
  const endView = new DataView(end.buffer);
  endView.setUint32(0, 0x06054b50, true); endView.setUint16(4, 0, true); endView.setUint16(6, 0, true);
  endView.setUint16(8, files.length, true); endView.setUint16(10, files.length, true); endView.setUint32(12, centralSize, true);
  endView.setUint32(16, centralOffset, true); endView.setUint16(20, 0, true);
  return new Blob([...localRecords, ...centralRecords, end], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
}

function downloadXlsx(filename, rows) {
  const link = document.createElement("a");
  link.href = URL.createObjectURL(inventoryXlsxBytesFromRows(rows));
  link.download = filename;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

function inventoryProductImportExportRow(product) {
  const offers = inventoryProductConsumerOffers(product, Number(product.price || 0));
  const giftName = (id) => inventoryGiftItems().find((item) => String(item.id) === String(id))?.name || String(id);
  const attributes = product.attributeLines?.length
    ? product.attributeLines
    : String(product.attributes || "").split(";").map((entry) => {
      const [attribute, ...values] = entry.split(":");
      return { attribute: String(attribute || "").trim(), values: values.join(":").trim() };
    }).filter((row) => row.attribute);
  const exported = {
    "Product": product.name || "", "Reference": product.sku || "", "Category": product.category || "",
    "Product Class": product.productClass || (product.promotionType === "cp" ? "CP" : product.promotionType === "non-cp" ? "Non-CP" : ""),
    "Carton Size": product.cartonSize || "",
    "Carton Price": product.cartonPrice ?? product.unitConversions?.find((row) => /^carton$/i.test(String(row.unit || "")))?.salePrice ?? (/^carton$/i.test(String(product.purchaseUom || "")) ? Number(product.price || 0) * Number(product.purchaseUnitQuantity || 0) : ""),
    "Units per Carton": product.unitsPerCarton ?? (/^carton$/i.test(String(product.purchaseUom || "")) ? product.purchaseUnitQuantity : ""),
    "Supplier": productPrimarySupplierName(product) || "", "Sales Price": product.price ?? 0, "Cost": product.cost ?? 0,
    "Stock Unit": product.stockUom || "Units", "Status": product.archived ? "Inactive" : "Active", "Currency": "BDT", "Cost Currency": "BDT",
    "Product Type": product.productType === "service" ? "Service" : product.productType === "combo" ? "Combo" : "Goods",
    "Barcode": product.barcode || product.sku || "", "Variant Label": product.variantLabel || "", "Include Category In Title": product.includeCategoryInTitle ? "Yes" : "No", "Promotion Type": salesProductPromotionType(product).toUpperCase(),
    "Offer Name": offers[0]?.name || "Standard offer", "Offer Price": offers[0]?.unitPrice ?? product.price ?? 0,
    "Gift Items": (offers[0]?.giftItemIds || []).map(giftName).join("; "), "Gift Selection Mode": offers[0]?.giftSelectionMode || "fixed",
    "Consumer Offers JSON": JSON.stringify(offers.map((offer) => ({ name: offer.name, unitPrice: offer.unitPrice, giftItems: offer.giftItemIds.map(giftName), giftSelectionMode: offer.giftSelectionMode }))),
    "Purchase Unit": product.purchaseUom || product.stockUom || "Units", "Purchase Unit Quantity": product.purchaseUnitQuantity ?? 1,
    "Purchase Unit Price": product.purchaseUnitPrice ?? product.cost ?? 0, "Net Content Value": product.netContentValue ?? "", "Net Content Unit": product.netContentUnit || "g",
    "Unit Conversions JSON": JSON.stringify(product.unitConversions || []), "Vendor Prices JSON": JSON.stringify(product.vendorPrices || []),
    "Pricelist Items JSON": JSON.stringify(product.pricelistItems || []), "Attributes JSON": JSON.stringify(attributes),
    "Track Inventory": product.inventoryEnabled !== false ? "Yes" : "No", "Tracking": product.tracking || "By Quantity", "Favorite": product.favorite ? "Yes" : "No",
    "Sales Enabled": product.enabledIn?.sales !== false ? "Yes" : "No", "Purchase Enabled": product.enabledIn?.purchase !== false ? "Yes" : "No",
    "Subscriptions Enabled": product.enabledIn?.subscriptions ? "Yes" : "No", "Expenses Enabled": product.enabledIn?.expenses ? "Yes" : "No", "POS Enabled": product.enabledIn?.pos ? "Yes" : "No",
    "Company": product.company || "", "Description": product.description || "", "Purchase Description": product.purchaseDescription || "",
    "Sales Description": product.salesDescription || "", "Sales Packaging": product.salesPackaging || "", "Sales Options": product.salesOptions || "",
    "Sales Accessories": product.salesAccessories || "", "Sales Similar": product.salesSimilar || "", "Invoice Policy": product.invoicePolicy || "",
    "Vendor Bill Control": product.vendorBillControl || "", "Inventory Responsible": product.inventoryResponsible || "", "Dropship": product.routeDropship ? "Yes" : "No",
    "Weight": product.weight ?? "", "Volume": product.volume ?? "", "Delivery Time": product.deliveryTime ?? "", "Version": product.version || "",
    "Receipt Description": product.receiptDescription || "", "Delivery Description": product.deliveryDescription || "", "Transfer Description": product.transferDescription || "",
    "Sales Tax ID": product.salesTaxId ?? "", "Purchase Tax ID": product.purchaseTaxId ?? "", "Vendor Lead Time": product.vendorLeadTime ?? "",
    "Minimum Order Qty": product.minimumOrderQty ?? "", "Reinvoice Costs": product.reinvoiceCosts || "", "Rental Period": product.rentalPeriod || "",
    "Gelato Template Reference": product.gelatoTemplateReference || "", "Website Category": product.websiteCategory || "", "Website Description": product.websiteDescription || "",
    "Website Published": product.websitePublished ? "Yes" : "No", "Avatax Category": product.avataxCategory || "", "Avatax Parameters JSON": JSON.stringify(product.avataxParameters || []),
    "Commodity Code": product.commodityCode || "", "Country of Origin": product.countryOfOrigin || "", "Invoice Email Template": product.invoiceEmailTemplate || "",
    "UNSPSC Category": product.unspscCategory || "", "Income Account": product.incomeAccount || "", "Expense Account": product.expenseAccount || "",
    "Tags": (product.tags || []).join("; "),
  };
  return inventoryProductImportColumns.map((column) => exported[column] ?? "");
}

