const inventoryCategoryExportTemplatesKey = "odooFmcgCategoryExportTemplates";
let inventoryCategoryExportDraft = null;
let inventoryCategoryExportRecords = [];

function inventoryCategoryExportTemplates() {
  try {
    const templates = JSON.parse(localStorage.getItem(inventoryCategoryExportTemplatesKey) || "[]");
    return Array.isArray(templates) ? templates.filter((item) => item && typeof item.name === "string" && Array.isArray(item.fields)) : [];
  } catch { return []; }
}

function inventoryCategoryExportTemplateOptions(selectedId = "") {
  return `<option value="">Select a template...</option>${inventoryCategoryExportTemplates().map((item) => `<option value="${escapeHtml(item.id)}" ${String(item.id) === String(selectedId) ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}`;
}

function inventoryCategoryExportField(key) { return inventoryCategoryExportFields.find((field) => field.key === key); }

function inventoryCategoryExportAvailableMarkup(query = "") {
  const normalizedQuery = String(query || "").trim().toLocaleLowerCase();
  const fields = inventoryCategoryExportFields.filter((field) => (!inventoryCategoryExportDraft?.updateableOnly || field.updateable)
    && (!normalizedQuery || field.label.toLocaleLowerCase().includes(normalizedQuery) || field.group.toLocaleLowerCase().includes(normalizedQuery)));
  const groups = [...new Set(fields.map((field) => field.group))];
  return groups.map((group) => `<section class="inventory-product-export-field-group"><h3>${escapeHtml(group)}</h3>${fields.filter((field) => field.group === group).map((field) => {
    const selected = inventoryCategoryExportDraft.fields.includes(field.key);
    return `<div class="inventory-product-export-available-row"><span>${escapeHtml(field.label)}${inventoryCategoryExportDraft.updateableOnly ? '<small>can be updated</small>' : ""}</span><button type="button" data-category-export-add="${escapeHtml(field.key)}" aria-label="Add ${escapeHtml(field.label)}" ${selected ? "disabled" : ""}>+</button></div>`;
  }).join("")}</section>`).join("") || '<span class="inventory-product-export-empty">No fields match this search.</span>';
}

function renderInventoryCategoryExportFields() {
  const modal = document.querySelector("#modal-root .modal-card");
  if (!modal || !inventoryCategoryExportDraft) return;
  const available = modal.querySelector("[data-category-export-available]");
  const selected = modal.querySelector("[data-category-export-selected]");
  const template = modal.querySelector("[data-category-export-template]");
  if (available) available.innerHTML = inventoryCategoryExportAvailableMarkup(modal.querySelector("[data-category-export-search]")?.value || "");
  if (selected) selected.innerHTML = inventoryCategoryExportDraft.fields.map((key, index) => {
    const field = inventoryCategoryExportField(key);
    if (!field) return "";
    return `<li draggable="true" data-category-export-field="${escapeHtml(key)}" data-category-export-index="${index}"><span class="inventory-product-export-drag" aria-hidden="true">↕</span><span>${escapeHtml(field.label)}${field.updateable ? '<small>updatable</small>' : '<small>read-only</small>'}</span><button type="button" data-category-export-remove="${escapeHtml(key)}" aria-label="Remove ${escapeHtml(field.label)}">${icon("trash")}</button></li>`;
  }).join("") || '<li class="inventory-product-export-empty">Add category fields from the list.</li>';
  if (template) template.innerHTML = inventoryCategoryExportTemplateOptions(inventoryCategoryExportDraft.templateId);
  const deleteTemplate = modal.querySelector("[data-action='inventory-category-export-delete-template']");
  if (deleteTemplate) deleteTemplate.disabled = !inventoryCategoryExportDraft.templateId;
}

function openInventoryCategoryExportModal(records = null) {
  closeMenus();
  inventoryCategoryExportRecords = records || categories.filter((category) => [...state.selected].some((id) => String(id) === String(category.id)));
  inventoryCategoryExportDraft = { fields: ["displayName"], updateableOnly: false, format: "xlsx", templateId: "" };
  openModal(`<header class="modal-header"><div><h2>Export Data</h2><p>Choose category fields to export for the selected records.</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Close">×</button></header><form id="inventory-category-export-form"><div class="modal-body inventory-product-export-body"><div class="inventory-product-export-grid"><section class="inventory-product-export-pane"><header><div class="inventory-category-export-available-heading"><h3>Available fields</h3><label class="inventory-category-export-updatable"><input type="checkbox" data-category-export-updatable><span>Updatable fields only</span></label></div><input type="search" data-category-export-search placeholder="Search..." aria-label="Search available category fields"></header><div class="inventory-product-export-available" data-category-export-available></div></section><section class="inventory-product-export-pane"><header><h3>Fields to export</h3><label class="inventory-product-export-template-label"><span>Template:</span><select aria-label="Export template" data-category-export-template>${inventoryCategoryExportTemplateOptions()}</select></label><button type="button" class="action-button tertiary inventory-category-export-template-save" data-action="inventory-category-export-save-template" aria-label="Save template" title="Save current fields as a template">${icon("upload")}</button><button type="button" class="action-button tertiary inventory-category-export-template-delete" data-action="inventory-category-export-delete-template" aria-label="Delete template" title="Delete selected template" disabled>${icon("trash")}</button></header><ol class="inventory-product-export-selected" data-category-export-selected aria-label="Fields to export"></ol></section></div><label class="inventory-category-export-format"><span>Format</span><select name="format"><option value="xlsx">Excel Workbook (.xlsx)</option><option value="csv">CSV</option></select></label></div><footer class="modal-footer"><button type="submit" class="action-button">Export</button><button type="button" class="action-button secondary" data-action="close-modal">Close</button></footer></form>`, false);
  document.querySelector("#modal-root .modal-card")?.classList.add("inventory-product-export-modal-card", "inventory-category-export-modal-card");
  renderInventoryCategoryExportFields();
}

function inventoryCategoryExportValues(category) {
  const parent = String(category.parent || "").trim();
  const parentRecord = categories.find((item) => String(item.name || "").toLocaleLowerCase() === parent.toLocaleLowerCase());
  const completeNameFor = (item, visited = new Set()) => {
    const key = String(item.id ?? item.name);
    if (visited.has(key)) return String(item.name || "");
    visited.add(key);
    const parentName = String(item.parent || "").trim();
    const parentItem = parentName && !/^product category$/i.test(parentName)
      ? categories.find((record) => String(record.name || "").toLocaleLowerCase() === parentName.toLocaleLowerCase())
      : null;
    if (parentItem) return `${completeNameFor(parentItem, visited)} / ${item.name}`;
    return parentName && !/^product category$/i.test(parentName) ? `${parentName} / ${item.name}` : String(item.name || "");
  };
  const completeName = completeNameFor(category);
  const products = salesProducts.filter((product) => String(product.category || "").toLocaleLowerCase() === String(category.name || "").toLocaleLowerCase()).length;
  const children = categories.filter((item) => String(item.parent || "").toLocaleLowerCase() === String(category.name || "").toLocaleLowerCase()).map((item) => item.name).join("; ");
  const values = {
    id: category.id ?? "", externalId: category.externalId || category.xmlId || "", name: category.name || "", displayName: category.name || "",
    completeName, parent: parentRecord ? parentRecord.name : parent || "", type: category.type || "Goods", active: category.active === false ? "No" : "Yes",
    company: category.company || "All Companies", productCount: products, childCategories: children,
    costingMethod: category.costingMethod || "standard", inventoryValuation: category.inventoryValuation || "periodic",
    forceRemovalStrategy: category.forceRemovalStrategy || "", reservePackagings: category.reservePackagings || "full",
    routes: Array.isArray(category.routes) ? category.routes.join("; ") : String(category.routes || ""), avataxCategory: category.avataxCategory || "", incomeAccount: category.incomeAccount || "",
    expenseAccount: category.expenseAccount || "", invoicesToIssueAccount: category.invoicesToIssueAccount || "",
    invoicedNotDeliveredAccount: category.invoicedNotDeliveredAccount || "", billsToReceiveAccount: category.billsToReceiveAccount || "",
    billedNotReceivedAccount: category.billedNotReceivedAccount || "", stockAccount: category.stockAccount || "",
    stockVariationAccount: category.stockVariationAccount || "", attachmentCount: Number(category.attachmentCount || 0),
    hasMessage: Array.isArray(category.chatter) && category.chatter.length ? "Yes" : "No",
  };
  return values;
}

function exportInventoryCategories(form) {
  const fields = [...(inventoryCategoryExportDraft?.fields || [])];
  if (!fields.length) { showToast("Choose at least one category field to export."); return; }
  if (!inventoryCategoryExportRecords.length) { showToast("There are no selected categories to export."); return; }
  const labels = fields.map((key) => inventoryCategoryExportField(key).label);
  const rows = [labels, ...inventoryCategoryExportRecords.map((category) => {
    const values = inventoryCategoryExportValues(category);
    return fields.map((key) => values[key] ?? "");
  })];
  const format = form.querySelector("[name='format']")?.value || "xlsx";
  if (format === "csv") downloadCsv("inventory-categories.csv", rows); else downloadXlsx("inventory-categories.xlsx", rows);
  closeModal();
  showToast(`${inventoryCategoryExportRecords.length} categor${inventoryCategoryExportRecords.length === 1 ? "y" : "ies"} exported with ${fields.length} field${fields.length === 1 ? "" : "s"}.`);
}

let inventoryProductExportDraft = null;
let inventoryProductExportScopeProducts = { selected: [], filtered: [], all: [] };
const inventoryProductExportTemplatesKey = "odooFmcgProductExportTemplates";

function inventoryProductExportTemplates() {
  try {
    const templates = JSON.parse(localStorage.getItem(inventoryProductExportTemplatesKey) || "[]");
    return Array.isArray(templates) ? templates.filter((item) => item && typeof item.name === "string" && Array.isArray(item.fields)) : [];
  } catch { return []; }
}

function inventoryProductExportTemplateOptions(selectedId = "") {
  return `<option value="">Custom field selection</option>${inventoryProductExportTemplates().map((item) => `<option value="${escapeHtml(item.id)}" ${String(item.id) === String(selectedId) ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}`;
}

function inventoryProductExportLabel(field) {
  return field === "Sales Price" ? "Piece Price" : field;
}

function inventoryProductExportAvailableMarkup(query = "") {
  const normalizedQuery = String(query || "").trim().toLocaleLowerCase();
  const known = new Set(inventoryProductExportGroups.flatMap(([, fields]) => fields));
  const groups = [...inventoryProductExportGroups, ["Other product fields", inventoryProductImportColumns.filter((field) => !known.has(field))]];
  return groups.map(([group, fields]) => {
    const visible = fields.filter((field) => !normalizedQuery || field.toLocaleLowerCase().includes(normalizedQuery) || inventoryProductExportLabel(field).toLocaleLowerCase().includes(normalizedQuery));
    if (!visible.length) return "";
    return `<section class="inventory-product-export-field-group"><h3>${escapeHtml(group)}</h3>${visible.map((field) => {
      const selected = inventoryProductExportDraft.fields.includes(field);
      const locked = inventoryProductExportDraft.compatible && inventoryProductExportRequiredFields.includes(field);
      return `<div class="inventory-product-export-available-row"><span>${escapeHtml(inventoryProductExportLabel(field))}${locked ? '<small>required for safe re-import</small>' : ""}</span><button type="button" data-product-export-add="${escapeHtml(field)}" aria-label="Add ${escapeHtml(inventoryProductExportLabel(field))}" ${selected || locked ? "disabled" : ""}>+</button></div>`;
    }).join("")}</section>`;
  }).join("") || '<span class="inventory-product-export-empty">No fields match this search.</span>';
}

function renderInventoryProductExportFields() {
  const modal = document.querySelector("#modal-root .modal-card");
  if (!modal || !inventoryProductExportDraft) return;
  const available = modal.querySelector("[data-product-export-available]");
  const selected = modal.querySelector("[data-product-export-selected]");
  const template = modal.querySelector("[data-product-export-template]");
  if (available) available.innerHTML = inventoryProductExportAvailableMarkup(modal.querySelector("[data-product-export-search]")?.value || "");
  if (selected) selected.innerHTML = inventoryProductExportDraft.fields.map((field, index) => {
    const locked = inventoryProductExportDraft.compatible && inventoryProductExportRequiredFields.includes(field);
    return `<li draggable="${locked ? "false" : "true"}" data-product-export-field="${escapeHtml(field)}" data-product-export-index="${index}"><span class="inventory-product-export-drag" aria-hidden="true">↕</span><span>${escapeHtml(inventoryProductExportLabel(field))}${locked ? '<small>required</small>' : ""}</span><button type="button" data-product-export-remove="${escapeHtml(field)}" aria-label="Remove ${escapeHtml(inventoryProductExportLabel(field))}" ${locked ? "disabled title=\"Required in a re-importable export\"" : ""}>${icon("trash")}</button></li>`;
  }).join("") || '<li class="inventory-product-export-empty">Add product fields from the list.</li>';
  if (template) template.innerHTML = inventoryProductExportTemplateOptions(inventoryProductExportDraft.templateId);
  const scope = modal.querySelector("[data-product-export-scope]");
  if (scope) scope.innerHTML = `${inventoryProductExportScopeProducts.selected.length ? `<option value="selected" ${inventoryProductExportDraft.scope === "selected" ? "selected" : ""}>Selected products (${inventoryProductExportScopeProducts.selected.length})</option>` : ""}<option value="filtered" ${inventoryProductExportDraft.scope === "filtered" ? "selected" : ""}>Current filtered products (${inventoryProductExportScopeProducts.filtered.length})</option><option value="all" ${inventoryProductExportDraft.scope === "all" ? "selected" : ""}>All products (${inventoryProductExportScopeProducts.all.length})</option>`;
  const deleteTemplate = modal.querySelector("[data-action='inventory-product-export-delete-template']");
  if (deleteTemplate) deleteTemplate.disabled = !inventoryProductExportDraft.templateId;
}

