function exportInventoryProducts(form) {
  let fields = [...(inventoryProductExportDraft?.fields || [])];
  const compatible = Boolean(form.querySelector("[name='compatible']")?.checked);
  if (compatible) fields = [...inventoryProductExportRequiredFields, ...fields.filter((field) => !inventoryProductExportRequiredFields.includes(field))];
  if (!fields.length) { showToast("Choose at least one product field to export."); return; }
  const scope = form.querySelector("[data-product-export-scope]")?.value || "filtered";
  const products = scope === "selected" ? inventoryProductExportScopeProducts.selected : scope === "all" ? inventoryProductExportScopeProducts.all : inventoryProductExportScopeProducts.filtered;
  if (!products.length) { showToast("There are no products in this export scope."); return; }
  const rows = [fields.map(inventoryProductExportLabel), ...products.map((product) => {
    const exported = inventoryProductImportExportRow(product);
    return fields.map((field) => exported[inventoryProductImportColumns.indexOf(field)] ?? "");
  })];
  const format = form.querySelector("[name='format']:checked")?.value || "xlsx";
  if (format === "csv") downloadCsv("inventory-products.csv", rows); else downloadXlsx("inventory-products.xlsx", rows);
  closeModal();
  showToast(`${products.length} product${products.length === 1 ? "" : "s"} exported with ${fields.length} field${fields.length === 1 ? "" : "s"}.`);
}

let inventoryProductImportPreview = null;
let inventoryProductImportMapping = [];
let inventoryProductImportMappingFileKey = "";
let inventoryProductImportOverrides = new Map();
let inventoryProductImportSelectedRows = new Set();

async function inventoryInflateZipEntry(compressed, method, uncompressedSize) {
  if (uncompressedSize > 25 * 1024 * 1024) throw new Error("Workbook sheet is too large to import.");
  if (method === 0) return new TextDecoder().decode(compressed);
  if (method !== 8 || typeof DecompressionStream !== "function") throw new Error("This browser cannot read the selected Excel workbook.");
  const stream = new Blob([compressed]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
  const expanded = await new Response(stream).arrayBuffer();
  if (expanded.byteLength > 25 * 1024 * 1024) throw new Error("Workbook sheet is too large to import.");
  return new TextDecoder().decode(expanded);
}

async function inventoryReadXlsxRows(file) {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let eocd = -1;
  for (let offset = Math.max(0, bytes.length - 65557); offset <= bytes.length - 22; offset += 1) {
    if (view.getUint32(offset, true) === 0x06054b50) eocd = offset;
  }
  if (eocd < 0) throw new Error("This is not a valid .xlsx workbook.");
  const entryCount = view.getUint16(eocd + 10, true);
  let centralOffset = view.getUint32(eocd + 16, true);
  const decoder = new TextDecoder();
  const entries = new Map();
  for (let index = 0; index < entryCount; index += 1) {
    if (view.getUint32(centralOffset, true) !== 0x02014b50) throw new Error("The Excel workbook could not be opened.");
    const flags = view.getUint16(centralOffset + 8, true);
    const method = view.getUint16(centralOffset + 10, true);
    const compressedSize = view.getUint32(centralOffset + 20, true);
    const uncompressedSize = view.getUint32(centralOffset + 24, true);
    const nameLength = view.getUint16(centralOffset + 28, true);
    const extraLength = view.getUint16(centralOffset + 30, true);
    const commentLength = view.getUint16(centralOffset + 32, true);
    const localOffset = view.getUint32(centralOffset + 42, true);
    const name = decoder.decode(bytes.subarray(centralOffset + 46, centralOffset + 46 + nameLength));
    if (flags & 1) throw new Error("Password-protected workbooks are not supported.");
    if (/^xl\/(?:worksheets\/sheet\d+\.xml|sharedStrings\.xml)$/i.test(name)) {
      if (view.getUint32(localOffset, true) !== 0x04034b50) throw new Error("The Excel workbook could not be opened.");
      const localNameLength = view.getUint16(localOffset + 26, true);
      const localExtraLength = view.getUint16(localOffset + 28, true);
      const dataStart = localOffset + 30 + localNameLength + localExtraLength;
      entries.set(name, { compressed: bytes.slice(dataStart, dataStart + compressedSize), method, uncompressedSize });
    }
    centralOffset += 46 + nameLength + extraLength + commentLength;
  }
  const sheetName = [...entries.keys()].filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/i.test(name)).sort()[0];
  if (!sheetName) throw new Error("No worksheet was found in this workbook.");
  const mainNs = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
  const sharedXml = entries.has("xl/sharedStrings.xml") ? await inventoryInflateZipEntry(entries.get("xl/sharedStrings.xml").compressed, entries.get("xl/sharedStrings.xml").method, entries.get("xl/sharedStrings.xml").uncompressedSize) : "";
  const sharedDocument = sharedXml ? new DOMParser().parseFromString(sharedXml, "application/xml") : null;
  if (sharedDocument?.querySelector("parsererror")) throw new Error("The workbook strings could not be read.");
  const sharedStrings = sharedDocument ? [...sharedDocument.getElementsByTagNameNS(mainNs, "si")].map((item) => [...item.getElementsByTagNameNS(mainNs, "t")].map((node) => node.textContent || "").join("")) : [];
  const sheetEntry = entries.get(sheetName);
  const sheetXml = await inventoryInflateZipEntry(sheetEntry.compressed, sheetEntry.method, sheetEntry.uncompressedSize);
  const sheet = new DOMParser().parseFromString(sheetXml, "application/xml");
  if (sheet.querySelector("parsererror")) throw new Error("The worksheet could not be read.");
  const columnIndex = (reference) => {
    const letters = String(reference || "").match(/^[A-Z]+/i)?.[0]?.toUpperCase() || "";
    return [...letters].reduce((sum, letter) => sum * 26 + letter.charCodeAt(0) - 64, 0) - 1;
  };
  return [...sheet.getElementsByTagNameNS(mainNs, "row")].map((row) => {
    const cells = [...row.getElementsByTagNameNS(mainNs, "c")];
    const values = [];
    cells.forEach((cell) => {
      const type = cell.getAttribute("t");
      const index = columnIndex(cell.getAttribute("r"));
      const valueNode = cell.getElementsByTagNameNS(mainNs, "v")[0];
      let value = valueNode?.textContent || "";
      if (type === "s") value = sharedStrings[Number(value)] || "";
      else if (type === "inlineStr") value = [...cell.getElementsByTagNameNS(mainNs, "t")].map((node) => node.textContent || "").join("");
      else if (type === "b") value = value === "1" ? "true" : "false";
      values[index] = value;
    });
    return values;
  }).filter((row) => row.some((value) => String(value || "").trim()));
}

