async function importInventoryStockCounts(form) {
  const file = form.querySelector("input[type='file']")?.files?.[0];
  if (!file) { showToast("Choose a CSV file to import."); return; }
  let rows;
  try { rows = parseCsvRows(await file.text()); }
  catch { showToast("The selected CSV could not be read."); return; }
  if (rows.length < 2) { showToast("The CSV has no stock count rows."); return; }
  const headers = rows[0].map((value) => String(value).trim().toLowerCase());
  const skuIndex = headers.findIndex((value) => ["sku", "internal reference"].includes(value));
  const countIndex = headers.findIndex((value) => ["counted", "counted quantity", "quantity"].includes(value));
  const locationIndex = headers.indexOf("location");
  const referenceIndex = headers.indexOf("reference");
  if (skuIndex < 0 || countIndex < 0) { showToast("The CSV needs SKU and Counted columns."); return; }
  const staged = [];
  const keys = new Set();
  for (const [index, row] of rows.slice(1).entries()) {
    const sku = String(row[skuIndex] || "").trim();
    const product = salesProducts.find((item) => String(item.sku || "").toLowerCase() === sku.toLowerCase());
    const rawCount = String(row[countIndex] || "").replaceAll(",", "").trim();
    const counted = Number(rawCount);
    const location = String(locationIndex >= 0 ? row[locationIndex] || "WH/Stock" : "WH/Stock").trim() || "WH/Stock";
    const key = `${sku.toLowerCase()}::${location.toLowerCase()}`;
    if (!product) { showToast(`Row ${index + 2}: SKU “${sku || "blank"}” was not found.`); return; }
    if (!rawCount || !inventoryQuantityValid(counted, product.stockUom || "Units", { allowZero: true })) { showToast(`Row ${index + 2}: enter a valid counted quantity in ${product.stockUom || "the stock unit"}.`); return; }
    if (keys.has(key)) { showToast(`Row ${index + 2}: this SKU and location appear more than once.`); return; }
    keys.add(key);
    staged.push({ product, counted, location, reference: String(referenceIndex >= 0 ? row[referenceIndex] || "" : "").trim() });
  }
  if (!staged.length) { showToast("The CSV has no usable stock counts."); return; }
  const snapshot = inventorySnapshot();
  const keysToReplace = new Set(staged.map(({ product, location }) => `${product.sku}::${location}`));
  state.inventoryCounts = state.inventoryCounts.filter((item) => !keysToReplace.has(`${item.sku}::${item.location || "WH/Stock"}`));
  const timestamp = Date.now();
  staged.forEach(({ product, counted, location, reference }, index) => state.inventoryCounts.push({ id: timestamp + index, sku: product.sku, product: product.name, location, counted, reference, scheduledDate: inputLocalDate(), user: state.userProfile?.login || "Current User" }));
  if (!inventoryPersistCounts()) { inventoryRestore(snapshot); return; }
  closeModal(); setPage("inventory-adjustments");
  showToast(`${staged.length} physical count${staged.length === 1 ? "" : "s"} imported as drafts. Review before applying.`);
}

function addInventoryStockToDashboard(name) {
  const cleanName = String(name || "").trim();
  if (!cleanName) { showToast("Enter a name for the dashboard link."); return; }
  const existing = state.dashboardRecords.find((record) => record.name.toLowerCase() === cleanName.toLowerCase());
  if (existing) {
    if (existing.type !== "inventory-stock") { showToast("A different dashboard already uses this name. Choose another name."); return; }
    closeMenus(); showToast(`${cleanName} is already linked to your dashboard.`); return;
  }
  const section = state.dashboardSections.includes("Logistics") ? "Logistics" : state.dashboardSections[0] || "Logistics";
  if (!state.dashboardSections.includes(section)) state.dashboardSections.push(section);
  const record = { id: `inventory-stock-${Date.now()}`, name: cleanName, section, accessGroup: "All Users", allowedUsers: "", published: true, type: "inventory-stock" };
  state.dashboardRecords.push(record);
  if (!persistDashboardRecords()) { state.dashboardRecords.pop(); return; }
  if (!persistDashboardSections()) { state.dashboardRecords.pop(); persistDashboardRecords(); return; }
  closeMenus();
  showToast(`${cleanName} added to Dashboards → ${section}.`);
}

