document.addEventListener("change", (event) => {
  if (!event.target.matches("[data-contact-chatter-attachment]")) return;
  const input = event.target;
  const file = input.files?.[0];
  const contact = state.contacts.find((item) => String(item.id) === String(state.contactEditor?.id));
  if (!file) return;
  if (!contact) { input.value = ""; showToast("Save the contact before adding an attachment."); return; }
  if (file.size > 1024 * 1024) { input.value = ""; showToast("Contact attachments must be 1 MB or smaller in this local workspace."); return; }
  input.disabled = true;
  const reader = new FileReader();
  reader.onload = () => {
    const attachment = { id: `attachment-${Date.now()}`, name: file.name, type: file.type || "application/octet-stream", size: file.size, data: String(reader.result || ""), addedAt: new Date().toISOString() };
    if (!attachment.data) { input.disabled = false; input.value = ""; showToast("This attachment could not be read."); return; }
    if (!persistPartnerContact({ ...contact, attachments: [...(Array.isArray(contact.attachments) ? contact.attachments : []), attachment] })) { input.disabled = false; input.value = ""; return; }
    render();
    showToast(`${file.name} attached to this contact.`);
  };
  reader.onerror = () => { input.disabled = false; input.value = ""; showToast("This attachment could not be read."); };
  reader.readAsDataURL(file);
});
