document.addEventListener("click", (event) => {
  const sharedProductView = event.target.closest("[data-shared-product-view]");
  if (sharedProductView) {
    const viewKey = sharedProductView.dataset.viewKey;
    if (!["purchase", "sales", "invoice"].includes(viewKey)) return;
    state.sharedProductCatalogViews[viewKey] = sharedProductView.dataset.view === "list" ? "list" : "kanban";
    render();
    return;
  }
  const sharedProductCategory = event.target.closest("[data-shared-product-category]");
  if (sharedProductCategory) {
    const filterKey = sharedProductCategory.dataset.filterKey;
    if (!["purchaseProductCategoryFilter", "salesProductCategoryFilter", "invoiceProductCategoryFilter"].includes(filterKey)) return;
    state[filterKey] = sharedProductCategory.dataset.category || "all";
    state.selected.clear();
    render();
    return;
  }
  const addCategoryField = event.target.closest("[data-category-export-add]");
  if (addCategoryField && inventoryCategoryExportDraft) {
    const field = addCategoryField.dataset.categoryExportAdd;
    if (!inventoryCategoryExportDraft.fields.includes(field)) inventoryCategoryExportDraft.fields.push(field);
    renderInventoryCategoryExportFields();
    return;
  }
  const removeCategoryField = event.target.closest("[data-category-export-remove]");
  if (removeCategoryField && inventoryCategoryExportDraft) {
    inventoryCategoryExportDraft.fields = inventoryCategoryExportDraft.fields.filter((field) => field !== removeCategoryField.dataset.categoryExportRemove);
    renderInventoryCategoryExportFields();
    return;
  }
  const categoryExportAction = event.target.closest("[data-action]")?.dataset.action;
  if (categoryExportAction === "inventory-category-export-save-template") {
    if (!inventoryCategoryExportDraft?.fields.length) { showToast("Choose fields before saving a template."); return; }
    const name = String(window.prompt("Name this category export template:") || "").trim();
    if (!name) return;
    const templates = inventoryCategoryExportTemplates();
    const id = `category-export-${Date.now()}`;
    templates.push({ id, name, fields: [...inventoryCategoryExportDraft.fields], updateableOnly: inventoryCategoryExportDraft.updateableOnly });
    try { localStorage.setItem(inventoryCategoryExportTemplatesKey, JSON.stringify(templates)); }
    catch { showToast("This browser could not save the category export template."); return; }
    inventoryCategoryExportDraft.templateId = id;
    renderInventoryCategoryExportFields();
    showToast(`Export template “${name}” saved in this browser.`);
    return;
  }
  if (categoryExportAction === "inventory-category-export-delete-template") {
    if (!inventoryCategoryExportDraft?.templateId) return;
    const templates = inventoryCategoryExportTemplates().filter((item) => String(item.id) !== String(inventoryCategoryExportDraft.templateId));
    try { localStorage.setItem(inventoryCategoryExportTemplatesKey, JSON.stringify(templates)); }
    catch { showToast("This browser could not update category export templates."); return; }
    inventoryCategoryExportDraft.templateId = "";
    renderInventoryCategoryExportFields();
    showToast("Export template deleted.");
    return;
  }
  const addField = event.target.closest("[data-product-export-add]");
  if (addField && inventoryProductExportDraft) {
    const field = addField.dataset.productExportAdd;
    if (!inventoryProductExportDraft.fields.includes(field)) inventoryProductExportDraft.fields.push(field);
    renderInventoryProductExportFields();
    return;
  }
  const removeField = event.target.closest("[data-product-export-remove]");
  if (removeField && inventoryProductExportDraft) {
    const field = removeField.dataset.productExportRemove;
    if (!(inventoryProductExportDraft.compatible && inventoryProductExportRequiredFields.includes(field))) inventoryProductExportDraft.fields = inventoryProductExportDraft.fields.filter((item) => item !== field);
    renderInventoryProductExportFields();
    return;
  }
  const action = event.target.closest("[data-action]")?.dataset.action;
  if (["inventory-product-import-apply-selected", "inventory-product-import-apply-all"].includes(action) && inventoryProductImportPreview) {
    const applyToAll = action === "inventory-product-import-apply-all";
    const targets = inventoryProductImportPreview.rows.filter((row) => applyToAll || inventoryProductImportSelectedRows.has(row.rowNumber));
    if (!targets.length) { showToast("আগে এক বা একাধিক row টিক দিন, অথবা সব row-তে প্রয়োগ করুন।"); return; }
    const category = document.querySelector("[data-product-import-bulk-category]")?.value || "";
    const productClass = document.querySelector("[data-product-import-bulk-class]")?.value || "";
    if (!category && !productClass) { showToast("Category অথবা Product Class বেছে নিন।"); return; }
    targets.forEach((row) => {
      const override = inventoryProductImportOverrides.get(row.rowNumber) || {};
      if (category) { override.category = category; row.category = category; row.values.category = category; if (!row.provided.includes("category")) row.provided.push("category"); }
      if (productClass) { override.productClass = productClass; row.values.productClass = productClass; if (!row.provided.includes("productClass")) row.provided.push("productClass"); }
      inventoryProductImportOverrides.set(row.rowNumber, override);
    });
    renderInventoryProductImportPreview(inventoryProductImportPreview);
    showToast(`${targets.length} row-এ Category / Class প্রয়োগ হয়েছে।`);
    return;
  }
  if (action === "inventory-product-import-generate-references" && inventoryProductImportPreview) {
    const blankRows = inventoryProductImportPreview.rows.filter((row) => !row.sku);
    if (!blankRows.length) { showToast("সব row-তে Reference আছে।"); return; }
    const used = new Set(salesProducts.map((product) => normalizeProductIdentity(product.sku)));
    inventoryProductImportPreview.rows.forEach((row) => { if (row.sku) used.add(normalizeProductIdentity(row.sku)); });
    const prefix = `IMP-${Date.now().toString(36).toUpperCase()}`;
    let sequence = 1;
    blankRows.forEach((row) => {
      let reference = "";
      do { reference = `${prefix}-${String(sequence++).padStart(3, "0")}`; } while (used.has(normalizeProductIdentity(reference)));
      used.add(normalizeProductIdentity(reference));
      const override = inventoryProductImportOverrides.get(row.rowNumber) || {};
      override.reference = reference;
      inventoryProductImportOverrides.set(row.rowNumber, override);
    });
    const mode = document.querySelector("#inventory-product-import-mode");
    if (mode?.value === "update-only") mode.value = "upsert";
    const file = document.querySelector("#inventory-product-import-file")?.files?.[0];
    if (file) void prepareInventoryProductImportPreview(file);
    showToast(`${blankRows.length}টি unique Reference তৈরি হয়েছে; এগুলো নতুন product হিসেবে যাবে।`);
    return;
  }
  if (action === "inventory-product-export-save-template") {
    if (!inventoryProductExportDraft?.fields.length) { showToast("Choose fields before saving a template."); return; }
    const name = String(window.prompt("Name this product export template:") || "").trim();
    if (!name) return;
    const templates = inventoryProductExportTemplates();
    const id = `product-export-${Date.now()}`;
    templates.push({ id, name, fields: [...inventoryProductExportDraft.fields] });
    try { localStorage.setItem(inventoryProductExportTemplatesKey, JSON.stringify(templates)); }
    catch { showToast("This browser could not save the export template."); return; }
    inventoryProductExportDraft.templateId = id;
    renderInventoryProductExportFields();
    showToast(`Export template “${name}” saved in this browser.`);
    return;
  }
  if (action === "inventory-product-export-delete-template") {
    if (!inventoryProductExportDraft?.templateId) return;
    const templates = inventoryProductExportTemplates().filter((item) => String(item.id) !== String(inventoryProductExportDraft.templateId));
    try { localStorage.setItem(inventoryProductExportTemplatesKey, JSON.stringify(templates)); }
    catch { showToast("This browser could not update export templates."); return; }
    inventoryProductExportDraft.templateId = "";
    renderInventoryProductExportFields();
    showToast("Export template deleted.");
    return;
  }
  if (action === "inventory-product-import") { openInventoryProductImportModal(); return; }
  if (action === "inventory-product-import-template") { downloadInventoryProductImportTemplate(); return; }
  if (action === "inventory-product-website-import") { openInventoryProductWebsiteImportModal(); return; }
  if (action === "inventory-product-website-scan") { scanInventoryProductWebsite(event.target.closest("[data-action='inventory-product-website-scan']")); return; }
  if (action === "inventory-product-submenu") {
    const menu = event.target.closest(".toolbar-more-menu");
    const submenu = menu?.querySelector(`[data-inventory-product-submenu="${event.target.closest("[data-action='inventory-product-submenu']")?.dataset.submenu}"]`);
    if (submenu) submenu.hidden = !submenu.hidden;
    return;
  }
  if (action === "inventory-product-copy-link") {
    if (navigator.clipboard?.writeText) navigator.clipboard.writeText(window.location.href).then(() => showToast("Product menu link copied for your spreadsheet.")).catch(() => showToast("Copy the current browser address to link this product list in a spreadsheet."));
    else showToast("Copy the current browser address to link this product list in a spreadsheet.");
    return;
  }
  if (action === "inventory-product-dashboard") { addInventoryProductsToDashboard(); return; }
  if (action === "inventory-product-knowledge") { openInventoryProductsKnowledge(); }
});
