document.addEventListener("change", (event) => {
  if (event.target.id !== "todo-import-file") return;
  const file = event.target.files?.[0];
  event.target.value = "";
  if (!file) return;
  file.text().then((contents) => {
    const rows = contents.split(/\r?\n/).filter((line) => line.trim());
    if (rows.length < 2) { showToast("The CSV file has no to-do rows."); return; }
    const parseLine = (line) => { const values = []; let value = "", quoted = false; for (let i = 0; i < line.length; i += 1) { const char = line[i]; if (char === '"' && line[i + 1] === '"' && quoted) { value += '"'; i += 1; } else if (char === '"') quoted = !quoted; else if (char === "," && !quoted) { values.push(value); value = ""; } else value += char; } values.push(value); return values; };
    const headers = parseLine(rows.shift()).map((name) => name.trim().toLocaleLowerCase());
    const indexOf = (...names) => headers.findIndex((header) => names.includes(header));
    const titleIndex = indexOf("title", "to-do title", "todo title");
    if (titleIndex < 0) { showToast("CSV needs a Title column."); return; }
    const stageIndex = indexOf("stage", "column");
    const deadlineIndex = indexOf("deadline", "due date");
    const tagIndex = indexOf("tag", "tags");
    const descriptionIndex = indexOf("description", "summary");
    const imported = rows.map(parseLine).map((values) => {
      const title = String(values[titleIndex] || "").trim();
      if (!title) return null;
      const foundStage = stageIndex < 0 ? null : state.todoStages.find((stage) => stage.name.toLocaleLowerCase() === String(values[stageIndex] || "").trim().toLocaleLowerCase());
      return { id: `todo-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, title, stageId: foundStage?.id || "inbox", deadline: deadlineIndex < 0 ? "" : String(values[deadlineIndex] || "").trim(), tag: tagIndex < 0 ? "" : String(values[tagIndex] || "").trim(), description: descriptionIndex < 0 ? "" : String(values[descriptionIndex] || "").trim(), priority: 0, assignees: [], reminder: false, createdAt: new Date().toISOString() };
    }).filter(Boolean);
    if (!imported.length) { showToast("The CSV did not contain any usable to-dos."); return; }
    state.todoItems.unshift(...imported);
    if (!persistTodoData()) { state.todoItems.splice(0, imported.length); return; }
    render(); showToast(`${imported.length} to-do${imported.length === 1 ? "" : "s"} imported.`);
  }).catch(() => showToast("The CSV file could not be read."));
});
