function updateInventoryListDrag(event, drag = state.inventoryListDrag) {
  if (!drag || event.pointerId !== drag.pointerId) return;
  event.preventDefault();
  drag.preview.style.left = `${event.clientX - drag.grabOffsetX}px`;
  drag.preview.style.top = `${event.clientY - drag.grabOffsetY}px`;
  const tableRect = drag.table.getBoundingClientRect();
  const bodyRect = drag.tbody.getBoundingClientRect();
  const inside = event.clientX >= tableRect.left && event.clientX <= tableRect.right && event.clientY >= bodyRect.top && event.clientY <= bodyRect.bottom;
  drag.dropTargetValid = inside;
  drag.placeholder.classList.toggle("is-active", inside);
  if (!inside) return;
  const targetRows = [...drag.tbody.querySelectorAll("[data-inventory-sort-row]")];
  const before = targetRows.find((row) => event.clientY < row.getBoundingClientRect().top + row.getBoundingClientRect().height / 2);
  if (before) before.before(drag.placeholder);
  else drag.tbody.append(drag.placeholder);
}

function finishInventoryListDrag(commitDrop, event = null) {
  const drag = state.inventoryListDrag;
  if (!drag || (event && event.pointerId !== drag.pointerId)) return;
  if (event && commitDrop) updateInventoryListDrag(event, drag);
  const shouldDrop = commitDrop && drag.dropTargetValid;
  drag.preview.remove();
  if (shouldDrop) drag.placeholder.replaceWith(drag.row);
  else {
    if (drag.originalNextSibling?.parentElement === drag.tbody) drag.originalNextSibling.before(drag.row);
    else drag.tbody.append(drag.row);
    drag.placeholder.remove();
  }
  drag.grip.setAttribute("aria-grabbed", "false");
  document.body.classList.remove("is-inventory-list-dragging");
  state.inventoryListDrag = null;
  if (!shouldDrop) return;
  const ids = [...drag.tbody.querySelectorAll("[data-inventory-sort-row]")].map((row) => row.dataset.inventorySortRow);
  if (ids.length === drag.originalIds.length && ids.every((id, index) => id === drag.originalIds[index])) return;
  let idsToSave = ids;
  if (drag.listKey === "inventory-products") {
    const fullOrder = inventoryStoredListOrder("inventory-products", salesProducts).map((product) => String(product.id));
    const movedIds = new Set(drag.originalIds.map(String));
    const positions = fullOrder.map((id, index) => movedIds.has(id) ? index : -1).filter((index) => index >= 0);
    if (positions.length === ids.length) positions.forEach((position, index) => { fullOrder[position] = ids[index]; });
    idsToSave = fullOrder;
  } else if (drag.listKey === "inventory-return-reasons") {
    const snapshot = inventorySnapshot();
    const records = inventoryConfigRecords("inventory-return-reasons");
    const orderedRecords = inventoryStoredListOrder(drag.listKey, records.filter((record) => record.active !== false).sort((left, right) => Number(left.sequence ?? 10) - Number(right.sequence ?? 10)).map((record) => ({ ...record, sortId: record.id })));
    const fullOrder = orderedRecords.map((record) => String(record.id));
    const movedIds = new Set(drag.originalIds.map(String));
    const positions = fullOrder.map((id, index) => movedIds.has(id) ? index : -1).filter((index) => index >= 0);
    if (positions.length !== ids.length) { render(); return; }
    positions.forEach((position, index) => { fullOrder[position] = ids[index]; });
    const reasonById = new Map(records.map((record) => [String(record.id), record]));
    fullOrder.forEach((id, index) => { const reason = reasonById.get(id); if (reason) reason.sequence = (index + 1) * 10; });
    if (!inventoryCommit(snapshot, { config: true })) { render(); return; }
    idsToSave = fullOrder;
  }
  if (!persistInventoryListOrder(drag.listKey, idsToSave)) { render(); return; }
  state.selected.clear();
  render();
  showToast("List order updated.");
}

document.addEventListener("pointerdown", (event) => {
  const grip = event.target.closest("[data-inventory-sort-grip]");
  if (!grip || event.button !== 0) return;
  const row = grip.closest("[data-inventory-sort-row]");
  const tbody = row?.closest("tbody");
  const table = row?.closest("[data-inventory-sortable-list]");
  if (!row || !tbody || !table || state.inventoryListDrag) return;
  event.preventDefault();
  const rowRect = row.getBoundingClientRect();
  const preview = document.createElement("div");
  preview.className = "inventory-sort-drag-preview";
  preview.style.width = `${rowRect.width}px`;
  preview.style.gridTemplateColumns = [...row.cells].map((cell) => `${cell.getBoundingClientRect().width}px`).join(" ");
  [...row.cells].forEach((cell) => {
    const previewCell = document.createElement("div");
    previewCell.className = `inventory-sort-drag-preview-cell ${cell.className}`;
    previewCell.innerHTML = cell.innerHTML;
    preview.append(previewCell);
  });
  document.body.append(preview);
  const placeholder = document.createElement("tr");
  placeholder.className = "inventory-sort-drop-slot";
  placeholder.innerHTML = `<td colspan="${row.cells.length}"><div class="inventory-sort-drop-indicator"></div></td>`;
  placeholder.style.height = `${rowRect.height}px`;
  const originalNextSibling = row.nextElementSibling;
  const originalIds = [...tbody.querySelectorAll("[data-inventory-sort-row]")].map((item) => item.dataset.inventorySortRow);
  row.replaceWith(placeholder);
  state.inventoryListDrag = { row, grip, tbody, table, preview, placeholder, originalNextSibling, originalIds, listKey: table.dataset.inventorySortableList, pointerId: event.pointerId, grabOffsetX: event.clientX - rowRect.left, grabOffsetY: event.clientY - rowRect.top, dropTargetValid: false };
  grip.setAttribute("aria-grabbed", "true");
  document.body.classList.add("is-inventory-list-dragging");
  updateInventoryListDrag(event);
});
document.addEventListener("pointermove", (event) => updateInventoryListDrag(event));
document.addEventListener("pointerup", (event) => finishInventoryListDrag(true, event));
document.addEventListener("pointercancel", (event) => finishInventoryListDrag(false, event));
