function updateInventoryWarehouseDrag(event, drag = state.inventoryWarehouseDrag) {
  if (!drag || event.pointerId !== drag.pointerId) return;
  event.preventDefault();
  drag.preview.style.left = `${event.clientX - drag.grabOffsetX}px`;
  drag.preview.style.top = `${event.clientY - drag.grabOffsetY}px`;
  const listRect = drag.table.getBoundingClientRect();
  const bodyRect = drag.tbody.getBoundingClientRect();
  const inside = event.clientX >= listRect.left && event.clientX <= listRect.right && event.clientY >= bodyRect.top && event.clientY <= bodyRect.bottom;
  drag.dropTargetValid = inside;
  drag.placeholder.classList.toggle("is-active", inside);
  if (!inside) return;
  const targetRows = [...drag.tbody.querySelectorAll("[data-inventory-warehouse-row]")];
  const before = targetRows.find((row) => event.clientY < row.getBoundingClientRect().top + row.getBoundingClientRect().height / 2);
  if (before) before.before(drag.placeholder);
  else drag.tbody.append(drag.placeholder);
}

function finishInventoryWarehouseDrag(commitDrop, event = null) {
  const drag = state.inventoryWarehouseDrag;
  if (!drag || (event && event.pointerId !== drag.pointerId)) return;
  if (event && commitDrop) updateInventoryWarehouseDrag(event, drag);
  const shouldDrop = commitDrop && drag.dropTargetValid;
  drag.preview.remove();
  if (shouldDrop) drag.placeholder.replaceWith(drag.row);
  else {
    if (drag.originalNextSibling?.parentElement === drag.tbody) drag.originalNextSibling.before(drag.row);
    else drag.tbody.append(drag.row);
    drag.placeholder.remove();
  }
  drag.row.querySelector("[data-warehouse-drag]")?.setAttribute("aria-grabbed", "false");
  document.body.classList.remove("is-warehouse-dragging");
  state.inventoryWarehouseDrag = null;
  if (!shouldDrop) return;
  const ordered = [...drag.tbody.querySelectorAll("[data-inventory-warehouse-row]")]
    .map((row) => state.inventoryWarehouses.find((warehouse) => String(warehouse.id) === String(row.dataset.inventoryWarehouseRow)))
    .filter(Boolean);
  const changed = ordered.length === state.inventoryWarehouses.length && ordered.some((warehouse, index) => warehouse !== state.inventoryWarehouses[index]);
  if (!changed) return;
  const snapshot = inventorySnapshot();
  state.inventoryWarehouses.splice(0, state.inventoryWarehouses.length, ...ordered);
  if (!inventoryCommit(snapshot)) { render(); return; }
  state.selected.clear();
  render();
  showToast("Warehouse order updated.");
}

