    if (!order || order.status !== "Sales Order" || order.deliveryStatus === "Delivered") { showToast("This Sales Order is already delivered or is no longer open."); return; }
    const sourceLocation = String(new FormData(form).get("sourceLocation") || "WH/Stock");
    if (!state.inventoryLocations.some((item) => item.name === sourceLocation && String(item.usage || "Internal").toLowerCase() === "internal")) { showToast("Choose a configured internal source location."); return; }
    const lines = (order.lines || []).map((line, index) => ({ line, index })).filter(({ line }) => !line.type);
    const quantities = new Map();
    const stockBySku = new Map();
    for (const input of form.querySelectorAll("[data-delivery-qty]")) {
      const index = Number(input.dataset.lineIndex);
      const orderLine = order.lines[index];
      const qty = input.disabled ? 0 : Number(input.value);
      if (!orderLine || orderLine.type || !Number.isFinite(qty) || qty < 0) { showToast("Enter a valid delivery quantity on each product line."); return; }
      if (!qty) continue;
      const product = salesProducts.find((item) => item.sku === orderLine.sku);
      const unit = orderLine.uom || product?.stockUom || "";
      const factor = product ? purchaseUnitFactor(product, unit) : null;
      const outstanding = Math.max(0, Number(orderLine.qty || 0) - Number(orderLine.deliveredQty || 0));
      if (!product || !factor) { showToast(`${orderLine.product}: configure a verified ${unit} to ${product?.stockUom || "stock-unit"} conversion before delivery.`); return; }
      if (!inventoryQuantityValid(qty, unit) || qty > outstanding + 0.0001) { showToast(`${orderLine.product}: enter a valid whole/decimal quantity up to ${money(outstanding)} ${unit}.`); return; }
      quantities.set(index, qty);
      stockBySku.set(orderLine.sku, (stockBySku.get(orderLine.sku) || 0) + qty * factor);
    }
    if (!quantities.size) { showToast("Enter at least one quantity to deliver."); return; }
    if (String(state.inventoryConfig?.pickingPolicy || "asap") === "all") {
      const incompleteLines = lines.filter(({ line, index }) => {
        const remaining = Math.max(0, Number(line.qty || 0) - Number(line.deliveredQty || 0));
        return remaining > 0 && Number(quantities.get(index) || 0) < remaining - 0.0001;
      });
      if (incompleteLines.length) { showToast("Shipping Policy requires all remaining products to be delivered together. Check available stock and quantities."); return; }
    }
    for (const [sku, qty] of stockBySku) {
      const product = salesProducts.find((item) => item.sku === sku);
      if (!product || qty > inventoryQtyAt(sku, sourceLocation) + 0.0001) { showToast(`${product?.name || sku}: delivery quantity exceeds stock in ${sourceLocation}.`); return; }
    }
    const snapshot = inventorySnapshot();
    for (const [index, qty] of quantities) {
      const line = order.lines[index];
      const product = salesProducts.find((item) => item.sku === line.sku);
      const factor = purchaseUnitFactor(product, line.uom || product.stockUom);
      const stockQty = qty * factor;
      if (!inventoryAdjustQtyAt(product, sourceLocation, -stockQty)) { inventoryRestore(snapshot); showToast(`${product.name}: stock changed before delivery could be validated.`); return; }
      line.deliveredQty = Number(line.deliveredQty || 0) + qty;
      inventoryMove("Delivery", product, stockQty, product.stockUom, order.ref, { location: sourceLocation, salesUnit: line.uom || product.stockUom, salesQty: qty, customer: order.customer || "", status: "Done" });
    }
    const fullyDelivered = lines.every(({ line }) => Number(line.deliveredQty || 0) >= Number(line.qty || 0) - 0.0001);
    order.deliveryStatus = fullyDelivered ? "Delivered" : "Partially Delivered";
    if (fullyDelivered) order.status = "Delivered";
    if (!inventoryCommit(snapshot, { orders: true })) return;
    state.inventoryDeliveryEditor = null; setPage("inventory-deliveries");
