    if (!product || !inventoryQuantityValid(qty, product.stockUom || "Units") || qty > inventoryQtyAt(product.sku, from) + 0.0001 || !from || !to || from === to || !state.inventoryLocations.some((item) => item.name === from) || !state.inventoryLocations.some((item) => item.name === to)) { showToast("Choose a product, valid quantity within source stock, and two configured locations."); return; }
    const snapshot = inventorySnapshot();
