document.addEventListener("click", (event) => {
  const saveCategory = event.target.closest("[data-action='save-category-edit']");
  if (saveCategory) {
    const category = categories.find((item) => item.id === Number(saveCategory.dataset.id));
    const newName = document.querySelector("#edit-category-name")?.value.trim();
    if (category && newName && newName.toLowerCase() !== category.name.toLowerCase()) {
      if (categories.some((item) => item !== category && item.name.toLowerCase() === newName.toLowerCase())) { showToast("A product category with this name already exists."); return; }
      const previousName = category.name;
      const linkedProducts = salesProducts.filter((product) => String(product.category || "").toLowerCase() === previousName.toLowerCase());
      const snapshots = linkedProducts.map((product) => ({ product, name: product.name, baseName: product.baseName, category: product.category }));
      category.name = newName;
      linkedProducts.forEach((product) => {
        const baseName = salesProductBaseName(product);
        product.category = newName;
        product.baseName = baseName;
        product.name = salesProductVariantTitle(salesProductDisplayTitle(newName, baseName, product.variantLabel, product.includeCategoryInTitle !== false), product.netContentValue, product.netContentUnit);
      });
      try {
        localStorage.setItem(productCategoryStorageKey, JSON.stringify(categories));
        localStorage.setItem("odooFmcgSalesProducts", JSON.stringify(salesProducts));
        if (state.productCategoryFilter === previousName) state.productCategoryFilter = newName;
      } catch {
        category.name = previousName;
        snapshots.forEach(({ product, name, baseName, category: previousCategory }) => Object.assign(product, { name, baseName, category: previousCategory }));
        showToast("This browser could not save the category change.");
        return;
      }
    } else if (category && newName && !persistProductCategories()) { showToast("This browser could not save the category change."); return; }
    closeModal(); render(); showToast("Category updated.");
  }
});

function updatePackRulePreview() {
  const preview = document.querySelector("#pack-conversion-preview");
  if (!preview) return;
  const quantity = Number(document.querySelector("#pack-quantity")?.value);
  const pack = document.querySelector("#pack-purchase-unit")?.value.trim() || "supplier pack";
  const unit = document.querySelector("#pack-stock-uom")?.value || "unit";
  preview.textContent = Number.isFinite(quantity) && quantity > 0
    ? `1 ${pack} = ${quantity.toLocaleString("en-BD", { maximumFractionDigits: 3 })} ${unit}`
    : "Enter the verified pack quantity to preview the conversion.";
}

document.addEventListener("change", (event) => {
  if (event.target.matches("[data-stock-custom-image]")) {
    const input = event.target;
    const file = input.files?.[0];
    const product = salesProducts.find((item) => String(item.id) === String(input.dataset.productId));
    const field = state.inventoryStockCustomColumns.find((item) => String(item.id) === String(input.dataset.fieldId));
    if (!file || !product || !field) return;
    if (!file.type.startsWith("image/") || file.size > 6 * 1024 * 1024) {
      input.value = "";
      showToast("Choose an image smaller than 6 MB.");
      return;
    }
    input.disabled = true;
    Promise.resolve().then(() => createImageBitmap(file)).then((bitmap) => {
      const scale = Math.min(1, 360 / Math.max(bitmap.width, bitmap.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(bitmap.width * scale));
      canvas.height = Math.max(1, Math.round(bitmap.height * scale));
      const context = canvas.getContext("2d");
      context.fillStyle = "#ffffff";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
      bitmap.close();
      const snapshot = inventorySnapshot();
      product.inventoryStockCustomValues = { ...(product.inventoryStockCustomValues || {}), [String(field.id)]: canvas.toDataURL("image/jpeg", 0.78) };
      if (!inventoryCommit(snapshot)) { render(); return; }
      render();
      showToast(`${field.name} image saved for ${product.name}.`);
    }).catch(() => {
      input.disabled = false;
      input.value = "";
      showToast("This image could not be opened. Choose another image file.");
    });
    return;
  }
  if (event.target.matches("[data-stock-custom-value]")) {
    const input = event.target;
    const product = salesProducts.find((item) => String(item.id) === String(input.dataset.productId));
    const field = state.inventoryStockCustomColumns.find((item) => String(item.id) === String(input.dataset.fieldId));
    if (!product || !field) return;
    const snapshot = inventorySnapshot();
    const value = field.type === "boolean" ? input.checked : ["integer", "number"].includes(field.type) && input.value !== "" ? Number(input.value) : input.value;
    product.inventoryStockCustomValues = { ...(product.inventoryStockCustomValues || {}), [String(field.id)]: value };
    if (!inventoryCommit(snapshot)) render();
    return;
  }
  if (event.target.matches("[data-stock-report-datetime]")) {
    const selected = String(event.target.value || "");
    if (!selected || selected > inputLocalDateTime()) {
      event.target.value = state.inventoryStockReportDateTime || inputLocalDateTime();
      showToast("Choose a date and time up to the current time.");
      return;
    }
    state.inventoryStockReportDateTime = selected;
    state.inventoryStockReportDate = selected.slice(0, 10) === inputLocalDate() ? "" : selected.slice(0, 10);
    render();
    return;
  }
  if (event.target.matches("[data-inventory-count]")) {
    const input = event.target;
    const product = salesProducts.find((item) => item.sku === input.dataset.sku);
    const previous = state.inventoryCounts;
    if (!product) return;
    const location = input.dataset.location || "WH/Stock";
    if (input.value.trim() === "") {
      state.inventoryCounts = state.inventoryCounts.filter((item) => item.sku !== product.sku || (item.location || "WH/Stock") !== location);
      if (!inventoryPersistCounts()) { state.inventoryCounts = previous; input.value = inventoryCountRecord(product.sku, location)?.counted ?? ""; return; }
    } else {
      const counted = Number(input.value);
      if (!inventoryQuantityValid(counted, product.stockUom || "Units", { allowZero: true })) {
        input.value = inventoryCountRecord(product.sku, location)?.counted ?? "";
        showToast(`${product.name}: enter a valid counted quantity using ${product.stockUom || "the stock unit"}.`);
        return;
      }
      const existing = inventoryCountRecord(product.sku, location);
      const record = { ...(existing || {}), id: existing?.id || Date.now(), sku: product.sku, product: product.name, location, counted, reference: existing?.reference || "", scheduledDate: existing?.scheduledDate || inputLocalDate(), user: existing?.user || state.userProfile?.login || "Current User" };
      state.inventoryCounts = [...state.inventoryCounts.filter((item) => item.sku !== product.sku || (item.location || "WH/Stock") !== location), record];
      if (!inventoryPersistCounts()) { state.inventoryCounts = previous; input.value = inventoryCountRecord(product.sku, location)?.counted ?? ""; return; }
    }
    const hasCount = Boolean(inventoryCountRecord(product.sku, location));
    const apply = input.closest("tr")?.querySelector("[data-inventory-action='apply-count']");
    const clear = input.closest("tr")?.querySelector("[data-inventory-action='clear-count']");
    if (apply) apply.disabled = !hasCount;
    if (clear) clear.disabled = !hasCount;
    return;
  }
  if (event.target.matches("[data-accounting-range]")) {
    const key = event.target.dataset.accountingRange;
    const previous = { ...state.accountingRange };
    state.accountingRange[key] = event.target.value;
    if (state.accountingRange.start && state.accountingRange.end && state.accountingRange.start > state.accountingRange.end) {
      state.accountingRange = previous; showToast("The period start date must be on or before the end date."); render(); return;
    }
    render(); return;
  }
  if (event.target.matches("[data-dashboard-period]")) {
    state.dashboardPeriod = Number(event.target.value) || 90;
    state.dashboardOffset = 0;
    render();
    return;
  }
  const columnToggle = event.target.closest("[data-column-index]");
  if (columnToggle) {
    const table = currentListTable();
    const column = listColumnItems(table).find((item) => item.index === Number(columnToggle.dataset.columnIndex));
    if (!column) return;
    const columnKey = `${column.index}::${column.label}`;
    const visibilityKey = columnVisibilityKey();
    const initialVisibility = state.columnVisibility[visibilityKey] || defaultColumnVisibility(visibilityKey);
    const current = Array.isArray(initialVisibility) ? new Set(initialVisibility) : new Set(listColumnItems(table).map((item) => `${item.index}::${item.label}`));
    if (columnToggle.checked) current.add(columnKey); else current.delete(columnKey);
    state.columnVisibility[visibilityKey] = [...current];
    localStorage.setItem("odooColumnVisibility", JSON.stringify(state.columnVisibility));
    applySavedColumnVisibility(table);
    return;
  }
  const productChoice = event.target.closest("[data-select-product]");
  if (productChoice) showToast(`${productChoice.checked ? "Selected" : "Cleared"} product.`);
  const saleProductChoice = event.target.closest("[data-sale-product]");
  if (saleProductChoice) {
    const product = salesProducts.find((item) => item.id === Number(saleProductChoice.value));
    const line = saleProductChoice.closest(".sale-line");
    const unit = line?.querySelector("[data-sale-uom]");
    if (product && unit) {
      unit.innerHTML = product.saleUnits.map((value, index) => `<option value="${escapeHtml(value)}" ${index === 0 ? "selected" : ""} ${product.unitFactors?.[value] ? "" : "disabled"}>${escapeHtml(value)}${product.unitFactors?.[value] ? "" : " · configure pack"}</option>`).join("");
      unit.dataset.currentUnit = product.saleUnits[0] || product.stockUom;
      const notes = line.querySelectorAll(".sales-line-note");
      if (notes[0]) notes[0].textContent = product.sku;
      if (notes[1]) notes[1].textContent = product.packNote;
      const productCell = saleProductChoice.closest("td");
      productCell?.querySelector(".sale-promotion-gift-choice")?.remove();
      productCell?.querySelector(".sale-promotion-gift-fixed")?.remove();
      productCell?.querySelector("[data-sale-promotion-gift]")?.remove();
      productCell?.querySelector("[data-sale-consumer-offer]")?.remove();
      const offer = salesProductOffer(product);
      if (notes[0]) notes[0].insertAdjacentHTML("afterend", `${salesLineConsumerOfferSelectMarkup(product, offer?.id)}${salesLinePromotionGiftMarkup(product, "", false, offer?.id)}`);
      const qty = line.querySelector("[data-sale-qty]");
      const decimal = salesUnitAllowsFraction(product, product.saleUnits[0]);
      if (qty) { qty.min = decimal ? "0.001" : "1"; qty.step = decimal ? "0.001" : "1"; qty.value = "1"; }
      const price = line.querySelector("[data-sale-price]");
      if (price) price.value = String(salesProductOfferPrice(product, offer, product.saleUnits[0] || product.stockUom));
      const discount = line.querySelector("[data-sale-discount]");
      if (discount && state.salesSettings.lineDiscountsEnabled === false) discount.value = "0";
      const tax = line.querySelector("[data-sale-tax]");
      if (tax) tax.innerHTML = invoiceTaxOptions("out_invoice", product.salesTaxId || null);
      updateSaleTotal();
    }
  }
  const saleOfferChoice = event.target.closest("[data-sale-consumer-offer]");
  if (saleOfferChoice) {
    const line = saleOfferChoice.closest(".sale-line");
    const product = salesProducts.find((item) => item.id === Number(line?.querySelector("[data-sale-product]")?.value));
    const offer = salesProductOffer(product, saleOfferChoice.value);
    const unit = line?.querySelector("[data-sale-uom]")?.value || product?.stockUom;
    const price = line?.querySelector("[data-sale-price]");
    if (product && price) price.value = String(salesProductOfferPrice(product, offer, unit));
    line?.querySelector(".sale-promotion-gift-choice")?.remove();
    line?.querySelector(".sale-promotion-gift-fixed")?.remove();
    line?.querySelector("[data-sale-promotion-gift]")?.remove();
    const selector = line?.querySelector("[data-sale-consumer-offer]");
    if (selector) selector.insertAdjacentHTML("afterend", salesLinePromotionGiftMarkup(product, "", false, offer?.id));
    updateSaleTotal();
    return;
  }
  const saleUnitChoice = event.target.closest("[data-sale-uom]");
  if (saleUnitChoice) {
    const line = saleUnitChoice.closest(".sale-line");
    const qty = line?.querySelector("[data-sale-qty]");
    const product = salesProducts.find((item) => item.id === Number(line?.querySelector("[data-sale-product]")?.value));
    const decimal = salesUnitAllowsFraction(product, saleUnitChoice.value);
    const previousUnit = saleUnitChoice.dataset.currentUnit || product?.stockUom || saleUnitChoice.value;
    const previousFactor = product ? productUnitFactor(product, previousUnit) : null;
    const nextFactor = product ? productUnitFactor(product, saleUnitChoice.value) : null;
    if (qty) {
      if (previousFactor && nextFactor && Number(qty.value) > 0) qty.value = (Number(qty.value) * previousFactor / nextFactor).toFixed(3).replace(/\.?0+$/, "");
      qty.min = decimal ? "0.001" : "1";
      qty.step = decimal ? "0.001" : "1";
    }
    saleUnitChoice.dataset.currentUnit = saleUnitChoice.value;
    const price = line?.querySelector("[data-sale-price]");
    const offer = salesProductOffer(product, line?.querySelector("[data-sale-consumer-offer]")?.value || "");
    if (product && price) price.value = String(salesProductOfferPrice(product, offer, saleUnitChoice.value));
    updateSaleTotal();
  }
  if (event.target.matches("[data-sale-tax]")) updateSaleTotal();
  if (event.target.matches("[data-sales-period]")) {
    state.salesPeriod = event.target.value;
    render();
  }
});

document.addEventListener("input", (event) => {
  if (event.target.id !== "inventory-stock-custom-field-name") return;
  const label = event.target.value.trim() || "Field Label";
  const previewLabel = document.querySelector("[data-stock-field-preview-label]");
  const previewValue = document.querySelector("[data-stock-field-preview-value]");
  if (previewLabel) previewLabel.textContent = label;
  if (previewValue) previewValue.textContent = event.target.value.trim() ? "New column will appear in the stock list" : "Enter a label to preview the new column";
});

document.addEventListener("click", (event) => {
  const tile = event.target.closest("[data-stock-field-type]");
  if (tile) {
    const form = tile.closest("#inventory-stock-custom-field-form");
    if (!form) return;
    const type = tile.dataset.stockFieldType;
    const label = tile.querySelector("b")?.textContent || "Text";
    const descriptions = {
      text: "A short text value can be entered for each product.",
      integer: "Enter a whole number for each product.",
      number: "Enter a numeric value, including decimals.",
      date: "Choose a date for each product.",
      "datetime-local": "Choose a date and time for each product.",
      boolean: "Use a checkbox to track a yes or no value.",
      image: "Upload a product-specific image. Images are resized and saved in this browser.",
    };
    form.querySelector("input[name='type']").value = type;
    form.querySelectorAll("[data-stock-field-type]").forEach((item) => {
      const selected = item === tile;
      item.classList.toggle("is-selected", selected);
      item.setAttribute("aria-pressed", String(selected));
    });
    const selectedLabel = form.querySelector("[data-stock-field-selected-label]");
    const help = form.querySelector("[data-stock-field-type-help]");
    if (selectedLabel) selectedLabel.textContent = label;
    if (help) help.textContent = descriptions[type] || descriptions.text;
    return;
  }
  const clearImage = event.target.closest("[data-stock-custom-image-clear]");
  if (!clearImage) return;
  const product = salesProducts.find((item) => String(item.id) === String(clearImage.dataset.productId));
  const field = state.inventoryStockCustomColumns.find((item) => String(item.id) === String(clearImage.dataset.fieldId));
  if (!product || !field) return;
  const snapshot = inventorySnapshot();
  const values = { ...(product.inventoryStockCustomValues || {}) };
  delete values[String(field.id)];
  product.inventoryStockCustomValues = values;
  if (!inventoryCommit(snapshot)) return;
  render();
  showToast(`${field.name} image removed from ${product.name}.`);
});

document.addEventListener("keydown", (event) => {
  if (event.target.matches("[data-gift-item-search]") && ["Enter", "ArrowDown"].includes(event.key)) {
    const picker = event.target.closest("[data-product-gift-picker]");
    const menu = picker?.querySelector("[data-product-gift-menu]");
    const firstOption = menu?.querySelector("[data-gift-item-choice], [data-gift-item-create], [data-gift-item-create-edit]");
    if (firstOption) {
      event.preventDefault();
      if (event.key === "Enter") firstOption.click();
      else firstOption.focus();
      return;
    }
  }
  if (event.key === "Escape" && event.target.closest("[data-product-gift-picker]")) {
    const picker = event.target.closest("[data-product-gift-picker]");
    const menu = picker.querySelector("[data-product-gift-menu]");
    if (menu && !menu.hidden) {
      event.preventDefault();
      menu.hidden = true;
      picker.querySelector("[data-gift-item-search]")?.setAttribute("aria-expanded", "false");
      return;
    }
  }
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
    event.preventDefault();
    const input = document.querySelector("#global-search");
    if (input) input.focus();
  }
  if (event.key === "Escape") { closeMenus(); closeModal(); }
});

document.addEventListener("input", (event) => {
  const form = event.target.closest?.("#sales-product-form");
  if (form) syncSalesProductSaveState(form);
});

document.addEventListener("change", (event) => {
  const form = event.target.closest?.("#sales-product-form");
  const offerMode = event.target.closest?.("[data-consumer-offer-mode]");
  if (offerMode) {
    const row = offerMode.closest("[data-consumer-offer-row]");
    const chooseOne = offerMode.value === "choose-one";
    const legend = row?.querySelector("[data-consumer-offer-gifts-legend]");
    const help = row?.querySelector("[data-consumer-offer-gifts-help]");
    if (legend) legend.textContent = chooseOne ? "Gift choices" : "Gift products";
    if (help) help.textContent = chooseOne
      ? "Select the eligible alternatives here. The customer will choose exactly one when ordering."
      : "Every selected gift is included automatically with this offer.";
    row?.classList.toggle("is-choose-one-offer", chooseOne);
  }
  if (form) syncSalesProductSaveState(form);
});

document.addEventListener("click", (event) => {
  const changedFormControl = event.target.closest?.("#sales-product-form [data-product-add-row], #sales-product-form [data-product-remove-row], #sales-product-form [data-product-config-add-row], #sales-product-form [data-product-config-remove-row], #sales-product-form [data-product-add-gift], #sales-product-form [data-product-remove-gift], #sales-product-form [data-consumer-offer-add], #sales-product-form [data-consumer-offer-remove], #sales-product-form [data-product-favorite], #sales-product-form [data-product-image-generate], #sales-product-form [data-product-sku-auto]");
  if (changedFormControl) syncSalesProductSaveState(changedFormControl.closest("#sales-product-form"));
});

function inventorySeedDemoCatalog() {
  if (isFreshCompanyStart) return;
  const seedKey = "odooFmcgInventoryDemoSeedV1";
  try {
    if (localStorage.getItem(seedKey) === "done") return;
    inventoryEnsureBalances();
    localStorage.setItem("odooFmcgSalesProducts", JSON.stringify(salesProducts));
    localStorage.setItem("odooFmcgInventoryBalances", JSON.stringify(state.inventoryBalances));
    localStorage.setItem(seedKey, "done");
  } catch { /* Keep the sample catalogue in memory if browser storage is unavailable. */ }
}

inventorySeedDemoCatalog();
purgeLegacyDemoProducts();
persistLastRoute({ historyMode: "replace" });
render();

document.addEventListener("change", (event) => {
  const analysisField = event.target.closest("[data-purchase-analysis-field]");
  if (analysisField) {
    const key = analysisField.dataset.purchaseAnalysisField;
    if (["kind", "dateField", "dateRange", "measure", "customStart", "customEnd"].includes(key)) {
      state.purchaseAnalysis[key] = analysisField.value;
      if (key === "dateRange" && analysisField.value === "custom") {
        const today = purchaseAnalysisToday();
        state.purchaseAnalysis.customEnd ||= `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
        if (!state.purchaseAnalysis.customStart) { const start = new Date(today); start.setDate(start.getDate() - 29); state.purchaseAnalysis.customStart = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, "0")}-${String(start.getDate()).padStart(2, "0")}`; }
      }
      render();
    }
    return;
  }
  const analysisToggle = event.target.closest("[data-purchase-analysis-toggle]");
  if (analysisToggle) {
    state.purchaseAnalysis[analysisToggle.dataset.purchaseAnalysisToggle] = analysisToggle.checked;
    render();
    return;
  }
  const field = event.target.closest("[data-purchase-filter]");
  if (!field) return;
  const key = field.dataset.purchaseFilter;
  if (!["status", "vendor", "buyer"].includes(key)) return;
  state.purchaseFilters = { ...(state.purchaseFilters || {}), [key]: field.value };
  state.purchasePage = 0;
  render();
});
